import{A as e,M as t,j as n}from"./data-C-K-a5D8.js";import{t as r}from"./bio-C-n1p0Ws.js";import{n as i,t as a}from"./pedagogie-Dtc_OLV7.js";var o=e=>({niveau:1,duree:`Lecture : 5 minutes`,...e}),s=[o({id:`registre-elevage`,titre:`Le registre d'élevage et l'identification des animaux`,rubrique:`animaux`,emoji:`📒`,resume:`Qui doit tenir un registre, ce qu'il contient, et comment identifier chèvres, moutons, cochons, ânes et chevaux, même pour un ou deux animaux de compagnie.`,alias:[`registre`,`registre d elevage`,`boucles`,`boucle`,`identification`,`ede`,`numero d elevage`,`puce`,`document de circulation`],etapes:[{titre:`Qui est concerné`,texte:`Chèvres, moutons et cochons : dès le premier animal, même de compagnie, vous devez vous déclarer auprès de l'EDE (établissement de l'élevage de votre département), qui vous attribue un numéro d'élevage, et tenir un registre. Ânes et chevaux : identification par puce et déclaration du lieu de détention à l'IFCE. Volailles : déclaration en mairie, pas de registre pour une basse-cour familiale. Ruches : déclaration annuelle.`},{titre:`L'identification`,texte:`Chèvres et moutons : deux boucles d'oreille officielles (dont une électronique), posées avant 6 mois, commandées auprès de l'EDE ou de l'organisme agréé. Cochons : boucle ou tatouage avant toute sortie de l'élevage. Ânes et chevaux : puce posée par un vétérinaire et document d'identification qui suit l'animal.`},{titre:`Ce que contient le registre`,texte:`Les coordonnées de l'élevage et son numéro ; chaque entrée (date, nombre, numéros, provenance), chaque naissance, chaque sortie (vente, don, avec la destination) et chaque mort (date, cause si connue, bon d'enlèvement de l'équarrissage) ; les documents de circulation ; les traitements vétérinaires et les ordonnances (à garder 5 ans).`},{titre:`Avec Racines`,texte:`Dans « Mon jardin → Animaux », le registre note chaque mouvement, met à jour l'effectif et s'exporte en tableur ; « Mes animaux un par un » garde les numéros de boucle, les dates de naissance et les races. Imprimez-le ou recopiez-le : seul le registre conforme (papier ou logiciel agréé) fait foi lors d'un contrôle.`},{titre:`Le recensement annuel`,texte:`Chaque année, l'EDE envoie un formulaire de recensement des chèvres et moutons présents : à renvoyer même si vous n'en avez que deux.`}],video:`registre d'élevage chèvres moutons particulier`,liens:[`chevre`,`mouton`,`cochon`,`ane`,`voisinage-regles`]}),o({id:`naissances`,titre:`Mises bas : chevreaux, agneaux, lapereaux, porcelets`,rubrique:`animaux`,emoji:`🍼`,resume:`Préparer la mise bas, reconnaître quand appeler le vétérinaire, le colostrum indispensable dans les premières heures, et que faire si un petit ne tète pas.`,alias:[`mise bas`,`mettre bas`,`agnelage`,`chevrotage`,`colostrum`,`chevreau`,`agneau`,`lapereaux`,`porcelets`,`ne tete pas`,`biberon`,`naissance`],etapes:[{titre:`Préparer`,texte:`Chèvre : 150 jours de gestation ; brebis : 147 ; lapine : 31 ; truie : 114. Une à deux semaines avant, un box propre et paillé épais, à l'abri des courants d'air, de l'eau tiède, une lampe frontale, des gants, de l'iode pour le cordon et le numéro du vétérinaire affiché.`},{titre:`La mise bas normale`,texte:`La femelle s'isole, gratte, se couche et se relève ; la poche des eaux apparaît puis le petit, pattes avant et tête d'abord, en 30 minutes à 1 heure. La mère lèche le petit. Désinfectez le cordon à l'iode. Laissez faire : la plupart des mises bas se passent sans aide.`},{titre:`Quand appeler le vétérinaire`,texte:`Plus d'une heure d'efforts sans rien voir sortir ; une seule patte, la queue ou la tête seule qui se présente ; la mère épuisée ou qui saigne beaucoup ; le placenta non expulsé après 12 heures ; un petit qui ne respire pas malgré un frottement vigoureux avec de la paille.`},{titre:`Le colostrum : vital`,texte:`Le premier lait (colostrum), épais et jaune, apporte les anticorps : le petit doit en boire dans les 2 heures, au moins 10 % de son poids dans les premières 24 heures. Après 24 heures, il ne peut plus absorber ces anticorps. Vérifiez qu'il tète vraiment (ventre plein, queue qui frétille).`},{titre:`Si le petit ne tète pas`,texte:`Mettez-le au pis en guidant sa bouche ; s'il est faible ou froid, réchauffez-le d'abord (bouillotte, lampe, contre vous). Si la mère n'a pas de lait ou le rejette : traire la mère et donner le colostrum au biberon, ou utiliser du colostrum congelé d'une autre mère ou un colostrum en poudre. Un petit qui ne tète pas en 6 heures est en danger : vétérinaire.`},{titre:`Les jours suivants`,texte:`Surveillez que chaque petit tète plusieurs fois par jour et prend du poids. Pour les lapereaux : ne touchez pas le nid les premiers jours, retirez seulement les petits morts. Les petits à vendre ou donner partent jamais avant le sevrage (8 semaines pour les chevreaux et agneaux) et identifiés si l'espèce l'exige.`}],video:`mise bas chèvre chevrotage colostrum`,liens:[`chevre`,`mouton`,`lapin`,`cochon`,`registre-elevage`]}),o({id:`vacances-animaux`,titre:`Partir en vacances quand on a des animaux`,rubrique:`animaux`,emoji:`🧳`,resume:`Combien de temps laisser des poules seules, comment préparer la personne qui garde, et la fiche à lui laisser pour chaque espèce.`,alias:[`vacances`,`partir en vacances`,`absence`,`garder mes poules`,`qui nourrit mes poules`,`pension animaux`,`voisin garde`],etapes:[{titre:`Combien de temps seuls ?`,texte:`Poules, canards, cailles : 2 jours au plus, avec mangeoire et abreuvoir de grande contenance et une porte automatique contre le renard ; au-delà, quelqu'un doit passer chaque jour (ramasser les œufs, vérifier l'eau, fermer). Lapins : un passage par jour indispensable (foin, eau). Chèvres, moutons, ânes, cochons : un passage quotidien obligatoire. Abeilles : aucun souci en dehors de la période d'essaimage (avril-juin).`},{titre:`Trouver qui garde`,texte:`Un voisin (souvent ravi en échange des œufs), un réseau de « gardes de poules » entre éleveurs, un pet-sitter qui accepte les animaux de ferme, ou une pension pour les chevaux et les ânes. Faites un essai d'une journée avant le départ.`},{titre:`La fiche à laisser`,texte:`Pour chaque espèce : quantité d'aliment et d'eau, où ils sont rangés, heure d'ouverture et de fermeture du poulailler, comment compter les animaux, signes d'alerte (animal isolé, qui ne mange plus, boiterie), numéro du vétérinaire et le vôtre, ce qu'il ne faut JAMAIS donner (voir la fiche de chaque animal).`},{titre:`Avant de partir`,texte:`Faire le plein d'aliment, de paille et de foin, nettoyer le poulailler, vérifier les clôtures et la porte automatique (piles !), traiter les poux rouges si besoin, retirer une poule couveuse. En été, prévoir de l'ombre et deux points d'eau ; en hiver, une solution contre l'eau gelée.`},{titre:`Au retour`,texte:`Compter les animaux, observer chacun quelques minutes, vérifier la ponte, et noter dans Racines les soins faits par la personne qui gardait.`}],video:`partir en vacances poules organisation`,liens:[`poule`,`lapin`,`chevre`,`nuisibles-predateurs`]}),o({id:`deces-animal`,titre:`Quand un animal meurt : que faire ?`,rubrique:`animaux`,emoji:`🕯️`,resume:`Repérer une mort suspecte, les règles pour enterrer ou faire enlever le corps selon l'espèce, et les démarches à ne pas oublier.`,alias:[`poule morte`,`animal mort`,`enterrer un animal`,`equarrissage`,`cadavre`,`mort subite`,`mort d'une chevre`,`deces animal`],etapes:[{titre:`D'abord : est-ce suspect ?`,texte:`Plusieurs animaux morts en peu de temps, ou des signes inhabituels (crêtes bleues, troubles nerveux, sang) : NE TOUCHEZ PAS les corps à mains nues, isolez les autres, appelez votre vétérinaire ou la DDPP (grippe aviaire, maladies réglementées). Une mort isolée et âgée est le plus souvent naturelle.`},{titre:`Volailles, lapins et petits animaux`,texte:`Un particulier peut enterrer un petit animal sur son propre terrain, loin de tout puits, source ou cours d'eau (au moins 35 m), assez profond (1 m, recouvert de chaux vive à défaut de terre suffisante) pour que les renards ne le déterrent pas. Sinon : vétérinaire (incinération) ou déchetterie selon les communes. Jamais dans les ordures ménagères ni dans la nature.`},{titre:`Chèvres, moutons, cochons, ânes, chevaux`,texte:`L'équarrissage est obligatoire : un service d'enlèvement agréé vient chercher le corps (gratuit ou payant selon l'espèce et le département, par téléphone ou en ligne). Gardez le bon d'enlèvement avec le registre et inscrivez la mort. Ânes et chevaux : déclarez aussi la mort à l'IFCE ; une incinération individuelle est possible par un service spécialisé.`},{titre:`Comprendre la cause`,texte:`Pour éviter que cela recommence, notez les signes observés ; votre vétérinaire peut faire une autopsie (utile pour un troupeau). Vérifiez les causes fréquentes : prédateur, coup de chaleur, plante toxique, parasites, poux rouges.`},{titre:`Avec les enfants`,texte:`Dites la vérité avec des mots simples, laissez-les dire au revoir s'ils le souhaitent, et lavez-vous tous les mains après avoir touché l'animal.`}],video:`que faire poule morte enterrer équarrissage`,liens:[`registre-elevage`,`grippe-aviaire`,`hygiene-animaux`]}),o({id:`poules-potager`,titre:`Les poules au potager : quand les lâcher, quand les tenir à l'écart`,rubrique:`animaux`,emoji:`🐔`,resume:`Faire travailler les poules au jardin (désherbage, ravageurs, fumure) sans qu'elles ne dévorent semis et récoltes.`,alias:[`poules au potager`,`lacher les poules`,`poules dans le jardin`,`poules et potager`,`tracteur a poules`,`poulailler mobile potager`],etapes:[{titre:`Quand les lâcher`,texte:`De la fin des récoltes (octobre) au début des semis (mars) : elles grattent, mangent larves, limaces, graines d'adventices et fertilisent. Sur une planche récoltée en été, une semaine suffit à la nettoyer. Avec un tracteur à poules (enclos mobile sans fond), on choisit précisément la planche à travailler.`},{titre:`Quand les tenir à l'écart`,texte:`Semis et jeunes plants (elles grattent et arrachent tout), fraises, tomates mûres, salades, choux : clôturez le potager ou protégez les planches par des arceaux et filets. Une clôture de 1,20 m suffit pour la plupart des poules (coupez une aile si besoin), 1,80 m pour les races légères.`},{titre:`Ce qu'elles font de mieux`,texte:`Nettoyer une parcelle envahie avant de la cultiver ; manger les vers blancs, taupins et limaces ; travailler le paillage et le compost (un tas à gratter au fond du parcours) ; débarrasser le verger des fruits tombés et des larves de carpocapse.`},{titre:`Les précautions`,texte:`Ne les laissez pas sur une planche traitée (même au cuivre) ni où poussent des plantes toxiques pour elles (avocatier, feuilles de rhubarbe, haricots crus, morelle). Attendez 3 à 4 mois entre leur passage et la récolte de légumes mangés crus (fientes). Elles adorent les fraises et les tomates cerises : protégez-les.`},{titre:`Une rotation potager-poules`,texte:`Sur un grand terrain, alternez : une parcelle en potager, une en parcours de poules, une en prairie, et faites tourner chaque année. Les poules préparent la terre, le potager en profite l'année suivante.`}],video:`poules au potager tracteur à poules quand les lâcher`,liens:[`poule`,`poulailler`,`cultiver-pour-animaux`,`fumiers`]}),o({id:`hiver-basse-cour`,titre:`L'hiver à la basse-cour : eau gelée, froid, lumière, ponte`,rubrique:`animaux`,emoji:`❄️`,resume:`Garder de l'eau liquide, protéger du froid humide plus que du froid, et comprendre pourquoi les poules pondent moins (et pourquoi ne pas forcer).`,alias:[`eau gelee`,`abreuvoir gele`,`abreuvoir chauffant`,`poules en hiver`,`froid poulailler`,`lumiere poulailler`,`ponte hiver`,`gel poules`],etapes:[{titre:`L'eau qui gèle`,texte:`Le premier danger de l'hiver : sans eau, une poule cesse de pondre et s'affaiblit en un jour. Apportez de l'eau tiède matin et soir, utilisez un abreuvoir en caoutchouc (on casse la glace facilement), un socle chauffant électrique pour abreuvoir métallique, ou deux abreuvoirs en alternance. Une balle de ping-pong qui flotte retarde la prise en glace.`},{titre:`Le froid et l'humidité`,texte:`Les poules supportent bien le froid sec (jusqu'à -10 °C pour les races rustiques) grâce à leur plumage : il ne faut pas chauffer le poulailler. Ce qui les tue, c'est l'humidité et les courants d'air : litière épaisse et sèche (méthode de la litière accumulée), aération en haut sans courant d'air sur les perchoirs, toit étanche. Vaseline sur les crêtes des grandes races en cas de grand froid.`},{titre:`La ponte en hiver`,texte:`Il est normal que la ponte baisse ou s'arrête de novembre à février : il faut 14 heures de lumière par jour pour pondre régulièrement. C'est un repos utile après la mue.`},{titre:`Faut-il éclairer le poulailler ?`,texte:`Une lampe programmée le matin peut relancer la ponte, mais elle épuise les poules plus vite et raccourcit leur vie de pondeuse : c'est une pratique d'élevage intensif, déconseillée au jardin familial et interdite en bio au-delà de 16 heures de lumière par jour. Préférez avoir quelques races qui pondent l'hiver.`},{titre:`La ration d'hiver`,texte:`Un peu plus d'énergie (maïs concassé le soir), de la verdure (choux, restes de légumes du potager d'hiver), des coquilles d'huîtres toujours disponibles. Les autres animaux : foin à volonté, eau hors gel, abri sec (ânes et chèvres détestent la pluie).`}],video:`poules en hiver eau gelée conseils`,liens:[`poule`,`poulailler`,`chevre`,`ane`]}),o({id:`traite-fromage`,titre:`Traire une chèvre et faire ses premiers fromages`,rubrique:`animaux`,emoji:`🧀`,resume:`La traite à la main pas à pas, l'hygiène du lait cru, et un premier fromage frais (faisselle) en 24 heures.`,alias:[`traire`,`traite`,`fromage de chevre`,`faire du fromage`,`lait de chevre`,`faisselle`,`presure`,`lait cru`],etapes:[{titre:`Avant de traire`,texte:`Une chèvre ne donne du lait qu'après une mise bas (lactation de 8 à 10 mois). Quai de traite ou planche surélevée, un peu de céréales dans une mangeoire pour l'occuper, seau en inox propre, linge propre. Lavez-vous les mains, nettoyez le pis à l'eau tiède et essuyez-le.`},{titre:`La traite`,texte:`Éliminez les premiers jets (plus chargés en germes) dans un bol : leur aspect vous renseigne (grumeaux ou sang = mammite, vétérinaire). Prenez le trayon à pleine main, fermez le haut entre pouce et index pour bloquer le lait, puis serrez les autres doigts de haut en bas. Alternez les deux trayons sans tirer. 10 minutes au début, 5 minutes avec l'habitude ; deux fois par jour, à heures fixes.`},{titre:`Le lait`,texte:`Filtrez aussitôt dans un linge propre, refroidissez vite (bain d'eau froide) et gardez au réfrigérateur. Le lait cru peut transmettre des maladies (listériose, brucellose dans certaines régions) : pour les femmes enceintes, les jeunes enfants et les personnes fragiles, pasteurisez-le (chauffé à 72 °C pendant 15 secondes, ou 63 °C pendant 30 minutes) ou faites-le bouillir.`},{titre:`Un premier fromage frais`,texte:`1 L de lait à 20-25 °C, 2 gouttes de présure (pharmacie ou magasin de fromagerie) et un peu de ferment ou une cuillère de petit-lait de la veille ; couvrez et laissez cailler 24 heures à température ambiante. Moulez le caillé à la louche dans des faisselles, égouttez 12 à 24 heures, salez. Se conserve 5 jours au frais.`},{titre:`Aller plus loin`,texte:`Crottins affinés, tommes, yaourts : un stage chez un fromager ou un livre de fromagerie fermière vous apprendra l'affinage. La vente de fromages est soumise à agrément sanitaire : réservé à la consommation familiale sans démarches.`}],video:`traire une chèvre à la main fromage frais`,liens:[`chevre`,`hygiene-animaux`]}),o({id:`tonte-laine`,titre:`Tondre ses moutons et utiliser la laine`,rubrique:`animaux`,emoji:`🧶`,resume:`Quand et comment faire tondre, ce qu'on fait de la laine (paillage, isolant, filage), et les races qui n'ont pas besoin de tonte.`,alias:[`tonte`,`tondre un mouton`,`tondre les moutons`,`laine`,`tondeur`,`laine de mouton`,`paillage laine`],etapes:[{titre:`Pourquoi tondre`,texte:`La plupart des moutons n'ont pas de mue naturelle : non tondus, ils souffrent de la chaleur, de parasites et de myiases (asticots) dans la laine souillée. La tonte est obligatoire une fois par an, en mai-juin, après les dernières gelées.`},{titre:`Faire appel à un tondeur`,texte:`Un tondeur professionnel tond un mouton en 3 à 5 minutes, sans le blesser, pour quelques euros par animal : c'est la solution la plus simple pour 2 à 10 moutons. Les tondeurs passent souvent par tournée : réservez au printemps. Gardez les moutons au sec la veille (laine mouillée = pas de tonte).`},{titre:`Tondre soi-même`,texte:`Avec des forces (grands ciseaux) ou une tondeuse électrique spéciale, après une formation : on assoit le mouton sur son arrière-train, le dos contre ses jambes, et on tond par grands passages en tendant la peau. Le risque de coupure est réel au début.`},{titre:`Que faire de la laine`,texte:`La laine brute se vend mal, mais elle est précieuse au jardin : paillage (au pied des arbres, des fraisiers, contre les limaces), engrais à décomposition lente (riche en azote), isolant de nichoirs. Lavée et cardée, elle se file ou se feutre. Ne la brûlez pas.`},{titre:`Les races sans tonte`,texte:`Mouton du Cameroun, Barbados, Dorper : poil ras qui mue seul. Idéal si l'on veut des moutons pour entretenir un pré sans contrainte de tonte.`}],video:`tonte mouton particulier laine utilisation`,liens:[`mouton`,`myiase`]}),o({id:`recolte-miel`,titre:`Récolter le miel de sa ruche familiale`,rubrique:`animaux`,emoji:`🍯`,resume:`Quand récolter, combien laisser aux abeilles, et la récolte pas à pas avec ou sans extracteur.`,alias:[`recolter le miel`,`recolte du miel`,`extracteur`,`hausse`,`miel`,`desoperculer`,`maturateur`],etapes:[{titre:`Quand`,texte:`Quand les cadres de la hausse (la partie au-dessus du corps de ruche) sont operculés (cire qui ferme les alvéoles) aux trois quarts : en général juin-juillet, parfois en fin d'été. Jamais le corps de ruche : ce sont les réserves d'hiver des abeilles.`},{titre:`Combien laisser`,texte:`Une colonie a besoin de 15 à 20 kg de miel pour passer l'hiver. Ne récoltez que les hausses, et vérifiez les réserves en septembre : si la ruche est légère, nourrissez au sirop épais avant l'hiver.`},{titre:`Retirer les hausses`,texte:`Posez un chasse-abeilles sous la hausse la veille : le lendemain, elle est presque vide d'abeilles. Combinaison, voile, gants, enfumoir ; travaillez par temps doux et calme, en milieu de journée.`},{titre:`Extraire`,texte:`Dans une pièce fermée (sinon pillage par les abeilles), désoperculez les cadres au couteau ou à la fourchette, passez-les dans un extracteur (souvent prêté ou loué par le syndicat apicole), filtrez et laissez reposer quelques jours en maturateur avant de mettre en pots. Sans extracteur : écraser les rayons et laisser couler à travers un tamis (méthode des ruches Warré ou kenyanes).`},{titre:`Rendre la hausse`,texte:`Reposez les hausses vides au-dessus des ruches le soir : les abeilles les nettoient. Rangez-les ensuite à l'abri de la fausse teigne (froid, ou soufre).`}],video:`récolte du miel débutant extraction`,liens:[`abeille`,`varroa`]}),o({id:`hygiene-animaux`,titre:`Animaux, enfants et hygiène : œufs, lait, zoonoses`,rubrique:`securite`,emoji:`🧼`,resume:`Les maladies que les animaux peuvent transmettre aux personnes, les gestes simples qui les évitent, et les précautions pour les enfants et les personnes fragiles.`,alias:[`salmonelle`,`salmonellose`,`zoonose`,`hygiene`,`enfants et poules`,`laver les oeufs`,`lait cru`,`tetanos`,`teigne`],etapes:[{titre:`Les maladies à connaître`,texte:`Salmonellose (fientes, œufs souillés), campylobactériose, E. coli (fumier), teigne (champignon de la peau des lapins, veaux, chèvres), fièvre Q et toxoplasmose (mise bas des chèvres et brebis, à éviter pendant la grossesse), tétanos (terre, fumier : vaccin à jour), psittacose (oiseaux), leptospirose (eau souillée par les rats).`},{titre:`Les bons gestes`,texte:`Lavage des mains au savon après chaque contact avec les animaux, le poulailler, le fumier ou les œufs, et toujours avant de manger. Chaussures et vêtements réservés au poulailler. Pas d'animaux de ferme dans la cuisine ni de poussins à la maison. Rats éloignés (aliment dans des bidons fermés).`},{titre:`Les enfants`,texte:`Les moins de 5 ans sont les plus sensibles : pas de bisous aux poules ni aux poussins, mains lavées sous surveillance, pas de main à la bouche au poulailler. Expliquez qu'on ne prend pas un animal par les ailes ou les oreilles. Les enfants adorent ramasser les œufs : c'est une excellente tâche, suivie du lavage des mains.`},{titre:`Les œufs`,texte:`Ramassez-les chaque jour, ne lavez pas les œufs propres (vous retireriez la protection naturelle de la coquille) ; brossez à sec les œufs un peu sales, jetez les œufs fêlés ou très souillés. Conservez au frais et à l'abri des variations de température. Cuisez bien les œufs pour les personnes fragiles (femmes enceintes, jeunes enfants, personnes âgées).`},{titre:`Le lait cru et la viande`,texte:`Lait cru : pasteurisé pour les personnes fragiles. Viande de l'abattage familial : chaîne du froid, cuisson à cœur pour la volaille et le porc.`}],video:`hygiène poules enfants salmonelle conseils`,liens:[`oeufs`,`traite-fromage`,`deces-animal`]}),o({id:`autres-animaux`,titre:`Alpagas, lamas, vaches naines, paons, faisans, et animaux de compagnie`,rubrique:`animaux`,emoji:`🦙`,resume:`Les espèces que Racines ne détaille pas encore dans une fiche : ce qu'il faut savoir avant de se lancer, et les obligations.`,alias:[`alpaga`,`lama`,`vache naine`,`vache`,`dexter`,`highland`,`paon`,`faisan`,`cochon d inde`,`lapin nain`,`cobaye`,`animal de compagnie`],etapes:[{titre:`Alpagas et lamas`,texte:`Animaux grégaires : au moins deux (jamais seuls). Environ 1 000 m² de pré pour deux alpagas, un abri, du foin l'hiver, tonte annuelle de la fibre, soin des ongles et des dents. Ils utilisent un même tas pour leurs crottes (précieux engrais). Déclaration et identification par puce recommandées ; vétérinaires connaissant les camélidés à repérer avant l'achat.`},{titre:`Vaches naines (Dexter, Highland, Jersiaise)`,texte:`Une vache reste un bovin : identification obligatoire (boucles, passeport), déclaration à l'EDE, registre, prophylaxie annuelle. Il faut au moins 0,5 à 1 ha par animal, un abri, de l'eau en quantité (50 L par jour), et ne jamais la garder seule. La traite d'une vache laitière est quotidienne, sans exception.`},{titre:`Paons et faisans d'ornement`,texte:`Le paon est très bruyant (cris au printemps, souvent source de conflits de voisinage) et vole : il lui faut de grands arbres ou une grande volière. Les faisans vivent en volière plantée. Comme pour les volailles : déclaration en mairie ; certaines espèces de faisans exotiques sont réglementées (certificat de capacité au-delà de quelques individus).`},{titre:`Lapins nains et cochons d'Inde (animaux de compagnie)`,texte:`Mêmes bases que le lapin de ferme : foin à volonté (80 % de la ration), légumes frais, eau, vaccins (lapin) ; mais ils vivent souvent à l'intérieur, ont besoin de compagnie de leur espèce et de 2 à 3 heures de liberté par jour. Le cochon d'Inde a besoin de vitamine C chaque jour (poivron, persil). Les sites spécialisés NAC et un vétérinaire NAC (nouveaux animaux de compagnie) sont les bonnes références.`},{titre:`Avant d'adopter une nouvelle espèce`,texte:`Renseignez-vous sur la réglementation (mairie, EDE, DDPP), le voisinage, le coût annuel, la durée de vie, et un vétérinaire capable de la soigner. Commencez par les espèces de Racines si vous débutez.`}],video:`alpaga lama au jardin débutant`,liens:[`integrer-animaux`,`voisinage-regles`,`lapin`]})],c=e=>({niveau:2,duree:`Lecture : 6 minutes`,...e}),l=[c({id:`outils-maraichers`,titre:`Les outils du maraîcher : désherber vite, semer juste, faire ses mottes`,rubrique:`demarrer`,emoji:`🛠️`,resume:`Houe maraîchère, binette oscillante, semoir de précision, plaques alvéolées, presse-mottes : les outils qui divisent le temps de travail par trois sur un grand potager.`,alias:[`outils maraichers`,`houe maraichere`,`binette oscillante`,`sarcleuse`,`semoir de precision`,`presse mottes`,`plaque alveolee`,`motte`,`rateau maraicher`,`vibroculteur`],etapes:[{titre:`Désherber : intervenir tôt`,texte:`Le secret du maraîcher : désherber quand les herbes sont au stade « fil blanc » (germées, pas encore visibles) ou de 2 feuilles, toutes les 7 à 10 jours. La binette oscillante (lame articulée qui coupe en poussant et en tirant), la houe maraîchère à roue et le sarcloir font en quelques minutes une planche entière, debout, sans se baisser.`},{titre:`Préparer la planche`,texte:`Grelinette pour décompacter sans retourner, croc ou griffe pour émietter, râteau large pour niveler, rouleau ou planche pour raffermir avant semis. Le faux-semis (préparer, laisser lever, détruire au râteau) avant chaque semis direct évite l'essentiel du désherbage.`},{titre:`Semer juste`,texte:`Le semoir de précision (à brosses ou à rouleaux interchangeables) sème carottes, radis, navets, épinards à l'espacement voulu sur 3 à 6 rangs à la fois : moins de graines et presque pas d'éclaircissage. À défaut, une planche à trous ou un semoir manuel à molette.`},{titre:`Les plants en plaques et en mottes`,texte:`Plaques alvéolées (77 à 150 trous) pour salades, choux, oignons ; godets de 7 à 9 cm pour tomates, aubergines, courges. Le presse-mottes fabrique des cubes de terreau pressé sans pot : zéro plastique, racines qui ne tournent pas, reprise excellente. Mélange : 2/3 terreau sans tourbe, 1/3 compost tamisé, bien humide.`},{titre:`Les petits plus`,texte:`Une brouette à deux roues, des caisses de récolte empilables, une table de rempotage à hauteur, un tuyau avec lance douche fine pour les semis, et des étiquettes réutilisables (date, variété, série).`}],video:`binette oscillante houe maraîchère presse mottes`,liens:[`desherbage`,`semis-interieur`,`carre-potager-diy`]}),c({id:`irrigation-raisonnee`,titre:`Irrigation raisonnée : goutte-à-goutte, aspersion, tensiomètre`,rubrique:`arrosage`,emoji:`💧`,resume:`Quel système pour quelle culture, comment dimensionner un goutte-à-goutte, combien de temps arroser, et savoir quand arroser grâce au tensiomètre ou au test de la tarière.`,alias:[`irrigation`,`aspersion`,`tensiometre`,`dimensionner goutte a goutte`,`duree arrosage`,`gaine goutte a goutte`,`programmateur`,`micro aspersion`],etapes:[{titre:`Quel système pour quoi`,texte:`Goutte-à-goutte (gaine perforée tous les 20 à 30 cm) : tomates, courges, poireaux, choux, fraisiers, toutes les cultures plantées, paillées. Micro-aspersion ou arrosage en pluie fine : semis directs (carottes, radis, mâche) et jeunes salades, le temps de la levée. L'aspersion mouille les feuilles : à faire le matin pour limiter les maladies.`},{titre:`Dimensionner`,texte:`Une gaine à goutteurs de 2 L/h tous les 30 cm débite environ 6,7 L/h par mètre. Une planche de 10 m avec 2 lignes : 134 L/h. Vérifiez que votre robinet ou votre pompe fournit le débit de toutes les planches arrosées en même temps (un robinet de jardin donne souvent 1 000 à 1 500 L/h) ; sinon, arrosez par secteurs avec un programmateur.`},{titre:`Combien de temps`,texte:`Besoin d'un potager paillé en été : 3 à 5 L/m² par jour en pleine chaleur, la moitié au printemps et à l'automne. Planche de 7,5 m² en juillet : environ 30 L par jour, soit 15 minutes avec les deux lignes ci-dessus. Mieux vaut arroser longuement 2 à 3 fois par semaine que peu chaque jour (racines profondes).`},{titre:`Savoir quand arroser`,texte:`Le tensiomètre (une sonde planté à 20-30 cm) mesure la force avec laquelle la terre retient l'eau : en dessous de 20 centibars la terre est humide, au-dessus de 40 à 60 il faut arroser (sols sableux plus tôt, argileux plus tard). Sans tensiomètre : enfoncez une tarière ou un transplantoir à 15 cm ; si la terre ne colle plus en boule, arrosez.`},{titre:`Entretenir`,texte:`Filtre à l'entrée (sable, algues), purge des gaines en début de saison, vidange avant l'hiver. Eau de pluie : filtre fin indispensable.`}],video:`dimensionner goutte à goutte potager tensiomètre`,liens:[`arrosage-bien-arroser`,`recuperateur-pluie`,`jardin-sec`]}),c({id:`tunnel-pilotage`,titre:`Piloter un tunnel : aération, ombrage, forçage, cultures d'hiver`,rubrique:`serre`,emoji:`🏕️`,resume:`Gérer la température et l'humidité d'un tunnel au fil des saisons, forcer les cultures de printemps sous voile, ombrer l'été, et produire des légumes d'hiver.`,alias:[`tunnel`,`piloter serre`,`aeration serre`,`ombriere`,`voile de forcage`,`forcage`,`cultures d hiver`,`serre en hiver`,`temperature serre`],etapes:[{titre:`Les températures repères`,texte:`Ouvrez dès que le tunnel dépasse 25 °C (les tomates avortent leurs fleurs au-delà de 32 °C), fermez en fin d'après-midi pour garder la chaleur la nuit. Un thermomètre mini-maxi est indispensable. L'humidité stagnante (buée le matin) favorise mildiou et botrytis : aérez même par temps froid, en milieu de journée.`},{titre:`Le printemps : forcer`,texte:`Dès février, voile de forçage (P17) posé directement sur les cultures à l'intérieur du tunnel : 2 à 4 °C de plus la nuit. Salades, radis, navets, épinards, puis plantations de tomates dès mi-avril sous double protection. Retirez le voile en journée quand il fait doux.`},{titre:`L'été : ombrer`,texte:`Filet d'ombrage (30 à 40 %) ou peinture blanche spéciale (blanc de Meudon) sur la bâche de juin à août, tunnel ouvert aux deux extrémités jour et nuit. Paillez épais et arrosez au goutte-à-goutte le matin.`},{titre:`L'automne et l'hiver : produire encore`,texte:`Après les tomates (septembre-octobre), plantez mâche, épinards, salades d'hiver, oignons blancs, radis d'hiver, persil : ils poussent lentement mais se récoltent tout l'hiver. Le tunnel protège du vent et du gel modéré (-5 °C), pas des grands froids sans voile.`},{titre:`La rotation sous abri`,texte:`Le tunnel tente de cultiver des tomates chaque année au même endroit : alternez tomates, concombres-melons et légumes-feuilles, apportez du compost chaque année, et faites un engrais vert dès qu'une planche se libère.`}],video:`piloter un tunnel maraîcher aération ombrage`,liens:[`serre`,`chassis`,`gel-grele`]}),c({id:`apres-recolte`,titre:`Après la récolte : laver, refroidir, conserver, conditionner`,rubrique:`recolte`,emoji:`📦`,resume:`Ce qui se joue dans les heures qui suivent la récolte : refroidir vite, laver ou non, les bonnes conditions de conservation de chaque légume, et le conditionnement pour donner ou vendre.`,alias:[`apres recolte`,`post recolte`,`chambre froide`,`conservation des legumes`,`lavage legumes`,`conditionnement`,`cave`,`silo`,`stockage legumes`],etapes:[{titre:`Récolter au bon moment`,texte:`Le matin pour les légumes-feuilles et les racines (pleins d'eau, frais), l'après-midi pour les légumes qu'on stocke (oignons, courges, pommes de terre secs). Mettez tout de suite à l'ombre dans des caisses, jamais au soleil.`},{titre:`Refroidir vite`,texte:`Salades, épinards, herbes, radis perdent l'essentiel de leur fraîcheur en quelques heures de chaleur : bain d'eau froide 10 minutes, égouttage, puis au frais. Une vieille armoire réfrigérante ou un frigo dédié à 4 °C fait une chambre froide familiale.`},{titre:`Les trois familles de conservation`,texte:`Froid et humide (0-4 °C, 90-95 % d'humidité) : carottes, betteraves, navets, céleri, poireaux, choux, salades (en sable humide ou en bac à légumes). Frais et sec (10-15 °C, 60-70 %) : courges, patates douces. Frais, sec et à l'obscurité (4-10 °C) : pommes de terre, oignons, ail, échalotes (séchés et tressés).`},{titre:`Laver ou pas`,texte:`On ne lave pas ce qu'on stocke (carottes, pommes de terre : brossées à sec, la terre les protège). On lave ce qui se consomme dans la semaine. L'eau de lavage doit être potable si vous donnez ou vendez.`},{titre:`Conditionner`,texte:`Bottes de radis, de carottes nouvelles et d'herbes liées au raphia ou à l'élastique, salades en caisses, tomates en cagettes en une seule couche, fruits fragiles en barquettes. Caisses propres, réservées aux légumes, et une étiquette (date, variété) si vous donnez ou vendez.`}],video:`conservation légumes après récolte chambre froide cave`,liens:[`conserver-recoltes`,`vendre-surplus`]}),c({id:`plantes-de-service`,titre:`Plantes de service : bandes fleuries, insectaires, plantes pièges`,rubrique:`fleurs`,emoji:`🌼`,resume:`Organiser les fleurs et plantes compagnes au service du potager : où les placer, lesquelles semer, et pour quel ravageur.`,alias:[`plantes de service`,`bande fleurie`,`insectaire`,`plante piege`,`plantes compagnes`,`auxiliaires potager`,`fleurs au potager`],etapes:[{titre:`Une bande fleurie tous les 20 à 30 mètres`,texte:`En bout ou au milieu de chaque série de planches, une bande de 1 m semée de fleurs simples (phacélie, bleuet, souci, coriandre et aneth en fleurs, sarrasin, mélilot, achillée) attire syrphes, chrysopes et guêpes parasites qui mangent pucerons et chenilles. Fleurs simples et étalées dans le temps : les auxiliaires ont besoin de pollen d'avril à octobre.`},{titre:`Les plantes pièges`,texte:`Capucine en bord de planche pour attirer les pucerons noirs loin des fèves et des choux ; moutarde ou radis fourrager pour les altises ; tournesol pour les punaises. On arrache ou on taille la plante piège quand elle est couverte.`},{titre:`Les insectaires vivants`,texte:`Haie champêtre, tas de pierres, mare, bande d'herbes hautes non fauchées l'hiver : carabes, araignées, crapauds et oiseaux y passent l'hiver et sortent au printemps pour chasser dans le potager.`},{titre:`Dans la planche`,texte:`Quelques pieds d'œillet d'Inde, de souci ou de bourrache intercalés tous les 2 à 3 mètres dans les planches de légumes-fruits ; basilic et persil laissés fleurir en fin de saison.`},{titre:`Mesurer l'effet`,texte:`Observez une colonie de pucerons au printemps : si des larves de coccinelles ou de syrphes s'y installent dans les 2 semaines, votre système fonctionne. N'utilisez aucun insecticide (même bio) qui casserait cet équilibre.`}],video:`bande fleurie potager auxiliaires maraîchage`,liens:[`jardin-pollinisateurs`,`hotel-insectes`,`associations`]}),c({id:`vendre-surplus`,titre:`Vendre son surplus de légumes, d'œufs ou de miel : ce que dit la loi`,rubrique:`securite`,emoji:`🧾`,niveau:1,resume:`Donner est libre, vendre ne l'est pas : statut, déclarations, registre des traitements, traçabilité, étiquetage, hygiène, AMAP et marchés.`,alias:[`vendre legumes`,`vendre son surplus`,`vendre ses oeufs`,`vendre son miel`,`cotisant solidaire`,`msa`,`siret`,`amap`,`marche`,`registre phytosanitaire`,`tracabilite`,`cahier de culture`,`etiquetage`,`micro ferme`,`maraicher`],etapes:[{titre:`Donner, troquer, vendre`,texte:`Donner ou troquer ses légumes est libre. Les vendre, même un peu et même à des voisins, est une activité agricole qui doit être déclarée : sinon, c'est du travail dissimulé, et votre assurance ne vous couvre pas.`},{titre:`Le statut`,texte:`Pour une petite activité : cotisant solidaire auprès de la MSA (selon la surface cultivée et le temps de travail, avec des seuils fixés par département), immatriculation (numéro SIRET) auprès du guichet des formalités des entreprises. Au-delà, exploitant agricole. Le point accueil installation de la chambre d'agriculture vous oriente gratuitement.`},{titre:`Le registre des traitements`,texte:`Dès que vous vendez, tout traitement (même autorisé en bio : soufre, cuivre, Bt, savon) doit être noté dans un registre : date, planche, culture, produit, dose. Les produits professionnels demandent le certificat individuel (Certiphyto). Le cahier de la planche de Racines (Plan de culture → Mes planches) en est une base exportable.`},{titre:`Traçabilité et étiquetage`,texte:`Pouvoir dire d'où vient chaque lot (planche, date de récolte) ; sur les étals, le nom du produit, l'origine (votre commune), le prix au kilo ou à la pièce, et la catégorie pour certains légumes. Œufs : vente directe au consommateur possible sans marquage pour un très petit élevage, mais pas de vente à des commerces sans centre d'emballage agréé. Miel : étiquette avec le nom, l'adresse, le poids, la date de durabilité et l'origine France.`},{titre:`Le mot « bio »`,texte:`Interdit sans certification par un organisme agréé, même si vos pratiques sont irréprochables. Parlez de « cultivé sans traitement chimique » seulement si c'est vrai.`},{titre:`Où vendre`,texte:`Vente à la ferme (panneau, distributeur), AMAP (un groupe de consommateurs s'engage à l'avance pour une saison : idéal pour planifier avec l'onglet « Produire en continu »), marchés de producteurs (demande d'emplacement en mairie), restaurants et épiceries de proximité. Hygiène : caisses propres, eau potable pour laver, chaîne du froid pour les produits fragiles.`}],video:`vendre ses légumes statut cotisant solidaire MSA`,liens:[`jardiner-bio`,`apres-recolte`,`traiter-loi`]})],u=e=>({niveau:2,duree:`Lecture : 6 minutes`,...e}),d=[`abeille`],f=[u({id:`api-calendrier`,titre:`L'année de l'apiculteur, mois par mois`,rubrique:`animaux`,emoji:`📅`,resume:`Ce qu'il faut faire au rucher chaque mois : visites, hausses, récolte, lutte contre le varroa, nourrissement, hivernage, déclaration.`,alias:[`calendrier apicole`,`annee apicole`,`travaux rucher`,`quand visiter ruche`,`visite de printemps`,`rucher mois par mois`],etapes:[{titre:`Janvier - février`,texte:`Ne pas ouvrir. Soupeser les ruches (famine), candi si elles sont légères. Traitement d'hiver à l'acide oxalique hors couvain (décembre-janvier). Préparer le matériel, fondre et gaufrer la cire, commander les cadres.`},{titre:`Mars - avril : visite de printemps`,texte:`Par une journée à plus de 15 °C, sans vent : vérifier la reine (œufs), le couvain (en plaque, sans trous), les réserves, l'état sanitaire (loques). Retirer 2 à 3 vieux cadres sombres, poser un cadre à mâles. Réunir les colonies trop faibles. Premier comptage du varroa.`},{titre:`Avril - juin : essaimage et miellées`,texte:`Visites tous les 7 à 10 jours : cellules royales ? Agrandir à temps (hausse quand 7 à 8 cadres sont occupés), faire des divisions. Miellées de colza, d'acacia, de fruitiers puis de ronce, tilleul, châtaignier selon les régions. Récolte de printemps.`},{titre:`Juillet - août : récolte et traitement d'été`,texte:`Dernière récolte, puis traitement contre le varroa SANS ATTENDRE (c'est la période qui décide de la survie à l'hiver). Réduire les entrées contre le pillage et le frelon asiatique (muselières), point d'eau.`},{titre:`Septembre - octobre : mise en hivernage`,texte:`Vérifier les réserves (15 à 20 kg), nourrir au sirop épais si besoin avant mi-octobre, réunir les colonies faibles, réducteur d'entrée et grille anti-souris, ruches bien calées et légèrement inclinées vers l'avant. Comptage varroa de contrôle.`},{titre:`Novembre - décembre`,texte:`Laisser les colonies en paix. Déclaration annuelle des ruches (1er septembre - 31 décembre). Bilan de l'année dans le carnet du rucher.`}],video:`calendrier apicole mois par mois débutant`,liens:d}),u({id:`api-visite`,titre:`Faire une visite de ruche et lire les cadres`,rubrique:`animaux`,emoji:`🔍`,resume:`Préparer, ouvrir, lire chaque cadre (œufs, couvain, réserves, cellules royales) et noter l'essentiel en 10 minutes.`,alias:[`visite ruche`,`ouvrir une ruche`,`lire les cadres`,`reine vue`,`oeufs`,`cellules royales`,`enfumoir`],etapes:[{titre:`Préparer`,texte:`Temps doux (plus de 15 °C), sans vent, en milieu de journée quand les butineuses sont dehors. Tenue, gants fins, enfumoir allumé avec un combustible naturel (aiguilles de pin, carton brut), lève-cadre, brosse, carnet du rucher.`},{titre:`Ouvrir`,texte:`Deux ou trois bouffées de fumée froide à l'entrée, attendre une minute, soulever le couvre-cadres, une bouffée légère. Gestes lents, jamais au-dessus du trou de vol.`},{titre:`Lire les cadres`,texte:`Œufs (petits bâtonnets au fond des cellules) = reine présente il y a moins de 3 jours. Couvain en plaque compacte = bonne reine ; couvain en mosaïque = problème (loque, reine épuisée). Couronne de miel et de pollen autour du couvain. Cellules royales en bas des cadres = essaimage en préparation ; au milieu d'un cadre = remplacement de la reine.`},{titre:`Refermer et noter`,texte:`Remettre les cadres dans le même ordre et le même sens. Noter dans le carnet de Racines : reine ou œufs vus, nombre de cadres de couvain, de miel, de pollen, humeur, cellules royales, intervention.`}],video:`visite de ruche lire un cadre débutant`,liens:[`abeille`,`api-essaimage`]}),u({id:`api-essaimage`,titre:`Essaimage : le prévenir, récupérer un essaim, faire un essaim artificiel`,rubrique:`animaux`,emoji:`🐝`,resume:`Reconnaître les signes de l'essaimage, le limiter, cueillir un essaim posé, et multiplier ses colonies par division.`,alias:[`essaimage`,`essaim`,`recuperer un essaim`,`cueillir un essaim`,`essaim artificiel`,`division de ruche`,`diviser une ruche`,`multiplier ses ruches`],etapes:[{titre:`Les signes`,texte:`Colonie très populeuse, cadres pleins, cellules royales operculées en bas des cadres, abeilles en barbe devant la ruche en mai-juin.`},{titre:`Prévenir`,texte:`Donner de la place à temps (hausse, cadres à bâtir), renouveler les reines tous les 2 ans, retirer les cellules royales (cela ne suffit pas seul), faire une division.`},{titre:`Faire un essaim artificiel (division)`,texte:`Méthode simple : dans une ruchette, 2 cadres de couvain avec œufs et abeilles, 2 cadres de réserves, 1 cadre à bâtir, sans la reine ; secouer en plus les abeilles de 2 cadres. Fermer 48 heures puis installer à plus de 3 km, ou sur place en déplaçant la souche. La ruchette élève une reine à partir des œufs : vérifier la ponte 4 semaines plus tard.`},{titre:`Cueillir un essaim posé`,texte:`Un essaim est doux (les abeilles sont gorgées de miel). Placez une caisse ou une ruchette sous la grappe, secouez la branche d'un coup sec, posez la caisse au sol entrouverte : si la reine est dedans, les abeilles y entrent en « battant le rappel ». Installez la ruche le soir à son emplacement définitif. Traitez l'essaim contre le varroa dans la semaine (pas de couvain : très efficace).`},{titre:`Les essaims chez les voisins`,texte:`Un essaim n'appartient à personne tant que l'apiculteur ne l'a pas suivi ; de nombreuses mairies et syndicats tiennent une liste de « cueilleurs d'essaims » : inscrivez-vous.`}],video:`faire un essaim artificiel division ruche`,liens:[`abeille`,`api-reines`]}),u({id:`api-reines`,titre:`Les reines : marquer, remplacer, élever, gérer l'orphelinage`,rubrique:`animaux`,emoji:`👑`,resume:`Couleurs de marquage par année, introduire une reine, élevage simple à partir d'œufs, colonie orpheline et ouvrières pondeuses, réunir deux colonies.`,alias:[`reine`,`marquer la reine`,`couleur reine`,`elever des reines`,`elevage de reines`,`introduire une reine`,`remerage`,`reunir deux colonies`,`papier journal`],etapes:[{titre:`Marquer la reine`,texte:`Une pastille ou un point de peinture sur le thorax, couleur selon l'année de naissance (dernier chiffre) : 1 ou 6 blanc, 2 ou 7 jaune, 3 ou 8 rouge, 4 ou 9 vert, 5 ou 0 bleu. Une reine marquée se retrouve en quelques secondes et on connaît son âge.`},{titre:`Remplacer une reine`,texte:`Une reine de plus de 2 à 3 ans pond moins et favorise l'essaimage. Introduisez une reine fécondée dans sa cagette, bouchée de candi, après avoir retiré l'ancienne : les ouvrières la libèrent en 2 à 3 jours et l'acceptent.`},{titre:`Élever des reines simplement`,texte:`Dans une ruchette orpheline, donnez un cadre portant des œufs d'une colonie douce et productive : les abeilles élèvent plusieurs cellules royales. Vous pouvez découper les cellules en surplus pour créer d'autres ruchettes. Pour aller plus loin : greffage des larves (formation en rucher-école).`},{titre:`Colonie orpheline`,texte:`Plus d'œufs ni de jeune couvain, colonie bruyante : vérifiez deux fois à 8 jours, puis donnez un cadre d'œufs ou une reine. Des ouvrières pondeuses (plusieurs œufs par cellule) n'accepteront plus de reine : réunissez la colonie.`},{titre:`Réunir deux colonies`,texte:`Méthode du papier journal : placez la colonie faible au-dessus de la forte, séparées par une feuille de journal percée de quelques trous ; en 2 à 3 jours, elles la rongent et s'habituent à l'odeur l'une de l'autre. Retirez l'une des deux reines si les deux sont présentes.`}],video:`marquer la reine couleur année élevage reines simple`,liens:[`abeille`,`orpheline`]}),u({id:`api-varroa`,titre:`Plan de lutte contre le varroa`,rubrique:`animaux`,emoji:`🦠`,resume:`Mesurer, traiter au bon moment avec des médicaments autorisés, alterner les molécules, et tenir le registre : la condition de survie des colonies.`,alias:[`plan de lutte varroa`,`traitement varroa`,`comptage varroa`,`lavage sucre glace`,`chute naturelle`,`acide oxalique`,`apivar`,`amitraze`,`thymol`,`acide formique`,`rupture de ponte`],etapes:[{titre:`Mesurer`,texte:`Chute naturelle : plateau grillagé + lange graissé, comptez les varroas tombés en 3 jours et divisez par 3. Lavage au sucre glace : 300 abeilles (une demi-tasse) prélevées sur un cadre de couvain, dans un pot à couvercle grillagé avec une cuillère de sucre glace, secouez 2 minutes, comptez les varroas tombés ; divisez par 3 pour obtenir le pourcentage. Notez chaque comptage dans le carnet du rucher.`},{titre:`Les seuils`,texte:`Printemps : plus de 1 à 2 % ou plus de 3 varroas tombés par jour, agissez par des méthodes douces (cadre à mâles, division). Été : plus de 3 % ou plus de 10 par jour en juillet, traitez immédiatement après la récolte. Après le traitement : moins de 1 %.`},{titre:`Les médicaments`,texte:`Utilisez uniquement des médicaments vétérinaires autorisés pour l'abeille, achetés en pharmacie, chez un vétérinaire ou via le programme sanitaire de votre GDSA : par exemple amitraze en lanières (Apivar), thymol (Apiguard, Thymovar), acide formique (MAQS, Formicpro) et acide oxalique (Api-Bioxal, Oxybee). Respectez la notice : température, durée, retrait des lanières, pas de hausse pendant le traitement. Cette liste est donnée à titre d'exemple et peut changer : vérifiez qu'un médicament est autorisé dans l'index officiel des médicaments vétérinaires (Agence nationale du médicament vétérinaire, ANSES), auprès de votre vétérinaire ou de votre GDSA.`},{titre:`Le calendrier`,texte:`Traitement d'été juste après la dernière récolte (fin juillet - août) ; traitement d'hiver à l'acide oxalique hors couvain (décembre-janvier). Les essaims et les divisions sans couvain se traitent dès leur installation.`},{titre:`Alterner et compléter`,texte:`Alternez les familles de molécules d'une année à l'autre (résistance à l'amitraze dans certaines régions). Méthodes biotechniques : retrait du couvain de mâles, rupture de ponte par encagement de la reine 24 jours, puis acide oxalique.`},{titre:`Le registre`,texte:`Chaque traitement est noté : date de pose et de retrait, produit, numéro de lot, ruches traitées, et l'ordonnance ou la facture conservée 5 ans. Le carnet du rucher de Racines l'enregistre et l'exporte.`}],video:`plan de lutte varroa comptage sucre glace traitement`,liens:[`varroa`,`abeille`]}),u({id:`api-nourrissement`,titre:`Nourrir les abeilles et préparer l'hivernage`,rubrique:`animaux`,emoji:`🍯`,resume:`Quand et comment nourrir (sirop léger, sirop lourd, candi), éviter le pillage, et mettre les colonies en hiver avec assez de réserves.`,alias:[`nourrir les abeilles`,`nourrissement`,`sirop`,`sirop 50/50`,`sirop 2/1`,`candi`,`hivernage`,`hivernage ruche`,`pillage`,`reserves hiver`],etapes:[{titre:`Ce qu'il faut à l'hiver`,texte:`Une colonie hiverne sur 15 à 20 kg de miel (une ruche Dadant pèse alors environ 35 à 40 kg avec le bois). Soupesez à l'arrière : si elle se soulève facilement en septembre, il faut nourrir.`},{titre:`Le sirop d'automne (lourd)`,texte:`2 kg de sucre blanc pour 1 L d'eau chaude (sirop 2/1), en septembre - début octobre, par 5 à 10 L dans un nourrisseur couvre-cadres : les abeilles le stockent comme réserve. Jamais de sucre roux, de miel d'origine inconnue (loques) ni de confiture.`},{titre:`Le sirop de printemps (léger)`,texte:`1 kg de sucre pour 1 L d'eau (sirop 50/50), en petites quantités (0,5 à 1 L), seulement si une colonie manque de réserves ou pour stimuler une division : il imite une miellée et relance la ponte.`},{titre:`Le candi en hiver`,texte:`Pâte de sucre posée directement au-dessus de la grappe (sur les têtes de cadres), de décembre à février, si la ruche est légère. On ne donne pas de sirop par le froid : les abeilles ne peuvent pas l'évaporer.`},{titre:`Éviter le pillage`,texte:`Nourrissez le soir, toutes les ruches en même temps, sans renverser de sirop, entrées réduites. Une colonie pillée peut mourir en quelques jours et propager des maladies.`},{titre:`La ruche en hiver`,texte:`Réducteur d'entrée et grille anti-souris, toit lesté, ruche surélevée de 30 à 50 cm et légèrement inclinée vers l'avant (l'eau de condensation s'écoule), à l'abri des vents dominants. Pas d'ouverture avant le printemps.`}],video:`nourrir abeilles sirop candi hivernage`,liens:[`abeille`,`famine`]}),u({id:`api-materiel`,titre:`Choisir sa ruche et son matériel`,rubrique:`animaux`,emoji:`🧰`,niveau:1,resume:`Dadant, Langstroth, Warré, kényane, ruchettes : avantages et inconvénients, et le matériel indispensable pour débuter.`,alias:[`dadant`,`langstroth`,`warre`,`ruche warre`,`ruche kenyane`,`ruchette`,`nuclei`,`materiel apicole`,`grille a reine`,`plateau grillage`,`trappe a pollen`,`combinaison apiculteur`],etapes:[{titre:`Dadant 10 cadres`,texte:`La plus répandue en France : matériel et essaims faciles à trouver, grand corps qui laisse la colonie se développer, hausses légères. Le bon choix pour débuter et pour échanger du matériel avec d'autres apiculteurs.`},{titre:`Langstroth`,texte:`Corps et hausses de même taille (tout est interchangeable), courante dans le monde : pratique pour élever ou multiplier, un peu moins répandue en France.`},{titre:`Warré et kényane`,texte:`Ruches « douces » où les abeilles bâtissent leurs rayons librement : moins d'interventions, mais visites et lutte contre le varroa plus délicates, récolte plus faible et cire non réutilisable. Pour apiculteurs expérimentés ou qui privilégient l'observation.`},{titre:`Ruchettes et nucléi`,texte:`Ruchettes de 5 ou 6 cadres pour les divisions, les essaims et l'hivernage des petites colonies ; nucléi miniatures pour la fécondation des reines.`},{titre:`Le matériel de base`,texte:`Combinaison ou vareuse avec voile, gants, enfumoir, lève-cadre, brosse, plateau grillagé (aération et comptage du varroa), grille à reine (garde la reine hors des hausses), chasse-abeilles (récolte), nourrisseur, réducteur d'entrée, cadres et cire gaufrée. Trappe à pollen si vous voulez récolter du pollen.`}],video:`choisir ruche dadant langstroth warré débutant`,liens:d}),u({id:`api-produits`,titre:`Les produits de la ruche : miel, cire, propolis, pollen`,rubrique:`animaux`,emoji:`🍯`,resume:`Un miel qui se conserve et cristallise bien, recycler la cire, récolter propolis et pollen, et la mention de l'origine florale.`,alias:[`miel qui cristallise`,`cristallisation`,`miel creme`,`humidite du miel`,`maturateur`,`fondre la cire`,`cerificateur`,`cire`,`propolis`,`pollen`,`gelee royale`,`origine florale`],etapes:[{titre:`Un miel bien mûr`,texte:`Ne récoltez que des cadres operculés aux trois quarts : le miel doit contenir au plus 18 % d'eau (vérifiable au réfractomètre), sinon il fermente. Après extraction : filtration, quelques jours en maturateur pour faire remonter l'écume, puis mise en pots propres et secs.`},{titre:`La cristallisation`,texte:`Tous les miels cristallisent un jour (colza en quelques jours, acacia en plusieurs mois) : c'est naturel et ce n'est pas du sucre ajouté. Pour un miel crémeux : ensemencez 10 % de miel déjà cristallisé finement et brassez chaque jour quelques minutes jusqu'à ce qu'il blanchisse. Pour le refondre : bain-marie à moins de 40 °C.`},{titre:`La cire`,texte:`Fondez les vieux cadres et les opercules au cérificateur solaire (une caisse vitrée, gratuite à faire soi-même) ou à la vapeur, filtrez, coulez en pains. Renouvelez environ un tiers des cadres du corps chaque année (3 à 4 sur une Dadant 10 cadres), en retirant les plus sombres au printemps : moins de maladies et de résidus. Les pains s'échangent contre de la cire gaufrée chez les fournisseurs.`},{titre:`La propolis`,texte:`Grattez-la sur les cadres et le couvre-cadres, ou posez une grille à propolis en été ; congelez-la, puis broyez-la. Teinture : macérée dans de l'alcool alimentaire à 70°.`},{titre:`Le pollen`,texte:`Trappe à pollen posée quelques jours au printemps sur les colonies fortes seulement, récolte chaque jour, séchage doux (moins de 40 °C) ou congélation. Gelée royale : production spécialisée, réservée aux apiculteurs formés.`},{titre:`L'étiquette`,texte:`Nom et adresse, poids, date de durabilité minimale, pays d'origine (France). La mention d'une origine florale (« miel de lavande ») suppose que cette plante domine réellement (analyse pollinique conseillée) ; sinon, écrivez « miel de printemps » ou « toutes fleurs ».`}],video:`miel crémeux cristallisation cérificateur solaire`,liens:[`recolte-miel`,`vendre-surplus`]}),u({id:`api-miellees`,titre:`Les miellées, l'emplacement du rucher et la transhumance`,rubrique:`animaux`,emoji:`🌸`,resume:`Les grandes floraisons qui font le miel, le choix d'un emplacement, et les règles pour déplacer ses ruches.`,alias:[`miellee`,`miellees`,`transhumance`,`emplacement rucher`,`ou installer une ruche`,`acacia`,`chataignier`,`tilleul`,`lavande miel`,`colza`,`lierre abeilles`],etapes:[{titre:`Les grandes miellées`,texte:`Mars-avril : saules, fruitiers, pissenlit, colza. Mai : acacia (robinier), aubépine. Juin-juillet : ronce, tilleul, châtaignier, trèfle, tournesol, lavande dans le Sud. Septembre-octobre : lierre, indispensable pour les réserves d'hiver. Un « trou de miellée » en été demande parfois de nourrir.`},{titre:`Choisir l'emplacement`,texte:`Ensoleillé le matin, abrité des vents dominants, sans humidité stagnante, avec une source de nectar et de pollen dans un rayon de 1,5 à 3 km, un point d'eau proche (abreuvoir avec des cailloux ou de la mousse pour qu'elles ne se noient pas), et accessible en voiture. Respectez les distances fixées par arrêté préfectoral ou municipal.`},{titre:`Au jardin`,texte:`Plantez des mellifères étalées dans l'année, laissez fleurir le lierre et les fleurs sauvages, ne traitez jamais pendant la floraison, et placez l'entrée de la ruche face à une haie ou un filet pour que les abeilles volent haut au-dessus des passages.`},{titre:`La transhumance`,texte:`Déplacer des ruches vers une miellée (lavande, châtaignier, montagne) : fermeture la veille au soir, transport de nuit, entrées grillagées et aération, installation avant l'aube. Toute ruche doit être déclarée avec son emplacement ; déclarez aussi le changement d'emplacement et prévenez le propriétaire du terrain.`}],video:`miellées emplacement rucher transhumance`,liens:[`jardin-pollinisateurs`,`abeille`]}),u({id:`api-securite`,titre:`Piqûres, allergies et voisinage`,rubrique:`securite`,emoji:`🚑`,niveau:1,resume:`Que faire après une piqûre, reconnaître une allergie grave, et éviter les conflits avec les voisins et les passants.`,alias:[`piqure d abeille`,`piqure abeille`,`allergie abeilles`,`choc anaphylactique`,`adrenaline`,`abeilles agressives`,`voisins abeilles`],etapes:[{titre:`Après une piqûre`,texte:`Retirez le dard en le grattant avec l'ongle ou une carte (sans pincer la poche à venin), éloignez-vous de la ruche (l'odeur du venin attire d'autres abeilles), rafraîchissez la peau. Un gonflement local, même important, est une réaction normale.`},{titre:`L'allergie grave : urgence`,texte:`Urticaire sur tout le corps, gonflement du visage ou de la gorge, difficulté à respirer, malaise, vomissements dans l'heure qui suit : appelez le 15 ou le 112. Si vous avez de l'adrénaline auto-injectable, utilisez-la. Une personne qui a fait une réaction générale doit voir un allergologue avant de reprendre l'apiculture (une désensibilisation existe).`},{titre:`Se protéger`,texte:`Tenue complète, gants, visites par beau temps, enfumoir. Ne visitez jamais seul une colonie agressive ; changez sa reine (douceur héréditaire). Prévenez vos proches de ce qu'il faut faire en cas de malaise, et gardez un téléphone sur vous au rucher.`},{titre:`Les voisins`,texte:`Respectez les distances réglementaires, une haie ou une palissade de 2 m devant les ruches, un point d'eau au rucher (sinon les abeilles vont boire à la piscine des voisins), pas de visite par temps orageux. Offrir un pot de miel apaise beaucoup de tensions.`}],video:`piqûre abeille allergie que faire`,liens:[`abeille`,`voisinage-regles`]}),u({id:`api-reseau`,titre:`Le réseau sanitaire et la formation de l'apiculteur`,rubrique:`animaux`,emoji:`🤝`,niveau:1,resume:`GDSA, techniciens sanitaires, vétérinaires, ruchers-écoles, déclarations : les interlocuteurs à connaître avant d'en avoir besoin.`,alias:[`gdsa`,`osad`,`technicien sanitaire apicole`,`tsa`,`rucher ecole`,`formation apiculture`,`programme sanitaire d elevage`,`pse`,`declaration maladie abeilles`,`ddpp`],etapes:[{titre:`Le GDSA`,texte:`Le groupement de défense sanitaire apicole de votre département : programme sanitaire d'élevage (accès aux médicaments contre le varroa à prix groupé), conseils, comptages collectifs, alertes. L'adhésion est peu coûteuse et très utile.`},{titre:`Techniciens et vétérinaires`,texte:`Les techniciens sanitaires apicoles (TSA) et les vétérinaires formés en apiculture font les visites sanitaires, les prélèvements et prescrivent les traitements.`},{titre:`Les ruchers-écoles`,texte:`Tenus par les syndicats apicoles : formation pratique sur une saison, prêt de matériel (extracteur), entraide pour les essaims. Le meilleur départ, même après des années, pour l'élevage de reines ou les nouvelles méthodes.`},{titre:`Ce qu'il faut déclarer`,texte:`Toutes les ruches chaque année (1er septembre - 31 décembre, en ligne) avec leurs emplacements ; la loque américaine et les dangers réglementés (Aethina tumida, Tropilaelaps) à la DDPP ; les mortalités massives (intoxication). Tenez un registre d'élevage : visites, traitements, mouvements de colonies.`}],video:`GDSA rucher école apiculteur débutant`,liens:[`abeille`,`api-varroa`]})],p=e=>({niveau:2,duree:`Lecture : 6 minutes`,rubrique:`recolte`,...e}),m=[p({id:`cs-securite`,titre:`Conserves maison : les règles de sécurité`,rubrique:`securite`,emoji:`⚠️`,niveau:1,resume:`Acide ou peu acide, pasteuriser ou stériliser, l'huile et l'ail, les bocaux à jeter, les personnes fragiles, les signes du botulisme : ce qu'il faut savoir avant le premier bocal.`,alias:[`securite conserves`,`botulisme`,`conserve dangereuse`,`acidite conserve`,`ph conserve`,`bocal bombe`,`couvercle bombe`,`conserve qui petille`,`ail dans l huile`,`conserves a l huile`,`huile parfumee`,`conserves pour bebe`,`pasteuriser ou steriliser`,`acidifier tomates`,`jus de citron conserve`],etapes:[{titre:`La règle qui décide de tout : acide ou peu acide`,texte:`Ce qui compte, c'est l'acidité (le pH). En dessous de pH 4,6, la bactérie du botulisme ne peut pas produire sa toxine : fruits, confitures, compotes, cornichons au vinaigre, choucroute fermentée. Au-dessus, ce sont les conserves PEU ACIDES : haricots, petits pois, asperges, champignons, carottes, betteraves, maïs, plats cuisinés, viandes, poissons. Elles demandent une stérilisation longue, idéalement sous pression (autoclave), ou bien la congélation.`},{titre:`Les tomates : toujours acidifier`,texte:`Les tomates sont à la limite (pH 4,2 à 4,9 selon les variétés et la maturité). Ajoutez dans chaque bocal 2 cuillères à soupe de jus de citron en bouteille (son acidité est régulière) ou ½ cuillère à café d'acide citrique par litre, avant de stériliser. Le goût ne change presque pas ; un peu de sucre l'équilibre si besoin.`,attention:`Un coulis contenant oignons, poivrons, ail ou viande devient peu acide : il se stérilise comme un plat cuisiné (ou se congèle).`},{titre:`Pasteuriser ou stériliser`,texte:`Pasteuriser, c'est chauffer à 70-90 °C : cela suffit pour les produits acides (jus, sirops, pickles au vinaigre, confitures allégées). Stériliser, c'est maintenir 100 °C (bocaux couverts d'eau bouillante) pendant un temps précis, ou 115-121 °C à l'autocuiseur-stérilisateur sous pression. Le temps se compte à partir du moment où l'eau bout, et s'allonge en altitude.`},{titre:`L'huile et l'ail : le piège`,texte:`L'huile coupe l'air, ce qui est justement le milieu préféré du botulisme. Ail, herbes fraîches, tomates séchées, légumes grillés ou champignons recouverts d'huile se gardent AU RÉFRIGÉRATEUR, 4 jours au plus, ou au congélateur. Pour les garder plus longtemps, il faut d'abord les acidifier (macération 24 h dans du vinaigre) ou les stériliser. Les huiles parfumées se font avec des herbes parfaitement sèches.`,attention:`Jamais de bocal d'ail ou de légumes à l'huile laissé à température ambiante.`},{titre:`Les bocaux à jeter sans goûter`,texte:`Couvercle bombé ou qui ne tient plus, joint décollé, liquide trouble ou qui mousse, bulles qui remontent, odeur anormale, jet à l'ouverture, moisissure. Jetez le contenu sans y goûter ni le donner aux animaux, enveloppé dans un sac fermé ; lavez à l'eau javellisée ce qui a été en contact. Le botulisme ne se voit ni ne se sent toujours : dans le doute, on jette.`},{titre:`Les signes du botulisme`,texte:`De quelques heures à quelques jours après le repas : vision double ou floue, paupières qui tombent, bouche très sèche, difficulté à avaler ou à parler, faiblesse qui descend des épaules vers les jambes, parfois gêne respiratoire. Appelez immédiatement le 15 (ou le 112) et gardez le bocal suspect pour l'analyse.`},{titre:`Les personnes fragiles`,texte:`Pas de miel ni de sirop maison au miel avant 1 an (botulisme infantile). Pour les petits pots de bébé, préférez la congélation en portions à la conserve maison de légumes. Femmes enceintes, personnes âgées ou immunodéprimées : évitez les produits au lait cru fermentés maison et les conserves douteuses, préférez les bocaux bien stérilisés ou réchauffés à ébullition.`},{titre:`Réchauffer par prudence`,texte:`Pour les conserves peu acides faites à 100 °C, faites bouillir le contenu 10 minutes avant de le manger : cela détruit la toxine si elle était présente (mais pas les spores). C'est une sécurité supplémentaire, pas une excuse pour un bocal douteux.`}],conseils:[`Notez sur chaque bocal le produit, la date, la méthode et le temps : en cas de doute, vous saurez lesquels écarter.`,`Ne modifiez pas une recette sûre (moins de vinaigre, moins de sucre, plus de légumes peu acides) sans en changer la méthode.`],video:`conserves maison sécurité botulisme acidité`,liens:[`bocaux`,`cs-temps`,`cs-plats-bocaux`]}),p({id:`cs-temps`,titre:`Temps de blanchiment, de pasteurisation et de stérilisation`,emoji:`⏱️`,niveau:1,duree:`Tableau à garder`,resume:`Combien de temps blanchir avant de congeler, pasteuriser un jus, stériliser un bocal de 0,5 ou 1 litre, et comment corriger en altitude.`,alias:[`combien de temps steriliser`,`temps de sterilisation`,`temps de pasteurisation`,`temps de blanchiment`,`blanchir`,`blanchiment`,`sterilisation bocaux temps`,`steriliser haricots`,`steriliser tomates`,`steriliser en altitude`,`autoclave`,`stérilisateur`],etapes:[{titre:`Le tableau complet`,texte:`Le tableau détaillé produit par produit (bocaux de 0,5 L et de 1 L) est dans la page Conserver, onglet « Temps ». Les repères ci-dessous résument les grandes familles.`},{titre:`Blanchir avant de congeler`,texte:`Eau bouillante abondante (4 L par 500 g), chronomètre dès la reprise de l'ébullition, puis bain d'eau glacée le même temps. Petits pois 2 min, épinards et blettes 2 min, haricots verts 3 min, brocoli et chou-fleur en bouquets 3 min, carottes en rondelles 2 min, choux de Bruxelles 4 min, asperges 3 min, maïs en épis 7 à 10 min. Pas de blanchiment : poivrons, oignons, herbes, tomates, petits fruits, courgettes râpées pour la cuisson.`},{titre:`Pasteuriser (produits acides)`,texte:`Jus de fruits et sirops : chauffés à 85 °C, mis en bouteilles chaudes, puis 20 minutes au bain à 85 °C. Pickles au vinaigre : 10 min (0,5 L) à 15 min (1 L) dans l'eau frémissante. Confitures allégées (moins de 50 % de sucre) : 10 à 15 min à l'eau bouillante.`},{titre:`Stériliser à 100 °C (bocaux couverts d'eau)`,texte:`Compotes et fruits au sirop : 20 à 30 min. Coulis de tomates acidifié : 35 min (0,5 L), 40 min (1 L). Tomates entières acidifiées : 1 h 10 (0,5 L), 1 h 25 (1 L). Légumes peu acides (haricots verts, petits pois, carottes) : 1 h 30 à 2 h selon la tradition française, avec stockage au frais et réchauffage 10 minutes à ébullition avant de manger.`,attention:`Pour les légumes peu acides, les plats cuisinés et les viandes, les autorités sanitaires de nombreux pays ne reconnaissent que la stérilisation sous pression (115-121 °C). À défaut d'autoclave, congelez.`},{titre:`Corriger en altitude`,texte:`L'eau bout plus bas en montagne (environ 97 °C à 1 000 m). Ajoutez 5 minutes de 300 à 900 m et 10 minutes de 900 à 1 800 m pour les produits acides ; au-delà de 900 m, les conserves peu acides se font sous pression ou se congèlent.`},{titre:`Bien compter`,texte:`Bocaux posés sur une grille, jamais en contact avec le fond, couverts d'au moins 2 à 3 cm d'eau. Le temps démarre à la reprise de l'ébullition. Les bocaux remplis chauds vont dans une eau chaude, les bocaux froids dans une eau froide (sinon ils éclatent).`}],video:`temps de stérilisation bocaux tableau`,liens:[`cs-securite`,`bocaux`,`cs-congelation`]}),p({id:`cs-confitures`,titre:`Confitures et gelées qui se gardent`,emoji:`🍓`,duree:`1 à 2 heures`,resume:`Proportion de sucre, pectine, test de l'assiette froide, mise en pots sûre, confitures allégées et gelées de coing ou de groseille.`,alias:[`confiture`,`confitures`,`gelee`,`gelee de groseille`,`gelee de coing`,`pectine`,`confiture allegee`,`confiture sans sucre`,`confiture moisit`,`retourner les pots`,`test de l assiette`,`marmelade`],materiel:[`Bassine large (cuivre ou inox), cuillère en bois`,`Pots propres ébouillantés, couvercles à capsule neufs`,`Thermomètre de cuisson (facultatif), assiette au congélateur`,`Citron, sucre cristallisé ou sucre spécial confiture`],etapes:[{titre:`La proportion`,texte:`Une confiture se garde grâce au sucre : au moins 60 % du poids final. Repère classique : 700 g à 1 kg de sucre par kg de fruits préparés. En dessous de 50 %, la confiture est « allégée » : elle doit être pasteurisée en pots (10 à 15 min à l'eau bouillante) et gardée au frais après ouverture.`},{titre:`La prise`,texte:`Les fruits riches en pectine prennent seuls : coing, pomme, groseille, cassis, agrumes, prune. Les fruits pauvres (fraise, cerise, pêche, poire, rhubarbe, figue) prennent mieux avec un jus de citron, quelques pépins ou trognons de pomme dans une gaze, ou un sucre à pectine.`},{titre:`Macérer et cuire`,texte:`Faites macérer les fruits coupés avec le sucre une nuit (ils rendent leur jus et gardent leur forme). Portez à ébullition franche, écumez, et cuisez vite : 5 à 15 minutes à gros bouillons pour les fruits fermes, plus pour les fruits juteux. Une cuisson courte garde la couleur et le goût.`},{titre:`Le test de la prise`,texte:`Déposez une goutte sur une assiette sortie du congélateur : si elle se fige et se ride quand on la pousse du doigt, c'est prêt. Au thermomètre : 104-105 °C (au niveau de la mer).`},{titre:`Mettre en pots`,texte:`Remplissez les pots ébouillantés jusqu'à 0,5 cm du bord avec la confiture bouillante, essuyez le bord, fermez aussitôt avec une capsule neuve. Le vide se fait en refroidissant (la capsule s'enfonce).`,attention:`Retourner les pots ne remplace pas une fermeture correcte et peut décoller le joint : ce n'est plus recommandé. Pas de paraffine (elle laisse passer les moisissures).`},{titre:`Les gelées`,texte:`Cuisez les fruits (groseilles, coings en morceaux, mûres) avec un peu d'eau, laissez égoutter le jus dans un torchon sans presser (pour une gelée limpide), pesez-le, ajoutez le même poids de sucre, cuisez jusqu'à la prise (5 à 10 min) et mettez en pots.`},{titre:`Conserver`,texte:`Au sec, au frais, à l'abri de la lumière : 1 an et plus. Une moisissure en surface : jetez le pot entier (ses filaments et toxines descendent dans la confiture).`}],erreurs:[`Diminuer le sucre sans pasteuriser les pots.`,`Cuire trop longtemps : confiture brune et caramélisée.`,`Réutiliser des capsules déjà serties.`],video:`confiture maison bien prise test assiette`,liens:[`fraisier`,`groseillier`,`cognassier`,`prunier`,`cs-fruits-sucre`]}),p({id:`cs-fruits-sucre`,titre:`Fruits au sirop, compotes, pâtes de fruits, fruits confits, sirops de fleurs`,emoji:`🍑`,duree:`1 à 3 heures`,resume:`Toutes les façons de garder les fruits avec du sucre, de la compote sans sucre ajouté aux sirops de fleurs de sureau.`,alias:[`fruits au sirop`,`compote`,`compote en bocaux`,`pate de fruits`,`pate de coing`,`fruits confits`,`sirop de sureau`,`sirop de fleurs`,`sirop de menthe`,`sirop maison`,`cotignac`,`poires au sirop`,`peches au sirop`,`cerises au sirop`],etapes:[{titre:`Fruits au sirop`,texte:`Fruits sains, à peine mûrs, pelés ou non, dénoyautés ou non. Sirop léger (200 g de sucre par litre d'eau) à moyen (350 g/L), versé chaud sur les fruits tassés, 2 cm de vide en haut. Stérilisez 20 min (0,5 L) à 30 min (1 L) à 100 °C. Abricots, pêches, poires, cerises, prunes, mirabelles.`},{titre:`Compotes`,texte:`Pommes, poires, coings, rhubarbe cuits avec très peu d'eau, sucrés ou non (les fruits sont acides, le sucre n'est pas nécessaire à la conservation). Versez bouillante en bocaux et stérilisez 20 min (0,5 L) à 25 min (1 L).`},{titre:`Pâtes de fruits`,texte:`Purée de coings, pommes ou abricots cuite avec son poids de sucre en remuant sans arrêt jusqu'à ce qu'elle se détache des parois (105-107 °C), coulée sur 1,5 cm dans un plat chemisé, séchée 2 à 4 jours à l'air, coupée et roulée dans le sucre. Se garde des mois dans une boîte en fer.`},{titre:`Fruits confits`,texte:`Écorces d'agrumes, cerises, angélique, petits fruits entiers : on les fait passer pendant plusieurs jours dans un sirop de plus en plus concentré (on recuit le sirop chaque jour), jusqu'à ce que le sucre ait remplacé l'eau. Égoutter et sécher.`},{titre:`Sirops de fleurs et de fruits`,texte:`Fleurs de sureau (ombelles bien ouvertes, sans les tiges), menthe, mélisse, ou jus de fruits rouges : faites infuser 24 à 48 h au frais dans de l'eau avec un citron en rondelles, filtrez, ajoutez 1 à 1,3 kg de sucre par litre, portez à 85 °C, mettez en bouteilles chaudes et pasteurisez 20 min à 85 °C. Au frais après ouverture.`,attention:`Sureau : uniquement les fleurs et les baies mûres et cuites du sureau noir ; jamais le sureau yèble (baies toxiques), ni les feuilles et les tiges.`}],video:`fruits au sirop bocaux stérilisation`,liens:[`sureau`,`cognassier`,`pecher`,`cs-confitures`,`cs-temps`]}),p({id:`cs-vinaigre`,titre:`Pickles au vinaigre, chutneys et vinaigre maison`,emoji:`🥒`,duree:`1 heure + attente`,resume:`Cornichons, oignons, betteraves, légumes en pickles ; chutneys et ketchups ; et faire son vinaigre avec une mère de vinaigre.`,alias:[`pickles`,`pickles au vinaigre`,`cornichons au vinaigre`,`chutney`,`chutneys`,`ketchup maison`,`vinaigre maison`,`mere de vinaigre`,`vinaigre de cidre maison`,`conserve au vinaigre`,`oignons au vinaigre`,`pickles rapides`],etapes:[{titre:`La proportion qui protège`,texte:`Le vinaigre doit titrer au moins 5 à 6 % d'acidité (vinaigre d'alcool, de cidre ou de vin du commerce). La saumure d'un pickle ne doit jamais contenir plus d'eau que de vinaigre : au minimum moitié vinaigre, moitié eau. Ne diminuez pas le vinaigre d'une recette.`},{titre:`Cornichons et petits légumes`,texte:`Cornichons brossés, dégorgés une nuit au gros sel, rincés et essuyés ; tassés en bocaux avec estragon, petits oignons, graines de moutarde, poivre. Couvrez de vinaigre bouillant (ou froid pour des cornichons plus croquants, qui se garderont alors au frais). Attendre 3 à 4 semaines. Pour une garde longue hors du frais : pasteurisez 10 min (0,5 L).`},{titre:`Pickles rapides`,texte:`Oignons rouges, radis, carottes, concombre émincés, recouverts d'un mélange chaud vinaigre-eau-sucre-sel (1-1-½ cuillère-1 cuillère) : prêts en 1 heure, se gardent 3 semaines au réfrigérateur.`},{titre:`Chutneys`,texte:`Fruits et légumes (pommes, tomates vertes, courgettes, rhubarbe, figues, mangue) cuits longuement avec vinaigre, sucre, oignon, épices et raisins secs jusqu'à une texture de confiture épaisse. Mise en pots bouillante, capsules neuves, pasteurisation 10 min pour les garder 1 an. Idéal pour écouler les surplus de fin de saison.`},{titre:`Faire son vinaigre`,texte:`Vin, cidre ou jus de fruits fermenté laissé dans un récipient large couvert d'un tissu, à 20-28 °C, avec une « mère de vinaigre » (le voile gélatineux d'un vinaigre non pasteurisé) : 4 à 8 semaines. Le vinaigre maison a une acidité inconnue et souvent plus faible : utilisez-le en cuisine, pas pour les conserves.`}],video:`cornichons au vinaigre maison bocaux`,liens:[`concombre`,`betterave`,`oignon`,`cs-securite`,`lactofermentation`]}),p({id:`cs-jus-cidre`,titre:`Jus, nectars, cidre et poiré`,emoji:`🍎`,duree:`Une journée de pressage`,resume:`Broyer, presser, pasteuriser un jus de pomme ou de raisin qui se garde un an, et faire un cidre fermier simple.`,alias:[`jus de pomme`,`jus de pomme maison`,`pressoir`,`presser les pommes`,`broyeur a pommes`,`pasteuriser du jus`,`jus de raisin`,`nectar`,`cidre`,`cidre maison`,`poire maison`,`jus de fruits maison`,`extracteur de jus`],etapes:[{titre:`Préparer les fruits`,texte:`Pommes et poires mûres, saines (on écarte les fruits pourris, qui gâtent le goût et peuvent contenir une toxine, la patuline), lavées. Mélanger des variétés douces, acidulées et un peu amères donne un jus équilibré.`},{titre:`Broyer et presser`,texte:`Broyez finement (broyeur à pommes ou robot), pressez au pressoir en couches dans des toiles. Rendement : environ 6 à 7 litres de jus pour 10 kg de pommes. Beaucoup d'associations et de mairies prêtent un pressoir ou organisent des journées de pressage.`},{titre:`Pasteuriser le jus`,texte:`Laissez décanter quelques heures, chauffez à 75-80 °C (pas plus, le goût cuit apparaît), versez en bouteilles chaudes et propres, capsulez, puis maintenez 20 à 30 minutes à 75-80 °C au bain. Se garde 1 an au frais et à l'abri de la lumière. Ouvert : quelques jours au réfrigérateur.`},{titre:`Le cidre fermier`,texte:`Jus frais non pasteurisé mis en fût ou en dame-jeanne propre avec un barboteur, au frais (10-15 °C) : il fermente seul en 4 à 8 semaines. Mise en bouteilles épaisses (type champagne) quand la densité a baissé (vers 1,010 à 1,015 au densimètre) pour un cidre doux et pétillant ; trop tôt, les bouteilles peuvent éclater.`,attention:`Bouteilles adaptées à la pression uniquement ; stockez-les couchées dans un carton fermé les premières semaines.`},{titre:`Jus de raisin, de petits fruits`,texte:`Raisins égrappés, fruits rouges : chauffés doucement pour libérer le jus, filtrés, sucrés ou non, puis pasteurisés comme le jus de pomme. On peut aussi utiliser un extracteur à vapeur, qui donne un jus déjà chaud prêt à embouteiller.`}],video:`pressage jus de pomme pasteurisation bouteilles`,liens:[`pommier`,`poirier`,`vigne`,`cs-atelier-collectif`]}),p({id:`cs-alcool`,titre:`Fruits à l'eau-de-vie, liqueurs et ratafias`,emoji:`🍒`,niveau:1,duree:`15 minutes + 2 mois`,resume:`Garder des fruits dans l'alcool, faire une liqueur de cassis ou un vin de noix, et ce qu'il faut savoir sur la distillation, qui est réglementée.`,alias:[`fruits a l eau de vie`,`cerises a l eau de vie`,`liqueur maison`,`creme de cassis`,`ratafia`,`vin de noix`,`limoncello`,`eau de vie`,`alambic`,`distiller`,`bouilleur de cru`,`prunes a l eau de vie`],etapes:[{titre:`Fruits à l'eau-de-vie`,texte:`Cerises (queues coupées à moitié), prunes, mirabelles, framboises, raisins : fruits sains, piqués d'une aiguille, en bocaux avec 150 à 250 g de sucre par litre, couverts d'eau-de-vie de fruits ou d'alcool pour fruits à 40-45 % vol. Attendre 2 à 3 mois. Les fruits doivent toujours rester sous l'alcool.`},{titre:`Liqueurs et crèmes`,texte:`Fruits ou feuilles macérés 1 à 2 mois dans l'alcool (cassis, framboise, feuilles de cassis, noix vertes, citron), filtrés, puis mélangés à un sirop de sucre : on obtient une liqueur à 18-25 % vol. Le vin de noix se fait avec des noix vertes cueillies fin juin, macérées dans du vin rouge, de l'alcool et du sucre.`},{titre:`La distillation est réglementée`,texte:`Distiller ses fruits n'est pas libre : il faut avoir le statut de bouilleur de cru (déclaré aux douanes), passer par un distillateur ambulant ou un atelier public de distillation, et déclarer les quantités. Posséder un alambic doit aussi être déclaré. Renseignez-vous auprès du service des douanes de votre département avant toute distillation.`},{titre:`Avec modération`,texte:`Ces préparations restent de l'alcool : jamais pour les enfants ni les femmes enceintes, étiquetez-les clairement et rangez-les hors de portée.`}],video:`cerises à l'eau de vie maison`,liens:[`cerisier`,`groseillier`,`noyer`]}),p({id:`cs-sel-huile-fumage`,titre:`Sel, huile et fumage : les méthodes anciennes`,emoji:`🧂`,niveau:1,duree:`30 minutes + attente`,resume:`Sel aux herbes, haricots au sel, légumes confits à l'huile sans danger, ail et piments fumés.`,alias:[`sel aux herbes`,`sel de guerande aux herbes`,`haricots au sel`,`legumes au sel`,`conserver au sel`,`saumure`,`confits a l huile`,`legumes a l huile`,`tomates sechees a l huile`,`fumer`,`fumage`,`fumoir`,`ail fume`,`piment fume`,`paprika fume`,`conserve a l huile`],etapes:[{titre:`Sel aux herbes`,texte:`Hachez finement un mélange de légumes et d'herbes (céleri branche, poireau, carotte, persil, livèche, ciboulette, aneth) et mélangez avec 1 volume de gros sel pour 4 volumes de légumes. Tassez en bocaux, gardez au frais : il parfume soupes et sauces tout l'hiver (pensez à ne pas resaler).`},{titre:`Haricots au sel`,texte:`Méthode traditionnelle : haricots verts blanchis 3 minutes, refroidis, puis rangés en couches dans un grand pot en grès avec 1 kg de gros sel pour 3 à 4 kg de haricots, tassés sous un poids. Ils se dessalent 12 h dans plusieurs eaux avant la cuisson.`},{titre:`Confits à l'huile sans danger`,texte:`Légumes grillés, tomates séchées, artichauts : faites-les d'abord mariner 24 h dans du vinaigre (ou blanchir 3 min dans un mélange moitié eau moitié vinaigre), égouttez, puis couvrez d'huile. Ils se gardent alors 2 à 4 semaines au réfrigérateur. Sans cette étape acide : réfrigérateur et 4 jours au plus, ou congélation.`,attention:`Ail, herbes fraîches et champignons dans l'huile à température ambiante : risque de botulisme. Jamais.`},{titre:`Le fumage`,texte:`Fumage à chaud (60-90 °C, quelques heures) pour cuire et parfumer, fumage à froid (moins de 30 °C, plusieurs jours) pour sécher et conserver. Au jardin : ail, piments, poivrons (paprika fumé), sel, tomates séchées. Bois sec non traité de feuillus (hêtre, chêne, arbres fruitiers), jamais de résineux ni de bois peint. Un fumoir se bricole avec un vieux meuble métallique ou un fût et un conduit éloigné du foyer.`},{titre:`Conserver après fumage`,texte:`Le fumage seul ne conserve pas longtemps les légumes : séchez-les ensuite complètement (piments, ail) ou congelez-les.`}],video:`sel aux herbes maison bocal`,liens:[`cs-securite`,`cs-sechage`,`ail`,`poivron`]}),p({id:`cs-sechage`,titre:`Le séchage, de A à Z`,emoji:`☀️`,duree:`1 à 3 jours`,resume:`Préparer, sécher au soleil, au four ou au déshydrateur, savoir quand c'est assez sec, stocker sans mites et réhydrater.`,alias:[`sechage`,`secher`,`deshydrater`,`deshydrateur`,`sechoir solaire`,`secher des tomates`,`tomates sechees`,`pommes sechees`,`chips de pommes`,`pruneaux`,`secher des champignons`,`secher des herbes`,`tisanes`,`mites alimentaires`,`rehydrater`,`fruits secs maison`],etapes:[{titre:`Préparer`,texte:`Fruits et légumes mûrs et sains, coupés en tranches régulières de 5 mm (elles sèchent toutes en même temps). Pommes et poires dans de l'eau citronnée pour qu'elles ne noircissent pas. Les légumes (haricots, carottes, choux) se blanchissent 2-3 min avant séchage pour garder leur couleur et se conserver mieux.`},{titre:`Choisir sa méthode`,texte:`Déshydrateur électrique (le plus régulier, 50-60 °C) ; four à 50 °C porte entrouverte avec une cuillère en bois (gourmand en énergie) ; séchoir solaire (une caisse noire vitrée avec entrées d'air et claies, à fabriquer avec des matériaux de récup) ; air libre à l'ombre pour les herbes, les piments et les haricots secs ; soleil direct seulement dans le Midi, sous une moustiquaire.`},{titre:`Savoir quand c'est sec`,texte:`Fruits : souples et cuirassés, aucune goutte quand on les plie ou les coupe (comme un raisin sec). Légumes et champignons : cassants. Herbes : feuilles qui s'effritent. Test du bocal : enfermez la récolte refroidie 1 semaine dans un bocal ; si de la buée apparaît, remettez-la à sécher.`},{titre:`Stocker`,texte:`En bocaux hermétiques, au sec, au frais et à l'obscurité : 6 mois à 1 an. Contre les mites alimentaires (petits papillons, toiles dans les bocaux), passez la récolte 3 jours au congélateur avant de la ranger et n'utilisez que des bocaux bien fermés. Noix, noisettes et châtaignes se sèchent en couche mince et aérée : une moisissure les rend dangereuses (jetez-les).`},{titre:`Réhydrater et utiliser`,texte:`Tomates séchées : 15 minutes dans l'eau chaude, puis à l'huile (au réfrigérateur) ou directement dans les plats. Champignons : 20 minutes dans l'eau tiède, gardez l'eau pour la sauce. Pommes : en chips ou dans les compotes et gâteaux. Légumes secs en poudre : bases de soupe.`},{titre:`Ce qui sèche bien`,texte:`Tomates (variétés charnues), pommes, poires, prunes, abricots, figues, raisins, champignons, piments, haricots en grains, pois, maïs, herbes aromatiques et plantes à tisane (menthe, verveine, mélisse, tilleul), fleurs comestibles, graines.`}],video:`séchoir solaire fait maison fruits`,liens:[`tomate`,`pommier`,`prunier`,`cs-sel-huile-fumage`,`graines-maison`]}),p({id:`cs-congelation`,titre:`Congeler ses récoltes : la méthode complète`,emoji:`❄️`,niveau:1,duree:`Variable`,resume:`Blanchir, congeler à plat, emballer sans air, combien de temps garder chaque produit, décongeler, et que faire en cas de panne.`,alias:[`congeler`,`congelation`,`congeler les haricots`,`congeler les tomates`,`congeler les courgettes`,`congeler les fruits`,`congeler les herbes`,`duree congelation`,`combien de temps au congelateur`,`recongeler`,`decongeler`,`panne de congelateur`,`brulure de congelation`,`pesto congele`],etapes:[{titre:`Ce qui se congèle bien`,texte:`Haricots, petits pois, fèves, épinards, blettes, choux, brocolis, poivrons, maïs, petits fruits, cerises dénoyautées, prunes, rhubarbe, herbes hachées, purées, soupes, coulis, pesto. Mal : salades, concombre cru, radis, pommes de terre crues, tomates crues pour la salade (elles deviennent molles, mais restent parfaites pour la cuisson).`},{titre:`Préparer`,texte:`Légumes : blanchis (voir les temps), refroidis dans l'eau glacée, bien égouttés et séchés dans un torchon. Fruits : lavés, séchés, étalés sur un plateau 2 heures au congélateur avant d'être mis en sachets : ils restent séparés. Herbes : hachées dans des bacs à glaçons avec un peu d'eau ou d'huile.`},{titre:`Emballer`,texte:`Sachets de congélation, boîtes ou bocaux en verre droit (2 cm de vide pour l'expansion). Chassez l'air au maximum (une paille ou une machine sous vide) : l'air donne des « brûlures » (taches blanches sèches). Congelez à plat en portions familiales, étiquetez avec le produit et la date.`},{titre:`Combien de temps`,texte:`À -18 °C : légumes blanchis et fruits 8 à 12 mois ; herbes 6 mois ; légumes non blanchis 3 à 6 mois ; soupes et plats cuisinés 3 mois ; pesto 6 mois. Au-delà, ce n'est pas dangereux mais le goût et la texture se perdent.`},{titre:`Décongeler`,texte:`Légumes : directement dans l'eau bouillante ou la poêle, sans décongeler. Fruits : au réfrigérateur, ou encore congelés pour les compotes et smoothies. Ne recongelez pas un produit décongelé, sauf s'il a été cuit entre-temps.`},{titre:`Panne ou coupure`,texte:`Gardez la porte fermée : un congélateur plein tient 24 à 48 heures. Des cristaux encore présents : on peut recongeler les fruits et légumes, ou les cuisiner aussitôt. Totalement décongelé depuis plus de 2 heures à température ambiante : cuisinez immédiatement ou jetez (plats cuisinés).`}],video:`congeler légumes du jardin blanchir`,liens:[`cs-temps`,`conserver-recoltes`,`haricot`]}),p({id:`cs-plats-bocaux`,titre:`Plats, soupes et sauces en bocaux`,emoji:`🍲`,niveau:3,duree:`Une demi-journée`,resume:`Ratatouille, soupes, sauces tomate cuisinées : des conserves peu acides qui demandent une vraie méthode, ou la congélation.`,alias:[`ratatouille en bocaux`,`soupe en bocaux`,`plat en bocaux`,`sauce tomate en bocaux`,`conserves de plats`,`conserver la ratatouille`,`puree en bocaux`,`batch cooking conserves`],etapes:[{titre:`Pourquoi c'est délicat`,texte:`Un plat qui mélange légumes peu acides, huile, oignons ou viande est une conserve peu acide, la plus exposée au botulisme. L'épaisseur ralentit aussi la montée en température au centre du bocal : les purées et soupes épaisses chauffent mal.`},{titre:`La solution la plus sûre`,texte:`Congelez les plats cuisinés en portions (3 mois de garde). C'est ce que recommandent les autorités sanitaires quand on n'a pas d'autoclave.`},{titre:`Avec un autoclave (stérilisateur sous pression)`,texte:`Bocaux adaptés, 115-121 °C pendant le temps donné par le fabricant pour chaque plat. Méthode de référence des conserveries et des ateliers associatifs équipés.`},{titre:`À 100 °C, si vous le faites quand même`,texte:`Suivez la tradition française la plus prudente : bocaux de 0,5 L plutôt que 1 L, plat pas trop épais, 2 heures de stérilisation à partir de l'ébullition, stockage au frais (cave), consommation dans les 6 mois et réchauffage 10 minutes à ébullition avant de servir. Une sauce tomate simple (tomates, sel, herbes, sans oignon) acidifiée au citron reste plus sûre.`}],video:`ratatouille en bocaux stérilisation autoclave`,liens:[`cs-securite`,`cs-temps`,`cs-materiel`]}),p({id:`cs-cave`,titre:`La cave et le fruitier : combien de temps se garde chaque récolte`,emoji:`🏚️`,niveau:1,resume:`Les durées de garde au frais par légume et par fruit, les variétés de garde, et la tournée de surveillance qui évite les pertes.`,alias:[`cave`,`cellier`,`fruitier`,`garde des pommes`,`conserver les pommes`,`conserver les courges`,`conserver les pommes de terre`,`pommes de terre qui germent`,`varietes de garde`,`pommes de garde`,`oignons de garde`,`hygrometre cave`,`combien de temps se garde`],etapes:[{titre:`Les conditions`,texte:`Une cave idéale : 2 à 8 °C, 85 à 95 % d'humidité pour les racines, obscurité, aération sans courant d'air. Un thermomètre-hygromètre à quelques euros permet de vérifier. Trop sec : posez un seau d'eau ou arrosez le sol en terre battue ; trop humide : aérez par temps sec.`},{titre:`Durées de garde au frais`,texte:`Pommes de terre 4 à 8 mois ; carottes, betteraves, panais, céleri-rave en sable 4 à 6 mois ; oignons et ail secs 6 à 10 mois ; échalotes 8 à 12 mois ; courges musquées et butternut 6 à 12 mois, potirons 3 à 6 mois ; choux pommés suspendus 2 à 4 mois ; poireaux en jauge 2 à 3 mois ; pommes 1 à 6 mois et poires 1 à 3 mois selon la variété ; noix sèches 1 an.`},{titre:`Choisir des variétés de garde`,texte:`Pommes de garde (reinette, belle de Boskoop, Canada, patte de loup, Melrose), poires d'hiver (Passe-Crassane, Comice tardive), oignons de conservation (jaune paille des Vertus, Stuttgart), ail violet ou rose de printemps, courges musquées (musquée de Provence, butternut, longue de Nice), pommes de terre de garde (Bintje, Désirée, Charlotte moins). La fiche de chaque plante précise ses points forts.`},{titre:`La tournée de la semaine`,texte:`Une fois par semaine : retirez tout fruit ou légume qui pourrit ou germe (un seul suffit à contaminer ses voisins), vérifiez température et humidité, cuisinez en priorité les sujets abîmés. L'appli peut vous le rappeler depuis le garde-manger.`},{titre:`Les incompatibilités`,texte:`Pommes et poires dégagent de l'éthylène qui fait germer les pommes de terre et donne un goût aux choux : éloignez-les. Oignons et pommes de terre ne se rangent pas ensemble (humidité et germination). Pommes de terre à l'obscurité totale (elles verdissent et deviennent toxiques à la lumière).`}],video:`cave à légumes conserver hiver`,liens:[`conserver-recoltes`,`apres-recolte`,`pommier`,`pomme-de-terre`,`courge`]}),p({id:`cs-materiel`,titre:`Le matériel de conserverie : acheter, récupérer, économiser`,rubrique:`fabriquer`,emoji:`🧰`,niveau:1,resume:`Bocaux, stérilisateur, autoclave, déshydrateur, pressoir : ce qui est indispensable, ce qui se récupère, et comment dépenser moins d'énergie.`,alias:[`materiel conserves`,`sterilisateur`,`autoclave`,`autocuiseur sterilisateur`,`deshydrateur`,`presse puree`,`moulin a legumes`,`pressoir`,`bocaux le parfait`,`le parfait`,`familia wiss`,`bocaux de recup`,`capsules`,`joints de bocaux`,`reutiliser les bocaux`,`pots de confiture recuperes`],etapes:[{titre:`L'indispensable`,texte:`Une grande marmite avec une grille au fond (ou un stérilisateur avec thermomètre), des bocaux à joint (type Le Parfait) ou à capsule (type Familia Wiss), un entonnoir à large col, une pince à bocaux, des étiquettes. Un moulin à légumes pour les coulis et compotes.`},{titre:`Ce qui se récupère, et ce qui ne se récupère pas`,texte:`Les bocaux en verre se réutilisent indéfiniment s'ils ne sont ni ébréchés ni fêlés. Les JOINTS en caoutchouc et les CAPSULES (couvercles à visser) sont à usage unique pour les stérilisations : rachetez-les. Les pots de confiture du commerce à couvercle twist-off conviennent aux confitures et pickles avec un couvercle neuf, pas aux longues stérilisations.`},{titre:`Pour aller plus loin`,texte:`Autocuiseur-stérilisateur sous pression (autoclave domestique) pour les légumes peu acides et les plats : un investissement à partager en association. Déshydrateur à plateaux pour le séchage. Pressoir et broyeur pour les jus (souvent prêtés). Machine sous vide pour la congélation. Réfractomètre pour mesurer le sucre des confitures et des sirops.`},{titre:`Économiser l'énergie`,texte:`Remplissez le stérilisateur au maximum à chaque fournée, réutilisez l'eau chaude pour la fournée suivante, préférez le séchoir solaire au four, faites des fournées collectives entre voisins ou en atelier associatif, et ne stérilisez pas ce qui se garde aussi bien en cave ou en terre.`}],video:`matériel conserves stérilisateur bocaux débutant`,liens:[`bocaux`,`cs-temps`,`cs-atelier-collectif`]}),p({id:`cs-atelier-collectif`,titre:`Ateliers collectifs, conserveries partagées et hygiène`,rubrique:`recolte`,emoji:`🤝`,resume:`Organiser un atelier de conserves en association, mutualiser le matériel, tenir un cahier de fabrication et respecter l'hygiène.`,alias:[`atelier conserves`,`atelier collectif`,`conserverie partagee`,`conserverie associative`,`legumerie`,`conserverie mobile`,`journee de pressage`,`association conserves`,`cahier de sterilisation`,`hygiene conserves`,`tracabilite conserves`,`numero de lot`],etapes:[{titre:`Mutualiser`,texte:`Pressoir, broyeur, autoclave, grand stérilisateur, déshydrateur : du matériel coûteux et peu utilisé, idéal à partager. Cherchez près de chez vous les conserveries partagées, légumeries associatives, conserveries mobiles, jardins partagés, centres sociaux et syndicats de jardiniers : beaucoup prêtent du matériel ou proposent des ateliers.`},{titre:`Organiser un atelier`,texte:`Un thème par séance (tomates, compotes, lacto-fermentation), un animateur formé, des postes de travail (lavage, épluchage, cuisson, mise en bocaux, stérilisation, étiquetage), un nombre de participants adapté aux feux disponibles. Chacun repart avec ses bocaux étiquetés à son nom.`},{titre:`L'hygiène de l'atelier`,texte:`Mains lavées et cheveux attachés, plans de travail désinfectés, séparation du sale (terre, épluchures) et du propre, ustensiles réservés, pas d'animaux, aucun participant malade (gastro-entérite). Légumes triés : rien d'abîmé dans les bocaux.`},{titre:`Le cahier de fabrication`,texte:`Pour chaque fournée : date, produit, recette, numéro de lot, nombre et taille des bocaux, heure de début et de fin de stérilisation, température, contrôle de fermeture le lendemain, nom du responsable. Il permet de retrouver tous les bocaux d'une fournée en cas de problème. L'appli génère des numéros de lot et des étiquettes.`},{titre:`Assurance et responsabilité`,texte:`Vérifiez que l'assurance de l'association couvre l'activité, et précisez par écrit que les bocaux sont destinés à la consommation familiale des participants (la vente relève d'autres règles).`}],video:`atelier conserves associatif conserverie partagée`,liens:[`cs-materiel`,`cs-donner-vendre`,`cs-securite`]}),p({id:`cs-donner-vendre`,titre:`Donner ou vendre ses conserves : les règles`,rubrique:`recolte`,emoji:`🏷️`,resume:`Ce qu'on peut offrir librement, ce qu'impose la vente (déclaration, étiquetage, allergènes, dates), et le cas des produits animaux.`,alias:[`vendre ses conserves`,`vendre des confitures`,`vendre des bocaux`,`donner ses conserves`,`etiquetage conserves`,`etiquette confiture`,`allergenes etiquette`,`ddm`,`dluo`,`date de durabilite minimale`,`declaration ddpp`,`marche vente confitures`,`agrement sanitaire`],etapes:[{titre:`Donner`,texte:`Offrir ses bocaux à sa famille, ses voisins ou dans une gratiféria est libre, mais vous restez responsable : étiquette lisible (produit, date, ingrédients), bocaux contrôlés, et prudence avec les conserves peu acides. Ne les donnez pas à des inconnus ni à une collecte alimentaire, qui n'acceptent pas les conserves maison.`},{titre:`Vendre : se déclarer`,texte:`Dès qu'on vend (marché, AMAP, vente directe, même occasionnelle), on devient exploitant du secteur alimentaire : déclaration d'activité auprès de la direction départementale de la protection des populations (DDPP), statut (micro-entreprise ou agricole), respect des bonnes pratiques d'hygiène et formation à l'hygiène alimentaire conseillée. Les conserves contenant des produits animaux (viande, plats) exigent en plus un agrément sanitaire ou une dérogation.`},{titre:`L'étiquette obligatoire`,texte:`Dénomination (« Confiture de fraises »), liste des ingrédients par ordre décroissant, allergènes mis en évidence (fruits à coque, céleri, moutarde, sulfites…), quantité nette, date de durabilité minimale (« À consommer de préférence avant ») ou date limite de consommation pour les produits périssables, conditions de conservation, nom et adresse, numéro de lot. Pour la confiture : quantité de fruits et de sucre pour 100 g.`},{titre:`Prouver la sécurité`,texte:`Pour vendre des conserves peu acides, un barème de stérilisation validé (autoclave, valeur stérilisatrice) et parfois des analyses en laboratoire sont exigés. Les produits acides (confitures, compotes, pickles, jus pasteurisés) sont bien plus simples à commercialiser.`}],video:`vendre ses confitures réglementation étiquetage`,liens:[`vendre-surplus`,`cs-atelier-collectif`]})],h=e=>({niveau:2,duree:`Lecture : 6 minutes`,...e}),g=[h({id:`api-frelon`,titre:`Le frelon asiatique : protéger ses ruches`,rubrique:`animaux`,emoji:`🐝`,resume:`Reconnaître le frelon asiatique, protéger les ruches pendant l'été et l'automne, piéger sans tuer les autres insectes, et faire détruire les nids.`,alias:[`frelon asiatique`,`frelons asiatiques`,`vespa velutina`,`frelon devant la ruche`,`frelons ruche`,`piege a frelons`,`pieger les frelons`,`nid de frelons`,`harpe electrique`,`museliere ruche`,`paralysie de butinage`],etapes:[{titre:`Le reconnaître`,texte:`Plus petit et plus sombre que le frelon européen : thorax noir, une seule bande orange sur l'abdomen, bout des pattes jaune. Il fait du « vol stationnaire » devant la planche d'envol pour attraper les butineuses qui rentrent. Le frelon européen (roux et jaune, plus gros) est protégé dans plusieurs pays et chasse peu les abeilles : ne le confondez pas.`},{titre:`Ce qu'il fait au rucher`,texte:`De juillet à novembre, la pression des frelons empêche les butineuses de sortir : c'est la « paralysie de butinage ». La colonie ne rentre plus ni nectar ni pollen, consomme ses réserves et s'affaiblit avant l'hiver. Une colonie faible peut être envahie et vidée.`},{titre:`Protéger les ruches`,texte:`Réduisez les entrées (muselière grillagée ou réducteur à mailles de 5,5 mm qui laissent passer les abeilles et pas les frelons), gardez des colonies fortes (réunissez les faibles), nourrissez si la paralysie de butinage dure, posez les ruches surélevées à 40-50 cm. Les harpes électriques, posées devant les ruches, tuent les frelons en vol stationnaire sans toucher les abeilles.`},{titre:`Piéger sans massacrer`,texte:`Le piégeage au printemps (fondatrices) et les pièges à bière ou à sirop non sélectifs tuent surtout d'autres insectes, dont des pollinisateurs : leur efficacité est discutée. Si vous piégez, utilisez des pièges sélectifs (cônes et trous de sortie pour les petits insectes), à proximité immédiate des ruchers attaqués, et relevez-les souvent. Suivez les consignes de votre GDSA ou du réseau local de lutte.`},{titre:`Signaler et faire détruire les nids`,texte:`Les nids secondaires, souvent très haut dans les arbres, se repèrent à la chute des feuilles. Signalez-les à votre mairie ou à la plateforme de signalement de votre région : la destruction est faite par des professionnels, de préférence au crépuscule et avant la sortie des futures reines (avant novembre).`,attention:`Ne vous approchez jamais d'un nid et ne tentez pas de le détruire vous-même : les attaques collectives sont dangereuses, surtout pour les personnes allergiques.`}],video:`frelon asiatique protéger ruches muselière harpe`,liens:[`abeille`,`api-securite`,`api-reseau`]}),h({id:`api-miellerie`,titre:`La miellerie : hygiène de l'extraction et traçabilité du miel`,rubrique:`animaux`,emoji:`🍯`,resume:`Une pièce propre pour extraire, du matériel alimentaire, des lots numérotés : les bonnes pratiques pour donner ou vendre son miel en toute sécurité.`,alias:[`miellerie`,`extraction du miel`,`extracteur`,`hygiene du miel`,`vendre son miel`,`lot de miel`,`tracabilite miel`,`maturateur inox`,`pot de miel etiquette`],etapes:[{titre:`La pièce`,texte:`Une pièce fermée aux abeilles et aux animaux, lavable (sol et murs), avec un point d'eau potable, une bonne lumière et une température de 25 à 30 °C (le miel coule mieux). Une cuisine propre convient pour un usage familial ; pour la vente, une pièce dédiée est fortement conseillée.`},{titre:`Le matériel`,texte:`Uniquement du matériel de contact alimentaire : inox ou plastique alimentaire (extracteur, maturateur, filtres, seaux). Pas de récipients galvanisés ni de cuivre. Tout est lavé à l'eau chaude et bien séché avant et après la récolte.`},{titre:`Les gestes`,texte:`Mains propres, tablier, cheveux attachés. Cadres de hausse seulement (jamais de cadres de corps avec du couvain ou des traitements). Désoperculez au-dessus d'un bac, extrayez, filtrez, laissez maturer 3 à 8 jours en maturateur fermé, écumez, mettez en pots propres et secs.`},{titre:`Lots et traçabilité`,texte:`Chaque récolte d'un rucher à une date forme un lot : notez le numéro de lot, la date, les ruches, le poids et l'humidité si vous la mesurez. Le numéro figure sur l'étiquette des pots. En cas de problème (fermentation, résidu), vous retrouvez tous les pots concernés.`},{titre:`Pour vendre`,texte:`Déclaration d'activité auprès des services vétérinaires (DDPP), respect du « paquet hygiène » européen, étiquetage complet (dénomination, poids, date de durabilité minimale, nom et adresse, pays d'origine, numéro de lot). Les produits de la ruche sont des denrées d'origine animale : renseignez-vous avant la première vente.`}],video:`miellerie hygiène extraction miel`,liens:[`recolte-miel`,`api-produits`,`cs-donner-vendre`]}),h({id:`porc-familial`,titre:`Élever un ou deux porcs : biosécurité, soins et règles`,rubrique:`animaux`,emoji:`🐖`,niveau:3,resume:`Ce qu'exige vraiment un porc familial : clôtures contre les sangliers, formation, identification, soins, interdits, castration et abattage.`,alias:[`porc`,`porcs`,`cochon`,`cochons`,`porc familial`,`biosecurite porc`,`peste porcine africaine`,`ppa`,`castration porcelet`,`elever un cochon`,`abattage cochon`,`rouget du porc`],etapes:[{titre:`Se déclarer d'abord`,texte:`Avant l'arrivée du premier porc, même de compagnie : déclaration auprès de l'établissement départemental de l'élevage (EDE) qui attribue un indicatif de marquage, tenue d'un registre d'élevage, identification des animaux (boucle ou tatouage) avant tout déplacement.`},{titre:`La biosécurité`,texte:`La peste porcine africaine circule chez les sangliers en Europe : c'est elle qui justifie les règles. Clôture solide qui empêche tout contact avec les sangliers (double clôture en plein air), aliment et paille stockés à l'abri, tenue et bottes réservées au parc, aucune visite inutile. Selon le type de détention, une formation biosécurité et un plan de biosécurité écrit sont exigés : renseignez-vous auprès de la DDPP ou du GDS de votre département.`,attention:`Jamais de restes de cuisine, de viande ou de charcuterie : c'est interdit et c'est la principale voie d'entrée du virus.`},{titre:`Les soins`,texte:`Vermifuge après coproscopie (analyse des crottes) 1 à 2 fois par an ; vaccination contre le rouget conseillée par beaucoup de vétérinaires en plein air ; surveillance de la gale (démangeaisons, croûtes) ; bauge et ombre l'été (coups de chaleur) ; pieds et onglons vérifiés.`},{titre:`Ce qui est interdit`,texte:`La castration des porcelets mâles sans anesthésie ni antidouleur est interdite : elle se fait par un vétérinaire, ou on choisit des femelles ou des mâles abattus jeunes. La coupe systématique des queues et des dents est interdite. Les porcs vivent au moins à deux (animal social).`},{titre:`L'abattage`,texte:`En abattoir, ou abattage familial à la ferme encadré : animal élevé par la famille, consommation exclusivement familiale, étourdissement obligatoire, respect de l'animal. Renseignez-vous auprès de la DDPP avant toute chose ; beaucoup d'éleveurs familiaux passent par un abattoir de proximité.`}],video:`élever un cochon plein air biosécurité clôture`,liens:[`cochon`,`registre-elevage`,`abattage-volaille`]}),h({id:`produire-ses-plants`,titre:`Produire ses plants : terreau, pépinière, noyaux, marcottes et greffes`,rubrique:`semis`,emoji:`🌱`,niveau:3,duree:`Toute la saison`,resume:`Le terreau de semis maison, une petite pépinière, semer des noyaux et pépins (stratification), marcotter, et greffer tomates et aubergines.`,alias:[`produire ses plants`,`terreau de semis`,`terreau maison`,`pepiniere`,`stratification`,`semer des noyaux`,`semer un noyau`,`semer des pepins`,`marcottage`,`marcotter`,`greffer des tomates`,`greffe tomate`,`porte greffe tomate`,`plants maison`],etapes:[{titre:`Le terreau de semis`,texte:`Fin, léger et pauvre : un tiers de compost bien mûr tamisé, un tiers de sable ou de terre de jardin tamisée, un tiers de fibre de coco ou de terreau de feuilles. Pas d'engrais (il brûle les jeunes racines). Pour limiter la fonte des semis, ébouillantez-le ou passez-le 30 minutes au four à 80 °C.`},{titre:`Une petite pépinière`,texte:`Un coin abrité, mi-ombragé, près d'un point d'eau : on y élève en godets ou en pleine terre les jeunes arbustes, fraisiers, vivaces et boutures pendant 1 ou 2 ans avant de les planter. Paillez, arrosez régulièrement, étiquetez tout (nom, date, origine).`},{titre:`Semer noyaux et pépins (stratification)`,texte:`Les graines d'arbres (noyaux de pêche, d'abricot, pépins de pomme, glands, châtaignes) doivent passer un hiver au froid humide pour germer. Mélangez-les à du sable humide dans un pot, laissez-les dehors ou 2 à 3 mois au réfrigérateur, puis semez au printemps. Un semis de pomme ou de poire ne reproduit pas la variété : il sert de porte-greffe ou donne une variété nouvelle.`},{titre:`Marcotter`,texte:`Courbez une branche basse jusqu'au sol, entaillez-la légèrement en dessous, enterrez cette partie sous 5 à 10 cm de terre en laissant dépasser le bout, maintenez-la avec un crochet. Quelques mois plus tard, elle a des racines : coupez-la de la plante mère. Parfait pour vigne, noisetier, cassissier, jasmin, figuier. Les fraisiers se marcottent tout seuls (stolons).`},{titre:`Greffer tomates et aubergines`,texte:`Sur un porte-greffe vigoureux et résistant aux maladies du sol (vendu en graines), greffez au stade 2 à 3 vraies feuilles, en fente ou à l'anglaise avec une pince à greffe : les plants greffés résistent mieux aux sols fatigués (fusariose, verticilliose) et produisent plus longtemps. Gardez-les 5 à 7 jours à l'ombre et à l'humidité après la greffe.`}],video:`faire ses plants terreau de semis maison stratification`,liens:[`semis-interieur`,`graines-maison`,`bouturage`,`greffe`]}),h({id:`potager-hiver`,titre:`Le potager d'hiver : récolter de novembre à mars`,rubrique:`semis`,emoji:`❄️`,resume:`Ce qu'on sème et plante en été pour l'hiver, comment protéger, et ce qui se récolte quand il gèle.`,alias:[`potager d hiver`,`potager en hiver`,`legumes d hiver`,`que recolter en hiver`,`cultiver en hiver`,`legumes resistants au froid`,`hiver au potager`],etapes:[{titre:`Tout se prépare en été`,texte:`Les légumes d'hiver se sèment ou se plantent de juin à septembre : poireaux d'hiver (plantés en juillet), choux de Milan, de Bruxelles et kale (plantés en juin-juillet), carottes et navets d'automne (semés en juillet), mâche et épinards (août-septembre), oignons blancs et ail (automne), fèves et pois d'hiver dans le Sud.`},{titre:`Ce qui tient au froid`,texte:`Poireau, chou kale, chou de Bruxelles, chou de Milan, mâche, panais, topinambour, salsifis, carotte et betterave sous un paillage épais, épinard, roquette, poirée, cresson de terre, oignon blanc, ail. La plupart supportent -5 à -10 °C, le kale et le poireau davantage.`},{titre:`Protéger`,texte:`Paillage épais (feuilles, paille) sur les racines laissées en terre, voile d'hivernage sur les salades et la mâche lors des fortes gelées, tunnel ou châssis pour avancer les semis de fin d'hiver. Récoltez les légumes-feuilles hors gel (à midi), jamais gelés.`},{titre:`Sous abri`,texte:`En serre froide ou tunnel : laitues d'hiver, mâche, épinards, radis, oignons blancs et mesclun poussent lentement tout l'hiver ; aérez par beau temps pour éviter la pourriture grise.`}],video:`potager d'hiver que planter en été pour récolter en hiver`,liens:[`poireau`,`chou-kale`,`mache`,`gel-grele`,`conserver-recoltes`]}),h({id:`arbo-eclaircissage-gel`,titre:`Arboriculture : éclaircir les fruits et protéger les fleurs du gel`,rubrique:`recolte`,emoji:`🍐`,resume:`Deux gestes d'arboriculteur qui changent la récolte : retirer une partie des jeunes fruits, et sauver la floraison d'une gelée de printemps.`,alias:[`eclaircissage`,`eclaircir les fruits`,`eclaircir les pommes`,`trop de fruits`,`alternance`,`gel des fleurs`,`gelee de printemps`,`proteger floraison gel`,`gelee noire`,`aspersion antigel`],etapes:[{titre:`Pourquoi éclaircir`,texte:`Un arbre trop chargé donne de petits fruits, casse ses branches et ne fleurit presque pas l'année suivante (alternance). En retirant une partie des jeunes fruits, on obtient de plus beaux fruits et une récolte régulière chaque année.`},{titre:`Comment éclaircir`,texte:`Après la chute naturelle de juin, quand les fruits ont la taille d'une noisette : pommes et poires, gardez 1 à 2 fruits par bouquet (le plus beau, souvent celui du centre pour la pomme) ; pêches et abricots, un fruit tous les 10 à 15 cm de rameau ; raisin de table, retirez les grappes en excès et ciselez les grains serrés.`},{titre:`Le danger du gel de printemps`,texte:`Une fleur ouverte gèle vers -2 °C, un jeune fruit dès -1 °C. Les nuits claires et sans vent d'avril sont les plus dangereuses (gelée blanche), surtout en bas de pente où l'air froid s'accumule.`},{titre:`Protéger une floraison`,texte:`Petits arbres et espaliers : voile d'hivernage double posé le soir et retiré le matin. Arrosage du sol la veille (un sol humide restitue plus de chaleur). Variétés à floraison tardive dans les zones gélives. Les arboriculteurs utilisent l'aspersion d'eau toute la nuit : la glace formée protège la fleur à 0 °C, mais cela demande beaucoup d'eau et un arrosage continu.`}],video:`éclaircissage des fruits pommier`,liens:[`pommier`,`pecher`,`taille-fruitiers`,`gel-grele`]}),h({id:`reproduction-selection`,titre:`Reproduction et sélection : éviter la consanguinité`,rubrique:`animaux`,emoji:`🧬`,resume:`Choisir ses reproducteurs, renouveler les mâles, tenir un petit livre généalogique : garder un troupeau ou une basse-cour en bonne santé sur des années.`,alias:[`consanguinite`,`consanguin`,`reproducteurs`,`choisir un reproducteur`,`changer de coq`,`changer de bouc`,`selection animale`,`genealogie`,`livre genealogique`,`croisement`,`race pure`],etapes:[{titre:`Le risque de la consanguinité`,texte:`Reproduire entre frères et sœurs, parents et enfants, fait ressortir les défauts cachés : animaux plus petits, moins de ponte ou de lait, malformations, mortalité des jeunes, fragilité aux maladies. Les effets apparaissent en 2 ou 3 générations.`},{titre:`Renouveler les mâles`,texte:`Changez de coq, de jars, de lapin, de bouc ou de bélier tous les 2 à 3 ans, en le prenant dans un autre élevage, ou échangez vos mâles avec d'autres éleveurs (associations de race, bourses d'échange). Ne gardez jamais pour la reproduction un jeune mâle né chez vous avec ses mères.`},{titre:`Choisir les reproducteurs`,texte:`Gardez les animaux en bonne santé, bien conformés, rustiques, de bon caractère et productifs : poules qui pondent régulièrement et couvent bien, lapines bonnes mères, chèvres faciles à traire et sans mammite, brebis qui agnèlent seules. Écartez les animaux agressifs ou souvent malades.`},{titre:`Tenir un petit registre`,texte:`Pour chaque reproducteur : origine, date de naissance, parents, descendants, qualités et défauts. Dans Racines, l'onglet « Mes animaux un par un » sert de base : notez le père et la mère dans la note de chaque animal.`},{titre:`Races locales`,texte:`Beaucoup de races locales (poules, chèvres, ânes, moutons) sont menacées : les élever et les faire reproduire en lien avec leur association de race aide à les conserver, et donne accès à des reproducteurs non apparentés.`}],video:`éviter la consanguinité poules changer de coq`,liens:[`registre-elevage`,`naissances`,`couvaison`]}),h({id:`paturage-tournant`,titre:`Pâturage tournant et parasites : la base de la santé des herbivores`,rubrique:`animaux`,emoji:`🌾`,resume:`Diviser la prairie en parcs, déplacer les animaux, laisser l'herbe repousser : moins de vers, plus d'herbe, et le bon nombre d'animaux par surface.`,alias:[`paturage tournant`,`rotation des parcs`,`chargement`,`combien d animaux par hectare`,`surpaturage`,`strongles`,`parasites prairie`,`chevres vers`,`moutons vers`,`prairie`,`herbe`],etapes:[{titre:`Pourquoi tourner`,texte:`Les larves de vers (strongles) vivent dans l'herbe rase près des crottes. Des animaux qui restent toujours sur la même parcelle se réinfestent sans arrêt. En les changeant de parc, on casse ce cycle, l'herbe repousse et les animaux mangent mieux.`},{titre:`Organiser`,texte:`Divisez la surface en 4 à 6 parcs (clôture électrique mobile). Les animaux restent 5 à 10 jours par parc, puis changent ; chaque parc se repose 4 à 6 semaines au printemps et en été. Faites pâturer quand l'herbe atteint 10 à 15 cm, sortez les animaux à 5 cm.`},{titre:`Combien d'animaux`,texte:`Repères pour une prairie moyenne : 6 à 10 chèvres ou brebis par hectare, 1 à 2 chevaux par hectare, 2 ânes par hectare (moins si la prairie est pauvre ou sèche). En dessous de ces surfaces, il faut apporter du foin une grande partie de l'année.`},{titre:`Vermifuger juste`,texte:`Vermifuge seulement après une coproscopie (analyse des crottes) ou devant des signes (amaigrissement, diarrhée, muqueuses pâles chez les chèvres et moutons). Vermifuger trop souvent crée des vers résistants. Le pâturage mixte (chevaux puis moutons, ou poules après les moutons) réduit encore les parasites.`},{titre:`Plantes utiles`,texte:`Sainfoin, chicorée, plantain et lotier dans la prairie réduisent naturellement les vers chez les petits ruminants. Évitez les zones humides (douve du foie) et clôturez les mares.`}],video:`pâturage tournant chèvres moutons parasites`,liens:[`chevre`,`mouton`,`ane`,`cheval`,`vers-digestifs`]}),h({id:`taille-rosiers-arbustes`,titre:`Tailler les rosiers et les arbustes à fleurs`,rubrique:`fleurs`,emoji:`🌹`,resume:`Quand et comment tailler selon que l'arbuste fleurit sur le bois de l'année ou sur celui de l'an passé, et la taille des rosiers pas à pas.`,alias:[`taille des rosiers`,`tailler les rosiers`,`tailler un rosier`,`rosier grimpant taille`,`tailler les arbustes`,`tailler un forsythia`,`tailler un lilas`,`tailler un hortensia`,`quand tailler`],etapes:[{titre:`La règle d'or`,texte:`Arbustes à floraison de printemps (forsythia, lilas, groseillier à fleurs, deutzia, seringat) : ils fleurissent sur le bois de l'année passée, on les taille juste APRÈS la floraison. Arbustes à floraison d'été et d'automne (buddleia, lavatère, hibiscus, caryoptéris, hortensia paniculé) : ils fleurissent sur le bois de l'année, on les taille en fin d'hiver (février-mars).`},{titre:`Tailler les rosiers buissons`,texte:`En fin d'hiver, quand les forsythias fleurissent : supprimez le bois mort, malade et les branches qui se croisent, gardez 3 à 5 belles branches bien réparties et raccourcissez-les à 3 à 5 yeux, juste au-dessus d'un œil tourné vers l'extérieur, coupe en biais. Coupez les gourmands qui partent sous le point de greffe.`},{titre:`Rosiers grimpants et anciens`,texte:`Grimpants : on garde les longues branches palissées à l'horizontale (elles fleurissent mieux) et on raccourcit leurs ramifications latérales à 2 à 3 yeux. Rosiers anciens non remontants : légère taille après la floraison seulement.`},{titre:`Pendant la saison`,texte:`Coupez les fleurs fanées au-dessus d'une feuille à 5 folioles pour relancer la floraison des remontants (sauf si vous voulez des cynorhodons pour les oiseaux).`},{titre:`Outils et hygiène`,texte:`Sécateur bien affûté, désinfecté à l'alcool entre deux arbustes malades. Brûlez ou jetez (pas au compost) les bois atteints de maladie.`}],video:`tailler les rosiers en fin d'hiver pas à pas`,liens:[`rosier`,`hortensia`,`lilas`]}),h({id:`transport-animaux`,titre:`Transporter ses animaux : règles et bien-être`,rubrique:`animaux`,emoji:`🚚`,niveau:1,resume:`Déplacer des poules, des chèvres, un âne ou des ruches sans stress et dans les règles : documents, véhicule, durée, chaleur.`,alias:[`transport des animaux`,`transporter des poules`,`transporter une chevre`,`transporter un ane`,`van`,`remorque betaillere`,`document de circulation`,`deplacer des ruches`],etapes:[{titre:`Les documents`,texte:`Ruminants (chèvres, moutons), porcs, chevaux et ânes voyagent identifiés, avec leur document de circulation ou d'identification ; l'entrée et la sortie s'inscrivent au registre d'élevage et sont notifiées à l'EDE ou à l'IFCE selon l'espèce. Pour un transport à but commercial ou sur de longues distances, une autorisation de transporteur et une formation sont exigées.`},{titre:`Le véhicule`,texte:`Caisse ou remorque propre, aérée, sans courant d'air direct, au sol antidérapant (paille), assez haute pour que l'animal se tienne debout. Les volailles voyagent en caisses aérées, jamais dans un coffre fermé au soleil.`},{titre:`Le bien-être`,texte:`Évitez les heures chaudes : en été, voyagez tôt le matin ou le soir. Pas d'animal malade, blessé ou en fin de gestation. Eau avant le départ et à l'arrivée ; pour les trajets longs, pauses avec abreuvement. Une conduite douce évite les chutes.`},{titre:`À l'arrivée`,texte:`Quarantaine de 2 à 3 semaines pour tout nouvel animal (surtout volailles) avant de le mêler au groupe : on évite ainsi d'introduire maladies et parasites.`},{titre:`Les ruches`,texte:`Voir le guide des miellées et de la transhumance : fermeture la veille au soir, transport de nuit, ruches sanglées, entrées grillagées et aérées, déclaration du nouvel emplacement.`}],video:`transporter des chèvres remorque bien-être`,liens:[`registre-elevage`,`api-miellees`,`hygiene-animaux`]})],_=e=>({niveau:1,duree:`Lecture : 5 minutes`,...e}),v=[_({id:`planter-arbre`,titre:`Planter un arbre ou un arbuste`,rubrique:`demarrer`,emoji:`🌳`,duree:`30 minutes à 1 heure`,resume:`Le bon moment, le trou, le pralinage, le tuteur, le premier arrosage et le paillage : les gestes qui font qu'un arbre reprend et vit longtemps.`,alias:[`planter un arbre`,`planter un arbuste`,`plantation arbre`,`trou de plantation`,`tuteurer un arbre`,`tuteur arbre`,`planter une haie`,`arroser un arbre plante`,`arbre qui ne reprend pas`],materiel:[`Bêche ou pelle, fourche`,`Tuteur (piquet de châtaignier) et lien souple`,`Compost mûr (pas de fumier frais)`,`Arrosoir, paillage`],etapes:[{titre:`Le bon moment`,texte:`De novembre à mars, hors gel et hors sol détrempé (« à la Sainte-Catherine, tout bois prend racine »). Les plantes en racines nues se plantent uniquement à cette période ; les plantes en pot (conteneur) toute l'année sauf en été et par gel, mais l'automne reste le meilleur moment.`},{titre:`Le trou`,texte:`Deux à trois fois plus large que les racines ou la motte, et à peine plus profond. Griffez les parois à la fourche (sinon les racines tournent comme dans un pot). Mélangez la terre extraite avec un peu de compost mûr ; pas d'engrais chimique au fond du trou.`},{titre:`Préparer les racines`,texte:`Racines nues : coupez les bouts abîmés et pralinez (trempez-les dans une boue de terre, de compost et d'eau). Motte en pot : trempez-la 15 minutes dans un seau d'eau ; si les racines tournent en rond, démêlez-les ou incisez-les sur la hauteur.`},{titre:`Planter à la bonne hauteur`,texte:`Le collet (départ des racines) au niveau du sol, jamais enterré ; le point de greffe (bourrelet sur le tronc) toujours 5 à 10 cm au-dessus du sol. Plantez le tuteur AVANT l'arbre, du côté des vents dominants, puis rebouchez en tassant au pied.`},{titre:`Arroser et pailler`,texte:`Formez une cuvette autour du pied et versez 10 à 20 litres d'eau même s'il pleut (l'eau colle la terre aux racines). Paillez épais sur 1 m de diamètre. Les deux premiers étés, arrosez abondamment tous les 10 jours par temps sec : c'est la cause n° 1 des échecs.`},{titre:`Attacher et protéger`,texte:`Attachez le tronc au tuteur avec un lien souple en huit, sans serrer, à vérifier chaque année. Protection contre les lapins et chevreuils (manchon grillagé) à la campagne. Le tuteur s'enlève après 2 à 3 ans.`}],erreurs:[`Planter trop profond (le collet pourrit).`,`Ne pas arroser l'été suivant la plantation.`,`Laisser un lien qui étrangle le tronc.`],video:`planter un arbre racines nues pralinage tuteur`,liens:[`haie`,`taille-arbustes-calendrier`,`pommier`]}),_({id:`vivaces-guide`,titre:`Les vivaces : choisir, associer, diviser`,rubrique:`fleurs`,emoji:`🌼`,niveau:2,resume:`Des fleurs qui reviennent chaque année : comment composer un massif qui fleurit de mars à novembre, et multiplier ses vivaces gratuitement par division.`,alias:[`vivaces`,`vivace`,`massif de vivaces`,`vivaces faciles`,`plantes vivaces`,`diviser une vivace`,`division des vivaces`,`diviser les vivaces`,`plate bande`,`mixed border`],etapes:[{titre:`Choisir selon son sol et son exposition`,texte:`Soleil et sol sec : sauges arbustives, pérovskia, gaura, népéta, lavande, achillée. Soleil et sol frais : phlox, échinacée, rudbeckia, asters, hémérocalles. Mi-ombre et ombre : hellébores, hostas, heuchères, géraniums vivaces, anémones du Japon, fougères. La fiche de chaque plante indique son exposition, sa rusticité et son sol.`},{titre:`Composer pour toute l'année`,texte:`Prévoyez des floraisons étalées : hellébores et bulbes (fin d'hiver), géraniums et népéta (printemps), sauges, phlox, échinacées (été), anémones du Japon, asters, graminées (automne). Plantez par groupes de 3, 5 ou 7 d'une même plante, les hautes au fond, et laissez des feuillages persistants pour l'hiver.`},{titre:`Planter`,texte:`Au printemps ou en septembre-octobre (l'automne donne un enracinement plus fort). Espacement : celui indiqué sur la fiche (les vivaces doublent de volume en 2 ans). Paillez entre les plants la première année.`},{titre:`Diviser`,texte:`Tous les 3 à 5 ans, quand le centre de la touffe se dégarnit : soulevez la touffe à la fourche, coupez-la en morceaux à la bêche ou au couteau (chaque éclat garde des racines et des bourgeons), replantez les plus vigoureux de l'extérieur, donnez les autres. Vivaces de printemps : divisez en automne ; vivaces d'été et d'automne : au printemps.`},{titre:`L'entretien de l'année`,texte:`Coupez les fleurs fanées pour prolonger la floraison (sauf si vous voulez les graines pour les oiseaux). Laissez les tiges sèches en hiver : elles abritent les insectes utiles et protègent la souche ; coupez tout en fin d'hiver.`}],video:`massif de vivaces facile diviser les vivaces`,liens:[`hellebore`,`geranium-vivace`,`anemone-japon`,`jardin-ombre`]}),_({id:`jardin-ombre`,titre:`Le jardin d'ombre`,rubrique:`fleurs`,emoji:`🌿`,resume:`Ombre légère, mi-ombre, ombre sèche sous les arbres : les plantes qui y réussissent et comment préparer le sol.`,alias:[`jardin d ombre`,`plantes d ombre`,`plante pour l ombre`,`ombre seche`,`sous un arbre`,`cote nord`,`arbuste pour l ombre`,`fleurs ombre`,`massif ombre`],etapes:[{titre:`Reconnaître son ombre`,texte:`Mi-ombre : soleil le matin ou moins de 4 heures par jour. Ombre légère : sous un arbre au feuillage fin (bouleau). Ombre dense : côté nord d'un mur, sous un conifère. Ombre sèche : au pied des grands arbres, dont les racines boivent toute l'eau : c'est la plus difficile.`},{titre:`Préparer le sol`,texte:`Apportez du compost ou du terreau de feuilles chaque automne, et paillez avec les feuilles mortes : un sol d'ombre riche en humus garde la fraîcheur. Sous les arbres, ne mettez pas plus de 5 cm de terre sur leurs racines.`},{titre:`Les plantes`,texte:`Arbustes : laurier-tin, camélia et rhododendron (sol acide), hortensia, fusain, viorne. Vivaces : hellébores, hostas, heuchères, fougères, géranium macrorrhizum (même en ombre sèche), anémone du Japon, pervenche. Bulbes : jacinthes des bois, perce-neige, cyclamens rustiques. Grimpante : lierre.`},{titre:`Jouer avec la lumière`,texte:`Les feuillages panachés, argentés ou vert tendre éclairent un coin sombre ; les fleurs blanches se voient même au crépuscule.`}],video:`jardin d'ombre plantes faciles`,liens:[`hosta`,`hellebore`,`fougere-jardin`,`laurier-tin`,`vivaces-guide`]}),_({id:`couvre-sols-rocaille`,titre:`Couvre-sols et rocaille`,rubrique:`fleurs`,emoji:`⛰️`,resume:`Des plantes basses qui remplacent la pelouse ou le paillage sur un talus, et un jardin de rocaille pour les plantes des sols secs.`,alias:[`couvre sol`,`couvre-sol`,`plantes couvre sol`,`plantes couvre-sol`,`talus`,`remplacer la pelouse`,`rocaille`,`jardin de rocaille`,`plantes de rocaille`,`muret`],etapes:[{titre:`Pourquoi des couvre-sols`,texte:`Un sol couvert ne se dessèche pas, ne s'érode pas sur un talus et laisse peu de place aux herbes indésirables. Une fois installés (2 ans), ils ne demandent presque plus rien.`},{titre:`Lesquels`,texte:`Soleil : thym serpolet, origan, géranium sanguin, sédums, népéta basse, lierre terrestre. Mi-ombre et ombre : géranium macrorrhizum, pervenche, lamier, épimédium, lierre. Talus : millepertuis, rosiers couvre-sol, cotonéaster rampant.`},{titre:`Les installer`,texte:`Désherbez soigneusement avant, plantez serré (4 à 9 pieds par m² selon la plante), paillez entre eux la première année, arrosez la première saison. Ils couvrent tout en 1 à 3 ans.`},{titre:`La rocaille`,texte:`Un coin très drainé : butte de terre mélangée moitié à du gravier, grosses pierres à moitié enterrées, inclinées vers l'intérieur. On y plante les plantes des montagnes et des sols secs : sédums, joubarbes, thym, œillets nains, aubriète, saxifrages. Pas d'arrosage une fois installées, paillage minéral (gravier).`}],video:`plantes couvre-sol faciles talus`,liens:[`geranium-vivace`,`thym`,`jardin-sec`]}),_({id:`grimpantes-supports`,titre:`Plantes grimpantes : choisir et installer le bon support`,rubrique:`fleurs`,emoji:`🌸`,resume:`Chaque grimpante s'accroche à sa façon : ventouses, vrilles, tiges volubiles. Bien choisir le support, palisser et tailler.`,alias:[`plantes grimpantes`,`grimpante`,`grimpantes`,`treillage`,`pergola`,`palisser`,`couvrir un mur`,`cacher un grillage`,`support grimpante`,`tonnelle`],etapes:[{titre:`Comment elles grimpent`,texte:`Crampons et ventouses (lierre, vigne vierge à ventouses, hortensia grimpant) : s'accrochent seules à un mur. Vrilles et pétioles (clématites, passiflore, pois de senteur, vigne) : il leur faut un grillage ou des fils fins. Tiges qui s'enroulent (glycine, chèvrefeuille, jasmin, haricot) : un support vertical solide. Rosiers grimpants : aucun moyen, il faut les attacher.`},{titre:`Le bon support`,texte:`Mur : fils tendus horizontalement tous les 30 à 40 cm, à 5 cm du mur (l'air circule). Grillage, treillage, arceaux pour les clématites et rosiers. Pergola très solide pour la glycine, qui devient énorme et tord le métal léger.`},{titre:`Planter`,texte:`À 30-40 cm du pied du mur (la terre y est sèche, abritée de la pluie), inclinée vers le support. Clématite : pied à l'ombre (paillage, plante basse devant), tête au soleil, plantée 5 cm plus profond qu'en pot.`},{titre:`Palisser et tailler`,texte:`Attachez les jeunes tiges au fur et à mesure, à l'horizontale le plus possible : elles fleurissent davantage. Taille selon la plante : glycine en été et en hiver, clématites selon leur groupe, vigne vierge et lierre pour dégager fenêtres et toitures.`}],video:`plantes grimpantes support palissage mur`,liens:[`glycine`,`clematite`,`vigne-vierge`,`lierre-jardin`,`passiflore`]}),_({id:`taille-arbustes-calendrier`,titre:`Calendrier de taille des arbustes d'ornement`,rubrique:`fleurs`,emoji:`✂️`,niveau:2,resume:`Mois par mois, quels arbustes tailler et comment : la règle simple selon la période de floraison, et les exceptions.`,alias:[`calendrier de taille`,`quand tailler`,`quand tailler les arbustes`,`taille des arbustes`,`tailler la glycine`,`tailler une clematite`,`tailler les hortensias`,`tailler le buddleia`,`taille ornement`],etapes:[{titre:`Janvier - février`,texte:`Glycine (taille d'hiver : raccourcir à 2-3 yeux les pousses déjà taillées en été). Clématites des groupes 2 et 3 (groupe 3, floraison d'été : à 30 cm du sol ; groupe 2, grandes fleurs : légère taille). Rosiers en fin de période dans le Sud. Arbres caducs (bois mort, branches qui se croisent) hors gel.`},{titre:`Mars`,texte:`Rosiers buissons. Arbustes à floraison d'été et d'automne : buddleia (sévère), abélia, hibiscus de jardin, spirées d'été, caryoptéris, perovskia, sauge arbustive (après les gelées). Hortensias macrophylla : seulement les fleurs sèches. Hortensia paniculé : taille courte. Cornouillers : recépage d'un tiers des tiges. Graminées et vivaces : coupe des tiges sèches.`},{titre:`Avril - mai`,texte:`Juste après leur floraison : forsythia, laurier-tin, groseillier à fleurs, camélia, céanothe (légère), viorne. Premières tailles de haies persistantes à la fin mai, en vérifiant l'absence de nids.`},{titre:`Juin - juillet`,texte:`Après floraison : lilas, weigela, seringat, deutzia, spirées de printemps, rhododendrons (fleurs fanées), clématites du groupe 1 (montana). Haies : taille d'été légère. Glycine : taille d'été en juillet-août (pousses de l'année raccourcies à 5-6 feuilles).`},{titre:`Août - septembre`,texte:`Arbres fruitiers à noyau et cerisiers à fleurs par temps sec (moins de gomme). Deuxième taille des haies persistantes (photinia, fusain, laurier-tin à la fin de l'été). Lavande juste après la floraison, sans couper dans le vieux bois.`},{titre:`Octobre - décembre`,texte:`On taille peu : bois mort, branches cassées, et les arbres caducs une fois les feuilles tombées (érables du Japon, bouleaux uniquement à cette période ou en fin d'été car ils perdent beaucoup de sève au printemps). Les fiches des plantes et le calendrier de Racines indiquent le mois de taille de chaque arbuste.`}],video:`calendrier de taille arbustes d'ornement`,liens:[`taille-rosiers-arbustes`,`glycine`,`clematite`,`hortensia`,`buddleia`]}),_({id:`pelouse-semer`,titre:`Semer ou regarnir une pelouse`,rubrique:`demarrer`,emoji:`🌱`,duree:`Une demi-journée + 3 semaines de levée`,resume:`Préparer le sol, choisir le mélange de graines, semer au bon moment, et réparer les zones dégarnies sans tout refaire.`,alias:[`semer une pelouse`,`semer du gazon`,`regarnir une pelouse`,`regarnir le gazon`,`pelouse degarnie`,`trous dans la pelouse`,`gazon`,`creer une pelouse`,`quand semer le gazon`],etapes:[{titre:`Le bon moment`,texte:`Septembre est idéal (sol chaud, pluies d'automne, peu d'herbes concurrentes) ; sinon avril-mai. Jamais en plein été ni par gel.`},{titre:`Préparer le sol`,texte:`Retirez les herbes et cailloux, ameublissez sur 10 à 15 cm, nivelez au râteau. Laissez reposer 2 à 3 semaines et arrachez les herbes qui lèvent (faux-semis). Passez un rouleau léger pour tasser.`},{titre:`Choisir le mélange`,texte:`Pelouse rustique et résistante au piétinement : mélange avec ray-grass et fétuques. Sol sec et sans arrosage : fétuques élevées ou rouges, avec du trèfle blanc nain (reste vert l'été, enrichit le sol). Ombre : mélange « ombre » à base de fétuques et pâturin. 30 à 35 g de graines par m².`},{titre:`Semer`,texte:`Par temps calme, en deux passages croisés pour une répartition régulière, puis griffez légèrement au râteau et roulez. Arrosez en pluie fine chaque jour sans détremper jusqu'à la levée (8 à 20 jours). Première tonte haute (6-8 cm) quand l'herbe atteint 10 cm.`},{titre:`Regarnir les trous`,texte:`Griffez la zone dégarnie, ajoutez 1 cm de terreau, semez (le mélange d'origine si possible), tassez du pied, gardez humide 3 semaines. Cherchez la cause : ombre, piétinement, urine de chien, vers blancs.`}],video:`semer une pelouse étape par étape septembre`,liens:[`pelouse`,`vers-blancs`,`desherbage`]}),_({id:`fleurs-a-couper`,titre:`Un coin de fleurs à couper pour faire ses bouquets`,rubrique:`fleurs`,emoji:`💐`,resume:`Les fleurs qui tiennent en vase, comment organiser un carré de fleurs à couper, et les gestes pour des bouquets qui durent.`,alias:[`fleurs a couper`,`fleurs coupees`,`fleurs pour bouquets`,`bouquet du jardin`,`faire ses bouquets`,`jardin de fleurs a couper`,`fleurs en vase`],etapes:[{titre:`Les meilleures fleurs à couper`,texte:`Annuelles faciles à semer : cosmos, zinnias, mufliers, tournesols ramifiés, nigelle, pois de senteur, centaurées. Bulbes : tulipes, narcisses, dahlias, glaïeuls, ail d'ornement. Vivaces : pivoines, phlox, échinacées, asters, alstrœmères. Feuillages : eucalyptus, graminées, fenouil bronze.`},{titre:`Organiser le carré`,texte:`Comme un potager : des rangs au soleil, accessibles, tuteurés par un filet horizontal à 40 cm. Semez les annuelles en plusieurs fois (toutes les 3 semaines) pour couper tout l'été ; plantez les glaïeuls toutes les 2 semaines.`},{titre:`Couper au bon moment`,texte:`Tôt le matin, quand les tiges sont pleines d'eau, avec un sécateur propre. Coupez quand les fleurs commencent juste à s'ouvrir (pivoine en bouton « guimauve », dahlia et zinnia bien ouverts). Plongez aussitôt dans un seau d'eau. Plus on coupe les annuelles, plus elles refleurissent.`},{titre:`Faire durer le bouquet`,texte:`Retirez les feuilles qui trempent, recoupez les tiges en biais, vase très propre, eau changée tous les 2 jours. Tiges qui saignent (pavot, euphorbe) : passez le bout à la flamme.`}],video:`jardin de fleurs à couper débutant`,liens:[`cosmos`,`zinnia`,`dahlia`,`glaieul`]}),_({id:`jardiniere-fleurie`,titre:`Une jardinière fleurie qui tient tout l'été`,rubrique:`balcon`,emoji:`🌺`,resume:`Choisir les plantes selon l'exposition du balcon, le terreau et le bac, l'arrosage, l'engrais et le nettoyage qui gardent les jardinières fleuries jusqu'aux gelées.`,alias:[`jardiniere fleurie`,`jardinieres`,`fleurs de balcon`,`balcon fleuri`,`suspension fleurie`,`fleurs en pot ete`,`composer une jardiniere`,`geranium balcon`],etapes:[{titre:`Selon l'exposition`,texte:`Plein sud : géraniums (pélargoniums), gauras, verveines, gazanias, sauges, pourpiers. Est ou ouest : pétunias, surfinias, calibrachoas, bacopa, fuchsias (ouest). Nord : bégonias, impatiens, fuchsias, heuchères, lierres, fougères.`},{titre:`Le bac et le terreau`,texte:`Une jardinière d'au moins 20 cm de profondeur, percée, avec 2 cm de billes d'argile au fond. Terreau pour plantes fleuries de bonne qualité, avec un engrais à libération lente mélangé à la plantation. Plantez après les dernières gelées, en serrant (une plante tous les 15-20 cm).`},{titre:`Composer`,texte:`Au fond une plante haute (sauge, gaura), au milieu les plantes en touffe (géraniums, bégonias), devant les retombantes (surfinia, bacopa, lierre). Trois couleurs au plus pour un effet harmonieux.`},{titre:`Arroser et nourrir`,texte:`En été, arrosage chaque soir (deux fois par jour en plein sud lors des canicules), jusqu'à ce que l'eau sorte par les trous. Engrais liquide pour plantes fleuries tous les 10 à 15 jours de juin à septembre : les jardinières épuisent vite leur terreau.`},{titre:`Nettoyer`,texte:`Retirez les fleurs fanées chaque semaine, rabattez les surfinias de moitié s'ils s'étirent en juillet : ils refleurissent en 3 semaines. Les géraniums s'hivernent au frais et hors gel.`}],video:`composer une jardinière fleurie balcon`,liens:[`geranium`,`petunia`,`hivernage-pots`,`arrosage-auto-balcon`]})],y=e=>({niveau:2,duree:`Lecture : 6 minutes`,...e}),b=[y({id:`arrosage-automatique`,titre:`Installer un arrosage automatique`,rubrique:`arrosage`,emoji:`🚿`,duree:`Une journée`,resume:`Du robinet aux goutteurs : pression, filtre, programmateur, secteurs, goutte-à-goutte, asperseurs et arrosage enterré de pelouse, puis purge avant l'hiver.`,alias:[`arrosage automatique`,`arrosage enterre`,`programmateur arrosage`,`programmateur`,`filtre arrosage`,`reducteur de pression`,`pression d eau`,`asperseur`,`arroseur`,`tuyere`,`turbine arrosage`,`arrosage pelouse`,`secteurs arrosage`,`electrovanne`,`purger arrosage`,`hiverner arrosage`],etapes:[{titre:`Mesurer avant d'acheter`,texte:`Débit du robinet : chronométrez le remplissage d'un seau de 10 L (débit en L/min = 10 ÷ secondes × 60). Pression : un manomètre à visser sur le robinet (2 à 4 bars habituellement). Ces deux chiffres décident du nombre de goutteurs ou d'asperseurs qu'on peut faire fonctionner en même temps : la page Calculs le calcule.`},{titre:`La tête de réseau`,texte:`Dans l'ordre depuis le robinet : programmateur, filtre à tamis (indispensable, surtout avec l'eau de pluie ou de puits), réducteur de pression à 1-1,5 bar pour le goutte-à-goutte, raccord au tuyau principal. Un clapet anti-retour protège le réseau d'eau potable.`},{titre:`Goutte-à-goutte (potager, massifs, haies)`,texte:`Tuyau de 16 mm à goutteurs intégrés (tous les 30 cm pour le potager, 50 cm pour les haies) : l'eau va au pied, sans mouiller les feuilles ni arroser les allées. Lignes de 50 m au plus (sinon goutteurs autorégulants), bouchon en bout, piquets tous les mètres, posé sous le paillage.`},{titre:`Asperseurs et arrosage enterré (pelouse)`,texte:`Tuyères (portée 2 à 5 m, petites surfaces) ou turbines (5 à 15 m) placées pour que chaque arroseur atteigne le suivant (recouvrement « tête à tête »). Ne mélangez jamais tuyères et turbines sur un même secteur (débits très différents). Arrosez tôt le matin : moins d'évaporation et de maladies. Une pelouse résistante (fétuques, trèfle) peut souvent se passer d'arrosage.`},{titre:`Programmer`,texte:`Peu souvent et longtemps plutôt que tous les jours un peu : les racines descendent. Repère : 2 à 3 arrosages par semaine en été, durée calculée selon le besoin du mois. Ajoutez une sonde de pluie, ou coupez le programmateur après un orage.`},{titre:`Avant l'hiver`,texte:`Coupez l'eau, ouvrez les bouchons de fin de ligne, videz le réseau (ou soufflez à l'air faible pression), rentrez programmateur, filtre et réducteur hors gel. Nettoyez le filtre chaque printemps.`}],video:`installer arrosage goutte à goutte programmateur filtre réducteur`,liens:[`irrigation-raisonnee`,`recuperateur-pluie`,`jardin-sec`,`puits-forage`]}),y({id:`puits-forage`,titre:`Puits, forage et restrictions d'eau`,rubrique:`arrosage`,emoji:`💧`,resume:`Ce qu'il faut déclarer avant de creuser, la qualité de l'eau, et ce qui reste permis quand la préfecture prend des mesures de sécheresse.`,alias:[`puits`,`forage`,`creuser un puits`,`declarer un forage`,`declaration de puits`,`eau de puits`,`secheresse arrete`,`restrictions d eau`,`arrete secheresse`,`vigilance secheresse`,`alerte secheresse`,`interdiction d arroser`,`vigieau`],etapes:[{titre:`Déclarer avant de creuser`,texte:`Tout puits ou forage à usage domestique doit être déclaré en mairie au moins un mois avant les travaux (formulaire Cerfa n° 13837), puis à nouveau après réalisation. Au-delà de 1 000 m³ prélevés par an, ou en zone protégée, d'autres démarches s'ajoutent auprès de la direction départementale des territoires. Renseignez-vous aussi sur le règlement local (périmètres de captage d'eau potable).`},{titre:`Bien le réaliser`,texte:`Faites appel à un foreur qualifié : tête de puits étanche et surélevée, protégée des ruissellements, loin des fosses septiques et des fumières (au moins 35 m conseillés). Un forage mal fait pollue la nappe de tout le voisinage.`},{titre:`La qualité de l'eau`,texte:`L'eau d'un puits n'est pas potable par défaut : faites-la analyser par un laboratoire agréé (nitrates, bactéries) avant tout usage alimentaire, y compris pour arroser des légumes mangés crus. Le réseau du puits ne doit jamais être relié à celui de l'eau potable de la maison (risque de retour d'eau).`},{titre:`Les restrictions de sécheresse`,texte:`La préfecture fixe des niveaux (vigilance, alerte, alerte renforcée, crise) par zone : consultez la carte officielle des restrictions (site VigiEau) pour votre commune. Le plus souvent : arrosage des pelouses et massifs interdit ou limité aux heures fraîches, potager toléré le soir ou la nuit, goutte-à-goutte parfois autorisé plus longtemps. L'eau de pluie récupérée reste en général utilisable librement ; l'eau de puits ou de forage est en principe soumise aux mêmes restrictions.`},{titre:`S'y préparer`,texte:`Paillage, goutte-à-goutte, récupérateurs d'eau de pluie, plantes sobres et arrosage au pied : un jardin préparé passe une période d'alerte sans dommage.`}],video:`déclarer un forage puits mairie`,liens:[`jardin-sec`,`recuperateur-pluie`,`arrosage-automatique`,`voisinage-regles`]}),y({id:`taille-par-fruitier`,titre:`Tailler chaque fruitier : formation et fructification`,rubrique:`recolte`,emoji:`✂️`,niveau:3,resume:`Chaque espèce porte ses fruits sur un bois différent : la taille du pommier ne convient pas au pêcher. Formation des jeunes arbres, puis taille de fructification espèce par espèce.`,alias:[`taille du pommier`,`tailler un pommier`,`tailler un poirier`,`tailler un pecher`,`tailler un abricotier`,`tailler un cerisier`,`tailler un prunier`,`tailler la vigne`,`taille de la vigne`,`tailler les framboisiers`,`tailler un groseillier`,`tailler un cassissier`,`taille de fructification`,`taille de formation`,`lambourde`,`dard`,`brindille couronnee`],etapes:[{titre:`Formation (3 à 5 premières années)`,texte:`On construit la charpente : 3 à 5 branches principales bien réparties autour du tronc, ou un axe central selon la forme choisie. On raccourcit les prolongements d'un tiers au-dessus d'un bourgeon bien orienté, on supprime ce qui part vers l'intérieur. L'arbre ne doit pas encore trop porter de fruits.`},{titre:`Pommier et poirier`,texte:`Ils fructifient sur du bois de 2 ans et plus : dards et lambourdes (rameaux courts à gros bourgeons ronds). En hiver : supprimez les gourmands (rameaux verticaux vigoureux), raccourcissez les rameaux à bois de l'année à 3-4 yeux, éclaircissez les vieilles lambourdes trop ramifiées. En été (juillet-août), une taille en vert raccourcit les pousses vigoureuses et favorise les boutons à fleurs.`},{titre:`Pêcher et nectarinier`,texte:`Ils ne fructifient que sur les rameaux de l'année précédente, une seule fois. Chaque année, au moment de la floraison (mars), coupez les rameaux qui ont déjà porté et gardez des rameaux de remplacement près des charpentières. Un pêcher non taillé ne porte plus qu'en bout de branches.`},{titre:`Abricotier, cerisier, prunier`,texte:`Taille légère et en été, juste après la récolte, par temps sec : la taille d'hiver favorise la gomme et les maladies du bois. Aérez le centre, supprimez le bois mort et les branches qui se croisent ; ne raccourcissez pas systématiquement.`},{titre:`Vigne`,texte:`Taille courte en fin d'hiver (février-mars, hors gel) : sur chaque bras, gardez un rameau de l'an passé taillé à 2 yeux (« coursons ») ; chaque œil donnera un rameau portant 1 à 2 grappes. En été, pincez les rameaux 2 feuilles après la dernière grappe et retirez les entre-cœurs.`},{titre:`Petits fruits`,texte:`Framboisier non remontant : après la récolte, coupez au ras du sol les cannes qui ont porté et gardez 6 à 8 jeunes cannes par mètre. Remontant : tout couper au ras en février pour une seule belle récolte d'automne. Groseillier et cassissier : en hiver, retirez à la base les branches de plus de 3 ans (écorce sombre) et gardez 8 à 10 branches.`}],erreurs:[`Tailler un pêcher comme un pommier (plus de fruits au bout de 2 ans).`,`Tailler cerisiers et pruniers en plein hiver.`,`Couper tous les rameaux courts d'un pommier : ce sont eux qui portent les fruits.`],video:`taille de fructification pommier pêcher différence`,liens:[`taille-fruitiers`,`formes-fruitieres`,`pommier`,`pecher`,`vigne`,`framboisier`]}),y({id:`formes-fruitieres`,titre:`Les formes fruitières : palmette, cordon, gobelet, fuseau, haute-tige`,rubrique:`recolte`,emoji:`🍐`,niveau:3,resume:`Choisir la forme d'un fruitier selon la place, le porte-greffe et l'espèce, et la conduire les premières années.`,alias:[`forme fruitiere`,`formes fruitieres`,`palmette`,`palmette verrier`,`cordon`,`cordon de pommier`,`cordon horizontal`,`gobelet`,`fuseau`,`axe central`,`haute tige`,`demi tige`,`basse tige`,`espalier`,`contre espalier`,`arbre palisse`],etapes:[{titre:`Haute-tige et demi-tige`,texte:`Tronc de 1,8 à 2 m (haute-tige) ou 1,2 à 1,5 m (demi-tige), sur porte-greffe vigoureux : grand arbre durable, sous lequel on peut faire pâturer des moutons ou tondre. Production plus tardive (5 à 8 ans), mais pendant des décennies.`},{titre:`Fuseau (axe central)`,texte:`Un tronc vertical garni de branches fruitières courtes, plus longues en bas : arbre de 2 à 3 m sur porte-greffe faible (M9, M106 pour le pommier), productif dès la 3e année, idéal au petit jardin, à 1,5-2,5 m d'intervalle.`},{titre:`Gobelet`,texte:`Centre ouvert, 3 à 4 charpentières en coupe : la forme naturelle du pêcher, de l'abricotier et du prunier, qui aiment la lumière au centre.`},{titre:`Palmette et espalier`,texte:`Arbre palissé à plat contre un mur ou des fils tendus : branches horizontales (palmette à branches horizontales) ou en U (palmette Verrier). Le mur restitue la chaleur : idéal pour poiriers, pêchers et abricotiers en région fraîche. Demande une taille en vert régulière.`},{titre:`Cordon`,texte:`Pommier ou poirier sur porte-greffe très faible, conduit sur un seul bras horizontal à 40-50 cm du sol : il borde une allée du potager, produit beaucoup pour sa taille. Plantez à 1,5-2 m d'intervalle, courbez la tige progressivement la 1re année.`},{titre:`Accorder forme et porte-greffe`,texte:`Une forme basse exige un porte-greffe faible (sinon l'arbre « s'emballe »), une haute-tige un porte-greffe vigoureux. Achetez un « scion » d'un an (tige simple) pour former vous-même, ou une forme déjà formée en pépinière.`}],video:`palmette cordon fuseau formes fruitières conduite`,liens:[`taille-par-fruitier`,`pommier`,`poirier`,`planter-verger`]}),y({id:`planter-verger`,titre:`Planter un verger, et le soigner en hiver`,rubrique:`recolte`,emoji:`🌳`,niveau:2,resume:`Combien d'arbres, à quelles distances, comment placer les pollinisateurs, le verger pâturé, et les traitements d'hiver avec leurs limites.`,alias:[`planter un verger`,`verger familial`,`creer un verger`,`distance entre arbres fruitiers`,`verger pature`,`pre verger`,`traitement d hiver`,`huile blanche`,`huile de paraffine`,`cuivre automne`,`badigeon tronc`,`traiter les fruitiers en hiver`],etapes:[{titre:`Combien et lesquels`,texte:`Pour une famille : 2 à 3 pommiers de maturités échelonnées (été, automne, hiver de garde), 1 à 2 poiriers, 1 prunier ou mirabellier, 1 cerisier, et des petits fruits. Choisissez des variétés rustiques et résistantes adaptées à votre région (les associations de croqueurs de pommes conseillent les variétés locales).`},{titre:`Distances`,texte:`Haute-tige : 8 à 10 m entre arbres. Demi-tige : 5 à 6 m. Basse-tige sur porte-greffe faible : 3 à 4 m. Fuseau : 1,5 à 2,5 m. Cordon : 1,5 à 2 m. Respectez 2 m de la limite de propriété pour les arbres de plus de 2 m de haut.`},{titre:`Les pollinisateurs`,texte:`Intercalez les variétés qui se pollinisent entre elles, à moins de 50 m les unes des autres, et à floraison simultanée : la fiche de chaque fruitier précise ses besoins. Les abeilles et pollinisateurs sauvages font le reste : haie fleurie, pas de traitement pendant la floraison.`},{titre:`Le verger pâturé (pré-verger)`,texte:`Hautes-tiges sur prairie, pâturée par des moutons : protégez chaque tronc par une cage solide (les moutons écorcent les jeunes arbres ; chèvres et chevaux sont à proscrire). L'herbe remplace la tonte, les animaux mangent les fruits tombés (et les larves de carpocapse).`},{titre:`Les traitements d'hiver et leurs limites`,texte:`Huile de paraffine (« huile blanche », autorisée en bio) en fin d'hiver, avant le débourrement : étouffe les œufs de pucerons et les cochenilles, mais aussi les auxiliaires qui hivernent sur l'arbre : à réserver aux arbres très attaqués l'année précédente. Cuivre (bouillie bordelaise) à la chute des feuilles et au gonflement des bourgeons contre la cloque du pêcher et les chancres : à faible dose, car il s'accumule dans le sol (doses annuelles maximales réglementées). Le badigeon d'argile ou de chaux protège l'écorce du soleil d'hiver. Un verger varié, avec haies et nichoirs, demande de moins en moins de traitements.`}],video:`planter un verger familial distances pollinisation`,liens:[`planter-arbre`,`formes-fruitieres`,`pommier`,`cloque`,`puceron-cendre`,`paturage-tournant`]}),y({id:`elever-en-pot`,titre:`Élever des plantes en pot sur plusieurs années (méthode de pépinière)`,rubrique:`semis`,emoji:`🌱`,niveau:3,resume:`Le substrat, les rempotages successifs, le chignon racinaire, l'arrosage, l'engrais et l'hivernage des jeunes plantes cultivées en conteneur.`,alias:[`elever en pot`,`culture en conteneur`,`conteneur`,`pepiniere en pot`,`chignon racinaire`,`racines qui tournent`,`air pot`,`rempotage progressif`,`hiverner des pots`,`jeunes arbres en pot`,`substrat pepiniere`],etapes:[{titre:`Le substrat`,texte:`Plus grossier que le terreau de semis : écorce compostée, fibre de coco ou de bois, compost mûr et un peu de terre ou de sable pour le poids. Un substrat qui se tasse et reste détrempé fait pourrir les racines. Préférez les mélanges sans tourbe.`},{titre:`Rempoter progressivement`,texte:`Passez à un pot 1,5 à 2 fois plus grand dès que les racines atteignent les parois, pas avant (un trop grand pot reste humide et froid). Chaque rempotage, au printemps de préférence, en démêlant les racines extérieures.`},{titre:`Éviter le chignon`,texte:`Des racines qui tournent en rond au fond du pot continueront de tourner une fois plantées, et l'arbre tiendra mal. Pots ajourés (« air-pot ») ou pots à rainures verticales, rempotage à temps, et à la plantation, incisez les racines qui tournent.`},{titre:`Arroser et nourrir`,texte:`Arrosage regroupé et régulier (goutte-à-goutte ou capillarité sur une nappe) : un pot sèche en une journée d'été. Engrais à libération lente au printemps ; plus d'engrais après juillet, pour que le bois s'aoûte (durcisse) avant l'hiver.`},{titre:`Hiverner`,texte:`Les racines en pot sont bien plus sensibles au gel que la partie aérienne : groupez les pots contre un mur, enterrez-les dans du sable ou entourez-les de paille ou de feuilles. Les plantes rustiques restent dehors, à l'abri des vents.`},{titre:`Endurcir avant de planter`,texte:`Une plante élevée sous abri passe une à deux semaines dehors, à l'ombre puis au soleil, avant sa plantation définitive.`}],video:`culture en conteneur pépinière rempotage chignon racinaire`,liens:[`produire-ses-plants`,`rempoter`,`hivernage-pots`,`acheter-arbres`]}),y({id:`acheter-arbres`,titre:`Acheter des plants et des arbres de qualité`,rubrique:`demarrer`,emoji:`🏷️`,niveau:1,resume:`Ce qu'il faut regarder en pépinière : racines, collet, étiquette, passeport phytosanitaire, garantie de reprise, et quand préférer les racines nues.`,alias:[`acheter des plants`,`acheter un arbre`,`bien choisir un arbre`,`pepiniere`,`pepinieriste`,`plants certifies`,`passeport phytosanitaire`,`etiquette plante`,`garantie de reprise`,`vegetal local label`,`jardinerie ou pepiniere`],etapes:[{titre:`Les racines d'abord`,texte:`Sortez la motte du pot si on vous y autorise : racines claires et nombreuses, sans chignon serré ni odeur de pourri. Racines nues : fraîches, souples, sans dessèchement, abondant chevelu. Une plante très grande dans un petit pot reprend moins bien qu'un jeune sujet.`},{titre:`Le collet et le tronc`,texte:`Écorce saine, sans blessure ni chancre, point de greffe bien soudé. Pour un fruitier, préférez un scion d'un an ou un jeune arbre formé de 2 ans : il reprend mieux qu'un gros sujet.`},{titre:`L'étiquette`,texte:`Nom latin, variété (cultivar), et pour un fruitier le porte-greffe : c'est lui qui donne la taille adulte. Un « pommier » sans variété ni porte-greffe est un achat au hasard.`},{titre:`Garanties et traçabilité`,texte:`Le passeport phytosanitaire accompagne de nombreux végétaux vendus aux professionnels et certains végétaux vendus aux particuliers (notamment ceux sensibles à des organismes réglementés comme Xylella) : il garantit l'origine contrôlée. Le label « Végétal local » garantit des plantes sauvages d'origine régionale pour les haies. Demandez la garantie de reprise, fréquente chez les pépiniéristes.`},{titre:`Racines nues, motte ou conteneur`,texte:`Racines nues (novembre à mars) : moins chères, reprise excellente si plantées vite. Motte grillagée : arbres plus gros, persistants. Conteneur : toute l'année hors été et gel, plus cher. Un bon pépiniériste producteur conseille les variétés adaptées à votre sol et votre climat.`}],video:`bien choisir un arbre en pépinière racines`,liens:[`planter-arbre`,`elever-en-pot`,`acheter-plants`,`choisir-plante`]}),y({id:`concevoir-jardin`,titre:`Concevoir son jardin comme un paysagiste`,rubrique:`demarrer`,emoji:`📐`,niveau:2,duree:`Plusieurs semaines d'observation`,resume:`Relevé du terrain, programme, esquisse, plan à l'échelle, strates et palette végétale : la méthode des concepteurs paysagistes, adaptée à un jardin familial.`,alias:[`concevoir son jardin`,`conception jardin`,`plan de jardin`,`faire un plan de jardin`,`dessiner son jardin`,`amenager son jardin`,`creer un jardin`,`palette vegetale`,`strates vegetales`,`strates`,`esquisse jardin`,`plan masse`,`releve terrain`,`paysagiste`],etapes:[{titre:`1. Le relevé`,texte:`Mesurez le terrain et ce qui existe (maison, arbres, réseaux enterrés, regards, compteurs). Notez le nord, l'ensoleillement heure par heure en été et en hiver (les ombres changent beaucoup), les vents dominants, les vues à garder ou à cacher, la pente, les zones humides, et faites le test de votre sol.`},{titre:`2. Le programme`,texte:`Listez vos usages (repas dehors, jeux d'enfants, potager, poules, détente, stockage, compost), le budget, et surtout le temps d'entretien que vous acceptez par semaine : un jardin se conçoit pour l'entretien qu'on pourra vraiment lui donner.`},{titre:`3. L'esquisse`,texte:`Sur un calque posé sur le relevé, dessinez des « bulles » d'usages placées selon le soleil, les accès et l'intimité (terrasse au soleil près de la cuisine, potager près du point d'eau, compost loin des fenêtres), puis les circulations qui les relient.`},{titre:`4. Le plan à l'échelle`,texte:`Reportez le projet à l'échelle (1/100 : 1 cm = 1 m ; 1/50 pour les détails) : allées, terrasses, massifs, arbres dessinés à leur diamètre ADULTE (c'est l'erreur la plus fréquente). Le plan du jardin de Racines permet de placer ces éléments à l'échelle et de l'exporter.`},{titre:`5. Les strates`,texte:`Un jardin équilibré superpose les strates comme une lisière de forêt : arbres (ombre, structure), arbustes (écrans, haies), vivaces et graminées (masses fleuries), couvre-sols (sol toujours couvert), bulbes (printemps). Pensez aux quatre saisons : écorces, persistants et graminées pour l'hiver.`},{titre:`6. La palette végétale`,texte:`Choisissez un nombre limité d'espèces (5 à 7 plantes de structure, répétées) adaptées au sol et au climat (rusticité, exposition), plutôt qu'une plante de chaque. Répéter une même plante en plusieurs points unifie le jardin. Les fiches Racines donnent rusticité, hauteur, feuillage, floraison et sol de chaque plante.`},{titre:`7. Phaser les travaux`,texte:`Ordre logique : terrassements et réseaux (drainage, arrosage, électricité), allées et terrasses, arbres et haies (en hiver), puis arbustes, vivaces et gazon. Un jardin se construit souvent en 2 ou 3 saisons.`}],video:`concevoir son jardin comme un paysagiste étapes plan`,liens:[`permaculture`,`planter-arbre`,`vivaces-guide`,`jardin-accessible-pente`,`budget-reglementation`]}),y({id:`jardin-accessible-pente`,titre:`Jardin accessible et jardin en pente`,rubrique:`demarrer`,emoji:`♿`,niveau:2,resume:`Un jardin praticable avec l'âge, un fauteuil ou une poussette, et l'aménagement d'un terrain en pente : terrasses, talus, escaliers, érosion.`,alias:[`jardin accessible`,`jardin pmr`,`jardin fauteuil roulant`,`jardin pour personnes agees`,`jardiner assis`,`bac sureleve hauteur`,`terrain en pente`,`jardin en pente`,`talus`,`restanques`,`terrasses de culture`,`escalier de jardin`,`erosion`,`gabion`],etapes:[{titre:`Circuler sans obstacle`,texte:`Allées principales de 1,20 à 1,50 m de large, pente de 5 % au plus (au-delà, prévoir des paliers), revêtement stable et non glissant (stabilisé compacté, dalles jointives), sans marche ni bordure saillante. Éclairage des passages et mains courantes là où il y a un dénivelé.`},{titre:`Cultiver à bonne hauteur`,texte:`Bacs surélevés de 70 à 80 cm de haut pour jardiner debout sans se pencher ; 60 à 70 cm avec un espace libre dessous pour les genoux en fauteuil ; largeur de 1,20 m au plus si on travaille des deux côtés (60 cm d'un seul côté). Robinets et réserves d'eau à hauteur de main, outils à long manche légers.`},{titre:`Moins d'efforts`,texte:`Paillage permanent, goutte-à-goutte programmé, vivaces plutôt qu'annuelles, assises à l'ombre le long du parcours. Les plantes parfumées et à toucher (sauges, lavandes, graminées) enrichissent le jardin pour les personnes malvoyantes.`},{titre:`Terrain en pente : travailler avec`,texte:`Plantez et formez les rangs en suivant les courbes de niveau, jamais dans le sens de la pente (l'eau ravine). Sur un talus, couvre-sols et arbustes à racines traçantes (cornouiller, millepertuis, rosiers couvre-sol) sur un paillage ou une toile biodégradable tiennent la terre.`},{titre:`Terrasses et soutènements`,texte:`Des terrasses (restanques) retenues par des murets en pierre sèche, rondins ou gabions transforment une pente en planches cultivables. Au-delà d'environ 1 m de terre à retenir, un mur de soutènement se calcule : faites appel à un professionnel.`},{titre:`Escaliers de jardin`,texte:`Marches confortables quand deux hauteurs plus une profondeur font environ 63 cm (par exemple 15 cm de haut et 33 cm de profondeur), hauteurs toutes identiques, avec une légère pente vers l'avant pour l'écoulement de l'eau.`}],video:`aménager un jardin en pente terrasses talus`,liens:[`muret-pierre-seche`,`methodes-culture`,`couvre-sols-rocaille`,`concevoir-jardin`]}),y({id:`allees-terrasses`,titre:`Allées et terrasses : gravier, stabilisé, dalles, bois`,rubrique:`fabriquer`,emoji:`🧱`,niveau:2,duree:`1 à 3 week-ends`,resume:`Choisir le revêtement selon l'usage, préparer un fond solide, poser une allée de gravier ou de pas japonais, une terrasse en dalles ou en bois.`,alias:[`allee de jardin`,`allees`,`faire une allee`,`allee en gravier`,`stabilise`,`pas japonais`,`faire une terrasse`,`terrasse en bois`,`terrasse en dalles`,`dalles sur plots`,`bordure`,`geotextile`,`terrasse sans beton`],etapes:[{titre:`Choisir selon l'usage`,texte:`Passage quotidien, brouette, fauteuil : stabilisé compacté ou dalles. Allée secondaire : gravier, copeaux, pas japonais dans l'herbe. Terrasse de repas : dalles (pierre, béton, grès) ou bois. Privilégiez les sols perméables : l'eau de pluie s'infiltre au lieu de ruisseler vers la maison.`},{titre:`Le fond, c'est la solidité`,texte:`Décaissez de 15 à 20 cm (allée piétonne) ou davantage pour un passage de voiture, posez un géotextile (il empêche le mélange avec la terre et freine les herbes), puis une couche de grave (cailloux concassés de différentes tailles) compactée en plusieurs fois. Prévoyez une légère pente (1 à 2 %) pour l'écoulement de l'eau.`},{titre:`Bordures`,texte:`Bordures en acier, bois, pierre ou briques posées avant le revêtement : elles retiennent le gravier et rendent le dessin net. Indispensables pour le gravier et le stabilisé.`},{titre:`Gravier et stabilisé`,texte:`Gravier roulé (agréable mais instable sous les roues) ou concassé de 6/10 mm sur 4 à 5 cm. Stabilisé : sable calcaire ou concassé fin, arrosé et compacté au rouleau, très praticable. Pas japonais : dalles posées à fleur de gazon, espacées de 60 à 65 cm (un pas).`},{titre:`Terrasse en dalles`,texte:`Sur lit de sable ou de gravillons compactés (pose « drainante », sans béton), avec joints de sable, ou sur plots réglables au-dessus d'un sol stable. Pente de 1 à 2 % à l'opposé de la maison.`},{titre:`Terrasse en bois`,texte:`Lambourdes posées sur plots ou sur dés de béton, jamais directement sur la terre, espacées de 40 à 50 cm ; essences durables (mélèze, châtaignier, robinier) ou bois traité classe 4 pour les lambourdes. Laissez 5 mm entre les lames et une bonne ventilation dessous.`}],video:`faire une allée en gravier géotextile bordure`,liens:[`concevoir-jardin`,`drainage-terrain`,`budget-reglementation`,`materiaux-recup`]}),y({id:`muret-pierre-seche`,titre:`Monter un muret en pierre sèche`,rubrique:`fabriquer`,emoji:`⛰️`,niveau:3,duree:`Un week-end par mètre linéaire`,resume:`Un muret sans mortier, durable et plein de vie (lézards, insectes, plantes de rocaille) : fondation, fruit, boutisses, remplissage.`,alias:[`muret`,`muret en pierre seche`,`pierre seche`,`mur en pierres`,`monter un muret`,`restanque`,`mur de soutenement`,`gabion`],etapes:[{titre:`Les pierres`,texte:`Trois sortes : de grosses pierres plates pour la base, des pierres de parement (la face visible) et des boutisses (pierres longues qui traversent le mur et le lient, une tous les mètres par rang), plus des cailloux de remplissage. Comptez environ 1,5 tonne de pierres par m² de mur de 50 cm d'épaisseur.`},{titre:`La fondation`,texte:`Une tranchée de 15 à 20 cm de profondeur, un peu plus large que le mur, au sol compacté : les plus grosses pierres y sont posées à plat, légèrement inclinées vers l'intérieur.`},{titre:`Le fruit`,texte:`Le mur se rétrécit en montant : ses faces s'inclinent vers l'intérieur d'environ 10 à 15 cm par mètre de hauteur. C'est ce « fruit » qui lui donne sa stabilité sans mortier. Un gabarit en bois tendu de cordeaux aide à le respecter.`},{titre:`Monter`,texte:`Chaque pierre repose sur deux pierres du rang inférieur (on « croise les joints », comme des briques), le côté le plus long vers l'intérieur du mur. Calez par derrière avec les cailloux de remplissage, jamais par devant. Finissez par un couronnement de pierres plates ou posées de chant.`},{titre:`Soutènement : la limite`,texte:`Un muret de soutènement doit être plus épais à la base, très incliné vers la terre retenue, et drainé (gravier derrière). Au-delà d'environ 1 m de terre retenue, faites calculer et réaliser l'ouvrage par un professionnel.`}],video:`monter un muret en pierre sèche fruit boutisses`,liens:[`jardin-accessible-pente`,`couvre-sols-rocaille`,`hotel-insectes`]}),y({id:`drainage-terrain`,titre:`Drainer un terrain humide`,rubrique:`sol`,emoji:`💧`,niveau:2,resume:`Diagnostiquer pourquoi l'eau stagne, puis choisir la bonne solution : améliorer le sol, cultiver en buttes, créer une noue, ou poser un drain.`,alias:[`drainage`,`drainage jardin`,`drainer un terrain`,`terrain humide`,`eau stagnante`,`sol detrempe`,`flaques jardin`,`drain agricole`,`noue`,`puits perdu`,`sol argileux humide`],etapes:[{titre:`Le test d'infiltration`,texte:`Creusez un trou de 30 cm, remplissez-le d'eau, laissez s'écouler, remplissez à nouveau et mesurez la baisse en une heure. Plus de 2,5 cm par heure : drainage correct. Moins de 1 cm par heure : sol très mal drainé (argile compacte, semelle de labour, nappe proche).`},{titre:`Améliorer le sol`,texte:`Sur une petite surface, apports réguliers de matière organique (compost, BRF), engrais verts à racines profondes (féverole, radis fourrager) et paillage améliorent la structure en 2 à 3 ans. Évitez de marcher ou de travailler un sol détrempé (il se tasse).`},{titre:`Cultiver au-dessus`,texte:`Buttes, planches surélevées et bacs gardent les racines hors de l'eau d'hiver : la solution la plus simple pour un potager sur sol lourd.`},{titre:`Une noue ou une mare`,texte:`Plutôt que d'évacuer l'eau, recueillez-la : une noue (fossé large et peu profond, engazonné ou planté) ou une mare au point bas recueille le ruissellement et l'infiltre lentement. Plantez-y des plantes de milieu humide (iris des marais, cornouillers, saules).`},{titre:`Poser un drain`,texte:`Tranchée de 50 à 80 cm, pente régulière d'au moins 0,5 à 1 % vers un exutoire (fossé, noue, puits perdu), géotextile, lit de gravier, drain annelé, gravier par-dessus, géotextile replié, terre. Un réseau de drains se pose en arêtes de poisson tous les 5 à 10 m. Le rejet dans le réseau public ou chez le voisin nécessite une autorisation : renseignez-vous en mairie.`}],video:`drainer un terrain humide drain gravier noue`,liens:[`connaitre-sol`,`methodes-culture`,`hotel-insectes`,`concevoir-jardin`]}),y({id:`cloture-cache-vue`,titre:`Clôtures, cache-vue et brise-vent`,rubrique:`fabriquer`,emoji:`🌿`,niveau:1,resume:`Clore, se protéger des regards et du vent : haie vivante, clôture doublée d'une haie, brise-vue en bois ou végétal, et les règles à respecter.`,alias:[`cloture`,`faire une cloture`,`cache vue`,`brise vue`,`brise-vent`,`brise vent`,`se proteger du vis a vis`,`vis a vis`,`haie brise vent`,`palissade`,`grillage`,`ganivelle`,`hauteur cloture`],etapes:[{titre:`Ce que dit la règle`,texte:`La hauteur et l'aspect des clôtures sont fixés par le plan local d'urbanisme (PLU) ou le règlement du lotissement ; dans certaines communes ou secteurs protégés, une déclaration préalable est exigée. Consultez la mairie avant d'acheter. Une haie plantée à moins de 2 m de la limite ne doit pas dépasser 2 m de haut.`},{titre:`Le brise-vent qui marche`,texte:`Un brise-vent efficace laisse passer environ 40 à 50 % du vent (haie champêtre, ganivelle, claie) : un mur plein crée des tourbillons derrière lui. Il protège sur une distance de 10 à 15 fois sa hauteur.`},{titre:`Clôture + haie`,texte:`Le plus durable : un grillage simple doublé d'une haie mélangée côté jardin. Le grillage protège tout de suite (animaux, enfants), la haie fera l'intimité en 3 à 5 ans et accueillera oiseaux et insectes. Laissez des passages de 15 cm au bas du grillage pour les hérissons.`},{titre:`Brise-vue rapides`,texte:`Claies et ganivelles en châtaignier, panneaux en osier, treillage couvert de grimpantes (chèvrefeuille, jasmin étoilé, clématites persistantes, lierre) : intimité en une saison. Évitez les bâches plastiques qui se dégradent vite et prennent le vent.`},{titre:`Contre le bruit`,texte:`Une haie n'arrête presque pas le bruit ; seuls un mur ou un merlon (talus de terre planté) massifs le réduisent. Le bruit de l'eau (fontaine) masque agréablement le fond sonore.`}],video:`brise vue végétal rapide haie grillage`,liens:[`haie`,`grimpantes-supports`,`budget-reglementation`,`voisinage-regles`]}),y({id:`eclairage-jardin`,titre:`Éclairer son jardin sans gêner la nuit`,rubrique:`fabriquer`,emoji:`💡`,niveau:1,resume:`Éclairer les passages et la terrasse en sécurité électrique, et limiter la pollution lumineuse qui perturbe hérissons, chauves-souris et insectes.`,alias:[`eclairage jardin`,`eclairer le jardin`,`lumiere jardin`,`spot jardin`,`lampe solaire`,`eclairage solaire`,`eclairage basse tension`,`pollution lumineuse`,`eclairage terrasse`],etapes:[{titre:`Éclairer utile`,texte:`Les passages, les marches, l'entrée et la terrasse quand on l'utilise. Inutile d'éclairer les arbres toute la nuit : la lumière artificielle désoriente les insectes et les chauves-souris, retarde le sommeil des oiseaux et attire les papillons de nuit, pollinisateurs eux aussi.`},{titre:`Les bons réglages`,texte:`Lumière orientée vers le sol (jamais vers le ciel), lampes chaudes (2 700 K ou moins, couleur ambrée), détecteur de présence ou minuterie qui éteint vers 23 h. Évitez les guirlandes et spots allumés en permanence.`},{titre:`La sécurité électrique`,texte:`Matériel conçu pour l'extérieur (indice de protection IP65 au moins pour les luminaires exposés à la pluie), câble enterré à 50 cm sous gaine rouge avec grillage avertisseur, circuit protégé par un disjoncteur différentiel 30 mA. Le plus simple et le plus sûr : un éclairage très basse tension (12 V) par transformateur, ou des lampes solaires.`},{titre:`Les lampes solaires`,texte:`Faciles à poser sans câble, mais à choisir de bonne qualité (batterie remplaçable) ; en hiver, elles éclairent peu. Recyclez les batteries en déchetterie.`}],video:`éclairage de jardin basse tension pollution lumineuse`,liens:[`jardin-sobre`,`hotel-insectes`,`concevoir-jardin`]}),y({id:`budget-reglementation`,titre:`Budget et règles d'un aménagement de jardin`,rubrique:`demarrer`,emoji:`📋`,niveau:1,resume:`Des ordres de grandeur de coût au m² (en le faisant soi-même ou par un professionnel), et les autorisations à demander pour un abri, une clôture, une piscine ou une terrasse.`,alias:[`budget amenagement jardin`,`prix amenagement jardin`,`cout jardin`,`combien coute un jardin`,`prix au m2 jardin`,`devis paysagiste`,`abri de jardin declaration`,`declaration prealable`,`permis de construire jardin`,`piscine declaration`,`plu jardin`,`urbanisme jardin`],etapes:[{titre:`Ordres de grandeur (fournitures, en le faisant soi-même)`,texte:`Pelouse semée : 1 à 3 € par m². Gazon en rouleaux : 5 à 10 € par m². Allée de gravier avec géotextile et bordure : 10 à 25 € par m². Massif de vivaces et couvre-sols : 15 à 40 € par m² selon la densité. Haie champêtre en jeunes plants : 5 à 15 € par mètre. Terrasse en dalles posées sur gravier : 30 à 80 € par m².`},{titre:`Par un professionnel`,texte:`Comptez en général 2 à 4 fois ces montants, main-d'œuvre comprise (par exemple 30 à 80 € par m² pour une allée, 80 à 200 € par m² pour une terrasse, 150 à 400 € par m² de face pour un muret en pierre sèche). Ces chiffres varient beaucoup selon la région, l'accès et les matériaux : demandez plusieurs devis détaillés. Les services à la personne (entretien du jardin) ouvrent droit à un crédit d'impôt, pas les travaux de création.`},{titre:`Abri de jardin`,texte:`Moins de 5 m² : pas d'autorisation (hors secteur protégé). De 5 à 20 m² : déclaration préalable. Plus de 20 m² : permis de construire. Le PLU peut fixer des règles d'aspect et d'implantation. Un abri de plus de 5 m² peut entrer dans le calcul de la taxe d'aménagement.`},{titre:`Piscine et terrasse`,texte:`Piscine de moins de 10 m² : pas d'autorisation ; de 10 à 100 m² non couverte : déclaration préalable ; au-delà, permis. Une terrasse de plain-pied ne demande en général pas d'autorisation, mais une terrasse surélevée ou dans un secteur protégé peut en demander une.`},{titre:`Murs et clôtures`,texte:`Clôture : selon le PLU et la commune (déclaration préalable parfois exigée). Mur de plus de 2 m de haut : déclaration préalable. Dans tous les cas, renseignez-vous en mairie ou sur le PLU en ligne avant les travaux : une construction non autorisée peut devoir être démolie.`}],video:`abri de jardin déclaration préalable règles`,liens:[`concevoir-jardin`,`voisinage-regles`,`cloture-cache-vue`,`jardin-sans-argent`]})],x=e=>({niveau:2,duree:`Lecture : 6 minutes`,rubrique:`animaux`,...e}),S=[x({id:`calendrier-reproduction`,titre:`Calendrier de reproduction : chèvres, brebis, lapines`,emoji:`📅`,resume:`Saisons des chaleurs, préparation des mères, durée de la lutte, nombre de mâles, rythme de la lapine, âges de sevrage et de première reproduction.`,alias:[`calendrier de reproduction`,`lutte des brebis`,`lutte`,`mise au belier`,`mise au bouc`,`chaleurs chevre`,`saison sexuelle`,`effet bouc`,`effet belier`,`flushing`,`rythme de reproduction lapine`,`saillie lapine`,`combien de portees par an`,`sevrage agneaux`,`sevrage chevreaux`,`sevrage lapereaux`],etapes:[{titre:`Chèvres`,texte:`La plupart des races sont « saisonnées » : chaleurs de septembre à janvier, tous les 21 jours, pendant 1 à 2 jours (chèvre qui bêle, remue la queue, mange moins). L'arrivée d'un bouc après plusieurs semaines d'absence déclenche les chaleurs (« effet bouc »). Un bouc pour 30 à 40 chèvres. Gestation de 150 jours : saillies en octobre, mises bas en mars.`},{titre:`Brebis`,texte:`Saison sexuelle de l'été à l'hiver selon les races (certaines, comme la Romane ou la Mérinos, se reproduisent presque toute l'année). Cycle de 17 jours ; une lutte dure 35 à 45 jours (deux cycles). Un bélier pour 30 à 50 brebis, marqué au crayon ou au harnais pour repérer les saillies. Gestation de 147 jours.`},{titre:`Préparer les femelles`,texte:`En bon état mais pas grasses : 3 semaines avant la lutte, un léger complément (flushing : 200 à 300 g de céréales) augmente le nombre d'ovulations. Vermifuge sur coproscopie, parage des onglons et vaccins à jour avant la lutte, pas pendant la gestation sans avis vétérinaire.`},{titre:`Lapines`,texte:`L'ovulation est provoquée par l'accouplement : on présente toujours la lapine au mâle, dans sa cage à lui. Rythme familial raisonnable : nouvelle saillie 10 à 12 jours après la mise bas ou après le sevrage, soit 4 à 6 portées par an, avec une pause l'été. Un mâle pour 8 à 10 lapines ; une lapine reproduit environ 3 ans. Gestation de 31 jours.`},{titre:`Âges de sevrage`,texte:`Lapereaux : 5 semaines (pas avant 4). Agneaux : 2,5 à 3 mois. Chevreaux : 2 à 3 mois (12-15 kg minimum). Sevrez progressivement, au calme, et séparez les mâles des femelles avant leur maturité (lapereaux dès 10-12 semaines, agneaux et chevreaux vers 4 mois).`},{titre:`Première reproduction`,texte:`Chevrettes à 7-8 mois et 60 % de leur poids adulte ; agnelles à 7-9 mois (races précoces) ou 18 mois (races rustiques) ; lapines à 4,5-5 mois. La page Calculs donne les dates de mise bas, de préparation et de sevrage, et le carnet de reproduction garde l'historique de chaque femelle.`}],video:`calendrier de lutte brebis chèvres effet bouc`,liens:[`chevre`,`mouton`,`lapin`,`naissances`,`reproduction-selection`]}),x({id:`gestes-jeunes`,titre:`Gestes sur les jeunes : écornage, castration, queue, boucles`,emoji:`🏷️`,niveau:3,resume:`Ce qui se fait, à quel âge, avec quelle prise en charge de la douleur, et ce qui est interdit ou déconseillé, pour les agneaux, chevreaux, porcelets et volailles.`,alias:[`ecornage`,`ebourgeonnage`,`ecornage chevreau`,`castration agneau`,`castration chevreau`,`castrer`,`anneau elastique`,`elastrateur`,`caudectomie`,`couper la queue agneau`,`boucle electronique`,`boucler les agneaux`,`identification agneaux`,`epointage bec`],etapes:[{titre:`Une règle d'abord`,texte:`Ces gestes sont douloureux : un antidouleur est recommandé dans tous les cas, et plusieurs ne peuvent se faire que par un vétérinaire ou avec anesthésie au-delà d'un certain âge. Les règles évoluent : vérifiez-les auprès de votre vétérinaire ou du GDS avant de vous lancer. Ne faites que ce qui est utile à votre élevage.`},{titre:`Écorner (ébourgeonner) les chevreaux`,texte:`Une chèvre cornue n'est pas une chèvre malade : les cornes servent à réguler la chaleur et à la hiérarchie. Si vous mélangez cornues et écornées, ou pour la sécurité des enfants, l'ébourgeonnage se fait dans les premiers jours (3 à 10 jours) au fer chaud, idéalement par le vétérinaire avec sédation et antidouleur. Plus tard, c'est une chirurgie lourde.`},{titre:`Castrer`,texte:`Inutile pour des agneaux ou chevreaux abattus jeunes (avant 4 à 5 mois). Pour les mâles gardés (compagnie, débroussaillage) : anneau élastique dans la première semaine, ou plus tard castration par le vétérinaire avec anesthésie. Un bouc castré trop jeune risque davantage les calculs urinaires. Porcelets : jamais sans anesthésie ni antidouleur (interdit).`},{titre:`Couper la queue des agneaux`,texte:`Pratique courante chez les races à laine pour éviter les asticots (myiases) : anneau élastique dans les premiers jours, en laissant assez de queue pour couvrir l'anus (et la vulve des femelles). Inutile chez les races à queue courte ou à poils. Elle est limitée en agriculture biologique. Chez le porc, la coupe systématique est interdite.`},{titre:`Boucler`,texte:`Agneaux et chevreaux sont identifiés dans les premiers mois et avant toute sortie de l'élevage, avec les boucles commandées à l'EDE (boucle électronique selon la destination de l'animal). La pose se fait d'un geste sec, au bon endroit de l'oreille, entre les nervures, avec une pince propre. Notez chaque numéro au registre.`},{titre:`Volailles`,texte:`Pas d'épointage du bec chez soi : le picage se règle par l'espace, l'occupation (bain de poussière, parcours) et une alimentation riche en protéines.`}],video:`boucler des agneaux identification pince`,liens:[`registre-elevage`,`naissances`,`calculs-urinaires`,`myiase`,`porc-familial`]}),x({id:`poussins`,titre:`Élever des poussins de 0 à 8 semaines`,emoji:`🐣`,resume:`Chauffage semaine par semaine, aliments démarrage et croissance, eau, litière, vaccins, et reconnaître les coqs des poules.`,alias:[`poussins`,`elever des poussins`,`chauffer les poussins`,`lampe chauffante poussins`,`temperature poussins`,`aliment demarrage`,`aliment poussin`,`eleveuse`,`sexer les poussins`,`reconnaitre un coq`,`poussin coq ou poule`,`poussins sans mere`],etapes:[{titre:`Préparer l'éleveuse`,texte:`Un bac ou une cage propre, à l'abri des courants d'air, des chats et des rats, avec 5 cm de copeaux de bois (pas de journal glissant), une source de chaleur (plaque chauffante ou lampe infrarouge bien fixée, loin de la litière à cause du feu) et un thermomètre au niveau des poussins.`},{titre:`La température`,texte:`Sous la source de chaleur : 32-35 °C la première semaine, puis environ 3 °C de moins chaque semaine, jusqu'à 20 °C vers la 5e ou 6e semaine. Observez-les : serrés sous la lampe et piaillant, ils ont froid ; éloignés, haletants, ils ont trop chaud ; répartis et calmes, tout va bien. Laissez toujours une zone plus fraîche.`},{titre:`Manger et boire`,texte:`Aliment « démarrage » poussins (20-22 % de protéines, en miettes) les 4 premières semaines, puis aliment « croissance » jusqu'à 8-10 semaines. Abreuvoir à petite cuvette (les poussins se noient dans un bol), eau tiède et propre changée chaque jour. Trempez le bec des premiers poussins pour leur montrer l'eau.`},{titre:`La santé`,texte:`Achetez des poussins vaccinés contre la maladie de Marek. Surveillez les fientes collées au cloaque (nettoyez à l'eau tiède) et la coccidiose (sang dans les fientes, poussins en boule). Litière toujours sèche : l'humidité favorise coccidiose et aspergillose.`},{titre:`Coq ou poule ?`,texte:`Certaines races et croisements se sexent à la naissance par la couleur du duvet (souches « sexables »). Sinon, vers 6 à 10 semaines : crête et barbillons plus rouges et plus grands chez le coq, puis plumes pointues et brillantes sur le cou et le dos (camail, lancettes). Le chant arrive vers 3 à 5 mois.`},{titre:`Sortir dehors`,texte:`Entièrement emplumés vers 6 à 8 semaines, ils sortent par temps doux, d'abord quelques heures. On les mêle aux adultes vers 3 mois, progressivement (voir le guide sur l'intégration de nouveaux animaux).`}],video:`élever des poussins température lampe semaine`,liens:[`couvaison`,`integrer-animaux`,`marek`,`coccidiose`,`aspergillose`]}),x({id:`volailles-chair`,titre:`Élever des volailles pour la viande`,emoji:`🍗`,niveau:2,resume:`Choisir des souches à croissance lente, durée d'élevage, alimentation, parcours, rendement, et ce qu'il faut savoir sur le chapon et le foie gras.`,alias:[`poulet de chair`,`poulets de chair`,`engraisser des poulets`,`elever des poulets`,`souche croissance lente`,`cou nu`,`poulet label`,`poulet fermier`,`chapon`,`chaponner`,`foie gras`,`gavage`,`canard a rotir`,`dinde de noel`,`pintade de chair`],etapes:[{titre:`Choisir la souche`,texte:`Pour un poulet savoureux : souches à croissance lente (cou nu, poulets fermiers « label », races mixtes comme la Sussex, la Faverolles ou la Gâtinaise). Les souches industrielles à croissance rapide grossissent en 6 semaines mais ont souvent des problèmes de pattes et de cœur : elles conviennent mal au plein air familial.`},{titre:`Durée et parcours`,texte:`Un poulet label rouge vit au moins 81 jours avec accès à un parcours herbeux ; en élevage familial, comptez 90 à 120 jours pour une chair ferme. Parcours ombragé (arbres, haies), abri contre les prédateurs la nuit. Pintades : 4 mois ; canards de Barbarie : 10 à 12 semaines (canes), 12 semaines (mâles) ; dindes de Noël : achetées en juin-juillet.`},{titre:`Alimentation`,texte:`Aliment démarrage puis croissance, puis les dernières semaines une finition riche en céréales (maïs, blé) qui donne une chair plus ferme et plus goûteuse. Un poulet de 120 jours consomme environ 10 à 12 kg d'aliment. Eau propre à volonté.`},{titre:`Rendement`,texte:`Un poulet fermier de 2,5 à 3 kg vif donne environ 1,8 à 2,1 kg prêt à cuire (environ 70 %). Notez dépenses et production dans Racines pour connaître votre coût de revient au kilo.`},{titre:`Chapon et foie gras`,texte:`Le chapon est un coq castré chirurgicalement jeune, puis élevé longtemps : c'est un geste chirurgical réservé à des opérateurs formés, à ne pas pratiquer soi-même. Le foie gras suppose le gavage, une pratique très encadrée réservée aux élevages déclarés et discutée pour le bien-être animal : il ne se pratique pas en basse-cour familiale.`},{titre:`Abattage`,texte:`Voir le guide d'abattage familial : animal à jeun 12 heures, étourdissement obligatoire, hygiène, consommation familiale uniquement.`}],video:`élever des poulets fermiers croissance lente plein air`,liens:[`poule`,`abattage-volaille`,`poussins`,`conserver-viande`]}),x({id:`ponte-lumiere-mue`,titre:`Ponte, lumière et mue : comprendre l'arrêt de ponte`,emoji:`🥚`,niveau:1,resume:`Pourquoi les poules pondent moins en automne et en hiver, comment les accompagner pendant la mue, et ce qu'il faut savoir avant d'éclairer un poulailler.`,alias:[`mue des poules`,`poules ne pondent plus en hiver`,`arret de ponte hiver`,`eclairer le poulailler`,`lumiere poulailler`,`ponte et lumiere`,`poule perd ses plumes`,`combien d oeufs par an`,`age des poules ponte`],etapes:[{titre:`La lumière commande la ponte`,texte:`Une poule pond bien quand les jours dépassent 13 à 14 heures. En automne, la durée du jour baisse : la ponte ralentit puis s'arrête souvent de novembre à janvier, surtout chez les races anciennes. C'est un repos naturel, pas une maladie.`},{titre:`La mue`,texte:`Chaque automne, la poule renouvelle ses plumes en 6 à 10 semaines et arrête de pondre. Elle a besoin de plus de protéines (aliment pondeuse complet, pois, insectes séchés, un peu de graines de tournesol), de calme et d'un abri sec. Ne la manipulez pas trop : les plumes neuves sont sensibles.`},{titre:`Éclairer ou non`,texte:`Une lampe sur minuterie qui allonge le matin la journée à 14 heures maintient la ponte, mais fatigue plus vite les poules. Si vous éclairez : jamais plus de 16 heures de jour en tout, au moins 8 heures de nuit noire, allumage le matin (pas le soir : elles doivent pouvoir regagner le perchoir au crépuscule naturel), et jamais sur des poulettes trop jeunes. Beaucoup d'éleveurs familiaux préfèrent laisser le repos d'hiver.`},{titre:`Combien d'œufs`,texte:`Une poule hybride pond 250 à 300 œufs la première année, une poule de race 150 à 200. La ponte baisse d'environ 10 à 15 % chaque année ; une poule vit 8 à 10 ans mais pond peu après 4 ans. Notez la ponte chaque jour dans Racines : le taux de ponte s'affiche.`},{titre:`Si la ponte s'arrête hors saison`,texte:`Cherchez la cause : poux rouges, vers, chaleur, stress (prédateur, déménagement), manque d'eau ou de calcium, poule couveuse, œufs mangés ou pondus ailleurs. La fiche « Ponte en baisse » du diagnostic vous guide.`}],video:`mue des poules arrêt de ponte hiver lumière`,liens:[`poule`,`oeufs`,`hiver-basse-cour`,`arret-ponte`]})],C=e=>({niveau:2,duree:`Lecture : 6 minutes`,...e}),w=[C({id:`devenir-maraicher`,titre:`Devenir maraîcher bio : les étapes et le réalisme`,rubrique:`demarrer`,emoji:`🧑‍🌾`,niveau:3,resume:`Formation, test d'activité, accès à la terre, statut, investissements et premières années : ce qu'il faut savoir avant de s'installer en maraîchage bio diversifié.`,alias:[`devenir maraicher`,`devenir maraicher bio`,`s installer en maraichage`,`installation agricole`,`bprea`,`dja`,`dotation jeunes agriculteurs`,`espace test agricole`,`terre de liens`,`trouver des terres`,`reconversion agricole`,`vivre du maraichage`],etapes:[{titre:`Se former et se tester`,texte:`Le BPREA (brevet professionnel de responsable d'entreprise agricole) est la formation de référence pour adultes ; il ouvre droit aux aides à l'installation. Avant de s'engager, travaillez une ou deux saisons chez des maraîchers (wwoofing, salariat, stages) puis testez votre projet en grandeur réelle dans un espace-test agricole, qui prête terre, matériel et accompagnement pendant 1 à 3 ans.`},{titre:`Trouver la terre`,texte:`Il faut de l'eau d'abord, puis un sol correct, un accès, et si possible un bâtiment. Pistes : le point accueil installation de la chambre d'agriculture, la SAFER (ventes de terres), Terre de Liens (terres achetées par épargne citoyenne et louées en bail rural), les communes qui créent des régies ou des fermes municipales, et les cédants qui partent à la retraite.`},{titre:`Le statut et les aides`,texte:`Au-delà d'une surface ou d'un temps de travail minimal, on cotise à la MSA comme chef d'exploitation. Les aides (dotation jeunes agriculteurs avant 40 ans, aides régionales, prêts d'honneur) demandent un plan d'entreprise validé. Le point accueil installation oriente gratuitement vers les bons interlocuteurs.`},{titre:`Investir juste`,texte:`Irrigation, tunnels, chambre froide, outils, véhicule de livraison : de quelques dizaines de milliers d'euros au strict minimum à bien davantage pour une ferme équipée. Le matériel d'occasion, l'autoconstruction et les CUMA (matériel en commun) réduisent fortement la facture.`},{titre:`Le réalisme économique`,texte:`Un maraîchage diversifié bio en vente directe occupe en général une personne à temps plein pour moins d'un hectare cultivé, avec des semaines de 50 heures en saison. Les premières années servent à apprendre : visez une commercialisation simple (paniers, marché, magasin de producteurs) et une gamme stable. L'onglet Économie du plan de culture aide à repérer les cultures qui rémunèrent.`}],video:`devenir maraîcher bio installation témoignage`,liens:[`certification-bio`,`outils-maraichers`,`vendre-surplus`,`budget-reglementation`]}),C({id:`certification-bio`,titre:`La certification bio pour un producteur`,rubrique:`demarrer`,emoji:`🏷️`,niveau:2,resume:`Pour vendre sous le label bio : organisme certificateur, conversion, semences, intrants, registres et contrôles. Ce qui change par rapport au simple jardinage bio.`,alias:[`certification bio`,`certifier bio`,`label ab`,`conversion bio`,`organisme certificateur`,`ecocert`,`semences bio obligatoires`,`derogation semences`,`cahier des charges bio`,`vendre en bio`,`agence bio notification`],etapes:[{titre:`Jardiner bio ou être certifié`,texte:`Pour sa consommation, chacun jardine comme il veut. Mais pour vendre en utilisant les mots « bio » ou « biologique », ou le logo AB et l'eurofeuille, il faut être certifié : sinon c'est une tromperie du consommateur. On peut toujours dire « cultivé sans produits chimiques de synthèse » si c'est exact.`},{titre:`S'engager`,texte:`Choisissez un organisme certificateur agréé (il en existe plusieurs, comparez les tarifs : quelques centaines d'euros par an pour une petite ferme), signez le contrat et notifiez votre activité auprès de l'Agence Bio. Des certifications de groupe existent pour les très petits producteurs.`},{titre:`La conversion`,texte:`Les parcelles doivent être cultivées selon le cahier des charges pendant au moins 2 ans avant le semis (cultures annuelles) et 3 ans avant la récolte (cultures pérennes, fruitiers) pour vendre en bio. Pendant la conversion, la mention « en conversion vers l'agriculture biologique » est possible sous conditions. Un historique prouvé sans intrants interdits peut parfois réduire cette période.`},{titre:`Semences et intrants`,texte:`Les semences et plants doivent être bio. Si une variété n'existe pas en bio, une dérogation est possible via la base nationale des semences biologiques, à demander avant d'acheter. Engrais, amendements et traitements doivent figurer dans la liste des intrants autorisés (mention « utilisable en agriculture biologique »).`},{titre:`Registres et contrôle`,texte:`Tenez à jour : achats d'intrants et de semences (factures), cahier de culture (dates, parcelles, traitements), récoltes et ventes. Un contrôle annuel au moins, parfois inopiné. Le cahier de culture de Racines (export dans Plan de culture) aide à garder ces traces.`},{titre:`Les aides`,texte:`Selon les années : aides à la conversion et au maintien de la politique agricole commune, crédit d'impôt pour l'agriculture biologique, aides régionales. Renseignez-vous auprès du groupement d'agriculture biologique (GAB) ou de la chambre d'agriculture de votre département.`}],video:`certification bio producteur conversion organisme certificateur`,liens:[`labels-bio`,`devenir-maraicher`,`semences`]}),C({id:`idees-recues`,titre:`Idées reçues du jardin : ce qui marche, ce qui ne marche pas, ce qui est interdit`,rubrique:`demarrer`,emoji:`🤔`,niveau:1,resume:`Peau de banane, coquilles d'œufs, vinaigre, sel, bicarbonate, cendres, marc de café, lune : le tri entre astuces utiles, croyances et pratiques nuisibles.`,alias:[`idees recues`,`astuces de grand mere`,`peau de banane engrais`,`peau de banane`,`coquilles d oeufs limaces`,`vinaigre desherbant`,`sel desherbant`,`bicarbonate jardin`,`eau de cuisson`,`mythe jardin`,`fausses astuces`,`arroser en plein soleil`],etapes:[{titre:`Peau de banane et coquilles d'œufs`,texte:`La peau de banane contient un peu de potassium, mais enterrée entière au pied d'une plante, elle pourrit lentement et attire mouches et rongeurs : mettez-la plutôt au compost. Les coquilles d'œufs broyées apportent du calcium très lentement ; contre les limaces, les essais montrent qu'elles ne les arrêtent pas.`},{titre:`Vinaigre et sel : non`,texte:`Utiliser du vinaigre ou du sel comme désherbant est interdit (ce ne sont pas des herbicides autorisés) et nuisible : le sel stérilise durablement le sol, le vinaigre détruit aussi la vie du sol en surface. Pour désherber : paillage, binage, eau bouillante de cuisson (non salée) sur les allées.`},{titre:`Bicarbonate et lait : à petite dose`,texte:`Le bicarbonate de soude (5 g par litre) ou le lait dilué (1 pour 9) freinent l'oïdium en préventif. À forte dose, le bicarbonate brûle les feuilles et accumule du sodium dans le sol.`},{titre:`Cendres et marc de café : avec modération`,texte:`Les cendres de bois (non traité) apportent potasse et calcaire : une poignée par m² et par an au plus, jamais sur les plantes de terre acide. Le marc de café se composte ou s'étale en fine couche : en couche épaisse il moisit et peut freiner certaines plantes.`},{titre:`Ce qui marche vraiment`,texte:`Le paillage, le compost, la rotation, l'arrosage au pied le matin, les filets et voiles, les fleurs pour les auxiliaires, le purin d'ortie dilué, le savon noir sur pucerons, le piège à bière pour les limaces. Arroser en plein soleil ne « brûle » pas les feuilles, mais l'eau s'évapore : c'est surtout du gaspillage.`},{titre:`Et la lune ?`,texte:`Aucune étude sérieuse n'a montré d'effet des phases de la lune sur les cultures : si le calendrier lunaire vous aide à vous organiser, rien n'empêche de le suivre, mais la météo et l'état du sol comptent bien davantage.`}],video:`idées reçues jardinage vrai faux`,liens:[`engrais-naturels`,`desherbage`,`traiter-loi`,`limaces`]}),C({id:`tunnel-petit-prix`,titre:`Tunnels et voiles à petit prix`,rubrique:`fabriquer`,emoji:`⛺`,niveau:2,duree:`Une journée`,resume:`Construire un tunnel ou un mini-tunnel avec des arceaux en tube ou en bois, une bâche adaptée ou de récupération, solidement ancré contre le vent.`,alias:[`tunnel pas cher`,`tunnel maison`,`fabriquer un tunnel`,`mini tunnel`,`arceaux`,`arceaux en noisetier`,`arceaux en tube`,`tunnel de culture`,`bache de serre`,`abri de culture pas cher`,`chenille`,`tunnel nantais`],etapes:[{titre:`Mini-tunnels (chenilles)`,texte:`Pour une planche : arceaux tous les 1,2 à 1,5 m (fil de fer épais, tube d'irrigation de 20-25 mm sur fers à béton, ou baguettes de noisetier ou de châtaignier courbées fraîches), recouverts d'un voile de forçage, d'un filet anti-insectes ou d'une bâche perforée. Bords enterrés ou lestés de sacs de sable, aération en soulevant un côté.`},{titre:`Tunnel de culture où l'on entre`,texte:`Arceaux en tube d'irrigation de 32 à 40 mm emmanchés sur des fers à béton plantés tous les 1,2 m, ou en bois cintré pour les plus habiles ; faîtage et contreventement en diagonale ; portes aux deux bouts pour l'aération. Largeur 3 à 5 m, hauteur au moins 2 m au centre.`},{titre:`La bâche`,texte:`Une bâche de serre traitée anti-UV (180 à 200 microns) dure 4 à 5 ans ; une bâche ordinaire ou de récupération se déchire en un an au soleil. Posez-la par temps doux et sans vent (elle se tend en refroidissant). Une bâche « thermique » garde mieux la chaleur la nuit.`},{titre:`Ancrer contre le vent`,texte:`C'est le vent qui détruit les tunnels : bâche enterrée dans une tranchée de 30 cm sur les côtés, ou fixée sur des planches vissées, cordes ou sangles croisées par-dessus d'un côté à l'autre, ancrages en spirale. Fermez le tunnel par grand vent (un tunnel ouvert d'un seul côté s'envole comme un parachute).`},{titre:`Faire durer`,texte:`Ruban adhésif spécial serre pour les accrocs, protection des arceaux sous la bâche (ruban mousse) aux points de frottement, rangement au sec et à l'ombre des voiles hors saison. En fin de vie, la bâche se recycle (filières agricoles ou déchetterie) : jamais brûlée ni enterrée.`}],video:`fabriquer un tunnel de culture pas cher arceaux tube`,liens:[`tunnel-pilotage`,`serre`,`chassis`,`plastique-jardin`]}),C({id:`eau-sans-electricite`,titre:`L'eau sans électricité : gravité, cuve IBC et pompe à bélier`,rubrique:`arrosage`,emoji:`💧`,niveau:3,resume:`Arroser par gravité depuis une cuve surélevée, choisir et préparer une cuve IBC, et monter l'eau d'un ruisseau sans moteur grâce au bélier hydraulique.`,alias:[`irrigation gravitaire`,`arrosage par gravite`,`cuve ibc`,`cuve de 1000 litres`,`pompe a belier`,`belier hydraulique`,`pompe sans electricite`,`pompe manuelle`,`pompe solaire`,`arroser sans electricite`,`goutte a goutte gravitaire`],etapes:[{titre:`La gravité`,texte:`Chaque mètre de hauteur donne 0,1 bar de pression. Une cuve posée à 1 ou 2 m de haut suffit pour un goutte-à-goutte « basse pression » (gaines poreuses, goutteurs gravitaires, tuyau à trous de gros diamètre), pas pour un goutte-à-goutte classique qui demande 1 bar. Prévoyez un filtre et des lignes courtes (20 à 30 m).`},{titre:`La cuve IBC`,texte:`Une cuve de 1 000 L sur palette, d'occasion, ayant contenu un produit ALIMENTAIRE (sirop, huile) uniquement : refusez celles qui ont contenu des produits chimiques. Rincez-la, couvrez-la ou peignez-la d'une teinte sombre (sinon des algues s'y développent à la lumière), posez-la sur un socle très solide (une tonne d'eau), fermez le haut contre les moustiques, et reliez plusieurs cuves par le bas.`},{titre:`Pompe manuelle ou solaire`,texte:`Pour remonter l'eau d'une cuve enterrée ou d'un puits peu profond : pompe à bras (jusqu'à 7 m de profondeur), ou petite pompe solaire qui remplit une cuve haute pendant la journée ; ensuite, tout se fait par gravité.`},{titre:`La pompe à bélier`,texte:`Si vous avez un ruisseau ou une source avec une petite chute (au moins 1 m), le bélier hydraulique utilise l'énergie de l'eau qui descend pour en remonter une partie, sans électricité, jour et nuit : environ un dixième du débit d'entrée, jusqu'à une hauteur de l'ordre de dix fois la chute. Il se fabrique avec des raccords de plomberie (deux clapets et une cloche d'air).`},{titre:`Les autorisations`,texte:`Prélever dans un cours d'eau, une source ou une nappe peut être soumis à déclaration ou autorisation (direction départementale des territoires) et aux restrictions de sécheresse. L'eau de pluie récupérée sur votre toit reste libre d'usage pour le jardin.`}],video:`pompe à bélier hydraulique fabrication`,liens:[`recuperateur-pluie`,`puits-forage`,`arrosage-automatique`,`jardin-sec`]}),C({id:`germoir`,titre:`Graines germées et jeunes pousses à la maison`,rubrique:`interieur`,emoji:`🌱`,niveau:1,duree:`3 à 10 jours`,resume:`Faire germer des graines en bocal ou en germoir, en toute sécurité, et cultiver des jeunes pousses sur un plateau : des légumes frais toute l'année pour quelques centimes.`,alias:[`germoir`,`graines germees`,`faire germer des graines`,`germination en bocal`,`jeunes pousses`,`micro pousses`,`pousses de tournesol`,`pousses de radis`,`luzerne germee`,`lentilles germees`],etapes:[{titre:`Le matériel`,texte:`Un bocal en verre fermé par un tissu fin ou une grille (vendue « couvercle de germination »), ou un germoir à étages. Des graines vendues « pour germination », bio : jamais de graines traitées destinées au semis.`},{titre:`Faire germer`,texte:`Faites tremper les graines 8 à 12 heures dans de l'eau fraîche, égouttez, puis rincez et égouttez matin et soir, bocal incliné tête en bas. En 3 à 6 jours : luzerne, radis, brocoli, moutarde, lentilles, pois chiches, haricot mungo, fenugrec. Mettez à la lumière le dernier jour pour qu'elles verdissent.`},{titre:`La sécurité`,texte:`La chaleur et l'humidité qui font germer les graines conviennent aussi aux bactéries : eau potable, rinçages réguliers, bocal lavé à chaque fois, conservation au réfrigérateur et consommation en 2 à 3 jours. Jetez tout ce qui sent mauvais ou moisit. Les enfants, les femmes enceintes et les personnes fragiles les mangent de préférence cuites.`},{titre:`À ne pas faire germer`,texte:`Haricots secs rouges et blancs (crus : toxiques), graines de tomate, d'aubergine, de pomme de terre et de rhubarbe (famille toxique), et toute graine traitée.`},{titre:`Jeunes pousses sur plateau`,texte:`Tournesol, pois, radis, roquette, moutarde semés serrés sur 2 cm de terreau ou de fibre de coco, près d'une fenêtre : coupe aux ciseaux en 7 à 14 jours, quand les deux premières feuilles sont formées. Voir les aromates et micro-pousses en intérieur.`}],video:`graines germées bocal débutant`,liens:[`herbes-interieur`,`potager-interieur`]}),C({id:`etagere-semis`,titre:`Une étagère de semis éclairée, avec du matériel de récup`,rubrique:`semis`,emoji:`💡`,niveau:2,duree:`Une demi-journée`,resume:`Des plants trapus en février-mars sans serre : étagère, réglettes LED, minuterie, réflecteurs et chaleur douce, pour quelques dizaines d'euros.`,alias:[`etagere de semis`,`etagere de semis lampe`,`eclairer les semis`,`lampe pour semis`,`led semis`,`semis qui filent`,`station de semis`,`tapis chauffant semis`],etapes:[{titre:`La structure`,texte:`Une étagère métallique ou en bois de récupération, 3 à 4 niveaux espacés de 40 cm, dans une pièce fraîche (15 à 18 °C). Les plateaux de récupération (caisses de fruits, bacs) reçoivent les godets.`},{titre:`La lumière`,texte:`Des réglettes LED « lumière du jour » (4 000 à 6 500 K) ou horticoles, 2 réglettes par niveau, suspendues par des chaînettes à 5-10 cm au-dessus des plants et remontées à mesure qu'ils poussent. Une minuterie : 14 à 16 heures par jour. Des parois de carton couvert d'aluminium ou de papier blanc renvoient la lumière.`},{titre:`La chaleur`,texte:`Les solanacées (tomates, poivrons, aubergines) lèvent mieux sur un tapis chauffant (20-25 °C) ; une fois levées, enlevez-le : des plants au chaud et sans assez de lumière filent.`},{titre:`L'air`,texte:`Un petit ventilateur quelques heures par jour, ou simplement passer la main sur les plants chaque jour : le mouvement rend les tiges plus solides et limite la fonte des semis.`},{titre:`La consommation`,texte:`Deux réglettes de 20 W allumées 15 heures pendant 8 semaines consomment environ 34 kWh, quelques euros d'électricité : bien moins que des plants achetés. Voir l'outil lampe de culture pour calculer selon votre installation.`}],video:`étagère de semis LED fabrication`,liens:[`semis-interieur`,`produire-ses-plants`,`fonte-semis`,`lumiere-led`]}),C({id:`outils-maraicher-maison`,titre:`Fabriquer ses outils de maraîcher`,rubrique:`fabriquer`,emoji:`🛠️`,niveau:3,duree:`Quelques heures par outil`,resume:`Grelinette, houe oscillante, rabot à planches, marqueur de lignes, plantoir à mottes, tamis : des outils efficaces fabriqués avec du matériel de récupération.`,alias:[`grelinette maison`,`fabriquer une grelinette`,`fabriquer ses outils`,`outils maison`,`houe oscillante maison`,`rabot a planche`,`marqueur de lignes`,`plantoir a mottes`,`tamis a terreau`,`outils de recup`],etapes:[{titre:`La grelinette`,texte:`Une barre horizontale en tube d'acier carré (60 cm) sur laquelle on soude 4 ou 5 dents (fers plats ou fers à béton épais forgés, 25-30 cm), et deux manches verticaux en bois ou en tube. Il faut un poste à souder et un peu d'expérience, ou l'aide d'un atelier partagé ; les associations d'autoconstruction agricole proposent des plans et des formations.`},{titre:`La houe oscillante (désherbage rapide)`,texte:`Un étrier en fer plat qui pivote au bout d'un manche, dont la lame (un morceau de lame de scie ou de fer plat affûté) coupe les herbes juste sous la surface en poussant et en tirant : l'outil qui fait gagner le plus de temps sur une planche.`},{titre:`Rabot à planches et marqueur de lignes`,texte:`Une planche de bois de la largeur de la planche de culture, fixée à un manche, nivelle la surface après le travail du sol. Un râteau en bois à dents réglables (chevilles tous les 10, 15 ou 30 cm) trace en un passage les lignes de semis ou de plantation.`},{titre:`Plantoir à mottes et tamis`,texte:`Plantoir : un tube ou une planchette percée de la taille de vos mottes, monté sur manche, pour préparer en une fois les trous d'une rangée. Tamis : un cadre en bois et un grillage de 5 à 10 mm pour le terreau de semis et le compost.`},{titre:`Sécurité et entretien`,texte:`Lunettes et gants pour la meuleuse et la soudure ; aiguisez les lames régulièrement ; huilez les manches en bois et rangez les outils à l'abri.`}],video:`fabriquer une grelinette soudure`,liens:[`outils-maraichers`,`reparer-outils`,`petits-outils-maison`]}),C({id:`ou-trouver-gratuit`,titre:`Où trouver gratuitement fumier, broyat, cartons et matériaux`,rubrique:`demarrer`,emoji:`🎁`,niveau:1,resume:`Les ressources qu'on vous donne volontiers, où les demander, et les précautions pour chacune (fumier traité, bois traité, plastiques).`,alias:[`ou trouver gratuitement`,`recuperer du fumier gratuit`,`fumier gratuit`,`broyat gratuit`,`copeaux gratuits`,`feuilles mortes gratuites`,`dreches de brasserie`,`marc de cafe gratuit`,`cartons gratuits`,`seaux gratuits`,`palettes gratuites`,`palette traitee`,`palettes hT`,`ressources gratuites jardin`],etapes:[{titre:`Fumier`,texte:`Centres équestres, élevages de chevaux, fermes, voisins qui ont des poules ou des lapins. Précautions : demandez si le foin ou la paille a été traité aux désherbants à base de pyridine (aminopyralide, clopyralid), qui persistent dans le fumier et déforment les tomates et haricots ; faites un test sur quelques plants de haricots. Compostez-le 6 mois avant usage.`},{titre:`Broyat, copeaux, feuilles`,texte:`Élagueurs et paysagistes (ils paient souvent pour s'en débarrasser), services espaces verts des communes (feuilles à l'automne, broyat). Le broyat frais s'utilise en surface (paillage des allées, des arbustes), pas mélangé à la terre (faim d'azote).`},{titre:`Matières riches`,texte:`Drêches de brasserie (orge humide très riche en azote : à composter vite, elle fermente), marc de café des cafés et restaurants, tontes de gazon non traitées, algues de plage là où le ramassage est autorisé (rincées, en petites quantités), épluchures d'un marché ou d'une cantine.`},{titre:`Contenants et cartons`,texte:`Cartons bruns sans adhésif plastique ni encre brillante (paillage, occultation), seaux alimentaires de boulangeries et restaurants, pots de jardineries et de paysagistes, bocaux en verre. Évitez les bidons ayant contenu des produits chimiques.`},{titre:`Bois de palette`,texte:`Seules les palettes marquées « HT » (traitement thermique) conviennent au jardin et au poulailler ; refusez celles marquées « MB » (bromure de méthyle) ou sans marquage, et les palettes tachées de produits. Les palettes de couleur appartiennent à des sociétés de location : ne les récupérez pas.`},{titre:`Graines et plants`,texte:`Grainothèques des médiathèques, bourses aux graines et aux plantes, trocs entre voisins, jardins partagés, et vos propres graines gardées d'une année sur l'autre.`}],video:`récupérer du fumier broyat gratuit jardin`,liens:[`jardin-sans-argent`,`materiaux-recup`,`fumiers-securite`,`graines-maison`]}),C({id:`plastique-jardin`,titre:`Le plastique au jardin : choisir, réparer, recycler`,rubrique:`fabriquer`,emoji:`♻️`,niveau:1,resume:`Voiles, bâches, filets, goutte-à-goutte et pots : choisir ce qui dure, réparer, limiter les microplastiques, et que faire en fin de vie.`,alias:[`plastique au jardin`,`zero dechet jardin`,`bache plastique`,`voile de forcage duree`,`microplastiques jardin`,`recycler les baches`,`toile tissee`,`reutiliser les pots`],etapes:[{titre:`Choisir durable`,texte:`Une toile tissée (occultation, allées) dure 10 ans ; un film fin se déchire en une saison et part en morceaux dans le sol. Pour l'occultation, une bâche d'ensilage de récupération (épaisse) fait très bien l'affaire. Un voile de forçage léger dure 1 à 2 saisons, un filet anti-insectes de bonne qualité 5 à 10 ans.`},{titre:`Remplacer quand c'est possible`,texte:`Paillage organique (paille, foin, broyat, feuilles) au lieu des films ; godets en papier journal ou en mottes pressées ; tuteurs en bois ou en bambou ; liens en raphia ou en ficelle de chanvre ; carton pour l'occultation.`},{titre:`Réparer`,texte:`Ruban adhésif spécial serre et bâche pour les accrocs, raccords et bouchons pour le goutte-à-goutte (un tuyau percé se répare en 2 minutes), couture pour les filets. Rangez voiles et bâches propres et secs, à l'abri de la lumière, roulés plutôt que pliés.`},{titre:`Les microplastiques`,texte:`Un film qui vieillit au soleil se fragmente en particules qui restent dans le sol des dizaines d'années : ramassez les vieux films avant qu'ils ne se déchirent, évitez les toiles « biodégradables » de qualité douteuse (certaines ne le sont qu'en compostage industriel).`},{titre:`En fin de vie`,texte:`Bâches et films propres : déchetterie (filière plastique) ou, pour les professionnels, la filière de collecte agricole. Pots : rapportez-les en jardinerie ou donnez-les. Jamais brûlés (fumées toxiques et interdiction de brûlage) ni enterrés.`}],video:`réduire le plastique au jardin`,liens:[`jardin-sobre`,`paillage`,`tunnel-petit-prix`]})],T=[{id:`creer-potager`,titre:`Créer son potager de A à Z`,rubrique:`demarrer`,emoji:`👨‍🌾`,niveau:1,duree:`Un week-end pour démarrer, puis une saison`,resume:`Du choix de l'emplacement aux premières récoltes : la méthode complète pour un premier potager qui réussit, sans se ruiner ni s'épuiser.`,quand:`Idéalement en automne (le sol se prépare tout l'hiver), sinon dès la fin de l'hiver.`,materiel:[`Grelinette ou fourche-bêche`,`Râteau, binette, plantoir, arrosoir`,`Ficelle et piquets`,`Carton brun sans scotch`,`Compost ou fumier décomposé`,`Paille, feuilles mortes ou tontes sèches (paillage)`],etapes:[{titre:`Choisir l'emplacement`,texte:`Le potager a besoin d'au moins 6 heures de soleil direct par jour en été. Choisissez un endroit plat ou en pente douce, abrité des vents dominants, proche d'un point d'eau et de la maison : un potager qu'on voit de la cuisine est un potager qu'on entretient.`,astuce:`Observez l'ombre à différentes heures avant de décider : les arbres et bâtiments projettent beaucoup plus d'ombre au printemps qu'en plein été.`},{titre:`Commencer petit`,texte:`Pour une première année, 10 à 20 m² suffisent largement (4 à 6 planches de 1,2 m de large). Un petit potager bien tenu produit plus qu'un grand envahi d'herbes. Vous agrandirez l'an prochain.`},{titre:`Dessiner le plan`,texte:`Tracez des planches de 1 à 1,2 m de large (on atteint le milieu sans marcher dessus) séparées par des allées de 40 cm. On ne marche JAMAIS sur les planches : la terre reste meuble. Prévoyez un coin pour le compost et un pour les vivaces (rhubarbe, fraisiers, aromatiques) qui restent en place plusieurs années.`},{titre:`Préparer le sol sans s'épuiser`,texte:`Sur une pelouse, la méthode la plus simple est de couvrir : tondez ras, posez du carton brun en le faisant se chevaucher, mouillez, recouvrez de 10 cm de compost ou de fumier décomposé puis de 10 cm de paille ou feuilles. En 3 à 6 mois (posé en automne pour le printemps), l'herbe est morte et les vers ont travaillé. Si vous êtes pressé, ameublissez à la grelinette sans retourner la terre, retirez les racines d'herbes vivaces (chiendent, liseron) à la main, et apportez 3 à 5 cm de compost en surface.`,attention:`Ne retournez pas profondément la terre à la bêche : vous enterrez la vie du sol et remontez des graines d'herbes. Ne passez pas de motoculteur sur du chiendent : chaque morceau de racine devient une nouvelle plante.`},{titre:`Choisir les légumes faciles`,texte:`La première année, misez sur les valeurs sûres : radis, salades, courgettes, haricots, pommes de terre, tomates cerises, blettes, petits pois, aromatiques (ciboulette, persil, thym). Cultivez ce que vous aimez manger, en petites quantités variées. Ajoutez des fleurs (capucines, soucis, œillets d'Inde) pour les pollinisateurs et les auxiliaires.`},{titre:`Semer ou acheter des plants ?`,texte:`Semez directement en place les radis, carottes, haricots, pois, épinards, betteraves. Achetez en plants (ou semez au chaud à l'intérieur) les tomates, poivrons, aubergines, courgettes, choux, poireaux et salades pour gagner du temps. Ouvrez le calendrier de l'application pour savoir quoi faire chaque mois dans votre zone.`},{titre:`Pailler, arroser, observer`,texte:`Dès que les plants sont installés et que le sol est réchauffé (mai), paillez épais entre les rangs : moins d'arrosage, moins de désherbage, plus de vie dans le sol. Arrosez au pied, abondamment et moins souvent. Passez au potager 10 minutes chaque jour : on repère un problème quand il est encore petit.`},{titre:`Tenir un carnet`,texte:`Notez ce que vous avez semé, où et quand, ce qui a réussi ou échoué : c'est la base de la rotation l'année suivante. L'application le fait pour vous dans « Mon jardin ».`}],conseils:[`Installez un récupérateur d'eau de pluie dès la première année.`,`Laissez un coin « sauvage » (orties, herbes hautes, tas de bois) : il héberge les auxiliaires.`,`Une grelinette (outil à deux manches et à dents) ameublit sans retourner la terre et épargne le dos.`],erreurs:[`Tout semer le même jour : vous aurez 30 salades en même temps. Semez peu et souvent.`,`Planter les tomates trop tôt (avant mi-mai dans la plupart des régions).`,`Arroser un peu tous les soirs : les racines restent en surface.`],video:`créer son premier potager débutant étape par étape`,liens:[`methodes-culture`,`rotation`,`associations`,`connaitre-sol`,`compost-tas`,`paillage`]},{id:`methodes-culture`,titre:`Carré potager, buttes, lasagnes, planches : quelle méthode ?`,rubrique:`demarrer`,emoji:`🌍`,niveau:1,duree:`1 à 3 heures par carré ou planche`,resume:`Comparez les grandes façons de cultiver et choisissez celle qui convient à votre terrain, votre dos et votre temps.`,materiel:[`Planches non traitées (douglas, mélèze) ou bordures`,`Carton, branches, feuilles, tontes, fumier, compost, terre`],etapes:[{titre:`Le carré potager`,texte:`Un cadre en bois de 1,2 × 1,2 m (ou 1 × 2 m) posé au sol, rempli d'un mélange de terre du jardin et de compost (moitié-moitié). Divisé en 9 ou 16 cases, chacune pour un légume différent. Idéal pour débuter, pour un petit jardin, pour un sol pauvre ou caillouteux, et sur une terrasse (posé sur une couche de drainage). Surélevé à 80 cm, il permet de jardiner sans se pencher (personnes âgées, fauteuil roulant).`,astuce:`Posez un grillage fin au fond si vous avez des taupes ou des campagnols.`},{titre:`La lasagne (culture en couches)`,texte:`Directement sur la pelouse ou un sol pauvre : carton mouillé, puis alternance de couches « brunes » (feuilles mortes, paille, broyat) et « vertes » (tontes, déchets de cuisine, fumier), terminées par 5-10 cm de compost ou de terreau. On plante tout de suite dans la couche du dessus. La lasagne s'affaisse de moitié en un an : on la recharge chaque automne. Parfaite pour démarrer un potager sur gazon sans bêcher.`},{titre:`La butte`,texte:`Un monticule de 60 cm à 1 m de haut construit sur un cœur de bois et de branches, puis de matières organiques et de terre. La butte se réchauffe vite au printemps, draine les sols lourds et humides et augmente la surface cultivable. Inconvénient : elle sèche vite en été (paillage obligatoire) et demande beaucoup de matériaux.`},{titre:`Les planches permanentes`,texte:`La méthode des maraîchers bio : des planches de 75 cm à 1,2 m de large, légèrement bombées, qu'on ne piétine jamais, ameublies à la grelinette et nourries de compost en surface chaque année. C'est la méthode la plus économique pour un potager de plus de 50 m².`},{titre:`La culture en pleine terre classique`,texte:`Rangs alignés et allées binées : simple mais plus de désherbage et de tassement. Combinée au paillage, elle reste efficace pour les grandes cultures (pommes de terre, courges, maïs).`},{titre:`Comment choisir`,texte:`Petit espace ou sol impossible : carré potager. Pelouse à transformer sans effort : lasagne. Sol lourd et humide : butte ou planches surélevées. Grand potager familial : planches permanentes. Mobilité réduite : carré ou bac surélevé. Rien n'empêche de combiner !`}],erreurs:[`Utiliser du bois traité (créosote, traverses de chemin de fer) pour les bordures : interdit pour cet usage et toxique.`,`Remplir un carré uniquement de terreau du commerce : il s'affaisse et s'épuise vite ; mélangez avec de la terre.`],video:`carré potager lasagne butte permaculture comparatif`,liens:[`creer-potager`,`compost-tas`,`paillage`]},{id:`rotation`,titre:`La rotation des cultures`,rubrique:`demarrer`,emoji:`🔄`,niveau:2,duree:`30 minutes de planification par an`,resume:`Ne pas cultiver la même famille de légumes au même endroit deux années de suite : moins de maladies, moins de ravageurs, un sol qui ne s'épuise pas.`,quand:`À planifier en hiver, avant les premiers semis.`,etapes:[{titre:`Pourquoi tourner ?`,texte:`Chaque famille de légumes puise les mêmes éléments dans le sol et attire ses propres maladies et ravageurs, qui restent dans la terre (hernie du chou, mildiou, nématodes, mouche de l'oignon…). En changeant de place, on casse leur cycle et on équilibre les besoins.`},{titre:`Classer par familles`,texte:`Solanacées (tomate, pomme de terre, aubergine, poivron) ; Cucurbitacées (courgette, courge, concombre, melon) ; Brassicacées (tous les choux, navet, radis, roquette) ; Fabacées (haricot, pois, fève) ; Apiacées (carotte, panais, céleri, persil, fenouil) ; Amaryllidacées ou alliacées (ail, oignon, poireau, échalote) ; Astéracées (laitue, artichaut) ; Amaranthacées (betterave, blette, épinard). Chaque fiche plante de l'application indique sa famille.`},{titre:`Classer par appétit`,texte:`Légumes GOURMANDS (tomates, courges, choux, poireaux, pommes de terre, maïs), MOYENS (carottes, salades, betteraves, épinards), PEU EXIGEANTS (ail, oignon, radis, mâche) et AMÉLIORANTS (haricots, pois, fèves, engrais verts) qui enrichissent le sol en azote.`},{titre:`La rotation de 4 ans`,texte:`Divisez le potager en 4 zones. Chaque année, chaque groupe avance d'une zone : 1) Gourmands sur une zone qui vient de recevoir du compost ou du fumier ; 2) Légumes-racines et feuilles moyens ; 3) Légumineuses ; 4) Peu exigeants + alliacées, puis engrais vert. Exemple : pommes de terre → carottes et salades → haricots et pois → ail, oignons, puis phacélie.`,astuce:`Le plan « Mon jardin » de l'application vérifie automatiquement vos rotations d'après l'historique de chaque planche.`},{titre:`Délais minimum à respecter`,texte:`Ne revenez pas avant : 3-4 ans pour les solanacées, 4-5 ans pour les choux (7 ans en cas de hernie), 3 ans pour les alliacées et les apiacées, 2-3 ans pour les cucurbitacées.`},{titre:`Et les vivaces ?`,texte:`Rhubarbe, artichaut, asperge, fraisiers, aromatiques vivaces restent en place plusieurs années dans une zone à part. Les fraisiers se renouvellent tous les 3-4 ans à un nouvel endroit.`}],erreurs:[`Suivre seulement le nom du légume : tomates puis pommes de terre au même endroit, c'est la même famille (mildiou).`,`Oublier les engrais verts : la moutarde est un chou (hernie).`],video:`rotation des cultures potager 4 ans explication`,liens:[`associations`,`engrais-verts`]},{id:`associations`,titre:`Associer les cultures (compagnonnage)`,rubrique:`demarrer`,emoji:`🤝`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Certaines plantes s'entraident quand elles poussent côte à côte, d'autres se gênent. Ce que l'on sait, ce qui relève de la tradition, et les associations qui marchent vraiment.`,etapes:[{titre:`Ce que dit la science, ce que dit la tradition`,texte:`Les tableaux d'associations circulent depuis des décennies. Certains effets sont démontrés (fleurs qui attirent les auxiliaires, légumineuses qui enrichissent le sol, plantes-pièges, rangs alternés qui brouillent l'odeur pour les mouches), d'autres sont des observations de jardiniers jamais testées. Considérez-les comme des pistes : votre propre observation compte.`},{titre:`Les associations solides`,texte:`Carottes et poireaux (ou oignons) en rangs alternés contre leurs mouches respectives. Les trois sœurs : maïs (tuteur), haricot grimpant (azote), courge (couvre-sol). Tomates et basilic (bon voisinage, même arrosage). Fleurs à ombelles (aneth, coriandre, carottes montées) contre les pucerons via les syrphes. Capucine à quelques mètres comme plante-piège à pucerons. Salades ou radis entre les rangs de légumes lents (carottes, poireaux) pour occuper la place.`},{titre:`Les mauvais voisinages à retenir`,texte:`Le fenouil gêne presque tous ses voisins. Les alliacées (ail, oignon, poireau) freinent la croissance des pois et haricots. Pomme de terre et tomate partagent le mildiou : pas côte à côte. Choux et fraisiers ne s'entendent pas.`},{titre:`Utiliser l'outil d'associations`,texte:`Dans l'application, choisissez les légumes que vous comptez cultiver : l'outil vous montre les bons et les mauvais voisinages et vous propose un ordre de placement.`}],video:`associations de cultures potager compagnonnage`,liens:[`rotation`]},{id:`potager-balcon`,titre:`Potager sur balcon, terrasse ou rebord de fenêtre`,rubrique:`balcon`,emoji:`🏢`,niveau:1,duree:`Une demi-journée d'installation`,resume:`Tomates cerises, fraises, salades, aromatiques et même pommes de terre : tout ce qu'il faut savoir pour récolter en appartement, en toute sécurité.`,materiel:[`Pots et jardinières percés, soucoupes`,`Terreau de qualité + compost (ou lombricompost)`,`Billes d'argile ou graviers pour le fond (facultatif)`,`Tuteurs, ficelle`,`Arrosoir à long bec, éventuellement oyas ou goutte-à-goutte`],etapes:[{titre:`Évaluer la lumière`,texte:`Exposition sud ou ouest (6 heures de soleil et plus) : tomates, poivrons, aubergines, courgettes naines, aromatiques méditerranéennes, fraises. Exposition est (soleil du matin) : salades, épinards, blettes, radis, persil, ciboulette, menthe, petits pois. Exposition nord : menthe, persil, cerfeuil, oseille, roquette, et surtout salades en été.`},{titre:`Vérifier le poids et le règlement`,texte:`La terre mouillée pèse lourd (environ 1,5 kg par litre de pot). Un balcon est dimensionné pour une charge limitée : regroupez les grands bacs le long du mur porteur, pas au bord, et renseignez-vous auprès du syndic si vous prévoyez de grands bacs. Le règlement de copropriété peut interdire les jardinières suspendues côté rue. Fixez solidement tout ce qui peut tomber.`,attention:`Jamais de pot posé sur le garde-corps sans fixation : un pot qui tombe d'un étage peut tuer.`},{titre:`Choisir des contenants assez grands`,texte:`Plus le pot est grand, moins vous arroserez. Minimum : 2-3 L pour les aromatiques, 10 L pour une salade ou des fraises, 15-20 L pour une tomate cerise, 30 L pour une tomate classique ou une courgette naine, sac de 40 L pour 3 pommes de terre. Les sacs de culture en géotextile sont légers et aèrent les racines. Évitez les pots noirs en plein soleil (racines cuites).`},{titre:`Le bon substrat`,texte:`Un terreau « potager » de qualité mélangé à 20-30 % de compost ou de lombricompost. Changez ou régénérez le substrat chaque année (moitié de compost neuf). Les plantes en pot n'ont que ce que vous leur donnez : apportez un engrais organique liquide (purin dilué, thé de crottin) tous les 15 jours en saison.`},{titre:`Choisir des variétés compactes`,texte:`Tomates cerises naines ou retombantes, poivrons et piments, aubergines naines, courgette ronde ou buissonnante, fraisiers remontants, laitues à couper, radis, blettes, haricots nains, petits pois nains, ciboulette, basilic, persil, thym, menthe. Grimpants sur treillis : haricots à rames, concombres, capucines.`},{titre:`Arroser malin`,texte:`En plein été, un pot au soleil peut demander de l'eau matin et soir. Paillez la surface des pots (paille, chanvre), utilisez des soucoupes, des oyas ou des bouteilles retournées, et regroupez les pots pour qu'ils se fassent de l'ombre. Avant de partir en vacances, voyez le tutoriel « Arroser pendant les vacances ».`},{titre:`Le vent`,texte:`En hauteur, le vent dessèche et casse. Brise-vue en canisse, tuteurs solides et plantes basses du côté exposé.`}],conseils:[`Un lombricomposteur sur le balcon fournit l'engrais de vos pots à partir de vos épluchures.`,`Les pollinisateurs montent rarement très haut : pollinisez tomates (secouez les bouquets de fleurs) et courgettes (pinceau ou fleur mâle) à la main.`],video:`potager sur balcon débutant tomates cerises pots`,liens:[`lombricompost`,`arrosage-vacances`,`herbes-interieur`]},{id:`connaitre-sol`,titre:`Connaître son sol (tests maison)`,rubrique:`sol`,emoji:`🧪`,niveau:1,duree:`1 heure + 24 heures d'attente`,resume:`Argileux, sableux, limoneux, calcaire ou acide ? Trois tests gratuits pour savoir ce que vous avez sous les pieds et comment l'améliorer.`,materiel:[`Un bocal en verre transparent avec couvercle`,`Une pelle`,`Vinaigre blanc`,`Bicarbonate de soude`,`Eau distillée ou de pluie`],etapes:[{titre:`Le test du boudin`,texte:`Prenez une poignée de terre humide (ni sèche ni détrempée), roulez-la entre vos mains. Elle ne tient pas et s'effrite : sol SABLEUX (léger, se réchauffe vite, sèche vite, retient mal les engrais). Elle forme un boudin qui se fissure quand on le courbe : sol LIMONEUX (souvent idéal, mais fait une croûte en surface). Elle forme un boudin souple qu'on peut plier en anneau : sol ARGILEUX (riche, mais lourd, collant mouillé et dur comme du béton sec).`},{titre:`Le test du bocal`,texte:`Remplissez le bocal au tiers de terre prélevée à 10-15 cm, complétez avec de l'eau, ajoutez une pincée de sel, secouez vigoureusement 2 minutes. Laissez reposer 24 heures : les couches se déposent dans l'ordre, sable au fond, limon au milieu, argile au-dessus, matière organique qui flotte. Mesurez l'épaisseur de chaque couche pour estimer les proportions.`},{titre:`Calcaire ou acide ?`,texte:`Mettez deux cuillères de terre dans deux récipients. Dans le premier, versez du vinaigre : si ça mousse, le sol est CALCAIRE (basique). Dans le second, mouillez avec de l'eau distillée et ajoutez du bicarbonate : si ça pétille, le sol est ACIDE. Rien ne se passe : sol neutre. Pour une valeur précise, un kit de pH de jardinerie ou une analyse de sol en laboratoire (40 à 80 €) donne aussi la matière organique et les éléments nutritifs.`},{titre:`Lire les plantes spontanées`,texte:`Les « mauvaises herbes » renseignent : orties et chénopodes = sol riche en azote ; prêles, renoncules, joncs = sol humide et tassé ; oseille sauvage, fougère, digitale = sol acide ; coquelicots, chicorée = sol calcaire ; mousse sur la pelouse = sol acide, tassé ou ombragé.`},{titre:`Améliorer sans tout changer`,texte:`Dans TOUS les cas, la solution est la même : de la matière organique (compost, fumier composté, paillage, engrais verts) chaque année. Elle allège les argiles, donne du corps aux sables et nourrit la vie du sol. Sol très acide : un peu de chaux ou de cendre. Sol très calcaire : compost et paillage, plantes adaptées (et les plantes de terre de bruyère en bac). Sol tassé : grelinette et racines d'engrais verts.`,attention:`Le sable ajouté à une argile fait… du béton. Améliorez une argile avec de la matière organique, pas du sable.`}],video:`test du bocal sol texture jardin`,liens:[`paillage`,`compost-tas`,`engrais-verts`]},{id:`paillage`,titre:`Le paillage : moins d'eau, moins d'herbes, plus de vie`,rubrique:`sol`,emoji:`🌾`,niveau:1,duree:`Quelques minutes par planche`,resume:`Couvrir le sol comme dans une forêt : la technique qui change le plus la vie du jardinier.`,quand:`Au printemps quand le sol est réchauffé (pas avant mai pour les légumes d'été), et en automne pour protéger le sol l'hiver.`,materiel:[`Paille, foin, tontes de gazon séchées, feuilles mortes, BRF (bois raméal fragmenté), broyat, fougères, carton, laine de mouton, chanvre ou lin (balcon)`],etapes:[{titre:`Pourquoi pailler`,texte:`Un sol nu se dessèche, se tasse sous la pluie, se fait lessiver et se couvre d'herbes. Un sol paillé garde son humidité (jusqu'à 2 à 3 fois moins d'arrosage), étouffe les herbes, nourrit les vers de terre et se transforme en humus.`},{titre:`Préparer`,texte:`Désherbez, arrosez copieusement (le paillage garde l'humidité qui est là, il n'en crée pas), attendez que le sol soit réchauffé au printemps (un paillage posé trop tôt garde le froid).`},{titre:`Étaler`,texte:`Couche de 5 à 10 cm pour les matériaux fins (tontes séchées : 2-3 cm à la fois sinon elles fermentent), 10 à 20 cm pour la paille et les feuilles. Laissez quelques centimètres autour du collet des plantes.`},{titre:`Choisir selon la culture`,texte:`Tomates, courges, fraisiers : paille ou foin. Légumes-feuilles : tontes séchées (riches en azote). Fruitiers et petits fruits : BRF, broyat, feuilles. Allées : broyat de branches ou carton recouvert. Plantes acidophiles : aiguilles de pin.`},{titre:`Entretenir`,texte:`Rechargez au fur et à mesure qu'il se décompose. En automne, couvrez les planches libres de feuilles mortes : au printemps, le sol est meuble et vivant.`}],erreurs:[`Enfouir du broyat ou du BRF frais dans la terre : sa décomposition « vole » l'azote des cultures (faim d'azote). Laissez-le en surface.`,`Pailler sous les semis de carottes : les limaces s'y cachent. Paillez une fois les plants bien levés.`,`Utiliser de la paille ou des tontes traitées aux désherbants (certains résidus déforment les tomates).`],video:`paillage potager comment pailler`,liens:[`arrosage-bien-arroser`,`limaces`]},{id:`engrais-naturels`,titre:`Nourrir son sol : engrais naturels`,rubrique:`sol`,emoji:`💩`,niveau:2,duree:`Lecture : 15 minutes`,resume:`Azote, phosphore, potasse : ce dont les plantes ont besoin, et comment le leur apporter gratuitement ou presque avec ce que produisent le jardin et les animaux.`,etapes:[{titre:`N, P, K en deux mots`,texte:`Azote (N) : les feuilles et la croissance (légumes-feuilles, choux, poireaux). Phosphore (P) : les racines et la floraison. Potasse (K) : les fleurs, les fruits et la résistance (tomates, courges, fraises). En agriculture naturelle, on nourrit le SOL (sa vie, ses vers, ses champignons) qui nourrit ensuite la plante.`},{titre:`Le compost : la base`,texte:`Compost mûr : 2 à 5 kg par m² et par an pour les gourmands, 1 à 2 kg pour les moyens, rien pour les peu exigeants. Épandu en surface ou griffé légèrement, en automne ou au printemps.`},{titre:`Les fumiers des animaux`,texte:`Fumier de poule : le plus riche, toujours composté. Lapin : utilisable directement. Mouton et chèvre : riches et chauds, à composter. Cheval et âne : pailleux, structurant. Vache : doux et équilibré. Voir le tutoriel dédié « Les fumiers de la ferme ».`,attention:`Un fumier frais enfoui au contact des racines les brûle et fait fourcher les carottes. Fumier frais = en automne, en surface, ou dans le compost.`},{titre:`Les engrais liquides maison`,texte:`Purin d'ortie (azote) pour la croissance ; purin de consoude (potasse) pour la floraison et les fruits ; thé de compost ou de crottin ; urine diluée à 10 %. Tous les 15 jours en saison pour les cultures gourmandes et les pots.`},{titre:`Les petits plus`,texte:`Cendre de bois (potasse et calcium) : une poignée par m² et par an au maximum. Coquilles d'œufs broyées (calcium, lent). Marc de café (en petite quantité, au compost de préférence). Engrais verts de légumineuses (azote gratuit).`},{titre:`Repérer les carences`,texte:`Vieilles feuilles jaunes : azote. Jeunes feuilles jaunes à nervures vertes : fer (chlorose, sol calcaire). Bord des feuilles brûlé, fruits mal colorés : potasse. Feuilles violacées : phosphore ou froid. Voir le diagnostic de l'application.`}],video:`engrais naturels potager purin compost fumier`,liens:[`compost-tas`,`fumiers`,`engrais-verts`,`purin-ortie`]},{id:`engrais-verts`,titre:`Semer des engrais verts`,rubrique:`sol`,emoji:`☘️`,niveau:1,duree:`30 minutes`,resume:`Ne laissez jamais le sol nu : des plantes semées pour nourrir et protéger la terre entre deux cultures.`,quand:`Après une récolte d'été (août-septembre) pour l'hiver, ou entre deux cultures au printemps.`,etapes:[{titre:`Choisir l'espèce`,texte:`Phacélie : la plus polyvalente, de mars à septembre, mellifère, sans famille au potager. Moutarde : très rapide, mais c'est un chou (pas avant ou après des choux). Vesce + seigle ou trèfle incarnat : couvert d'hiver qui apporte de l'azote. Sarrasin : en été, étouffe les herbes et attire les pollinisateurs. Seigle : structure les sols lourds.`},{titre:`Semer`,texte:`Griffez la surface, semez à la volée (densité sur le paquet), ratissez pour enfouir légèrement, tassez (dos du râteau ou planche) et arrosez si le temps est sec.`},{titre:`Détruire au bon moment`,texte:`Fauchez au début de la floraison (avant la formation des graines). Laissez les tiges en paillage sur place, ou incorporez superficiellement et attendez 3 semaines avant de semer ou planter (la décomposition gêne la germination).`},{titre:`Version sans outil`,texte:`Les espèces gélives (phacélie, moutarde, sarrasin) semées en fin d'été sont tuées par les gelées : au printemps, plantez directement à travers ce paillis naturel.`}],video:`engrais vert phacélie moutarde potager`,liens:[`rotation`,`paillage`]},{id:`compost-tas`,titre:`Faire un bon compost`,rubrique:`compost`,emoji:`♻️`,niveau:1,duree:`Installation : 1 heure ; compost mûr en 6 à 12 mois`,resume:`Transformer épluchures, feuilles et tontes en or noir pour le jardin. Les règles simples qui évitent les odeurs et les échecs.`,materiel:[`Un bac (bois, palettes, plastique) ou un simple tas à l'ombre, sur la terre`,`Une fourche`,`Un bioseau en cuisine`],etapes:[{titre:`Le bon emplacement`,texte:`Sur la terre nue (pour que les vers montent), à mi-ombre, à l'abri des vents, accessible avec une brouette et pas trop loin de la cuisine. Respectez une distance raisonnable avec les voisins.`},{titre:`Équilibrer vert et brun`,texte:`Les matières VERTES (humides, azotées) : épluchures, restes de légumes et de fruits, marc de café et sachets de thé, tontes fraîches, fumiers, fanes. Les matières BRUNES (sèches, carbonées) : feuilles mortes, paille, broyat de branches, carton brun déchiré, sciure non traitée. Visez environ autant de brun que de vert en volume. Gardez un stock de feuilles mortes ou de broyat à côté du composteur : à chaque seau d'épluchures, une poignée de brun.`},{titre:`Ce qui va au compost`,texte:`Tous les déchets végétaux de la cuisine et du jardin, coquilles d'œufs écrasées, litière des poules, lapins et chèvres, cendres de bois (un peu), mouchoirs et essuie-tout non imprimés.`},{titre:`Ce qui n'y va pas`,texte:`Viande, poisson, os, produits laitiers en quantité (odeurs, rats) ; excréments de chats et de chiens (parasites) ; plantes malades (mildiou, hernie, pourriture blanche) ; plantes montées en graines ou racines d'herbes envahissantes (liseron, chiendent) sauf si le compost chauffe beaucoup ; cendres de charbon et de bois traité ; papier glacé.`},{titre:`Humidité et aération`,texte:`Le compost doit être humide comme une éponge essorée : arrosez s'il est sec (il ne se décompose plus), ajoutez du brun s'il est détrempé et sent mauvais. Mélangez ou retournez les apports de surface à la fourche toutes les 2 à 4 semaines au début : l'air accélère la décomposition et évite les odeurs.`},{titre:`Récolter`,texte:`Le compost est mûr quand il est brun foncé, grumeleux, qu'il sent l'humus de sous-bois et qu'on ne reconnaît plus les matériaux (sauf quelques coquilles et brindilles). Tamisez éventuellement (grille de 1 cm) pour les semis ; les refus repartent dans le composteur. Compost « jeune » (3-4 mois) : en paillage au pied des gourmands. Compost mûr (8-12 mois) : partout, même pour les semis.`}],conseils:[`Deux ou trois bacs : un qu'on remplit, un qui mûrit, un qu'on utilise.`,`Un tas peut chauffer jusqu'à 60-70 °C en quelques jours s'il est assez grand (1 m³) et bien équilibré : il détruit alors une partie des graines et des germes.`,`Les poules adorent gratter le compost : elles y trouvent des vers et l'aèrent.`],erreurs:[`Tout en tontes de gazon : masse gluante et puante. Mélangez avec du brun.`,`Un tas sous un sapin ou dans un coin trop sec : rien ne se passe.`],video:`réussir son compost débutant vert brun`,liens:[`bac-palettes`,`lombricompost`,`bokashi`]},{id:`bac-palettes`,titre:`Fabriquer un composteur en palettes`,rubrique:`fabriquer`,emoji:`🌲`,niveau:1,duree:`1 à 2 heures`,resume:`Un composteur solide et gratuit avec 4 ou 5 palettes récupérées.`,materiel:[`4 palettes (5 pour une porte), de préférence marquées « HT » (traitement thermique) et non « MB »`,`Fil de fer galvanisé ou vis et équerres, ou colliers de serrage solides`,`Une scie, une visseuse`,`Éventuellement grillage fin pour le fond (rongeurs)`],etapes:[{titre:`Choisir les bonnes palettes`,texte:`Cherchez le tampon IPPC sur le côté : « HT » signifie traitement par la chaleur (sans danger). Évitez les palettes marquées « MB » (bromure de méthyle, ancien traitement chimique) et les palettes tachées ou de couleur (souvent des palettes de location ou ayant transporté des produits chimiques).`,attention:`Gants : échardes et clous rouillés. Vaccin antitétanique à jour.`},{titre:`Poser la base`,texte:`Désherbez un carré de 1,2 × 1,2 m sur la terre. Posez éventuellement un grillage à mailles fines au sol si vous craignez les rats.`},{titre:`Monter les côtés`,texte:`Dressez trois palettes en U et attachez-les entre elles aux angles avec du fil de fer, des vis ou des équerres. Planches horizontales à l'intérieur pour retenir le compost.`},{titre:`La façade`,texte:`La 4e palette se fixe d'un seul côté avec des charnières ou se maintient par des crochets : vous pourrez l'ouvrir pour retourner et récupérer le compost. Variante : façade en planches glissées entre deux tasseaux, à ajouter au fur et à mesure du remplissage.`},{titre:`Couvrir`,texte:`Un couvercle (vieille planche, carton épais, bâche respirante) limite le dessèchement l'été et le détrempage l'hiver.`},{titre:`Agrandir`,texte:`Avec 7 palettes, vous faites 2 bacs côte à côte qui partagent une paroi : l'un en remplissage, l'autre en maturation.`}],video:`fabriquer composteur palettes facile`,liens:[`compost-tas`]},{id:`lombricompost`,titre:`Lombricompostage en appartement`,rubrique:`compost`,emoji:`🐛`,niveau:1,duree:`Installation : 1 heure`,resume:`Composter ses épluchures dans la cuisine ou sur le balcon, sans odeur, grâce à des vers : il produit un engrais et un « thé » parfaits pour les plantes en pot.`,materiel:[`Lombricomposteur à plateaux superposés (ou 2-3 bacs en plastique opaques percés)`,`Vers de compost Eisenia fetida (ou andrei) : 250 à 500 g, en vente en ligne ou à donner par un voisin`,`Carton brun, papier journal, boîtes d'œufs déchirées (litière)`],etapes:[{titre:`Installer`,texte:`Placez le lombricomposteur à l'abri du soleil direct et du gel, entre 15 et 25 °C (cuisine, cellier, balcon abrité). Dans le premier plateau, mettez une litière de carton déchiré humidifié, puis les vers et une petite poignée d'épluchures.`},{titre:`Les bons déchets`,texte:`Épluchures de légumes et de fruits (peu d'agrumes, d'oignon et d'ail), marc de café, sachets de thé, coquilles d'œufs broyées, carton brun et papier journal déchirés. Coupez en petits morceaux : ça va beaucoup plus vite.`},{titre:`Les déchets interdits`,texte:`Viande, poisson, produits laitiers, plats huileux ou salés, et en grande quantité : agrumes, oignons, ail, poireaux, piments.`},{titre:`Nourrir progressivement`,texte:`Les vers mangent environ la moitié de leur poids par jour une fois installés : commencez petit (un bol par semaine), augmentez au fil des semaines. Recouvrez toujours les déchets d'une couche de carton humide.`},{titre:`Gérer l'humidité`,texte:`Trop humide (odeur, moucherons) : ajoutez du carton sec. Trop sec : vaporisez de l'eau. Récupérez régulièrement le liquide au robinet du bac inférieur.`},{titre:`Récolter`,texte:`Quand un plateau est plein, ajoutez-en un au-dessus avec de la nourriture : les vers montent. Au bout de 2-3 mois, le plateau du bas contient un lombricompost noir et fin, prêt à l'emploi.`},{titre:`Utiliser`,texte:`Lombricompost : 20 à 30 % du mélange de rempotage, ou en surface des pots. Liquide (« lombrithé ») : dilué 1 pour 10 en arrosage des plantes en pot et du potager.`}],erreurs:[`Mettre des vers de terre du jardin : ce ne sont pas les mêmes espèces, ils meurent dans le bac.`,`Suralimenter au début : pourriture et odeurs.`],video:`lombricomposteur appartement débuter`,liens:[`potager-balcon`,`bokashi`]},{id:`bokashi`,titre:`Le bokashi (fermentation des déchets de cuisine)`,rubrique:`compost`,emoji:`🧺`,niveau:2,duree:`2 semaines de fermentation`,resume:`Une méthode japonaise pour fermenter TOUS les déchets de cuisine, y compris un peu de viande et de laitage, dans un seau hermétique en appartement.`,materiel:[`Seau bokashi avec robinet et couvercle hermétique (ou deux seaux emboîtés)`,`Son de bokashi (son de céréales inoculé de micro-organismes efficaces)`],etapes:[{titre:`Remplir`,texte:`Déposez les déchets coupés en morceaux, tassez pour chasser l'air, saupoudrez une poignée de son, refermez hermétiquement. Recommencez à chaque apport.`},{titre:`Soutirer le jus`,texte:`Tous les 2-3 jours, récupérez le liquide par le robinet : dilué à 1 pour 100, c'est un engrais ; pur, il entretient les canalisations.`},{titre:`Laisser fermenter`,texte:`Quand le seau est plein, laissez-le fermé 2 semaines. Le contenu sent le vinaigre ou le mariné (pas la pourriture) et peut se couvrir de moisissure blanche (normal).`},{titre:`Finir au sol`,texte:`Le pré-compost est acide et n'est pas encore utilisable tel quel : enterrez-le dans une tranchée au jardin ou dans un grand bac de terre (balcon) et attendez 2 à 4 semaines avant de planter, ou ajoutez-le au composteur ou au lombricomposteur par petites quantités.`}],erreurs:[`Laisser entrer l'air : pourriture et mauvaises odeurs (moisissures noires ou vertes = raté).`],video:`bokashi compost appartement mode d'emploi`,liens:[`lombricompost`,`compost-tas`]},{id:`arrosage-bien-arroser`,titre:`Bien arroser : quand, combien, comment`,rubrique:`arrosage`,emoji:`💧`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Irrigation du potager : arroser moins souvent mais mieux, des racines profondes, des plantes plus résistantes, moins de maladies et d'eau gaspillée.`,etapes:[{titre:`Le moment`,texte:`Le matin tôt est le meilleur moment : la plante a de l'eau pour la journée et le feuillage sèche vite (moins de maladies). Le soir convient aussi en canicule, mais attire les limaces. Jamais en plein soleil sur le feuillage.`},{titre:`Au pied, pas sur les feuilles`,texte:`L'eau sur les feuilles favorise mildiou, oïdium et botrytis. Arrosez au pied, à l'arrosoir sans pomme ou au goutte-à-goutte. Exception : les salades et les semis apprécient une pluie fine.`},{titre:`La bonne quantité`,texte:`Un arrosage doit mouiller le sol sur 15 à 20 cm. Repère : environ 10 à 20 litres par m² une à deux fois par semaine en été pour un sol paillé, plus pour un sol nu et sableux. Vérifiez en creusant avec le doigt ou une petite pelle le lendemain.`},{titre:`Arroser en profondeur`,texte:`Des petits arrosages quotidiens gardent les racines en surface et rendent les plantes dépendantes. Des arrosages copieux et espacés poussent les racines à descendre chercher l'eau. « Un binage vaut deux arrosages » : briser la croûte du sol limite l'évaporation (ou paillez).`},{titre:`Repérer la soif`,texte:`Une plante qui flétrit aux heures chaudes et se redresse le soir va bien. Une plante encore flétrie le matin a soif. Les pots se vérifient au poids : un pot léger est sec.`},{titre:`Les besoins par culture`,texte:`Très gourmands en eau : salades, céleri, concombres, courgettes, choux, poireaux, fraises. Moyens : tomates, haricots, carottes. Peu : ail, oignons, aromatiques méditerranéennes, courges installées. Arrosage réduit en fin de maturation pour les tomates (goût), les melons (sucre) et l'ail/oignon (conservation).`}],conseils:[`Une eau à température ambiante (récupérateur, arrosoir rempli la veille) évite le choc thermique.`,`En période de restriction d'eau (arrêté préfectoral sécheresse), l'arrosage des potagers est souvent encore permis à certaines heures : renseignez-vous sur vigieau.gouv.fr.`],video:`comment bien arroser son potager`,liens:[`oyas`,`arrosage-vacances`,`recuperateur-pluie`,`paillage`]},{id:`oyas`,titre:`Fabriquer des oyas (arrosage par terre cuite)`,rubrique:`fabriquer`,emoji:`🏺`,niveau:1,duree:`30 minutes`,resume:`Une jarre de terre cuite poreuse enterrée près des plantes diffuse l'eau lentement, au rythme de leurs besoins : jusqu'à 50 % d'eau économisée.`,materiel:[`2 pots en terre cuite NON vernissés de même diamètre (15 à 25 cm), ou un pot et une soucoupe`,`Mastic silicone ou colle époxy compatible eau`,`Un bouchon, une capsule ou un petit galet`],etapes:[{titre:`Boucher le trou du bas`,texte:`Obturez le trou de drainage du premier pot avec du silicone (à l'intérieur et à l'extérieur), laissez sécher.`},{titre:`Assembler les deux pots`,texte:`Posez un cordon de silicone sur le bord du premier pot, collez le second pot à l'envers bord contre bord. Laissez sécher 24 heures. Le trou du pot du haut servira à remplir.`},{titre:`Enterrer`,texte:`Enterrez l'oya jusqu'au col, au milieu d'un groupe de plantes (une oya de 5 L arrose environ 1 m de diamètre), avant ou au moment de la plantation.`},{titre:`Remplir et fermer`,texte:`Remplissez d'eau par le trou (un entonnoir aide), bouchez avec un galet ou une capsule pour éviter évaporation, moustiques et noyades d'insectes. Remplissez quand elle est vide : 2 fois par semaine en été environ.`},{titre:`Hiver`,texte:`Videz et déterrez les oyas avant les gelées (l'eau gelée fait éclater la terre cuite), ou laissez-les vides en terre dans les régions douces.`}],video:`fabriquer oya pot terre cuite arrosage`,liens:[`arrosage-bien-arroser`,`arrosage-vacances`]},{id:`arrosage-vacances`,titre:`Arroser pendant les vacances (sans voisin)`,rubrique:`arrosage`,emoji:`🏖️`,niveau:1,duree:`1 heure de préparation`,resume:`Bouteilles, mèches, bassines, goutte-à-goutte avec programmateur : les solutions maison pour partir 1 à 3 semaines sans retrouver le potager grillé.`,materiel:[`Bouteilles en plastique, aiguille chaude ou clou`,`Mèches en coton ou lacets, bassine`,`Optionnel : kit goutte-à-goutte et programmateur à piles`],etapes:[{titre:`Préparer quelques jours avant`,texte:`Récoltez tout ce qui est mûr ou presque (courgettes, haricots, tomates), désherbez, paillez épais (10 cm) toutes les cultures, arrosez abondamment la veille du départ.`},{titre:`Bouteilles goutte-à-goutte`,texte:`Percez 2 ou 3 petits trous dans le bouchon d'une bouteille de 1,5 L remplie d'eau, retournez-la et enfoncez le goulot dans la terre au pied de la plante. Variante plus régulière : coupez le fond, enterrez un cône de bouteille percé et remplissez par le haut. Testez quelques jours avant de partir pour régler le débit (2 à 4 jours d'autonomie).`},{titre:`Mèches pour les pots`,texte:`Placez une bassine d'eau en hauteur au milieu des pots. Pour chaque pot, une mèche de coton (ou lacet) mouillée plongée dans la bassine et enfoncée de 5 cm dans le substrat : l'eau monte par capillarité. Testez avant.`},{titre:`Le bain de soucoupe (plantes d'intérieur)`,texte:`Regroupez les plantes dans une baignoire ou une bassine sur une couche de billes d'argile ou de serviettes mouillées avec 2-3 cm d'eau, à l'abri du soleil direct. Les pots ne doivent pas baigner (pourriture) : seulement toucher le fond humide. Éloignez-les des fenêtres plein sud.`},{titre:`Le goutte-à-goutte programmé`,texte:`Pour un potager de taille moyenne et plus de 10 jours d'absence, un kit goutte-à-goutte relié au robinet (ou au récupérateur avec une pompe) et un programmateur à piles (10 à 15 minutes tôt le matin) est l'investissement le plus fiable. Faites un essai d'une semaine avant de partir.`}],video:`arrosage automatique vacances bouteille mèche`,liens:[`oyas`,`arrosage-bien-arroser`]},{id:`recuperateur-pluie`,titre:`Installer un récupérateur d'eau de pluie`,rubrique:`arrosage`,emoji:`🌧️`,niveau:1,duree:`1 à 2 heures`,resume:`1 m² de toit = environ 600 à 900 litres d'eau gratuite par an dans la plupart des régions de France : une eau douce, idéale pour les plantes.`,materiel:[`Cuve opaque de 300 L à plusieurs m³ avec couvercle et robinet`,`Collecteur filtrant à installer sur la descente de gouttière`,`Socle stable (parpaings) pour surélever la cuve`,`Scie cloche adaptée au diamètre de la gouttière`],etapes:[{titre:`Dimensionner`,texte:`Surface du toit (au sol) × pluviométrie annuelle locale (en mètres) × 0,8 = litres récupérables. Un potager de 50 m² consomme environ 5 à 10 m³ en été : plusieurs cuves reliées entre elles ne sont pas un luxe.`},{titre:`Installer le collecteur`,texte:`Découpez la descente de gouttière à la hauteur indiquée par la notice et installez le collecteur filtrant : il remplit la cuve, retient les feuilles et renvoie le surplus dans la gouttière quand la cuve est pleine (indispensable pour éviter les débordements contre la maison).`},{titre:`Surélever la cuve`,texte:`Sur un socle stable de 40 à 50 cm : on passe un arrosoir sous le robinet et la pression est meilleure. Une cuve pleine de 1 000 L pèse une tonne : sol plan et dur.`},{titre:`Sécuriser`,texte:`Couvercle verrouillé (noyades d'enfants et d'animaux, moustiques tigres qui pondent dans l'eau stagnante). Cuve opaque (sinon les algues prolifèrent).`},{titre:`Hiverner`,texte:`En région froide, videz partiellement et ouvrez le robinet ou débranchez le collecteur avant les fortes gelées.`}],conseils:[`L'eau de pluie n'est pas potable : ne la buvez pas et ne la donnez pas à boire aux animaux sans précautions.`,`Certaines communes ou agglomérations subventionnent l'achat de récupérateurs.`],video:`installer récupérateur eau de pluie gouttière`,liens:[`arrosage-bien-arroser`]},{id:`semis-interieur`,titre:`Réussir ses semis à l'intérieur`,rubrique:`semis`,emoji:`🌱`,niveau:2,duree:`1 heure + 6 à 10 semaines de soins`,resume:`Tomates, poivrons, aubergines, choux, poireaux : produire ses plants soi-même, des centaines de variétés pour le prix d'un sachet.`,quand:`De février (aubergines, piments) à avril (courges, concombres), selon les légumes.`,materiel:[`Terreau spécial semis (fin et léger)`,`Godets, plaques alvéolées ou boîtes recyclées percées`,`Mini-serre ou film alimentaire`,`Pulvérisateur`,`Étiquettes`,`Une fenêtre très lumineuse au sud ou une lampe horticole LED`],etapes:[{titre:`Préparer`,texte:`Remplissez les contenants de terreau humide (il doit coller légèrement à la main sans goutter), tassez légèrement.`},{titre:`Semer`,texte:`Règle générale : enterrez la graine à 2 fois son épaisseur. Les très fines graines (céleri, laitue) se posent en surface et se tassent sans recouvrir. 2 ou 3 graines par godet, ou en ligne dans une caissette.`},{titre:`Chaleur pour germer`,texte:`Tomates, poivrons, aubergines, courges : 20-25 °C pour germer (dessus de frigo, tapis chauffant). Choux, laitues, poireaux : 15-18 °C suffisent. Couvrez pour garder l'humidité et vérifiez chaque jour.`},{titre:`Lumière dès la levée`,texte:`Dès que les premières pousses sortent, retirez le couvercle et donnez le maximum de lumière, à une température plus fraîche (16-18 °C). Sans lumière suffisante, les plants « filent » : tiges longues, fines, pâles, qui se couchent. Une lampe LED à 10-20 cm au-dessus, 14 heures par jour, change tout.`,astuce:`Un ventilateur doux quelques minutes par jour, ou caresser les plants de la main, les rend plus trapus.`},{titre:`Arroser par le dessous`,texte:`Posez les godets dans une soucoupe d'eau 15 minutes, puis videz. Laissez la surface sécher entre deux arrosages : c'est la meilleure prévention contre la fonte des semis.`},{titre:`Repiquer`,texte:`Au stade 2 vraies feuilles (après les 2 feuilles de germination), transplantez chaque plantule dans un godet individuel de 8-10 cm, en la tenant par une feuille (jamais par la tige). Les tomates s'enterrent jusqu'aux premières feuilles.`},{titre:`Endurcir`,texte:`1 à 2 semaines avant la plantation, sortez les plants dehors à l'ombre quelques heures, puis toute la journée, puis jour et nuit si les nuits sont douces. Sans endurcissement, les plants subissent un choc (brûlures, arrêt de croissance).`}],erreurs:[`Semer trop tôt sans assez de lumière : des plants étiolés qui végètent. Mieux vaut semer un peu plus tard.`,`Garder les plants trop longtemps en petits godets : ils durcissent et fleurissent trop tôt.`],video:`réussir semis intérieur tomates lumière repiquage`,liens:[`fonte-semis`,`creer-potager`]},{id:`semis-place`,titre:`Semer en pleine terre`,rubrique:`semis`,emoji:`🌰`,niveau:1,duree:`15 à 30 minutes par rang`,resume:`Carottes, radis, haricots, pois, betteraves, épinards : les gestes simples pour une levée régulière.`,materiel:[`Râteau`,`Cordeau`,`Serfouette ou manche d'outil pour tracer le sillon`,`Arrosoir à pomme fine`,`Planche`],etapes:[{titre:`Préparer un lit de semis`,texte:`Ameublissez la surface, retirez cailloux et herbes, émiettez au râteau jusqu'à obtenir une terre fine sur 5 cm. Le sol doit être ressuyé (il ne colle pas aux bottes) et assez réchauffé pour l'espèce (haricots : 12 °C minimum).`},{titre:`Tracer le sillon`,texte:`Tendez le cordeau, tracez un sillon à la bonne profondeur (indiquée sur chaque fiche plante), mouillez le fond du sillon avant de semer si la terre est sèche.`},{titre:`Semer clair`,texte:`Répartissez les graines régulièrement, sans les entasser. Graines fines : mélangez-les à du sable sec pour mieux les répartir. Grosses graines (haricots, pois, fèves) : en poquets ou une à une.`},{titre:`Recouvrir et tasser`,texte:`Refermez le sillon avec le dos du râteau, tassez avec le plat du râteau ou une planche pour que la graine soit en contact avec la terre humide. Arrosez en pluie fine. Étiquetez !`},{titre:`Jusqu'à la levée`,texte:`La surface ne doit jamais sécher (carottes surtout) : arrosages légers et fréquents, ou une planche/un carton posé sur le rang, à retirer dès la levée. Protégez des oiseaux (voile).`},{titre:`Éclaircir`,texte:`Quand les plantules ont 2-3 feuilles, supprimez les plants en trop pour laisser l'espacement final. C'est douloureux mais indispensable : des plants serrés restent petits. Les jeunes pousses éclaircies (radis, betteraves, roquette) se mangent en salade.`}],video:`semer en pleine terre carottes radis sillon`,liens:[`semis-interieur`]},{id:`graines-maison`,titre:`Récolter et conserver ses graines`,rubrique:`semis`,emoji:`🏺`,niveau:2,duree:`Selon les espèces`,resume:`Devenir autonome en semences, garder ses variétés préférées adaptées à son jardin, et échanger avec d'autres jardiniers.`,etapes:[{titre:`Variétés reproductibles uniquement`,texte:`Les variétés « F1 » (hybrides) ne redonnent pas des plantes identiques. Gardez les graines de variétés anciennes, « population » ou « libres de droits ».`},{titre:`Le plus facile pour commencer`,texte:`Tomates, haricots, pois, laitues, poivrons : elles s'autofécondent et se croisent peu. Choisissez les plus beaux pieds, sains et productifs, comme porte-graines.`},{titre:`Graines sèches`,texte:`Haricots, pois, laitues, radis, aromatiques : laissez sécher sur pied, récoltez par temps sec, finissez de sécher à l'abri 2 à 3 semaines, battez et triez (vannage au vent ou au sèche-cheveux froid).`},{titre:`Graines humides`,texte:`Tomates, concombres : prélevez les graines d'un fruit très mûr, laissez fermenter 2-3 jours dans un peu d'eau (le mucilage qui empêche la germination se dégrade), rincez dans une passoire, séchez sur une assiette (pas sur du papier absorbant, elles collent). Courges et melons : lavez et séchez simplement.`},{titre:`Éviter les croisements`,texte:`Courges d'une même espèce, maïs, choux, betteraves, carottes, oignons se croisent par les insectes ou le vent : il faut isoler les variétés (distance, voile, ensachage des fleurs) ou n'en cultiver qu'une par espèce.`},{titre:`Conserver`,texte:`Au sec, au frais et à l'obscurité, en enveloppes papier étiquetées (espèce, variété, année) rangées dans une boîte hermétique avec un sachet de riz sec ou de gel de silice. La durée de germination varie : 1 an pour le panais, 2 pour le poireau et l'oignon, 3-4 pour la carotte et la tomate, 5-6 pour les courges et le concombre. L'application suit votre stock de graines.`},{titre:`Tester la germination`,texte:`Pour des graines anciennes : posez 10 graines sur un essuie-tout humide dans une boîte fermée au chaud. Comptez les germées au bout de 7-10 jours pour connaître le taux de réussite.`}],video:`récolter ses graines tomates haricots conserver`,liens:[`semis-interieur`]},{id:`bouturage`,titre:`Bouturer : multiplier gratuitement`,rubrique:`semis`,emoji:`✂️`,niveau:1,duree:`15 minutes`,resume:`Aromatiques, plantes d'intérieur, petits fruits, géraniums : faire de nouvelles plantes à partir d'un morceau de tige.`,materiel:[`Sécateur ou couteau propre et affûté`,`Petits pots, terreau mélangé à du sable`,`Sachet plastique transparent`,`Optionnel : eau de saule (hormone d'enracinement naturelle)`],etapes:[{titre:`Le bon moment`,texte:`Boutures herbacées (basilic, menthe, pothos, géranium) : printemps-été. Semi-aoûtées (thym, romarin, lavande, sauge) : fin d'été. Bois sec (groseillier, cassis, figuier, vigne, saule) : en hiver, pendant le repos.`},{titre:`Prélever`,texte:`Coupez une tige saine, sans fleur, de 10 à 15 cm, juste sous un nœud (renflement d'où partent les feuilles). Retirez les feuilles du bas et coupez les grandes feuilles restantes en deux pour limiter l'évaporation.`},{titre:`Mettre à raciner`,texte:`Dans l'eau (pothos, menthe, basilic, saule) ou dans un mélange terreau-sable humide, enterré aux deux tiers. Couvrez d'un sachet transparent (mini-serre), à la lumière sans soleil direct.`},{titre:`L'eau de saule`,texte:`Faites tremper 24 heures des rameaux de saule coupés en morceaux dans de l'eau : elle contient des substances qui favorisent l'enracinement. Arrosez-en vos boutures.`},{titre:`Repiquer`,texte:`Quand de nouvelles feuilles apparaissent et qu'une légère traction rencontre une résistance (racines), retirez le sachet progressivement puis rempotez.`},{titre:`Boutures de bois sec`,texte:`En hiver, coupez des rameaux de l'année de 20-25 cm, enterrez-les aux deux tiers en pleine terre, dans un coin abrité. Ils racinent au printemps et se transplantent l'automne suivant.`}],video:`bouturage facile plantes aromatiques eau de saule`,liens:[`graines-maison`]},{id:`taille-fruitiers`,titre:`Tailler les arbres fruitiers (les bases)`,rubrique:`recolte`,emoji:`🔧`,niveau:2,duree:`30 minutes à 2 heures par arbre`,resume:`Une taille légère et raisonnée pour des arbres sains et productifs : quand, quoi couper, et surtout ce qu'il ne faut pas faire.`,quand:`Fruitiers à pépins (pommier, poirier) : en hiver hors gel. Fruitiers à noyau (cerisier, prunier, abricotier) : en fin d'été, après la récolte. Pêcher : à la floraison.`,materiel:[`Sécateur bien affûté et propre`,`Coupe-branches, scie d'élagage`,`Alcool pour désinfecter les lames entre deux arbres`,`Mastic à cicatriser ou argile pour les grosses coupes`],etapes:[{titre:`Les 4 D d'abord`,texte:`Supprimez le bois Mort, Malade, Mal placé (branches qui se croisent, qui frottent, qui partent vers le centre) et les gourmands Droits (rejets verticaux vigoureux qui poussent sur les branches).`},{titre:`Aérer le centre`,texte:`La lumière et l'air doivent pénétrer jusqu'au cœur de l'arbre : moins de maladies, des fruits mieux colorés. Une forme en gobelet (centre ouvert) convient à la plupart des fruitiers de jardin.`},{titre:`Bien couper`,texte:`Coupez juste au-dessus d'un bourgeon tourné vers l'extérieur, en biais, à 5 mm. Pour une branche entière, coupez au ras du bourrelet à la base (sans l'entailler) : c'est lui qui cicatrise.`},{titre:`Reconnaître les bourgeons`,texte:`Sur le pommier et le poirier : bourgeons à bois fins et pointus (feuilles), boutons à fleurs gros et ronds (fruits). Conservez les rameaux courts porteurs de boutons à fleurs (les « lambourdes »).`},{titre:`Ne pas trop tailler`,texte:`Une taille sévère provoque une avalanche de gourmands et moins de fruits. Ne retirez jamais plus d'un quart à un tiers du volume par an. Un vieil arbre négligé se rajeunit en 3 hivers.`}],erreurs:[`Tailler les cerisiers et pruniers en hiver (gommose et maladies).`,`Laisser des chicots (moignons de branches) : ils pourrissent.`,`Tailler par temps de gel ou de pluie.`],video:`taille pommier hiver débutant explication`,liens:[`chancre`]},{id:`greffe`,titre:`Greffer un arbre fruitier`,rubrique:`recolte`,emoji:`🌳`,niveau:3,duree:`15 minutes par greffe`,resume:`Ajouter une variété sur un arbre existant ou créer un fruitier sur un porte-greffe : les deux greffes les plus simples.`,quand:`Greffe en fente : fin d'hiver (février-mars), greffons prélevés en décembre-janvier et gardés au frais. Greffe en écusson : juillet-août.`,materiel:[`Greffoir ou cutter très affûté et propre`,`Rafia ou élastiques de greffe`,`Mastic à greffer`,`Greffons (rameaux d'un an de la variété voulue)`],etapes:[{titre:`Préparer les greffons`,texte:`En plein hiver, prélevez des rameaux d'un an, de la grosseur d'un crayon, sur l'arbre de la variété désirée. Conservez-les en sachet humide au réfrigérateur.`},{titre:`Greffe en fente`,texte:`Coupez la branche porte-greffe (2-5 cm de diamètre) bien net. Fendez-la au centre sur 4 cm. Taillez la base du greffon (3 yeux) en biseau double comme un coin. Insérez-le en bordure de la fente, de façon que l'écorce (et surtout la couche verte juste dessous, le cambium) du greffon touche celle du porte-greffe. Ligaturez et masticquez toutes les plaies.`},{titre:`Greffe en écusson`,texte:`En été, quand l'écorce se décolle bien : faites une incision en T sur le porte-greffe, prélevez un bourgeon (œil) avec un fin lambeau d'écorce sur la variété voulue, glissez-le sous l'écorce soulevée, ligaturez sans couvrir l'œil. Au printemps suivant, coupez le porte-greffe juste au-dessus de l'œil qui a pris.`},{titre:`Compatibilité`,texte:`Greffez entre espèces proches : pommier sur pommier, poirier sur poirier ou cognassier, prunier sur prunier, pêcher sur prunier ou amandier.`}],video:`greffe en fente pommier tuto`,liens:[`taille-fruitiers`]}],E=[{id:`serre`,titre:`Cultiver sous serre`,rubrique:`serre`,emoji:`🏡`,niveau:2,duree:`Toute la saison`,resume:`Une serre allonge la saison de 2 mois de chaque côté, protège tomates et melons de la pluie et du mildiou, et permet les semis précoces. À condition de bien la gérer : la chaleur et l'humidité y deviennent vite des ennemies.`,materiel:[`Serre tunnel (bâche) ou serre en polycarbonate/verre`,`Thermomètre mini-maxi`,`Ombrage (filet ou blanc d'Espagne)`,`Récupérateur d'eau à proximité`],etapes:[{titre:`Choisir et placer`,texte:`Orientation : le faîte orienté est-ouest pour un maximum de lumière en hiver ; en plein soleil, à l'abri des vents forts, sur un sol drainé. Une serre tunnel de 10 à 20 m² est un bon début. Le polycarbonate double paroi isole mieux que le verre simple. Ancrez solidement (une serre s'envole facilement).`,attention:`Une serre de plus de 5 m² (et moins de 1,80 m de haut) ou de plus de 1,80 m de haut peut nécessiter une déclaration préalable en mairie selon sa surface et votre commune : renseignez-vous.`},{titre:`Aérer, aérer, aérer`,texte:`Au soleil, une serre fermée dépasse 40-50 °C en quelques minutes, même en avril : les plantes cuisent et les fleurs avortent au-dessus de 32-35 °C. Ouvrez portes et aérations dès que le soleil est là, refermez le soir. Les ouvre-fenêtres automatiques (vérin à cire, sans électricité) sont précieux.`},{titre:`Ombrer l'été`,texte:`De juin à août, posez un filet d'ombrage ou badigeonnez le côté sud de blanc d'Espagne (craie) qui partira avec les pluies d'automne.`},{titre:`Le calendrier de la serre`,texte:`Fin d'hiver : semis précoces, salades, radis, épinards. Printemps : plants de tomates, poivrons, aubergines, concombres, melons (plantation 3-4 semaines plus tôt qu'en plein air). Été : légumes d'été et basilic. Automne-hiver : mâche, laitues d'hiver, épinards, blettes, oignons blancs, fèves, aromatiques en pot à l'abri.`},{titre:`Arroser et nourrir`,texte:`Il ne pleut jamais sous serre : arrosage régulier au goutte-à-goutte ou aux oyas, paillage, compost généreux. Le sol s'épuise plus vite qu'en plein air : apport de compost chaque année et rotation (tomates pas toujours au même endroit, ou en grands pots/sacs).`},{titre:`Surveiller les ravageurs`,texte:`Araignées rouges, aleurodes, pucerons et thrips adorent la chaleur sèche : bassinez les allées le matin, inspectez sous les feuilles, accueillez les auxiliaires (portes ouvertes en journée) ou lâchez-en (vendus en ligne).`},{titre:`Protéger du froid`,texte:`En hiver, un voile d'hivernage double à l'intérieur gagne 2 à 4 °C. Des bidons d'eau peints en noir stockent la chaleur du jour. Pour les nuits de gel fort, un petit chauffage hors gel (à bougies ou électrique homologué) protège les semis. Le compost en fermentation (couche chaude) placé sous les semis chauffe naturellement.`}],erreurs:[`Oublier d'ouvrir un matin de soleil : toute la production grillée.`,`Arroser le feuillage le soir : botrytis et mildiou.`],video:`bien utiliser une serre potager aération`,liens:[`chassis`,`semis-interieur`,`tetranyque`]},{id:`chassis`,titre:`Fabriquer un châssis froid ou une mini-serre`,rubrique:`fabriquer`,emoji:`🏙️`,niveau:1,duree:`2 heures`,resume:`Une vieille fenêtre et quelques planches suffisent pour avancer les semis et protéger les salades d'hiver.`,materiel:[`Une vieille fenêtre vitrée ou une plaque de polycarbonate`,`Planches non traitées`,`Vis, charnières`,`Tasseau pour caler l'ouverture`],etapes:[{titre:`Le caisson`,texte:`Assemblez un cadre aux dimensions de la fenêtre, plus haut à l'arrière (40 cm) qu'à l'avant (25 cm) pour capter le soleil et évacuer la pluie. Orientez la pente vers le sud.`},{titre:`Le couvercle`,texte:`Fixez la fenêtre à l'arrière par des charnières. Un tasseau cranté permet de l'entrouvrir pour l'aération.`},{titre:`Utilisation`,texte:`Posé sur une planche du potager, il permet de semer salades, radis, épinards, carottes hâtives 4 à 6 semaines plus tôt, et de protéger mâche et laitues d'hiver. Aérez par temps ensoleillé, fermez les nuits froides.`},{titre:`Couche chaude`,texte:`Pour des semis très précoces : creusez 40 cm, remplissez de fumier de cheval frais pailleux tassé, couvrez de 15 cm de terreau. La fermentation chauffe le substrat pendant plusieurs semaines.`},{titre:`Version sans bricolage`,texte:`Un tunnel de voile (arceaux + voile P17) ou des bouteilles en plastique coupées posées sur les jeunes plants (« cloches ») offrent aussi 2 à 3 °C de protection.`}],video:`fabriquer châssis froid vieille fenêtre potager`,liens:[`serre`]},{id:`plantes-interieur-bases`,titre:`Plantes d'intérieur : les 5 règles d'or`,rubrique:`interieur`,emoji:`🌿`,niveau:1,duree:`Lecture : 10 minutes`,resume:`La plupart des plantes d'intérieur meurent d'excès d'eau ou de manque de lumière. Ces règles simples suffisent à en garder la majorité en pleine forme.`,etapes:[{titre:`1. La lumière d'abord`,texte:`Avant d'acheter, regardez où la plante va vivre. À 1 m d'une fenêtre sud ou ouest : plantes de lumière (cactus, succulentes, yucca, agrumes, ficus). Près d'une fenêtre est : la majorité des plantes vertes. Pièce sombre ou fenêtre nord : pothos, sansevieria, ZZ, aspidistra, kentia, spathiphyllum. La lumière baisse très vite en s'éloignant de la fenêtre.`},{titre:`2. Arroser selon le besoin, pas selon le calendrier`,texte:`Enfoncez le doigt dans la terre : sec sur 2-3 cm, arrosez ; humide, attendez. Arrosez à fond jusqu'à ce que l'eau s'écoule par le trou, puis videz la soucoupe ou le cache-pot après 15-30 minutes. En hiver, la plupart des plantes boivent 2 à 3 fois moins.`},{titre:`3. Toujours un trou de drainage`,texte:`Un pot sans trou = racines qui pourrissent. Gardez le pot de culture en plastique percé dans un cache-pot décoratif.`},{titre:`4. L'humidité de l'air`,texte:`Le chauffage assèche l'air (souvent moins de 30 % d'humidité en hiver). Éloignez les plantes des radiateurs, groupez-les, posez-les sur un plateau de billes d'argile mouillées. La brumisation a un effet très bref.`},{titre:`5. Nourrir au printemps et en été seulement`,texte:`Engrais liquide organique dilué une fois par mois d'avril à septembre (ou lombrithé). Pas d'engrais en hiver, ni sur une plante fraîchement rempotée ou malade.`},{titre:`Bonus : observer les feuilles`,texte:`Jaunes et molles : trop d'eau. Sèches et cassantes au bout : air sec ou eau calcaire. Pâles et tiges longues : manque de lumière. Taches beiges brûlées : trop de soleil direct. Collantes : insectes. Le diagnostic de l'application vous guide.`}],conseils:[`Vérifiez la toxicité pour vos animaux de compagnie : chaque fiche l'indique (les lys sont mortels pour les chats, même le pollen).`],video:`plantes d'intérieur entretien débutant arrosage lumière`,liens:[`rempoter`,`pourriture-racines`]},{id:`rempoter`,titre:`Rempoter une plante`,rubrique:`interieur`,emoji:`💧`,niveau:1,duree:`20 minutes`,resume:`Quand, comment et dans quoi rempoter sans stresser la plante.`,quand:`Au printemps (mars-mai), quand les racines sortent par le trou du pot ou tournent en rond autour de la motte, tous les 1 à 3 ans.`,materiel:[`Pot de 2 à 4 cm de diamètre de plus (pas plus !)`,`Terreau adapté (plantes vertes, cactées, orchidées, agrumes…)`,`Billes d'argile ou tesson pour le fond (facultatif)`,`Journal pour protéger la table`],etapes:[{titre:`Arroser la veille`,texte:`Une motte légèrement humide se démoule mieux et souffre moins.`},{titre:`Dépoter`,texte:`Retournez le pot en tenant la base de la plante entre vos doigts, tapotez le bord. Si ça résiste, passez un couteau le long de la paroi.`},{titre:`Démêler`,texte:`Défaites doucement les racines qui tournent en rond, coupez les racines mortes (brunes et molles). Retirez un peu de vieille terre en surface.`},{titre:`Replanter`,texte:`Un peu de terreau au fond, posez la motte au même niveau qu'avant (pas plus enterrée), comblez sur les côtés en tassant légèrement, laissez 1-2 cm sous le bord pour l'arrosage.`},{titre:`Arroser et laisser reposer`,texte:`Arrosez pour tasser la terre, placez à l'ombre lumineuse une semaine, pas d'engrais pendant un mois (le terreau neuf en contient).`},{titre:`Surfaçage pour les grandes plantes`,texte:`Un gros sujet difficile à rempoter : retirez chaque printemps 3 à 5 cm de terre en surface et remplacez-la par du terreau neuf mélangé à du compost.`}],video:`rempoter plante intérieur étapes`,liens:[`plantes-interieur-bases`]},{id:`herbes-interieur`,titre:`Aromatiques et micro-pousses en cuisine`,rubrique:`interieur`,emoji:`🌿`,niveau:1,duree:`15 minutes + 1 à 3 semaines`,resume:`Basilic, persil, ciboulette sur le rebord de la fenêtre, et micro-pousses (radis, moutarde, roquette, pois, tournesol) récoltées en 10 jours toute l'année, même sans jardin.`,materiel:[`Pots percés et soucoupes, terreau`,`Plateau peu profond, terreau ou fibre de coco (micro-pousses)`,`Graines non traitées (bio de préférence)`,`Optionnel : lampe LED horticole`],etapes:[{titre:`Les aromatiques faciles en intérieur`,texte:`Ciboulette, persil, menthe, basilic (été), coriandre (semis réguliers), thym et romarin (au soleil). Placez-les à la fenêtre la plus lumineuse : l'hiver, une lampe LED 12 h par jour fait la différence.`},{titre:`Sauver le basilic du supermarché`,texte:`Divisez la motte en 3 ou 4 touffes, rempotez chacune dans un pot plus grand, arrosez, placez au soleil. Pincez les têtes régulièrement.`},{titre:`Les micro-pousses`,texte:`Remplissez un plateau de 3 cm de terreau humide, semez dru (les graines se touchent presque), tassez, couvrez 2-3 jours à l'obscurité, puis mettez à la lumière. Arrosez en vaporisant. Récoltez aux ciseaux en 7 à 14 jours, au stade 2 feuilles : radis, moutarde, roquette, chou rouge, pois (pousses), tournesol, cresson.`},{titre:`Les graines germées (sans terre)`,texte:`Dans un bocal avec couvercle grillagé : faites tremper la nuit, rincez et égouttez 2 fois par jour, tête en bas. Lentilles, alfalfa, radis, mungo, en 3 à 6 jours.`}],conseils:[`Hygiène des graines germées : rincez bien, consommez rapidement, jetez tout ce qui sent mauvais ou moisit ; déconseillées crues aux femmes enceintes, jeunes enfants et personnes immunodéprimées (risque bactérien).`],video:`micro-pousses intérieur facile plateau`,liens:[`potager-balcon`]},{id:`hotel-insectes`,titre:`Accueillir les auxiliaires : hôtel à insectes, nichoirs, mare`,rubrique:`fabriquer`,emoji:`🐞`,niveau:1,duree:`2 heures`,resume:`Un jardin vivant se défend tout seul : coccinelles, syrphes, mésanges, hérissons, crapauds font le travail si on leur offre gîte et couvert.`,materiel:[`Planches non traitées, tiges creuses (bambou, sureau, roseau), bûches percées, pommes de pin, paille`,`Nichoir à mésange (trou de 28 à 32 mm)`,`Bâche ou bac pour une mini-mare`],etapes:[{titre:`L'hôtel à insectes`,texte:`Une caisse de bois avec un toit, remplie de compartiments : bûches de bois dur percées de trous de 3 à 10 mm (abeilles solitaires), tiges creuses coupées net, paille (chrysopes), pommes de pin. Placez-le au soleil, abrité de la pluie, tourné vers le sud-est, à 1 m du sol, près de fleurs.`,astuce:`Plusieurs petits abris valent mieux qu'un grand hôtel décoratif. Un fagot de tiges creuses attaché à une clôture suffit.`},{titre:`Les nichoirs`,texte:`Posez-les en automne ou en hiver, à 2-3 m de haut, trou orienté sud-est, hors de portée des chats. Un couple de mésanges nourrit sa nichée de milliers de chenilles.`},{titre:`Le refuge à hérisson`,texte:`Un tas de bois et de feuilles dans un coin tranquille, ou une caisse retournée avec une entrée de 13 cm. Ouvrez des passages de 13 × 13 cm dans les clôtures.`},{titre:`La mini-mare`,texte:`Un bac ou une bâche enterrée avec une pente douce d'un côté (pour que les animaux puissent sortir), des pierres, des plantes aquatiques, sans poissons. Crapauds, grenouilles, libellules arrivent seuls en quelques mois et mangent limaces et moustiques.`,attention:`Sécurisez toute mare pour les jeunes enfants (grille, clôture) : un enfant peut se noyer dans 20 cm d'eau.`},{titre:`Fleurs pour toute l'année`,texte:`Des fleurs de février à novembre : saules et noisetiers (fin d'hiver), fruitiers, phacélie, bourrache, souci, aromatiques en fleurs, lavande, lierre (automne). Laissez fleurir quelques légumes (poireaux, carottes, radis).`}],video:`hôtel à insectes efficace auxiliaires jardin`,liens:[`pucerons`,`limaces`]},{id:`carre-potager-diy`,titre:`Construire un carré potager (ou un bac surélevé)`,rubrique:`fabriquer`,emoji:`🔨`,niveau:1,duree:`2 à 3 heures`,resume:`Un carré de 1,2 m de côté en planches, ou un bac surélevé à hauteur de taille pour jardiner sans se baisser.`,materiel:[`4 planches de 1,2 m × 20 cm × 2,7 cm (douglas, mélèze ou robinier non traités) par étage`,`4 tasseaux carrés de 5 cm pour les angles`,`Vis inox ou galvanisées, visseuse`,`Carton brun, grillage fin (taupes)`,`Terre, compost, broyat`],etapes:[{titre:`Assembler`,texte:`Vissez les planches sur les tasseaux d'angle (2 vis par planche et par angle). Pour un bac surélevé de 80 cm, empilez 4 étages et ajoutez des renforts au milieu des longueurs.`},{titre:`Préparer le sol`,texte:`Posez le cadre bien de niveau, sur un sol désherbé ou sur du carton si c'est de l'herbe. Grillage au fond contre les taupes et campagnols.`},{titre:`Remplir en couches`,texte:`Pour un bac haut : branches et broyat au fond (drainage, économie de terre), puis feuilles et déchets verts, puis 25-30 cm d'un mélange terre + compost (moitié-moitié) en surface. Pour un carré au sol : directement le mélange terre-compost.`},{titre:`Quadriller`,texte:`Tendez des ficelles pour former 9 ou 16 cases. Une case = une variété : un pied de tomate ou de courgette, 4 salades, 9 poireaux, 16 radis ou carottes.`}],erreurs:[`Bois traité autoclave classe 4 ou traverses de chemin de fer : à proscrire pour un potager.`],video:`construire carré potager bois facile`,liens:[`methodes-culture`]},{id:`conserver-recoltes`,titre:`Conserver ses récoltes (sans conserves)`,rubrique:`recolte`,emoji:`🧺`,niveau:1,duree:`Variable`,resume:`Cave, silo, séchage, congélation : les méthodes simples pour manger son potager tout l'hiver.`,etapes:[{titre:`La cave ou le cellier`,texte:`Frais (4-10 °C), sombre, aéré, humide pour les racines. Pommes de terre en cagettes dans le noir ; carottes, betteraves, céleri-rave, panais dans des caisses de sable légèrement humide, fanes coupées ; pommes et poires sur des clayettes sans se toucher, à l'écart des légumes (elles dégagent de l'éthylène qui fait germer les pommes de terre).`},{titre:`Le grenier sec`,texte:`Ail, oignons, échalotes tressés ou en filets, courges et potirons (12-15 °C), haricots secs, noix, graines : au sec et à l'abri du gel.`},{titre:`Le silo au jardin`,texte:`Sans cave : creusez une fosse de 40 cm dans un endroit drainé, tapissez de paille, empilez les légumes racines, recouvrez de paille puis de 20 cm de terre, avec une cheminée de paille pour l'aération. Grillage fin contre les rongeurs.`},{titre:`Laisser en terre`,texte:`Poireaux, panais, topinambours, choux d'hiver, carottes (sol léger, sous paillage), mâche : on récolte au fur et à mesure tout l'hiver.`},{titre:`Le séchage`,texte:`Aromatiques en bouquets tête en bas à l'ombre ; tomates, pommes, poires, prunes, champignons en tranches au déshydrateur ou au four à 50-60 °C porte entrouverte, ou au soleil sous une moustiquaire dans le Midi. Conservation en bocaux secs.`},{titre:`La congélation`,texte:`La plupart des légumes se blanchissent avant congélation (2 à 4 minutes dans l'eau bouillante puis bain glacé) pour stopper les enzymes : haricots, petits pois, choux, épinards, brocolis. Sans blanchiment : poivrons, oignons, herbes, petits fruits (congelés à plat sur un plateau puis en sachet), tomates entières pour la cuisson, courgettes râpées. Étiquetez et datez.`}],video:`conserver légumes hiver cave silo`,liens:[`bocaux`,`lactofermentation`]},{id:`bocaux`,titre:`Conserves en bocaux : stériliser sans risque`,rubrique:`recolte`,emoji:`🏺`,niveau:2,duree:`2 à 4 heures`,resume:`Coulis, haricots, ratatouille, confitures : la méthode sûre pour des conserves qui se gardent des mois, et la vérité sur le botulisme.`,materiel:[`Bocaux à joint caoutchouc neuf (type Le Parfait) ou à capsule neuve`,`Stérilisateur ou grande marmite avec grille au fond + thermomètre`,`Entonnoir, pince à bocaux`],etapes:[{titre:`Comprendre le risque`,texte:`Le botulisme est une intoxication rare mais grave, voire mortelle, due à une toxine produite par une bactérie (Clostridium botulinum) dans les conserves PEU ACIDES (haricots, petits pois, asperges, champignons, viandes, poissons) mal stérilisées. Les conserves acides (fruits, confitures, cornichons au vinaigre) sont beaucoup moins à risque. Les tomates sont à la limite : ajoutez toujours 2 cuillères à soupe de jus de citron par litre.`,attention:`Jetez sans goûter tout bocal bombé, qui pétille, sent mauvais, dont le joint ne tient plus ou dont le liquide est trouble. Ne goûtez jamais pour « vérifier ».`},{titre:`Préparer`,texte:`Lavez les bocaux à l'eau chaude savonneuse, rincez. Joints neufs à chaque fois (ébouillantés 1 minute). Légumes frais, sains, lavés, coupés.`},{titre:`Remplir`,texte:`Remplissez en laissant 2 cm de vide sous le couvercle. Couvrez de liquide (eau salée à 10 g/L pour les légumes, sirop pour les fruits). Essuyez soigneusement les bords, fermez.`},{titre:`Stériliser`,texte:`Placez les bocaux dans le stérilisateur, couvrez d'eau jusqu'aux couvercles. Comptez le temps À PARTIR DE L'ÉBULLITION (100 °C) : coulis de tomates acidifié 35 à 40 min, tomates entières acidifiées 1 h 10 à 1 h 25, fruits et compotes 20 à 30 min, haricots verts et légumes peu acides 1 h 30 à 2 h. Le tableau complet par produit et taille de bocal est dans la page Conserver.`,attention:`Pour les légumes peu acides et la viande, les autorités sanitaires de plusieurs pays recommandent un autoclave (stérilisation sous pression à 115-121 °C), seul capable de détruire les spores. À 100 °C, la sécurité repose sur un temps très long et sur un stockage au frais : en cas de doute, congelez plutôt.`},{titre:`Refroidir et vérifier`,texte:`Laissez refroidir dans l'eau ou sur un torchon. Le lendemain, vérifiez que chaque couvercle est bien hermétique (le joint tient en soulevant le bocal par le couvercle, la capsule ne fait pas « clic-clac »). Un bocal non scellé se met au réfrigérateur et se consomme vite.`},{titre:`Stocker`,texte:`Au frais (moins de 20 °C), à l'obscurité, étiquetés et datés. À consommer dans l'année.`}],video:`stérilisation bocaux maison méthode sûre`,liens:[`cs-securite`,`cs-temps`,`conserver-recoltes`,`lactofermentation`]},{id:`lactofermentation`,titre:`La lacto-fermentation (choucroute, pickles)`,rubrique:`recolte`,emoji:`🥒`,niveau:1,duree:`30 minutes + 3 à 6 semaines`,resume:`La plus ancienne et la plus simple des conserves, sans cuisson : du sel, des légumes, et les bonnes bactéries font le reste.`,materiel:[`Bocaux à joint (ou pot à choucroute)`,`Sel non iodé, sans antiagglomérant (sel gris, sel de mer)`,`Un poids (petit pot rempli d'eau, galet bouilli)`],etapes:[{titre:`Choisir les légumes`,texte:`Chou (choucroute), carottes, betteraves, radis, haricots verts, chou-fleur, cornichons, navets, poivrons, oignons. Ils doivent être très frais et non traités.`},{titre:`Préparer la saumure ou saler`,texte:`Légumes râpés ou émincés (choucroute) : 15 à 20 g de sel par kg, malaxez jusqu'à ce qu'ils rendent leur jus. Légumes en morceaux : saumure de 30 g de sel par litre d'eau non chlorée.`},{titre:`Tasser et immerger`,texte:`Tassez dans le bocal, les légumes doivent être entièrement sous le liquide (un poids les maintient), 2-3 cm de vide en haut. Aromates : ail, laurier, aneth, graines de moutarde, baies de genièvre.`},{titre:`Fermenter`,texte:`Fermez, laissez 3 à 7 jours à température ambiante (18-22 °C) : des bulles apparaissent (normal, le bocal peut « baver »). Puis stockez au frais (cave, réfrigérateur) au moins 3 semaines avant de déguster. Conservation plusieurs mois au frais.`},{titre:`Reconnaître un échec`,texte:`Une fine pellicule blanche en surface (levures) s'enlève. Une moisissure colorée ou duveteuse, une odeur de pourri ou des légumes mous et visqueux : jetez.`}],video:`lactofermentation légumes débutant bocal saumure`,liens:[`bocaux`,`conserver-recoltes`]},{id:`securite-jardin`,titre:`Jardiner en sécurité`,rubrique:`securite`,emoji:`⛑️`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Tétanos, tiques, dos, coups de chaleur, outils, enfants : les précautions qu'on oublie et qui évitent les vrais accidents.`,etapes:[{titre:`Le tétanos`,texte:`La bactérie du tétanos vit dans la terre et le fumier. Une simple écorchure peut suffire. Vérifiez que votre vaccin est à jour (rappel à 25, 45 et 65 ans, puis tous les 10 ans en France) : c'est la mesure de sécurité la plus importante pour un jardinier et un éleveur.`},{titre:`Les tiques`,texte:`Elles transmettent la maladie de Lyme. Après le jardin, les prés ou le soin des animaux, inspectez-vous (aisselles, aine, derrière les genoux, cuir chevelu des enfants). Retirez une tique au tire-tique, sans produit, en tournant. Surveillez la zone 30 jours : une plaque rouge qui s'étend = consultez.`},{titre:`Le dos`,texte:`Pliez les genoux, pas le dos ; utilisez une brouette ; alternez les tâches ; préférez la grelinette à la bêche ; installez des bacs surélevés si besoin.`},{titre:`Chaleur et soleil`,texte:`Jardinez tôt le matin ou le soir en été, chapeau, eau, crème solaire. Le coup de chaleur arrive vite quand on est penché au soleil.`},{titre:`Les outils`,texte:`Gants, chaussures fermées, lunettes pour la taille et la débroussailleuse. Ne laissez jamais un râteau dents vers le haut. Rangez sécateurs et outils tranchants hors de portée des enfants.`},{titre:`Produits et préparations`,texte:`Même naturels (cuivre, soufre, purins), stockez-les étiquetés, hors de portée des enfants et des animaux, jamais dans une bouteille alimentaire.`},{titre:`Piqûres et allergies`,texte:`Guêpes et frelons près des fruits mûrs et des ruches : en cas de gonflement du visage, de gêne respiratoire ou de malaise, appelez le 15 ou le 112 immédiatement.`},{titre:`Les enfants`,texte:`Clôturez mares, récupérateurs d'eau et bassins. Apprenez-leur à ne rien goûter sans demander. Gardez le numéro du centre antipoison de votre région dans votre téléphone.`}],video:`sécurité au jardin tétanos tiques conseils`,liens:[`plantes-toxiques`]},{id:`plantes-toxiques`,titre:`Plantes toxiques : enfants, chiens, chats et animaux de la ferme`,rubrique:`securite`,emoji:`☠️`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Les plantes du jardin et de la maison qui peuvent tuer ou rendre gravement malade, et qu'il faut éloigner des enfants, des animaux de compagnie et des enclos.`,etapes:[{titre:`Les plus dangereuses au jardin`,texte:`If (feuillage et graines mortels pour l'humain et tous les animaux, notamment chevaux, ânes, ruminants), laurier-rose, laurier-cerise, digitale, aconit, colchique, datura, ricin, ciguës (confusion avec persil, cerfeuil, carotte sauvage), muguet, belladone, morelle noire, séneçon de Jacobée (mortel pour les chevaux et ânes, même sec dans le foin), glycine (graines).`},{titre:`Dans la maison`,texte:`Pour les CHATS, tous les lys (Lilium, Hemerocallis) sont mortels même à très petite dose (pollen léché sur le pelage) : insuffisance rénale. Également toxiques : dieffenbachia, philodendron, pothos, monstera, spathiphyllum, poinsettia (irritant), cyclamen, aloe vera (ingéré), ficus (irritant), dracaena. Non toxiques : chlorophytum, kentia, calathea, pilea, fougère de Boston, orchidée phalaenopsis.`},{titre:`Pour les animaux de la ferme`,texte:`Évitez dans et autour des enclos : if, laurier-rose, laurier-cerise, rhododendron et azalée, pieris, buis, thuya, fougère aigle, érable sycomore (chevaux et ânes), feuilles fanées de cerisier, prunier et pêcher, glands en grande quantité, tontes de gazon, déchets de taille de haie non identifiés. Ne jetez jamais vos déchets de taille par-dessus la clôture d'un pré.`},{titre:`Au potager`,texte:`Feuilles et tiges de tomates et pommes de terre, tubercules verdis ou germés, feuilles de rhubarbe, haricots crus, baies d'asperge, fruits de la morelle, courges amères.`},{titre:`En cas d'ingestion`,texte:`Ne faites pas vomir. Appelez le centre antipoison (numéros régionaux, ou le 15) avec la plante ou une photo. Pour un animal, appelez votre vétérinaire ou un centre antipoison vétérinaire (CAPAE, CNITV).`}],video:`plantes toxiques jardin enfants animaux`,liens:[`securite-jardin`]},{id:`voisinage-regles`,titre:`Règles à connaître : voisins, eau, déchets verts`,rubrique:`securite`,emoji:`⚖️`,niveau:1,duree:`Lecture : 5 minutes`,resume:`Distances de plantation, branches qui dépassent, brûlage, arrêtés sécheresse, animaux : ce que dit la loi en France pour éviter les conflits.`,etapes:[{titre:`Distances de plantation`,texte:`Sauf règlement local ou usage contraire (article 671 du Code civil) : les arbres et haies de plus de 2 m de haut doivent être plantés à au moins 2 m de la limite de propriété ; ceux de moins de 2 m, à au moins 50 cm. Le voisin peut exiger que vous coupiez les branches qui dépassent chez lui ; il peut ramasser les fruits tombés naturellement sur son terrain, mais pas cueillir ceux de vos branches.`},{titre:`Brûlage interdit`,texte:`Le brûlage des déchets verts à l'air libre est interdit pour les particuliers (pollution aux particules fines), sauf dérogation préfectorale. Solutions : compost, broyage (location ou prêt de broyeur par la commune), paillage, déchetterie.`},{titre:`Sécheresse`,texte:`En période de restriction d'eau, des arrêtés préfectoraux limitent l'arrosage des jardins (souvent interdit en journée). Consultez vigieau.gouv.fr. L'eau de pluie récupérée n'est en général pas concernée.`},{titre:`Animaux`,texte:`Déclarations obligatoires : volailles en mairie, chèvres/moutons/porcs à l'EDE, ânes et chevaux à l'IFCE, ruches chaque année. Les fiches animaux de l'application détaillent chaque cas.`},{titre:`Bruits`,texte:`Tondeuses et outils bruyants : des horaires sont fixés par arrêté municipal ou préfectoral (souvent interdits le dimanche après-midi et les jours fériés) : renseignez-vous en mairie.`}],video:`distance plantation voisin loi haie`,liens:[`securite-jardin`]}],D=[{id:`poulailler`,titre:`Choisir ou construire son poulailler`,rubrique:`animaux`,emoji:`🏠`,niveau:2,duree:`1 à 3 week-ends (construction)`,resume:`Un poulailler sain, facile à nettoyer et imprenable par le renard : les dimensions, les matériaux et les détails qui comptent vraiment.`,materiel:[`Ossature bois non traité ou traité sans arsenic, panneaux, tôles ou bardeaux`,`Grillage à mailles fines (13 mm) pour les ouvertures, pas du grillage à poules hexagonal (le renard et la fouine le déchirent)`,`Perchoirs en bois, pondoirs`,`Porte automatique (option fortement conseillée)`],etapes:[{titre:`Les bonnes dimensions`,texte:`Comptez au moins 1 m² au sol pour 3 poules à l'intérieur (plus si elles restent enfermées par mauvais temps ou en cas de confinement aviaire), 20-25 cm de perchoir par poule, un pondoir de 30 × 30 cm pour 4-5 poules. Hauteur suffisante pour que VOUS puissiez nettoyer facilement : c'est ce qui fera la différence sur des années.`},{titre:`Aération sans courant d'air`,texte:`Les poules supportent bien le froid mais pas l'humidité ni l'ammoniac des fientes. Prévoyez des ouvertures grillagées en haut des murs (au-dessus des perchoirs), jamais un courant d'air au niveau des oiseaux. Une odeur d'ammoniac à l'entrée = ventilation insuffisante ou litière trop humide.`},{titre:`Contre les prédateurs`,texte:`Renard, fouine, martre, rat, chien errant, rapace pour les jeunes. Toutes les ouvertures en grillage soudé à petites mailles, porte qui ferme avec un loquet à double action (le raton laveur et la fouine ouvrent les loquets simples), plancher surélevé ou dalle, grillage enterré de 30-40 cm autour du parcours ou rabattu en L sur 50 cm à l'extérieur. Fermez CHAQUE soir : la plupart des attaques ont lieu au crépuscule ou à l'aube.`},{titre:`Contre les poux rouges`,texte:`Le moins de recoins possible : perchoirs posés sur des supports amovibles (pas cloués), bois lisse, parois accessibles. Les poulaillers en plastique recyclé ou en métal sont plus faciles à traiter, mais plus chauds en été.`},{titre:`Facile à nettoyer`,texte:`Une grande porte d'accès, une planche à fientes amovible sous les perchoirs (on la gratte chaque semaine : les fientes vont au compost), des pondoirs accessibles de l'extérieur pour ramasser les œufs sans entrer.`},{titre:`Le parcours`,texte:`Au moins 10 m² par poule, idéalement divisé en 2 ou 3 parcelles qu'on alterne toutes les quelques semaines pour que l'herbe repousse et que les parasites diminuent. Des arbres ou arbustes pour l'ombre et l'abri contre les rapaces. Un bac à poussière couvert.`},{titre:`Prévoir le confinement`,texte:`En période d'influenza aviaire à risque élevé, les volailles doivent être mises à l'abri ou sous filet : prévoyez dès la construction une partie du parcours couvrable (filet, toit) pour qu'elles ne restent pas enfermées des semaines à l'intérieur.`}],erreurs:[`Acheter un poulailler en kit « pour 6 poules » qui en loge à peine 3 confortablement.`,`Grillage à poules hexagonal comme seule protection.`],video:`construire poulailler anti renard plan`,liens:[`poule`]},{id:`couvaison`,titre:`Couvaison et élevage des poussins`,rubrique:`animaux`,emoji:`🐣`,niveau:2,duree:`21 jours + 6 à 8 semaines`,resume:`Faire naître ses poussins avec une poule couveuse ou une couveuse électrique, et les élever jusqu'à l'âge adulte.`,materiel:[`Poule couveuse OU couveuse électrique avec retournement automatique et hygrométrie`,`Œufs fécondés (coq présent)`,`Poussinière : caisse, lampe chauffante ou plaque chauffante, thermomètre`,`Aliment démarrage poussin, abreuvoir à poussins (peu profond)`],etapes:[{titre:`Choisir les œufs`,texte:`Propres naturellement (ne les lavez pas), de forme normale, de moins de 7 jours, conservés pointe en bas à 12-15 °C.`},{titre:`Avec une poule couveuse`,texte:`Isolez-la dans un nid calme et sombre avec eau et nourriture à portée, glissez les œufs le soir (8 à 12 selon sa taille). Elle se lève 1 à 2 fois par jour pour manger et faire ses besoins : c'est normal. Marquez les œufs au crayon pour repérer ceux qu'une autre poule viendrait ajouter.`},{titre:`Avec une couveuse`,texte:`Température 37,5-37,8 °C, humidité 45-55 % les 18 premiers jours, retournement plusieurs fois par jour (automatique). À J18 : arrêtez le retournement et montez l'humidité à 65-70 % pour l'éclosion. N'ouvrez plus la couveuse jusqu'à l'éclosion.`},{titre:`Mirer`,texte:`À J7 et J14, dans le noir, une lampe puissante contre l'œuf : un réseau de vaisseaux et une tache sombre = embryon vivant ; œuf clair = non fécondé (à retirer) ; anneau de sang = embryon mort (à retirer).`},{titre:`L'éclosion`,texte:`Vers le 21e jour (poule), 28 (cane), 30 (oie), 17-18 (caille). Le poussin perce d'abord la coquille (bêchage) puis peut mettre 12 à 24 heures à sortir. N'aidez pas, sauf blocage manifeste de plus de 24 h (et avec beaucoup de précaution).`},{titre:`La poussinière`,texte:`Si la poule n'élève pas ses petits : chaleur de 35 °C sous la lampe la 1re semaine, puis 3 °C de moins chaque semaine, jusqu'à 20 °C environ à 5-6 semaines. Observez : poussins entassés sous la lampe = froid ; écartés et haletants = trop chaud. Aliment démarrage à volonté, eau dans un abreuvoir peu profond (ajoutez des cailloux pour éviter les noyades). Litière de copeaux (pas de papier journal glissant : pattes écartées).`},{titre:`Mise dehors et intégration`,texte:`Sorties au soleil dès 3-4 semaines par beau temps, en enclos protégé (rats, chats, rapaces). Intégration au troupeau adulte vers 8-10 semaines, progressive, d'abord à travers un grillage.`},{titre:`Les coqs en surnombre`,texte:`Il naît environ autant de coqs que de poules. Prévoyez leur devenir à l'avance : poulets de chair (voir le tutoriel), échange, don. Un trop grand nombre de coqs provoque bagarres et stress pour les poules.`}],video:`couveuse œufs poussins éclosion débutant`,liens:[`poule`,`poulailler`,`abattage-volaille`]},{id:`integrer-animaux`,titre:`Accueillir de nouveaux animaux sans risque`,rubrique:`animaux`,emoji:`🧳`,niveau:1,duree:`2 à 3 semaines de quarantaine`,resume:`La quarantaine et l'introduction progressive évitent d'importer maladies et parasites et limitent les bagarres.`,etapes:[{titre:`Acheter malin`,texte:`Chez un éleveur qui montre ses installations, des animaux vifs, propres, au plumage ou pelage brillant, sans écoulement des yeux ou du nez, sans diarrhée. Demandez l'âge, les vaccins (Marek pour les poules, myxomatose/VHD pour les lapins), les vermifuges, et pour les ruminants les documents (boucles, attestation sanitaire).`},{titre:`Quarantaine`,texte:`2 à 3 semaines dans un espace séparé (sans contact direct ni partage d'eau), soignés APRÈS vos animaux, avec des bottes dédiées. Observez l'appétit, les crottes, la respiration, recherchez les poux. Une coproscopie pendant la quarantaine est une excellente idée.`},{titre:`Introduire les volailles`,texte:`D'abord côte à côte, séparées par un grillage, quelques jours. Puis réunies dans le parcours, avec plusieurs mangeoires et abreuvoirs et des cachettes. Les bagarres pour la hiérarchie (« ordre de becquée ») durent quelques jours ; séparez seulement en cas de blessure (le sang attire les coups de bec).`},{titre:`Introduire les ruminants`,texte:`Jamais un animal seul : chèvres et moutons ont besoin d'au moins un congénère. Présentation à travers une clôture, puis dans un grand espace neutre.`}],video:`quarantaine nouvelles poules intégration`,liens:[`poule`,`chevre`]},{id:`cultiver-pour-animaux`,titre:`Cultiver pour nourrir ses animaux`,rubrique:`animaux`,emoji:`🌽`,niveau:2,duree:`Toute l'année`,resume:`Réduire la facture d'aliment et boucler le cycle : le jardin nourrit les animaux, les animaux nourrissent le jardin. Ce que l'on peut cultiver, et les limites.`,etapes:[{titre:`Garder une base équilibrée`,texte:`Pour les volailles, le jardin complète mais remplace rarement totalement un aliment équilibré : les protéines et le calcium sont les points faibles. Pour les herbivores (lapins, chèvres, moutons, ânes), le foin reste la base et les légumes un complément. Toute nouvelle nourriture s'introduit progressivement.`},{titre:`Pour les volailles`,texte:`Maïs grain (énergie), féverole et pois secs (protéines, concassés), tournesol (graines grasses pour la mue), sarrasin, blé ou orge sur une petite parcelle, courges et potirons (se gardent tout l'hiver), choux fourragers et kale (verdure d'hiver), amarante. Lombricompost : les vers sont une friandise protéinée (avec modération).`},{titre:`Pour les lapins`,texte:`Une prairie fleurie à faucher (graminées, trèfle, plantain, pissenlit), luzerne (riche, à doser), fanes de carottes, feuilles de framboisier, chicorée, persil, céleri, branchages de saule, pommier, noisetier. Séchez une partie en foin pour l'hiver.`},{titre:`Pour chèvres et moutons`,texte:`Betteraves fourragères et topinambours (racines d'hiver), choux fourragers, courges, haies fourragères (saule, frêne, mûrier blanc, noisetier, orme) taillées en têtard : on coupe les branches feuillues en été pour les donner en vert ou les sécher (« fagots de feuilles », pratique ancienne précieuse en sécheresse).`},{titre:`Les arbres fourragers`,texte:`Mûrier blanc, saule, frêne, robinier (feuilles, avec prudence : écorce toxique), féviers, noisetiers : plantés en haie autour des parcs, ils donnent ombre et fourrage pendant les étés secs où l'herbe grille.`},{titre:`Ce qu'il ne faut pas faire`,texte:`Donner en masse un seul aliment (diarrhées, carences, acidose chez les ruminants), donner des restes de cuisine cuisinés ou contenant viande et poisson (interdit et dangereux), donner des végétaux moisis ou fermentés, des tontes de gazon en tas, ou les plantes listées comme interdites dans chaque fiche animal.`}],video:`nourrir ses poules avec le jardin autonomie`,liens:[`poule`,`lapin`,`chevre`,`mouton`]},{id:`fumiers`,titre:`Les fumiers de la ferme : lequel, comment, quand`,rubrique:`animaux`,emoji:`💩`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Chaque animal produit un engrais différent. Comment les composter, les doser et les utiliser au potager sans brûler les plantes ni risquer la santé.`,etapes:[{titre:`Fumier de poules, pintades, cailles, canards`,texte:`Le plus concentré (azote et phosphore). Jamais frais au contact des plantes : il brûle. Composté 6 mois minimum avec beaucoup de carbone (la litière de paille ou de copeaux suffit souvent). 1 à 2 kg de compost de fumier par m² pour les gourmands. La litière profonde du poulailler, vidée une ou deux fois par an, est déjà à moitié compostée.`},{titre:`Crottin de lapin`,texte:`Équilibré, sec, sans risque de brûlure : utilisable directement en surface, au pied des cultures et dans les pots. Le meilleur fumier pour débuter.`},{titre:`Fumier de chèvre et de mouton`,texte:`Riche, « chaud » (il chauffe en compostage), excellent pour les cultures gourmandes et le compost. Composté 3 à 6 mois, ou épandu frais à l'automne sur les planches vides.`},{titre:`Crottin d'âne et de cheval`,texte:`Plus pauvre mais très fibreux : il structure les sols lourds et les sols sableux. Frais et pailleux, il sert à faire des couches chaudes. Composté, il s'utilise partout. Attention aux vermifuges récents (attendez 2-3 semaines après traitement : certains tuent les insectes du sol).`},{titre:`Fumier de porc et de vache`,texte:`Porc : riche et humide, à composter longuement (parasites). Vache (souvent disponible chez un agriculteur voisin) : doux, équilibré, le fumier « universel ».`},{titre:`Hygiène`,texte:`Les fumiers contiennent des germes (salmonelles, E. coli, parasites). Compostage complet, gants, lavage des mains, pas d'apport frais sur des légumes consommés crus dans les 4 mois avant la récolte, légumes lavés.`},{titre:`Le purin de fumier`,texte:`Une pelletée de fumier dans un sac de jute plongé dans 10 L d'eau pendant une semaine : un « thé » à diluer à 10 % pour arroser les cultures gourmandes et les pots.`}],video:`quel fumier pour le potager poule lapin cheval`,liens:[`compost-tas`,`engrais-naturels`]},{id:`animaux-auxiliaires`,titre:`Les animaux contre les parasites (et les parasites des animaux)`,rubrique:`animaux`,emoji:`🛡️`,niveau:2,duree:`Lecture : 10 minutes`,resume:`Utiliser les animaux pour protéger le jardin, et le jardin pour protéger les animaux : ce qui marche vraiment et ce qui relève de la croyance.`,etapes:[{titre:`Poules sous les fruitiers`,texte:`Elles mangent les fruits tombés véreux, les larves de carpocapse, de mouches des fruits, de balanins et de nombreux insectes qui passent l'hiver au sol, et fertilisent. Résultat mesuré dans les vergers : moins de dégâts de certains ravageurs. Protégez le pied des jeunes arbres (grattage).`},{titre:`Canards contre les limaces`,texte:`Les canards coureurs indiens fouillent et mangent limaces et escargots. Parcours le soir ou tôt le matin dans le potager (en évitant les semis et jeunes salades), ou dans les allées.`},{titre:`Pintades contre les tiques et insectes`,texte:`Elles chassent tiques, criquets, insectes du sol et même jeunes serpents et rongeurs. Utiles autour des maisons en zone à tiques.`},{titre:`Poules après la récolte`,texte:`Un « tracteur à poules » (enclos mobile) posé sur une planche récoltée : en quelques jours, larves de taupins, vers blancs, noctuelles, graines d'herbes et restes de culture disparaissent, et le sol est fertilisé. Retirez-les avant de replanter.`},{titre:`Pâturage alterné ou mixte`,texte:`Les moutons, chèvres, ânes et chevaux ne partagent pas les mêmes vers digestifs : faire pâturer une parcelle successivement par des espèces différentes « nettoie » les larves présentes dans l'herbe. La rotation des parcelles (changer de parc toutes les 3 à 6 semaines, et ne pas y revenir avant 6 à 8 semaines) est la base de la lutte contre les parasites des herbivores.`},{titre:`Plantes utiles contre les parasites des animaux`,texte:`Démontré : le sainfoin et la chicorée, riches en tanins, réduisent l'infestation par les strongles chez les moutons et les chèvres quand ils font partie de la ration. Traditionnels, à l'effet léger ou non prouvé : ail, graines de courge, thym, absinthe. Aucun ne remplace une coproscopie et un vermifuge prescrit quand l'infestation est réelle.`,attention:`Une plante « naturelle » peut être toxique : l'absinthe et la tanaisie données en excès sont dangereuses. Demandez conseil à votre vétérinaire.`},{titre:`Contre les poux et acariens des volailles`,texte:`Le bain de poussière (terre fine + cendre de bois) est leur défense naturelle. Plantes aromatiques séchées dans les nids (lavande, menthe, thym, tanaisie) : effet répulsif modeste. La terre de diatomée sur les perchoirs et dans les fissures aide (évitez de la respirer, et elle perd son efficacité mouillée). Les poux rouges en forte infestation demandent un traitement vétérinaire.`},{titre:`Les produits des animaux contre les ravageurs du jardin`,texte:`Laine de mouton non lavée en paillage : retient l'eau, gêne les limaces et se décompose en azote. Cendre du poêle (à partir du bois) en barrière sèche. Les pièges à guêpes ne doivent pas être appâtés avec de la viande près des animaux (attire les mouches).`}],video:`poules verger carpocapse canards limaces permaculture`,liens:[`poule`,`canard`,`pintade`,`mouton`]},{id:`oeufs`,titre:`Ramasser, conserver et utiliser ses œufs`,rubrique:`animaux`,emoji:`🥚`,niveau:1,duree:`Lecture : 5 minutes`,resume:`Fraîcheur, lavage, conservation, congélation et anomalies : tout savoir sur les œufs de la basse-cour.`,etapes:[{titre:`Ramasser souvent`,texte:`Au moins une fois par jour, deux fois en été : œufs plus propres, moins de casse, et les poules ne prennent pas l'habitude de les picorer. Des nids propres garnis de paille fraîche donnent des œufs propres.`},{titre:`Ne pas laver (sauf exception)`,texte:`Un œuf est couvert d'une fine pellicule protectrice (cuticule) qui bloque les bactéries. Un œuf propre non lavé se conserve 3 à 4 semaines à température ambiante stable (moins de 20 °C), pointe en bas. Un œuf sale peut être brossé à sec ; s'il faut le laver, lavez-le juste avant de l'utiliser, ou mettez-le au réfrigérateur et consommez-le vite.`},{titre:`Tester la fraîcheur`,texte:`Dans un bol d'eau froide : l'œuf frais reste couché au fond ; à plat avec la pointe qui se relève : quelques semaines, à cuire ; debout ou flottant : à jeter. Cassé, un œuf frais a un blanc épais qui se tient et un jaune bombé.`},{titre:`Les surplus du printemps`,texte:`Congelez les œufs sans coquille : battus légèrement avec une pincée de sel (salé) ou de sucre (sucré), ou blancs et jaunes séparés, en bacs à glaçons. Jusqu'à 10 mois. Ou faites des pâtes fraîches à sécher, des crèmes, des meringues.`},{titre:`Anomalies sans gravité`,texte:`Double jaune (jeune poule), petite tache de sang (vaisseau éclaté, comestible), coquille rugueuse ou décolorée (âge, stress).`},{titre:`Anomalies à surveiller`,texte:`Coquilles molles ou absentes répétées : manque de calcium, stress, chaleur ou maladie (vérifiez les coquilles d'huîtres à volonté). Arrêt brutal de ponte hors mue et hiver : stress, prédateur, parasites, maladie. Œufs picorés : ennui, manque de protéines ou de calcium, nids trop éclairés.`},{titre:`Vendre ou donner`,texte:`Donner quelques œufs à ses proches est courant. La vente, même occasionnelle sur un marché, est encadrée (déclaration, marquage, règles sanitaires) : renseignez-vous auprès de la DDPP.`}],video:`conserver œufs poules non lavés fraîcheur`,liens:[`poule`]},{id:`fumiers-securite`,titre:`Fumiers sans risque : désherbants du foin, vermifuges, germes`,rubrique:`animaux`,emoji:`⚠️`,niveau:2,duree:`Lecture : 10 minutes`,resume:`Les angles morts de l'utilisation des déjections au potager : un fumier peut contenir des résidus qui détruisent les tomates pendant des années, des médicaments toxiques pour la vie du sol, ou des germes. Les règles et le test simple qui évitent les mauvaises surprises.`,etapes:[{titre:`Les désherbants persistants du foin`,texte:`Certains désherbants utilisés sur les prairies et les céréales (familles des pyridines : aminopyralide, clopyralide, picloram) traversent l'animal et restent actifs dans le fumier et même dans le compost pendant des mois ou des années. Résultat : tomates, pommes de terre, haricots, pois aux feuilles enroulées et tordues, qui ne produisent plus. Demandez toujours au fournisseur de foin, de paille ou de fumier s'il a été traité.`,attention:`Ces résidus ne sont pas détruits par le compostage. En cas de doute, faites le test des haricots avant d'utiliser un fumier ou une paille achetés.`},{titre:`Le test des haricots (ou des pois)`,texte:`Remplissez deux pots : l'un de terreau seul, l'autre de terreau mélangé à moitié avec le fumier à tester. Semez 3 haricots dans chacun. Au bout de 3 semaines, si les feuilles du pot « fumier » sont enroulées en cuillère, tordues ou décolorées alors que l'autre pot est normal, n'utilisez pas ce fumier au potager (utilisez-le au pied des arbres, des haies ou des graminées).`},{titre:`Les vermifuges`,texte:`Certains vermifuges (ivermectine et apparentés) passent dans les crottins pendant plusieurs semaines et tuent les bousiers et la faune du sol. Notez la date des traitements dans « Mon jardin → Animaux » et attendez au moins 3 à 4 semaines avant d'utiliser le fumier frais ; le compostage en dégrade une partie.`},{titre:`Les germes`,texte:`Salmonelles, E. coli, parasites : compostez toujours les fumiers de volailles, de porc et de ruminants (6 mois, idéalement un tas qui chauffe) ; aucun fumier frais sur des légumes consommés crus dans les 4 mois précédant la récolte ; gants, lavage des mains, légumes lavés.`,attention:`Jamais de déjections de chiens, de chats ou humaines (hors toilettes sèches gérées selon les règles) au potager : parasites dangereux (toxoplasmose, toxocarose).`},{titre:`Combien en mettre ?`,texte:`Le tableau des fumiers donne une dose par m² et par an. Repère simple : une brouette (60 L) de fumier composté pour 10 m² de légumes gourmands chaque automne ; deux fois moins pour les légumes moyens ; rien pour l'ail, l'oignon et les légumineuses. L'excès d'azote attire les pucerons et rend les légumes plus fragiles.`},{titre:`Stocker le fumier`,texte:`En tas couvert (bâche respirante ou paille) sur un sol plat, loin des puits, des fossés et des cours d'eau (les jus polluent l'eau), et à distance des voisins. Le jus qui s'écoule (purin) est un engrais : recueillez-le dans un bac et diluez-le à 10 %.`}],video:`fumier aminopyralide test haricots compost désherbant persistant`,liens:[`fumiers`,`compost-tas`,`cheval`,`mouton`]},{id:`repulsifs-animaux`,titre:`Les produits des animaux contre les nuisibles : ce qui marche vraiment`,rubrique:`animaux`,emoji:`🧶`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Laine, crottins, cendres, poils, coquilles, purins : ce que la basse-cour et les animaux apportent pour protéger le jardin, en distinguant ce qui est démontré de ce qui relève de la tradition.`,etapes:[{titre:`Démontré ou largement observé`,texte:`Laine de mouton en paillage ou en granulés : barrière qui gêne les limaces et garde l'humidité, puis se décompose en azote. Poules sous les fruitiers et en « tracteur » : moins de larves de carpocapse, de taupins, de vers blancs. Canards coureurs : grands mangeurs de limaces. Pintades : tiques et insectes. Pâturage alterné (moutons, ânes, chevaux) : casse le cycle des vers digestifs. Chicorée et sainfoin dans la ration des ruminants : moins de strongles.`},{titre:`Utile en barrière, à renouveler`,texte:`Cendre du poêle (bois non traité) et coquilles d'œufs broyées : barrière sèche contre les limaces, efficace seulement au sec (à renouveler après chaque pluie) ; la cendre apporte aussi de la potasse (une poignée par m² et par an, pas plus).`},{titre:`Tradition, effet limité ou variable`,texte:`Poils, cheveux ou laine accrochés aux arbres contre les chevreuils et les lapins sauvages ; urine ou crottin répandus pour éloigner les rongeurs ; sang séché contre les lapins : effet faible et de courte durée, à combiner avec une vraie protection (grillage, manchons, clôture). Le purin de fientes n'éloigne pas les ravageurs : c'est un engrais.`},{titre:`Ce qu'il ne faut pas faire`,texte:`Répandre de la viande, des abats ou des déchets d'abattage au jardin (rats, renards, maladies), utiliser les excréments des chiens ou des chats, ou laisser des animaux malades au contact du potager.`},{titre:`Le bon équilibre`,texte:`Les animaux protègent le jardin… et peuvent le ravager : poules, chèvres, oies et cochons doivent être tenus hors des cultures en place (clôtures), et n'y entrer qu'aux moments choisis (après récolte, sous les arbres, en hiver).`}],video:`laine de mouton limaces poules verger canards coureurs limaces`,liens:[`animaux-auxiliaires`,`fumiers`,`limaces`,`carpocapse`,`cendre`]},{id:`abattage-volaille`,titre:`Abattre et préparer une volaille de la basse-cour`,rubrique:`boucherie`,emoji:`🔪`,niveau:3,duree:`45 minutes à 1 heure 30 par oiseau`,sensible:!0,resume:`La méthode complète et respectueuse : préparation, étourdissement, saignée, échaudage, plumage, éviscération, retrait du fiel, refroidissement et repos de la viande. À lire en entier avant de commencer.`,quand:`Coqs de chair entre 4 et 6 mois (races mixtes) ou 12 à 16 semaines (races à croissance rapide). Poules de réforme à tout âge (viande pour bouillon et pot-au-feu). Par temps frais si possible, le matin.`,materiel:[`Un couteau très affûté (lame fine de 12-15 cm) et un fusil à affûter`,`Un bâton court et lourd (étourdissement) ou un matériel d'étourdissement adapté`,`Un cône d'abattage (cône métallique, seau ou bidon découpé fixé à un poteau) au-dessus d'un seau`,`Une grande marmite d'eau à 60-65 °C et un thermomètre de cuisine`,`Une table lavable, des planches à découper propres, des seaux, des sacs poubelle`,`Une bassine d'eau glacée (glaçons) ou un réfrigérateur libre`,`Gants, tablier, de l'eau propre en abondance`],etapes:[{titre:`Avant tout : la loi et le respect`,texte:`En France, vous pouvez abattre vous-même vos volailles et lapins pour la consommation de votre seule famille (abattage familial). La viande ne peut être ni vendue ni donnée hors du foyer. La loi impose d'épargner à l'animal toute douleur, détresse ou souffrance évitable : un geste rapide et sûr, et un étourdissement préalable, sont la façon de le respecter. Si c'est votre première fois, faites-vous montrer le geste par quelqu'un d'expérimenté (éleveur, voisin, association). Hésiter ou rater fait souffrir l'animal.`,attention:`Ne jamais abattre un animal malade, traité récemment (respectez le délai d'attente du médicament indiqué par le vétérinaire) ou mort de cause inconnue.`},{titre:`La veille : la diète`,texte:`Retirez la nourriture 12 à 24 heures avant (laissez l'eau à volonté). Jabot et intestins vides rendent l'éviscération beaucoup plus propre. Isolez calmement l'oiseau la veille au soir, dans un endroit sombre et tranquille : un animal calme a une meilleure viande (le stress durcit la chair).`},{titre:`Préparer le poste`,texte:`Installez tout AVANT d'aller chercher l'oiseau : cône fixé solidement, seau dessous, eau d'échaudage à température, table propre, eau glacée. Rien ne doit vous obliger à interrompre la suite des gestes. Travaillez à l'écart des autres animaux et hors de la vue des enfants qui ne le souhaitent pas.`},{titre:`Tenir et étourdir`,texte:`Prenez l'oiseau calmement, ailes maintenues contre le corps, parlez doucement. Placez-le tête en bas dans le cône : la position inversée le calme et la tête sort par le bas. Étourdissez-le immédiatement par un coup sec et franc derrière la tête (base du crâne) avec le bâton : l'oiseau perd conscience. Enchaînez sans délai.`,attention:`L'étourdissement est temporaire : la saignée doit suivre dans les secondes qui suivent.`},{titre:`Saigner`,texte:`Tenez la tête d'une main, tirez-la légèrement vers le bas. Avec la pointe du couteau, incisez profondément sur le côté du cou, juste sous la mâchoire, derrière l'oreille, pour sectionner la veine jugulaire et l'artère carotide (vous pouvez faire l'incision des deux côtés). Ne coupez pas la trachée ni la colonne vertébrale (la tête ne doit pas tomber à ce stade : le cœur doit continuer à pomper pour une bonne saignée). Laissez saigner 1 à 2 minutes dans le cône.`,astuce:`Des battements d'ailes et des convulsions peuvent survenir pendant une minute : ce sont des réflexes nerveux, l'oiseau est inconscient. Le cône empêche les blessures et les éclaboussures.`},{titre:`Échauder`,texte:`Plongez l'oiseau entier, tenu par les pattes, dans l'eau à 60-65 °C pendant 30 à 60 secondes, en l'agitant de haut en bas pour que l'eau pénètre jusqu'à la peau. Testez : si les grandes plumes des ailes et de la queue s'arrachent facilement, c'est prêt. Trop chaud ou trop long, la peau cuit et se déchire ; pas assez, les plumes résistent (replongez 10 secondes).`,astuce:`Canards et oies : leur plumage est imperméable. Ajoutez quelques gouttes de liquide vaisselle à l'eau (70 °C environ) et prolongez, ou plumez à sec pour récupérer le duvet (plus long).`},{titre:`Plumer`,texte:`Arrachez les plumes à pleines mains, à contre-sens de leur pousse, en commençant par les grandes plumes (ailes, queue) puis le corps. Tirez par petites poignées sur la peau fragile du dos et du bréchet. Les petits picots restants s'enlèvent avec la pointe du couteau, et les fins duvets se flambent rapidement à la flamme (brûleur, gazinière). Rincez à l'eau froide.`},{titre:`Retirer tête, pattes et glande du croupion`,texte:`Coupez la tête à la base du cou. Coupez les pattes à l'articulation (au-dessus de l'écaille) : pliez l'articulation et glissez la lame dans le joint, sans scier l'os. Gardez les pattes pour le bouillon. Sur le dessus de la queue (croupion), retirez la glande uropygienne (petite bosse jaunâtre qui sécrète de l'huile, au goût désagréable) en coupant en V sous elle.`},{titre:`Vider le cou`,texte:`Posez l'oiseau sur le dos. Incisez la peau du cou dans la longueur, côté dos, du bas de la tête jusqu'aux épaules. Décollez la peau : vous voyez le jabot (poche souple), l'œsophage et la trachée (tube annelé). Détachez-les du cou avec les doigts en descendant jusqu'à l'entrée du thorax, sans percer le jabot. Coupez le cou au ras des épaules en gardant la peau (utile pour farcir ou pour le bouillon).`},{titre:`Ouvrir l'abdomen`,texte:`Oiseau sur le dos, croupion vers vous. Pincez la peau entre la pointe du bréchet et le cloaque, soulevez-la et faites une petite incision horizontale de 5 à 8 cm, en soulevant toujours la peau pour ne pas percer les intestins juste en dessous. Puis découpez un cercle autour du cloaque (l'anus) en le gardant entier, sans le percer, à 1-2 cm autour.`},{titre:`Éviscérer`,texte:`Glissez la main à plat dans la cavité, le long de la paroi, le dos de la main contre le bréchet, jusqu'au fond (vers le cou). Décollez délicatement en faisant le tour, puis refermez la main en coupe et tirez doucement l'ensemble vers l'extérieur : intestins, gésier, foie et cœur sortent d'un bloc, reliés au cloaque. Ne tirez pas brutalement (les intestins se déchirent). Grattez ensuite avec les doigts les poumons, roses et spongieux, collés de chaque côté contre la colonne et les côtes. Retirez éventuellement les reins (masses rouge sombre dans le creux du dos) pour une meilleure conservation.`,attention:`Si un intestin ou le jabot se perce, rincez immédiatement la zone à l'eau froide claire et retirez toute partie souillée. Une contamination fécale est la principale source de salmonelles et campylobacter.`},{titre:`Retirer le fiel (vésicule biliaire) sans le crever`,texte:`Le fiel est une petite poche vert foncé, de la taille d'un petit pois à une noisette, collée sur la face intérieure du foie (entre les lobes). Il contient la bile, très amère : s'il se perce, la viande et les abats qu'il touche deviennent immangeables. Séparez d'abord le foie des intestins. Tenez le foie à plat dans la paume, vésicule vers le haut. Avec la pointe du couteau, découpez LARGEMENT autour de la vésicule en sacrifiant un peu de foie (quelques millimètres de marge), puis soulevez-la par le morceau de foie qui l'entoure, sans jamais pincer la poche elle-même. Jetez-la.`,attention:`Si le fiel éclate : rincez immédiatement et abondamment à l'eau froide, et coupez toute partie de foie ou de viande teintée de vert ou de jaune. Goûter un fragment cuit permet de vérifier : l'amertume est sans équivoque.`,astuce:`Faites ce geste au-dessus d'un bol à part, jamais au-dessus de la carcasse.`},{titre:`Inspecter le foie et les organes`,texte:`Un foie sain est rouge-brun, lisse et ferme ; un léger jaunissement est normal chez une poule grasse. Taches blanches ou jaunes, nodules, abcès, foie très hypertrophié ou friable, tumeurs sur les organes, liquide dans l'abdomen : ne consommez pas l'animal (ni ses abats) et parlez-en à votre vétérinaire, d'autres animaux du troupeau peuvent être concernés.`},{titre:`Préparer les abats`,texte:`Gésier : coupez le gras, ouvrez-le en deux dans le sens de la longueur, videz les graviers et la nourriture, puis décollez et retirez la membrane jaune et ridée de l'intérieur (elle s'enlève d'un bloc avec le pouce). Rincez. Cœur : retirez les gros vaisseaux et pressez pour chasser les caillots. Gardez le cou, les pattes, la graisse abdominale (paquet jaune autour du gésier et du cloaque) pour le bouillon et la cuisine.`},{titre:`Rincer et refroidir VITE`,texte:`Rincez l'intérieur et l'extérieur à l'eau froide claire, égouttez. Plongez immédiatement la carcasse dans une bassine d'eau glacée 30 à 60 minutes, ou placez-la au réfrigérateur : la viande doit descendre sous 4 °C le plus vite possible (bactéries).`},{titre:`Laisser reposer 24 heures`,texte:`Juste après l'abattage, les muscles se raidissent (rigidité cadavérique) : cuite ou congelée dans les heures qui suivent, la viande sera dure. Laissez reposer la volaille 24 à 48 heures au réfrigérateur (0-4 °C), sur une grille, couverte, avant de la cuire ou de la congeler. Ensuite, voir les tutoriels « Valoriser toute la carcasse » et « Conserver la viande ».`},{titre:`Nettoyer et gérer les déchets`,texte:`Lavez à l'eau chaude savonneuse tout le matériel, la table et le cône, puis rincez. Plumes, sang et viscères non consommés : en sac bien fermé aux ordures ménagères (de petites quantités d'abattage familial). Ne les donnez pas aux autres volailles (transmission de maladies, prise de goût pour la chair) et ne les laissez pas accessibles (renards, rats, chiens). Les plumes seules peuvent aller au compost (décomposition lente).`}],conseils:[`Pour un poulet tendre, préférez des races à chair ou mixtes (Sussex, Faverolles, Bresse, Cou nu, Marans) et abattez avant 6 mois. Une poule de 2 ans et plus se cuit longuement (pot-au-feu, coq au vin, bouillon).`,`Notez le poids de chaque oiseau dans l'application (rendement : la carcasse prête à cuire pèse environ 65 à 75 % du poids vif).`,`Si vous ne vous sentez pas capable du geste, des abattoirs de volailles et certains éleveurs proposent un service d'abattage à façon.`],erreurs:[`Aller chercher l'oiseau avant d'avoir tout préparé.`,`Couteau mal affûté : geste hésitant, souffrance.`,`Eau d'échaudage trop chaude : peau déchirée.`,`Percer le fiel ou l'intestin par précipitation.`,`Cuire ou congeler la viande dans l'heure qui suit l'abattage (viande dure).`],video:`abattre et plumer un poulet maison méthode respectueuse éviscération`,liens:[`utiliser-carcasse`,`conserver-viande`,`poule`]},{id:`utiliser-carcasse`,titre:`Valoriser toute la carcasse (zéro déchet)`,rubrique:`boucherie`,emoji:`🍲`,niveau:2,duree:`Variable`,sensible:!0,resume:`De la découpe au bouillon, des abats à la graisse : utiliser au maximum un animal qu'on a élevé, par respect et par économie.`,materiel:[`Couteau à désosser, ciseaux à volaille`,`Grande marmite`,`Bocaux, sacs de congélation`],etapes:[{titre:`Découper une volaille`,texte:`Cuisses : écartez la cuisse, incisez la peau entre cuisse et corps, faites sauter l'articulation en pliant vers l'arrière, coupez dans l'articulation. Pensez à détacher le « sot-l'y-laisse » (petit morceau tendre au creux du dos) avec la cuisse. Ailes : coupez à l'articulation de l'épaule. Filets : incisez de chaque côté du bréchet et suivez l'os de la pointe du couteau. Il reste la carcasse pour le bouillon.`},{titre:`Le bouillon (os, cou, pattes, ailerons)`,texte:`Carcasse, cou, pattes, ailerons et gésier dans une grande marmite d'eau froide, avec oignon, carotte, poireau, céleri, bouquet garni, poivre (salez à la fin). Portez doucement à frémissement, écumez, laissez frémir 3 à 4 heures sans bouillir fort. Filtrez, laissez refroidir, retirez la graisse figée en surface (gardez-la). Les pattes donnent un bouillon très gélatineux, riche et réconfortant.`},{titre:`Les pattes`,texte:`Plongez-les 30 secondes à 1 minute dans l'eau bouillante, puis retirez la peau jaune écailleuse (elle s'enlève comme un gant) et coupez les ongles. Pour le bouillon, ou en cuisine asiatique (pattes braisées), très riches en collagène.`},{titre:`La graisse (schmaltz)`,texte:`Coupez la graisse abdominale et la peau grasse en petits morceaux, faites fondre à feu très doux avec un fond d'eau, 1 heure. Filtrez dans un bocal : elle se garde des semaines au réfrigérateur, des mois congelée. Idéale pour rissoler les pommes de terre. Les morceaux de peau dorés qui restent (« grattons ») se grignotent salés.`},{titre:`Les abats`,texte:`Foie (fiel retiré !) : poêlé, en terrine ou en pâté, à consommer très frais (1 à 2 jours). Cœurs et gésiers : poêlés, en brochettes, ou gésiers confits dans la graisse (cuisson 2 heures à feu très doux). Crêtes et rognons : garnitures traditionnelles (« financière ») après blanchiment.`},{titre:`Les œufs en formation`,texte:`Une poule de réforme abattue en période de ponte contient parfois une grappe de jaunes en formation (« œufs de poule cachés ») : pochés dans le bouillon, c'est un mets traditionnel.`},{titre:`Le sang`,texte:`Il peut être recueilli à la saignée dans un bol contenant une cuillère de vinaigre (empêche la coagulation), pour lier une sauce de coq au vin ou de civet. À utiliser le jour même, dans des conditions d'hygiène strictes.`},{titre:`Les plumes`,texte:`Duvet d'oie et de canard : lavé, séché, il garnit coussins et couettes. Plumes de poule : compost (lent, riches en azote), artisanat, mouches de pêche. Évitez de les brûler (odeur, fumée).`},{titre:`Les os après le bouillon`,texte:`Jamais aux chiens ni aux chats : les os de volaille cuits éclatent en esquilles dangereuses. Les os cuits peuvent être séchés et calcinés au feu de bois : la cendre d'os, broyée, est un engrais riche en phosphore et calcium pour le compost.`}],video:`découper un poulet entier et faire un bouillon de carcasse`,liens:[`abattage-volaille`,`conserver-viande`]},{id:`conserver-viande`,titre:`Conserver la viande de la basse-cour`,rubrique:`boucherie`,emoji:`❄️`,niveau:2,duree:`Variable`,sensible:!0,resume:`Réfrigération, congélation, confit, rillettes, sous vide, conserves : durées sûres et règles d'hygiène pour la volaille et le lapin.`,etapes:[{titre:`La chaîne du froid d'abord`,texte:`Refroidissez sous 4 °C dans l'heure qui suit l'abattage. Au réfrigérateur (0-4 °C, dans la zone la plus froide) : volaille ou lapin entiers 2 à 3 jours après le repos, morceaux 1 à 2 jours, abats et viande hachée 24 heures. Toujours couverte, sur une assiette pour éviter les écoulements sur les autres aliments.`},{titre:`Congeler correctement`,texte:`Après le repos de 24 h, emballez hermétiquement (sous vide idéalement, ou sacs épais en chassant l'air) pour éviter les brûlures de congélation. Étiquetez : espèce, date, poids. À -18 °C : volaille entière jusqu'à 12 mois, morceaux 9 mois, abats 3 mois, viande cuite et bouillon 3 mois. Congelez à plat pour une congélation rapide.`},{titre:`Décongeler sans risque`,texte:`Toujours au réfrigérateur (comptez 24 h pour 2 kg), jamais à température ambiante sur le plan de travail. Ne recongelez jamais une viande crue décongelée (sauf après l'avoir cuite).`},{titre:`Le confit (canard, oie, poule)`,texte:`Salez les morceaux au gros sel 12 heures au frais (environ 15-20 g par kg), rincez, essuyez, cuisez à feu très doux (80-90 °C) 2 à 3 heures immergés dans leur graisse. Rangez dans un pot propre en couvrant entièrement de graisse : il se conserve plusieurs semaines au réfrigérateur. Pour une longue conservation à température ambiante, il faut une stérilisation adaptée (voir ci-dessous).`},{titre:`Rillettes et terrines`,texte:`La viande effilochée cuite longuement dans la graisse se conserve 1 à 2 semaines au réfrigérateur sous une couche de graisse, ou congelée.`},{titre:`Les conserves de viande en bocaux`,texte:`Viande et abats sont des conserves PEU ACIDES, à risque de botulisme. Les autorités sanitaires recommandent une stérilisation sous pression (autoclave domestique, 115-121 °C). Une stérilisation à 100 °C en bocaux, pratique traditionnelle française, impose des temps très longs (3 heures et plus selon le volume) et ne garantit pas la destruction de toutes les spores : à réserver aux personnes formées, avec stockage au frais.`,attention:`Bocal bombé, qui pétille, sent mauvais ou dont le joint a lâché : jetez sans goûter. En cas de doute, la congélation est la méthode la plus sûre.`},{titre:`Le fumage et le séchage`,texte:`Magret de canard séché (salé 24 h au gros sel puis poivré, enveloppé dans un linge, 2 à 3 semaines au réfrigérateur) ; volaille fumée à chaud. Ces techniques demandent rigueur sur le sel, la température et l'hygiène.`},{titre:`Hygiène en cuisine`,texte:`Une planche réservée à la viande crue, mains et ustensiles lavés après contact, cuisson à cœur de la volaille (75 °C au cœur, jus clair, plus aucune trace rosée près de l'os) : salmonelles et campylobacter ne résistent pas à une bonne cuisson.`}],video:`conserver volaille congélation confit canard maison`,liens:[`abattage-volaille`,`utiliser-carcasse`,`bocaux`]},{id:`preparer-lapin`,titre:`Abattre et préparer un lapin`,rubrique:`boucherie`,emoji:`🐇`,niveau:3,duree:`30 à 45 minutes`,sensible:!0,resume:`Étourdissement, saignée, dépouillage, éviscération et retrait du fiel : la méthode pas à pas pour l'abattage familial du lapin.`,quand:`Lapins de chair entre 10 et 14 semaines (2,5 à 3 kg vif) pour une viande tendre.`,materiel:[`Bâton court et lourd`,`Couteau très affûté`,`Crochets ou ficelle pour suspendre par les pattes arrière`,`Seau, table lavable, eau froide, sacs`,`Optionnel : gros sel et alun pour tanner la peau`],etapes:[{titre:`Préparer`,texte:`Même règles que pour la volaille : abattage familial uniquement pour la consommation du foyer, animal en bonne santé, sans traitement récent. Retirez la nourriture 12 heures avant (eau à volonté). Tout le matériel prêt avant d'aller chercher l'animal, calmement.`},{titre:`Étourdir`,texte:`Tenez le lapin par les pattes arrière, tête en bas, ou posé sur vos genoux contre vous. Donnez un coup sec et puissant derrière les oreilles, à la base du crâne, avec le bâton. Le lapin perd conscience immédiatement. Enchaînez sans attendre.`},{titre:`Saigner`,texte:`Suspendez le lapin par les pattes arrière (ficelle ou crochets passés derrière le tendon). Incisez profondément la gorge sous la mâchoire pour sectionner les gros vaisseaux, au-dessus d'un seau. Laissez saigner 1 à 2 minutes. Des mouvements réflexes peuvent survenir : l'animal est inconscient.`},{titre:`Dépouiller`,texte:`Toujours suspendu : incisez la peau en cercle autour de chaque patte arrière, au-dessus de l'articulation, puis le long de l'intérieur des cuisses jusqu'à l'anus. Décollez la peau des cuisses avec les doigts, puis tirez-la vers le bas d'un mouvement régulier, comme on retire un gant retourné ou un pull. Coupez la queue. Aux pattes avant, dégagez-les de la peau, puis tirez jusqu'à la tête. Coupez la tête et les pattes avant (ou dépouillez la tête si vous la cuisinez).`},{titre:`Ouvrir le ventre`,texte:`Pincez la fine paroi du ventre en bas, faites une petite incision, glissez deux doigts à l'intérieur pour soulever la paroi et protéger les organes, et ouvrez de bas en haut jusqu'aux côtes en guidant la lame entre vos doigts.`},{titre:`Éviscérer`,texte:`Retirez d'abord la vessie (petite poche transparente en bas du ventre) avec précaution : pincez-la à sa base et coupez, sans la percer (l'urine donne mauvais goût). Sortez les intestins et l'estomac en coupant le rectum au plus près du bassin (ouvrez le bassin d'un coup de couteau entre les deux os si nécessaire). Gardez le foie, les rognons (attachés au dos), le cœur et les poumons.`},{titre:`Retirer le fiel`,texte:`Comme chez la volaille, la vésicule biliaire est une petite poche verdâtre collée au foie. Découpez largement autour avec un peu de foie, en la soulevant par le foie, jamais en la pinçant. Si elle éclate, rincez immédiatement et coupez les parties verdies.`},{titre:`Inspecter le foie`,texte:`Un foie sain est rouge-brun, lisse. Des taches ou des petits nodules blancs ou jaunâtres signalent souvent une coccidiose hépatique : jetez le foie (la viande reste consommable si l'animal était en bon état) et parlez-en à votre vétérinaire pour le reste du clapier.`},{titre:`Rincer, refroidir, reposer`,texte:`Rincez à l'eau froide, essuyez, mettez sous 4 °C rapidement. Laissez reposer 24 heures au réfrigérateur avant de cuisiner ou de congeler (viande plus tendre).`},{titre:`La peau`,texte:`Elle peut être salée (gros sel sur la face chair, 2 semaines) puis tannée à l'alun pour en faire une fourrure, ou compostée enterrée profondément. Sinon, en sac fermé aux ordures ménagères avec les déchets d'abattage.`}],video:`préparer un lapin dépouiller vider méthode`,liens:[`conserver-viande`,`lapin`]}],O=[{id:`lumiere-led`,titre:`La lumière en intérieur : mesurer et compléter avec une lampe LED`,rubrique:`interieur`,emoji:`💡`,niveau:1,duree:`30 minutes`,resume:`La lumière est le facteur n° 1 de réussite en appartement. Comment savoir ce que reçoit chaque fenêtre, et comment choisir et régler une lampe horticole sans se tromper.`,materiel:[`Votre main et une feuille blanche (test de l'ombre)`,`Optionnel : application de luxmètre sur téléphone`,`Lampe LED horticole « spectre complet » (lumière blanche), minuterie`],etapes:[{titre:`Le test de l'ombre de la main`,texte:`À midi, par temps clair, tenez votre main à 30 cm au-dessus d'une feuille blanche posée à l'endroit de la plante. Ombre nette aux contours précis : lumière forte (cactus, succulentes, agrumes, strelitzia). Ombre floue mais visible : lumière moyenne (la plupart des plantes vertes). Ombre à peine perceptible : lumière faible (aspidistra, zamioculcas, sansevieria, pothos, aglaonema seulement).`},{titre:`Ce que reçoit chaque fenêtre`,texte:`Sud : la plus lumineuse, soleil direct qui peut brûler en été derrière la vitre (voilage). Ouest : soleil chaud de l'après-midi. Est : soleil doux du matin, idéal pour la majorité des plantes, orchidées, violettes africaines. Nord : lumière douce et constante mais faible ; réservez-la aux plantes d'ombre. À 2 mètres de la fenêtre, la lumière est souvent divisée par 4 à 10 : c'est la raison n° 1 des plantes qui s'étiolent.`,astuce:`Les applications de luxmètre du téléphone donnent un ordre de grandeur : moins de 1 000 lux = faible ; 1 000 à 5 000 = moyenne ; plus de 10 000 = forte.`},{titre:`Quand faut-il une lampe ?`,texte:`En hiver dans une pièce sombre, pour les semis et les aromatiques, pour cultiver des légumes en intérieur, ou dans une pièce sans fenêtre. Signes de manque de lumière : tiges longues et pâles, plante penchée, plus de fleurs, feuilles panachées qui reverdissent.`},{titre:`Choisir la lampe`,texte:`Prenez une LED « spectre complet » à lumière blanche (plus agréable à vivre que le violet, aussi efficace). Ne vous fiez pas aux « watts équivalents » des emballages : regardez la puissance réelle consommée. Repères : 10 à 20 W réels pour une étagère de plantes vertes ou d'aromatiques ; 30 à 50 W réels par m² pour des légumes-fruits (tomates cerises, poivrons) ou des semis.`},{titre:`Régler distance et durée`,texte:`Plantes vertes : 30 à 60 cm au-dessus. Semis et aromatiques : 15 à 30 cm. Durée : 10 à 12 h par jour pour les plantes vertes, 12 à 16 h pour les semis et légumes. Une minuterie (prise programmable) fait le travail. Les plantes ont besoin d'une nuit noire : jamais 24 h sur 24.`,attention:`Si les feuilles pâlissent ou se décolorent près de la lampe, éloignez-la ; si les tiges s'allongent, rapprochez-la.`}],conseils:[`Nettoyez vitres et feuilles : la poussière bloque une part importante de la lumière.`,`Tournez les pots d'un quart de tour chaque semaine pour une croissance régulière.`],video:`choisir lampe led horticole plantes intérieur tuto`,liens:[`manque-lumiere`,`plantes-interieur-bases`,`potager-interieur`]},{id:`potager-interieur`,titre:`Un potager d'intérieur sans balcon`,rubrique:`interieur`,emoji:`🍅`,niveau:2,duree:`1 heure d'installation`,resume:`Aromatiques, salades à couper, micro-pousses, et même tomates cerises, piments et fraises sous une lampe : ce qui marche vraiment dans un appartement.`,materiel:[`Rebord de fenêtre sud ou ouest, ou étagère avec lampe LED (30 à 50 W réels par m²)`,`Pots percés de 2 à 15 L, soucoupes`,`Terreau potager + compost ou lombricompost`,`Pinceau (pollinisation)`],etapes:[{titre:`Ce qui réussit facilement`,texte:`Sans lampe, sur une fenêtre lumineuse : ciboulette, persil, menthe, thym, laurier, micro-pousses, salade à couper, oignons verts en repousse, piments en été. Avec lampe : basilic toute l'année, laitues, radis, tomates cerises naines, poivrons et piments, fraises remontantes.`},{titre:`Tomates et piments en appartement`,texte:`Choisissez des variétés naines (« Micro Tom », « Tiny Tim », « Balconi », piments « Numex », « Basket of Fire »). Pot de 10 à 15 L, 14 à 16 h de lumière par jour, 20-25 °C le jour.`,attention:`Sans insectes pollinisateurs, il faut polliniser vous-même : secouez chaque jour les bouquets de fleurs de tomates et de piments, ou passez un pinceau de fleur en fleur pour les fraises.`},{titre:`Arroser et nourrir`,texte:`Les pots sèchent vite près d'une fenêtre ou sous une lampe. Arrosez quand le dessus est sec, et apportez un engrais organique liquide tous les 15 jours (ou du lombrithé dilué) : les plantes en pot n'ont que ce que vous leur donnez.`},{titre:`Organiser les récoltes`,texte:`Semez peu et souvent (micro-pousses chaque semaine, salade à couper tous les 15 jours) pour récolter en continu plutôt que tout en même temps.`}],video:`potager intérieur appartement sans balcon lampe tomates cerises`,liens:[`lumiere-led`,`herbes-interieur`,`repousses-cuisine`,`lombricompost`]},{id:`repousses-cuisine`,titre:`Faire repousser les restes de cuisine`,rubrique:`interieur`,emoji:`🥑`,niveau:1,duree:`10 minutes, puis quelques semaines`,resume:`Oignons verts, poireau, céleri, salade, avocat, ananas, patate douce, ail : des plantes gratuites et un super projet avec des enfants.`,materiel:[`Verres ou pots, cure-dents`,`Terreau`,`Restes de légumes frais, de préférence bio (les légumes traités contre la germination repoussent mal)`],etapes:[{titre:`Oignons verts, poireau, fenouil, céleri, cœur de laitue`,texte:`Gardez la base avec les racines sur 3 à 5 cm, posez-la dans un fond d'eau (racines dans l'eau, haut à l'air), changez l'eau tous les 2 jours. Les oignons verts et le poireau repoussent en une semaine et se coupent plusieurs fois. Plantez ensuite en terre pour une repousse plus vigoureuse.`},{titre:`Ail`,texte:`Une gousse germée plantée en pot donne des pousses vertes à ciseler comme de la ciboulette.`},{titre:`Avocat`,texte:`Lavez le noyau, piquez 3 cure-dents à mi-hauteur et posez-le sur un verre d'eau, partie pointue en haut, la base trempant. En 3 à 8 semaines, il se fend, une racine puis une tige apparaissent. Plantez en pot quand la tige fait 15 cm, et pincez-la à 30 cm pour qu'elle ramifie. Il donnera une belle plante verte, mais rarement des fruits en intérieur.`},{titre:`Ananas`,texte:`Tordez la couronne de feuilles pour la détacher, retirez les feuilles du bas sur 3 cm, laissez sécher 2 jours, puis posez-la dans l'eau jusqu'à l'apparition de racines, et plantez dans un terreau léger. Très décoratif ; une fleur (et un petit fruit) au bout de 2 à 3 ans au mieux.`},{titre:`Patate douce`,texte:`À moitié immergée dans un verre d'eau, elle produit de longues tiges retombantes très décoratives, dont on peut faire des boutures à planter au jardin en mai.`}],conseils:[`Changez l'eau souvent : une eau trouble et malodorante fait pourrir la base.`,`Les noyaux d'agrumes semés donnent de jolies plantes, mais pas de fruits avant de longues années.`],video:`faire repousser légumes restes cuisine avocat ananas`,liens:[`potager-interieur`,`herbes-interieur`]},{id:`hydroponie`,titre:`Culture sans terre : eau, billes d'argile et hydroponie`,rubrique:`interieur`,emoji:`💧`,niveau:2,duree:`1 heure`,resume:`Cultiver dans l'eau (boutures), en billes d'argile (« semi-hydro ») ou en hydroponie : moins de moucherons, arrosage simplifié, racines visibles. Attention : la culture hors-sol n'est pas compatible avec l'agriculture biologique (engrais minéraux, pas de sol vivant) ; pour un potager d'intérieur bio, préférez le pot de terreau sans tourbe.`,materiel:[`Billes d'argile expansée lavées (LECA) ou pouzzolane`,`Pot sans trou + pot intérieur percé, ou vase transparent`,`Indicateur de niveau d'eau (option)`,`Engrais spécial hydroculture ou engrais liquide organique très dilué`],etapes:[{titre:`La culture dans l'eau`,texte:`Pothos, philodendron, misère, lierre, chlorophytum vivent des mois voire des années dans un vase d'eau. Changez l'eau toutes les 1 à 2 semaines et ajoutez une goutte d'engrais liquide organique par mois.`},{titre:`La semi-hydroculture en billes d'argile`,texte:`Lavez soigneusement la plante en retirant toute la terre des racines, coupez les racines abîmées. Placez-la dans un pot percé rempli de billes d'argile trempées 24 h, dans un cache-pot étanche. Gardez une réserve d'eau sur le quart inférieur seulement : les billes la font remonter par capillarité, le haut des racines reste aéré.`,attention:`La transition terre → billes stresse la plante : faites-la au printemps, sur une plante en bonne santé ; les racines de terre meurent et sont remplacées par des racines d'eau en quelques semaines.`},{titre:`Nourrir`,texte:`Il n'y a aucun nutriment dans l'argile : engrais d'hydroculture (ou engrais liquide organique dilué de moitié) à chaque remplissage au printemps et en été. Rincez les billes à l'eau claire tous les 2-3 mois pour éliminer les sels.`},{titre:`L'hydroponie « active »`,texte:`Les kits d'intérieur (pompe, lampe, solution nutritive) font pousser aromatiques et salades très vite. Suivez la notice pour la solution nutritive et nettoyez le réservoir régulièrement (algues).`}],video:`semi hydroponie billes argile plantes intérieur tuto`,liens:[`sciarides`,`rempoter`,`bouturage`]},{id:`terrarium`,titre:`Créer un terrarium (et un kokedama)`,rubrique:`fabriquer`,emoji:`🥫`,niveau:2,duree:`1 heure`,resume:`Un petit jardin sous verre qui demande très peu d'arrosage, et la boule de mousse japonaise (kokedama) : deux réalisations décoratives pour petits espaces.`,materiel:[`Bocal ou aquarium en verre, avec ou sans couvercle`,`Billes d'argile ou graviers, charbon actif (filtration), terreau, mousse`,`Petites plantes de milieu humide (fittonia, petites fougères, peperomia, mousses) — jamais de succulentes dans un terrarium fermé`,`Pour le kokedama : terreau + argile (ou akadama), mousse en plaque, ficelle`],etapes:[{titre:`Les couches du terrarium`,texte:`Au fond, 2-3 cm de billes d'argile (réserve d'eau), une fine couche de charbon actif, une feuille de mousse ou de feutre pour séparer, puis 5 à 8 cm de terreau légèrement humide.`},{titre:`Planter`,texte:`Disposez les plantes les plus hautes à l'arrière, les plus petites devant, de la mousse en surface, quelques pierres ou bois. Arrosez très peu au vaporisateur.`},{titre:`Entretenir`,texte:`Lumière vive mais jamais de soleil direct (effet de serre : les plantes cuisent). Terrarium fermé : buée le matin = normal ; buée permanente = ouvrez quelques heures ; aucune buée = un peu d'eau. Retirez toute feuille morte (moisissures).`,attention:`Les cactus et succulentes vendus en « terrarium » fermé pourrissent : ils ne vivent que dans un contenant ouvert et sec.`},{titre:`Le kokedama`,texte:`Mélangez terreau et argile pour former une boule qui se tient, insérez-y la motte d'une petite plante (fougère, pothos, peperomia), enveloppez de mousse et ficelez. Arrosage : trempez la boule 10 minutes dans l'eau dès qu'elle devient légère, égouttez.`}],video:`fabriquer terrarium plantes tuto débutant kokedama`,liens:[`fittonia`,`fougere`]},{id:`champignons-maison`,titre:`Faire pousser des pleurotes sur du marc de café`,rubrique:`interieur`,emoji:`🍄`,niveau:2,duree:`1 heure + 4 à 6 semaines`,resume:`Recycler son marc de café en champignons comestibles, sans jardin, dans un coin de cuisine.`,materiel:[`Marc de café FRAIS (du jour, encore humide), environ 1 kg`,`Mycélium de pleurote (« blanc de champignon » sur grains, vendu en ligne)`,`Sac de congélation ou bocal, quelques trous`,`Vaporisateur`],etapes:[{titre:`Préparer`,texte:`Le marc de café frais est presque stérile grâce à l'eau bouillante de l'extraction : utilisez-le le jour même. Lavez-vous les mains, désinfectez le contenant à l'eau bouillante.`},{titre:`Ensemencer`,texte:`Mélangez environ 1 volume de mycélium pour 5 à 10 volumes de marc, tassez légèrement dans le sac, fermez et percez quelques petits trous.`},{titre:`Incuber`,texte:`2 à 4 semaines dans l'obscurité à 18-24 °C : le mycélium blanc colonise tout le marc. Une tache verte, noire ou orange = contamination : jetez.`},{titre:`Faire fructifier`,texte:`Quand tout est blanc, ouvrez une fente de 5 cm, placez à la lumière indirecte et au frais (15-20 °C), vaporisez de l'eau 2 fois par jour. Les pleurotes apparaissent en 1 à 2 semaines.`},{titre:`Récolter`,texte:`Coupez la grappe à la base quand les chapeaux sont encore légèrement enroulés. Une deuxième vague suit souvent. Le substrat épuisé part au compost ou au pied des plantes.`}],conseils:[`Ne consommez que des champignons issus d'un mycélium acheté et identifié, jamais une pousse spontanée inconnue.`],video:`pleurotes marc de café maison tuto`,liens:[`compost-tas`]},{id:`choisir-plante`,titre:`Choisir une plante saine et bien l'acclimater`,rubrique:`interieur`,emoji:`🛒`,niveau:1,duree:`Lecture : 5 minutes`,resume:`La plupart des problèmes commencent en magasin. Les points à vérifier avant d'acheter, et les 3 premières semaines à la maison.`,etapes:[{titre:`Avant d'acheter : la bonne plante pour le bon endroit`,texte:`Faites le test de l'ombre de la main à l'endroit prévu (voir le tutoriel sur la lumière) et vérifiez la toxicité si vous avez des chats, des chiens ou de jeunes enfants. Les filtres du catalogue « Pièce sombre », « Sans danger pour les animaux », « Pardonne les oublis » sont faits pour ça.`},{titre:`Inspecter la plante`,texte:`Retournez quelques feuilles : pas de toiles, de points, de cotons blancs ou de carapaces (parasites). Feuillage ferme et brillant, nouvelles pousses présentes. Soulevez le pot : des racines blanches et fermes au trou de drainage, pas d'odeur de moisi, pas de terre détrempée ni de moucherons.`},{titre:`En hiver, protéger du froid`,texte:`Exigez un emballage (papier ou plastique) et ne laissez jamais la plante dans une voiture froide : quelques minutes sous 10 °C suffisent pour faire tomber les feuilles d'un ficus ou d'un poinsettia.`},{titre:`Quarantaine`,texte:`Gardez la nouvelle plante 2 à 3 semaines à l'écart des autres et inspectez-la chaque semaine : c'est ainsi qu'on évite d'importer cochenilles, thrips et araignées rouges dans toute la maison.`},{titre:`Acclimatation`,texte:`Une chute de quelques feuilles dans les semaines qui suivent est normale (changement de lumière). Pas de rempotage ni d'engrais pendant 3 à 4 semaines, sauf si les racines débordent du pot. Puis ajoutez la plante dans « Mes plantes » pour recevoir les rappels d'arrosage.`}],video:`bien choisir plante d'intérieur magasin conseils`,liens:[`chute-feuilles`,`cochenilles`,`plantes-interieur-bases`]},{id:`eau-arrosage-interieur`,titre:`Quelle eau pour les plantes d'intérieur ?`,rubrique:`interieur`,emoji:`🚰`,niveau:1,duree:`Lecture : 5 minutes`,resume:`Calcaire, chlore, température, arrosage par le dessus ou par la soucoupe : les détails qui font la différence pour les plantes sensibles.`,etapes:[{titre:`L'eau du robinet`,texte:`Elle convient à la plupart des plantes. Laissez-la reposer une nuit dans l'arrosoir : elle se met à température ambiante et une partie du chlore s'évapore. En région calcaire, elle laisse des dépôts blancs et fait jaunir les plantes de terre acide.`},{titre:`Les plantes sensibles`,texte:`Calathea, maranta, plantes carnivores, orchidées, broméliacées, tillandsias, azalées, myrtilliers : eau de pluie, eau déminéralisée ou eau filtrée (carafe filtrante). Les plantes carnivores meurent avec l'eau du robinet.`},{titre:`Par le dessus ou par la soucoupe ?`,texte:`Par le dessus pour la plupart : arrosez jusqu'à ce que l'eau ressorte par le trou, puis videz la soucoupe après 15-30 minutes. Par la soucoupe pour les plantes qui détestent l'eau sur les feuilles ou au collet (violette africaine, cyclamen, bégonias) : 20 minutes de bain puis on vide. Par trempage pour les mottes très sèches, les orchidées et les bonsaïs.`},{titre:`Ce qu'il faut éviter`,texte:`L'eau adoucie (salée) est néfaste. L'eau de cuisson refroidie et non salée peut servir, sans excès. L'eau de l'aquarium est un engrais doux apprécié. Évitez les « astuces » au thé, au café, à la bière ou au lait sur les plantes d'intérieur : elles attirent moucherons et moisissures.`}],video:`quelle eau pour arroser plantes intérieur calcaire`,liens:[`air-sec`,`moisissure-terreau`,`eau-pluie`]},{id:`plantes-par-piece`,titre:`Quelle plante pour quelle pièce ? (et le mythe des plantes dépolluantes)`,rubrique:`interieur`,emoji:`🛋️`,niveau:1,duree:`Lecture : 5 minutes`,resume:`Salle de bain, chambre, bureau, entrée sombre, rebord plein sud : les meilleures plantes pour chaque situation, et ce que la science dit vraiment de la « dépollution ».`,etapes:[{titre:`Salle de bain avec fenêtre`,texte:`Humidité idéale pour fougère, calathea, maranta, fittonia, orchidée, tillandsia, alocasia. Sans fenêtre : aucune plante ne vit durablement sans lampe.`},{titre:`Chambre fraîche`,texte:`Lierre, cyclamen, aspidistra, sansevieria, zamioculcas, aloe ; un hiver frais aide aussi le cactus de Noël et l'orchidée à refleurir.`},{titre:`Entrée ou couloir sombre`,texte:`Aspidistra, zamioculcas, sansevieria, aglaonema, pothos — en acceptant une croissance lente. En dessous d'une lumière « faible », même elles déclinent : prévoyez une rotation près d'une fenêtre ou une lampe.`},{titre:`Fenêtre plein sud`,texte:`Cactus, succulentes, aloe, kalanchoé, agrumes, strelitzia, yucca, hoya, collier de perles, aromatiques méditerranéennes ; un voilage l'été pour les autres.`},{titre:`Avec chats ou chiens`,texte:`Chlorophytum, maranta, calathea, kentia, areca, pilea, fougère de Boston, peperomia, orchidée, violette africaine, hoya, aspidistra, cactus de Noël, broméliacées : filtre « Sans danger pour les animaux » dans le catalogue. Jamais de lys avec un chat.`},{titre:`Le mythe des plantes dépolluantes`,texte:`L'idée vient d'une étude de la NASA de 1989 menée dans de petites chambres closes. Des analyses plus récentes ont montré qu'il faudrait des centaines de plantes par mètre carré pour égaler l'effet d'une simple aération : ouvrir les fenêtres 10 minutes par jour est bien plus efficace. Les plantes apportent en revanche bien-être, humidité légère et beauté.`}],video:`quelle plante pour quelle pièce sombre salle de bain`,liens:[`lumiere-led`,`plantes-toxiques`,`choisir-plante`]},{id:`vacances-plantes-interieur`,titre:`Partir en vacances : les plantes d'intérieur`,rubrique:`interieur`,emoji:`🧳`,niveau:1,duree:`30 minutes`,resume:`Une semaine, deux semaines, un mois : la bonne solution selon la durée, sans voisin ni gadget coûteux.`,etapes:[{titre:`Une semaine`,texte:`Arrosez normalement la veille, éloignez les plantes des fenêtres plein sud, regroupez-les : la plupart tiennent sans rien.`},{titre:`Deux semaines`,texte:`Baignoire ou bac avec 2-3 cm d'eau sur une serviette ou des billes d'argile, pots posés dessus (le fond touche l'humidité sans baigner), loin du soleil. Ou mèches de coton reliant chaque pot à une bassine d'eau (voir le tutoriel « Arroser pendant les vacances »).`},{titre:`Trois semaines et plus`,texte:`Combinez : mèches ou cônes d'arrosage en terre cuite, sacs plastique transparents posés sur les petites plantes (mini-serres, sans contact avec les feuilles), plantes grasses laissées sèches. Rien ne remplace un passage hebdomadaire d'un voisin : laissez-lui une fiche simple (l'application peut lire à voix haute ou afficher chaque fiche).`},{titre:`À ne pas faire`,texte:`Laisser les pots baigner une semaine dans l'eau (pourriture), arroser les cactus « pour être sûr », fermer les volets complètement pendant un mois (les plantes ont besoin de lumière).`}],video:`arroser plantes intérieur vacances astuces`,liens:[`arrosage-vacances`,`soif`]}],k=[{id:`pelouse`,titre:`Une pelouse naturelle, sans arrosage ni produits`,rubrique:`sol`,emoji:`🌱`,niveau:1,duree:`Toute la saison`,resume:`Tondre, lutter contre la mousse, résister à la sécheresse, et transformer une partie de la pelouse en prairie fleurie pour les pollinisateurs.`,etapes:[{titre:`Tondre haut`,texte:`Réglez la tondeuse à 6-8 cm : l'herbe haute garde l'humidité, étouffe les herbes indésirables et résiste à la sécheresse. Ne coupez jamais plus d'un tiers de la hauteur à la fois.`},{titre:`Le mulching`,texte:`Laissez l'herbe coupée finement sur place (tondeuse mulching) : elle nourrit la pelouse, plus besoin d'engrais. Les tontes ramassées servent au paillage (en couche fine) et au compost.`},{titre:`La mousse`,texte:`La mousse indique un sol acide, tassé, humide ou ombragé : la scarifier sans corriger la cause ne sert à rien. Aérez (fourche-bêche enfoncée tous les 20 cm), un peu de cendre ou de chaux si le sol est acide, éclaircissez les arbres, ressemez des graminées adaptées à l'ombre.`},{titre:`L'été sec`,texte:`Une pelouse jaunie en août n'est pas morte : elle est en dormance et reverdit aux pluies d'automne. N'arrosez pas (souvent interdit en période de restriction) ; tondez moins souvent et plus haut.`},{titre:`La prairie fleurie`,texte:`Laissez une bande non tondue jusqu'en juillet (fauche tardive) : fleurs sauvages, papillons, sauterelles, nourriture pour les oiseaux et les hérissons. Fauchez une à deux fois par an et exportez le foin (aux lapins, chèvres ou au compost).`},{titre:`Tondre écologique`,texte:`Moutons d'Ouessant, oies ou un tracteur à lapins tondent sans bruit ni carburant (voir les fiches animaux). Respectez les horaires de bruit de votre commune pour la tondeuse thermique.`}],erreurs:[`Tondre ras (« au golf ») : sécheresse, mousse et mauvaises herbes garanties.`,`Désherbant ou engrais chimique : interdits ou inutiles au jardin familial, et toxiques pour les animaux qui broutent.`],video:`pelouse naturelle sans arrosage tonte haute mulching`,liens:[`outils-tondeuse`,`mouton`,`paillage`]},{id:`haie`,titre:`Planter et tailler une haie champêtre`,rubrique:`fabriquer`,emoji:`🌳`,niveau:1,duree:`Une journée de plantation`,resume:`Une haie de plusieurs essences locales protège du vent, nourrit les oiseaux et les auxiliaires, fournit fruits et fourrage, et résiste aux maladies mieux qu'un mur de thuyas ou de lauriers.`,quand:`Plantation de novembre à mars hors gel ; taille de préférence en automne-hiver.`,materiel:[`Jeunes plants en racines nues (60-90 cm), 3 à 4 par mètre en double rang`,`Paillage (broyat, carton, feuilles)`,`Protections contre les lapins et chevreuils si besoin`],etapes:[{titre:`Choisir les essences`,texte:`Mélangez 6 à 10 espèces locales : charme, noisetier, cornouiller, sureau, aubépine, prunellier, églantier, viorne, troène, houx, érable champêtre, fusain, groseillier, cassissier. Un tiers de persistants pour l'hiver. Évitez les espèces très toxiques (if, laurier-cerise, laurier-rose) le long d'un pré ou d'un enclos.`},{titre:`Respecter les distances`,texte:`Plus de 2 m de haut : à au moins 2 m de la limite de propriété ; moins de 2 m : à 50 cm (Code civil, sauf usage local).`},{titre:`Planter`,texte:`Préparez une bande travaillée de 1 m de large, plantez en quinconce sur deux rangs à 50 cm, pralinez les racines, tassez, arrosez, paillez épais. Rabattez les plants à 30 cm : ils repartiront touffus dès la base.`},{titre:`Tailler au bon moment`,texte:`Évitez de tailler de mi-mars à fin juillet : c'est la période de nidification des oiseaux (la taille y est interdite pour les exploitants agricoles et fortement déconseillée pour tous). Taillez en automne et en hiver.`},{titre:`Valoriser la taille`,texte:`Broyez les branches : le broyat (BRF) fait un paillage excellent. Les branches feuillues de saule, frêne, noisetier sont un fourrage pour chèvres, moutons et lapins.`}],video:`planter haie champêtre essences locales double rang`,liens:[`voisinage-regles`,`plantes-toxiques`,`hotel-insectes`]},{id:`nuisibles-predateurs`,titre:`Renard, fouine, rats, sangliers, chevreuils : protéger jardin et animaux`,rubrique:`animaux`,emoji:`🦊`,niveau:2,duree:`Lecture : 10 minutes`,resume:`Les visiteurs indésirables qui ravagent le potager ou la basse-cour, et les moyens efficaces et légaux de s'en protéger.`,etapes:[{titre:`Le renard`,texte:`Il attaque surtout au crépuscule et à l'aube, et creuse sous les clôtures. Protection : poulailler fermé chaque soir (porte automatique), grillage soudé enterré de 30-40 cm ou retourné en L vers l'extérieur, fil électrique bas à 20 cm du sol à l'extérieur du parcours. Ne laissez aucune nourriture ni déchet accessible.`},{titre:`La fouine et la martre`,texte:`Elles passent par un trou de 5 cm et tuent souvent toute la basse-cour en une nuit. Toutes les ouvertures du poulailler en grillage à petites mailles (13 mm), y compris les aérations ; loquets à double action.`},{titre:`Les rats et souris`,texte:`Attirés par l'aliment des volailles et le compost. Mangeoires suspendues ou à pédale, aliment stocké dans des bidons métalliques fermés, ramassage des restes le soir, compost sans viande ni pain, grillage fin sous le composteur. Pièges mécaniques en boîte, à l'écart des animaux domestiques.`,attention:`Les raticides empoisonnent aussi chiens, chats, rapaces et hérissons qui mangent les rongeurs empoisonnés : évitez-les, ou faites appel à un professionnel avec boîtes sécurisées.`},{titre:`Les rapaces`,texte:`Ils prennent poussins, cailles et petites poules : filet de protection au-dessus des jeunes, abris (arbustes) dans le parcours. Les rapaces sont protégés : il est interdit de les capturer ou de les tuer.`},{titre:`Les sangliers et chevreuils`,texte:`Sangliers : retournent potagers et pelouses ; clôture électrique à 2 ou 3 fils bas (20, 40, 60 cm), solidement alimentée. Chevreuils : abroutissent les jeunes arbres et les rosiers ; clôture de 1,8 m ou protections individuelles autour des troncs (manchons). Les répulsifs olfactifs ont un effet temporaire.`,astuce:`En cas de dégâts importants de gibier, renseignez-vous auprès de la fédération départementale des chasseurs et de la mairie.`},{titre:`Les chats et chiens du voisinage`,texte:`Grillage enterré autour des semis, branches épineuses sur les planches fraîchement semées ; le dialogue avec les voisins règle souvent plus que les répulsifs.`}],video:`protéger poulailler renard fouine grillage enterré`,liens:[`poulailler`,`poule`,`campagnol`]},{id:`moustique-tigre`,titre:`Moustique tigre, processionnaires, frelon asiatique : les nuisibles de santé`,rubrique:`securite`,emoji:`🦟`,niveau:1,duree:`Lecture : 5 minutes`,resume:`Trois nuisibles en progression dans toute la France, qui concernent directement la santé de la famille et des animaux.`,etapes:[{titre:`Le moustique tigre`,texte:`Il pond dans toute eau stagnante, même un bouchon : soucoupes, récupérateurs mal fermés, arrosoirs, jouets, bâches, gouttières bouchées. Chaque semaine : videz ou couvrez tout ce qui retient l'eau, posez une moustiquaire sur les récupérateurs d'eau de pluie, mettez du sable dans les soucoupes. Une mare avec poissons ou une eau courante n'est pas un problème.`,attention:`Il peut transmettre la dengue, le chikungunya et le zika : signalez sa présence sur le portail officiel de signalement (signalement-moustique.anses.fr) si votre commune n'est pas encore colonisée.`},{titre:`Les chenilles processionnaires`,texte:`Nids blancs dans les pins (hiver) ou sur les chênes (été), chenilles en file indienne au sol. Leurs poils sont très urticants pour les humains et peuvent provoquer une nécrose de la langue chez le chien. Ne les touchez jamais ; écopièges sur les troncs, retrait des nids par un professionnel. Voir la fiche « Chenilles processionnaires ».`},{titre:`Le frelon asiatique`,texte:`Il chasse les abeilles devant les ruches et construit de gros nids en hauteur (et parfois bas, dans les haies). Ne vous approchez jamais d'un nid : signalez-le en mairie ou sur la plateforme de votre département ; la destruction est faite par un professionnel. En cas de piqûres multiples ou de gêne respiratoire : 15 ou 112.`},{titre:`Piéger le frelon asiatique ?`,texte:`Les pièges à bière ou à sirop non sélectifs tuent surtout des abeilles, des guêpes et des mouches utiles : ils sont déconseillés. Seuls les pièges sélectifs (entrée calibrée, sorties pour les petits insectes), posés près d'un rucher au printemps (fondatrices) ou en fin d'été, ont un intérêt, souvent dans le cadre d'un plan départemental. Renseignez-vous auprès du groupement apicole ou de la mairie avant de piéger.`},{titre:`Les tiques`,texte:`Fauche des abords, pantalons rentrés dans les chaussettes, inspection au retour (voir « Jardiner en sécurité »). Les pintades en chassent beaucoup.`}],video:`moustique tigre jardin éliminer gîtes larvaires`,liens:[`processionnaire`,`securite-jardin`,`recuperateur-pluie`,`pintade`]},{id:`outils-tondeuse`,titre:`Entretenir ses outils et sa tondeuse`,rubrique:`fabriquer`,emoji:`🧰`,niveau:1,duree:`1 heure par saison`,resume:`Des outils propres et affûtés fatiguent moins, abîment moins les plantes et transmettent moins de maladies. L'entretien de fin de saison qui fait durer le matériel des décennies.`,materiel:[`Brosse métallique, lime plate, pierre à aiguiser`,`Huile de lin ou huile végétale, chiffon`,`Alcool à 70° (désinfection des lames)`,`Gants de protection`],etapes:[{titre:`Après chaque usage`,texte:`Retirez la terre (brosse, eau), séchez. Désinfectez sécateurs et scies à l'alcool entre deux arbres malades.`},{titre:`Affûter`,texte:`Bêche, binette, serfouette : un coup de lime sur le biseau, en poussant vers le tranchant. Sécateur : pierre à aiguiser sur le biseau de la lame seulement, puis ébavurez l'autre face à plat.`},{titre:`Protéger le bois et le métal`,texte:`En fin de saison, frottez les manches en bois à l'huile de lin et passez un chiffon huilé sur le métal. Rangez au sec, suspendus.`},{titre:`La tondeuse`,texte:`Débranchez la bougie (ou retirez la batterie) avant toute intervention. Nettoyez le dessous du carter, affûtez ou changez la lame chaque année (une lame émoussée arrache l'herbe et la fait jaunir), changez le filtre à air. Thermique : vidange d'huile annuelle, et videz le carburant ou ajoutez un stabilisant avant l'hiver.`,attention:`Ne retournez jamais une tondeuse thermique côté filtre à air ou carburateur (fuite d'huile).`},{titre:`Le récupérateur et le tuyau`,texte:`Avant les gelées : videz et rangez tuyaux et raccords, purgez le robinet extérieur, videz les oyas et le goutte-à-goutte.`}],video:`entretien outils de jardin affûtage sécateur tondeuse hiver`,liens:[`pelouse`,`securite-jardin`]},{id:`desherbage`,titre:`Désherber sans produit (et sans s'épuiser)`,rubrique:`sol`,emoji:`🌾`,niveau:1,duree:`Variable`,resume:`Les « mauvaises herbes » renseignent sur le sol et nourrissent la faune. Comment les contenir au potager, dans les allées et les massifs, sans désherbant (interdits aux particuliers).`,etapes:[{titre:`Comprendre avant d'arracher`,texte:`Les plantes spontanées indiquent l'état du sol : ortie et chénopode (sol riche), pissenlit et plantain (sol tassé), prêle et renoncule (sol humide), oseille sauvage (acide). Voir les fiches « Plantes sauvages » de l'application.`},{titre:`Ne jamais laisser le sol nu`,texte:`Paillage épais sur les cultures, engrais verts sur les planches vides : c'est 80 % du désherbage évité.`},{titre:`Intervenir jeune`,texte:`Un passage de binette ou de sarcloir quand les herbes ont 2 feuilles, par temps sec, prend quelques minutes ; trois semaines plus tard, c'est une corvée.`},{titre:`Les vivaces coriaces`,texte:`Liseron, chiendent, ronces, rumex : arrachage des racines à la fourche-bêche (jamais de motoculteur), occultation d'une saison sous carton et bâche, fauche répétée qui épuise les réserves. Les chèvres, ânes et poules (en tracteur) sont d'excellents auxiliaires de désherbage.`},{titre:`Les allées`,texte:`Couche épaisse de broyat ou de copeaux sur carton, ou enherbement tondu. Eau bouillante (eau de cuisson des pommes de terre) sur les joints de dallage. Le vinaigre, le sel et l'eau de Javel ne sont pas des désherbants autorisés et polluent le sol.`},{titre:`Laisser des zones sauvages`,texte:`Un coin d'orties, de pissenlits et de ronces nourrit chenilles, papillons, oiseaux et auxiliaires qui protègent ensuite le potager.`}],video:`désherber sans produit potager paillage occultation`,liens:[`paillage`,`liseron`,`chiendent`,`engrais-verts`]},{id:`jardin-sec`,titre:`Jardiner avec la sécheresse (et les restrictions d'eau)`,rubrique:`arrosage`,emoji:`🏜️`,niveau:2,duree:`Lecture : 10 minutes`,resume:`Étés plus chauds, arrêtés de restriction plus fréquents : les techniques pour produire avec beaucoup moins d'eau.`,etapes:[{titre:`Un sol éponge`,texte:`Chaque point de matière organique (compost, paillage, engrais verts) retient de l'eau supplémentaire : c'est l'investissement n° 1. Ne retournez pas la terre en été (elle se dessèche).`},{titre:`Pailler très épais`,texte:`10 à 20 cm de paille, foin, feuilles ou broyat dès que le sol est réchauffé, renouvelés.`},{titre:`Arroser malin`,texte:`Goutte-à-goutte ou oyas au pied, arrosage tôt le matin, copieux et espacé. Priorité aux semis, aux jeunes plants et aux légumes-fruits en formation ; les courges installées, l'ail, les aromatiques méditerranéennes se débrouillent.`},{titre:`Faire de l'ombre`,texte:`Voile d'ombrage (30-40 %) sur les salades et les semis en canicule, cultures hautes (maïs, tournesol, haricots à rames) au sud des légumes-feuilles.`},{titre:`Choisir des cultures sobres`,texte:`Variétés anciennes et locales, tomates « de plein champ », pois chiche, haricots secs, courges, patate douce, aromatiques méditerranéennes, figuier, olivier, amandier dans le Sud. Avancez les semis de printemps et décalez certaines cultures à l'automne.`},{titre:`Stocker l'eau de pluie`,texte:`Plusieurs récupérateurs reliés, ou une cuve enterrée ; une mare. L'eau de pluie récupérée reste généralement utilisable pendant les restrictions (vérifiez l'arrêté de votre département sur vigieau.gouv.fr).`}],video:`potager sans arrosage sécheresse paillage épais techniques`,liens:[`paillage`,`oyas`,`recuperateur-pluie`,`arrosage-bien-arroser`]},{id:`gel-grele`,titre:`Gel tardif, grêle, tempête : protéger le jardin`,rubrique:`serre`,emoji:`🌨️`,niveau:1,duree:`30 minutes à la veille d'une alerte`,resume:`Les accidents climatiques les plus destructeurs, et les gestes à faire quand la météo de l'application les annonce.`,etapes:[{titre:`Gel de printemps`,texte:`La veille au soir : voile d'hivernage (P17 ou P30) sur les plants frileux et les fleurs des fruitiers bas, cloches ou bouteilles coupées sur les jeunes plants, pots rapprochés du mur. Arrosez la veille : un sol humide restitue plus de chaleur qu'un sol sec. Retirez les voiles le matin quand il dégèle.`},{titre:`Après une gelée`,texte:`Ne taillez pas tout de suite les parties gelées : attendez une à deux semaines pour voir ce qui repart. Arrosez légèrement les plants touchés le matin avant le soleil (dégel plus lent).`},{titre:`Grêle`,texte:`Filets paragrêle sur les petits fruits et les tomates dans les régions exposées ; voile tendu sur arceaux en urgence. Après un orage de grêle : retirez les fruits éclatés (porte d'entrée des maladies), décoction de prêle sur les plants blessés, compost pour qu'ils repartent.`},{titre:`Vent fort et tempête`,texte:`Vérifiez tuteurs, ancrage de la serre (fermez portes et aérations), couchez ou rentrez les pots hauts, haubanez les jeunes arbres. Après : coupez proprement les branches cassées (coupe nette au-dessus d'un bourgeon).`},{titre:`Canicule`,texte:`Voir « Jardiner avec la sécheresse » : ombrage, arrosage du matin, paillage, aucune plantation ni taille pendant la vague de chaleur.`}],video:`protéger potager gel tardif voile hivernage grêle`,liens:[`serre`,`chassis`,`jardin-sec`]},{id:`sol-pollue`,titre:`Jardiner en ville : sols pollués et jardins partagés`,rubrique:`sol`,emoji:`🏙️`,niveau:2,duree:`Lecture : 10 minutes`,resume:`Ancien terrain industriel, bord de route, vieille maison aux peintures au plomb, remblais : les précautions pour manger sans risque ce qu'on cultive en ville.`,etapes:[{titre:`Connaître l'historique`,texte:`Interrogez la mairie, les voisins, consultez les bases publiques des anciens sites industriels (Géorisques : sites BASIAS/CASIAS). Les sols proches des routes très fréquentées, des voies ferrées, des anciens garages ou des façades peintes avant 1950 (plomb) sont à surveiller.`},{titre:`Faire analyser`,texte:`En cas de doute, une analyse des métaux lourds (plomb, cadmium, arsenic…) dans un laboratoire agréé coûte de 50 à 150 €. C'est la seule façon de savoir.`},{titre:`Si le sol est douteux`,texte:`Cultivez hors sol : carrés ou bacs sur géotextile remplis de terre et de compost d'apport ; lavez soigneusement et épluchez les légumes-racines ; privilégiez les légumes-fruits (tomates, courges, haricots) qui accumulent moins les métaux que les légumes-feuilles et racines ; lavez-vous les mains et faites retirer les chaussures en rentrant.`},{titre:`Les enfants d'abord`,texte:`Les jeunes enfants qui portent la terre à la bouche sont les plus exposés au plomb : bac à sable avec sable propre, zones de jeu enherbées ou couvertes.`},{titre:`Jardins partagés et familiaux`,texte:`Renseignez-vous sur le règlement (pas de produits, gestion du compost commun, eau partagée, tours d'arrosage pendant les vacances) : c'est souvent la meilleure option pour qui n'a pas de jardin, avec en prime l'expérience des jardiniers voisins.`}],video:`jardin urbain sol pollué analyse plomb bacs`,liens:[`connaitre-sol`,`carre-potager-diy`,`methodes-culture`]},{id:`cueillette-sauvage`,titre:`Cueillir les plantes sauvages sans danger`,rubrique:`securite`,emoji:`🧺`,niveau:2,duree:`Lecture : 10 minutes`,resume:`Ortie, pissenlit, mouron, ail des ours, mûres, sureau… la cueillette sauvage est un plaisir, à condition de connaître les confusions mortelles et les règles.`,etapes:[{titre:`La règle d'or`,texte:`On ne mange JAMAIS une plante sauvage sur la seule foi d'une application ou d'une photo, même avec un score élevé. Il faut être certain de l'identification, idéalement confirmée par un connaisseur (sorties botaniques, associations, pharmacien).`},{titre:`Les confusions mortelles à connaître`,texte:`Ail des ours ↔ muguet et colchique (l'ail des ours sent l'ail quand on froisse la feuille). Carotte sauvage, cerfeuil, persil ↔ ciguës. Sureau noir ↔ sureau hièble. Myrtilles ↔ baies de belladone. Consoude et bourrache ↔ digitale. Les fiches « Plantes dangereuses » de l'application détaillent les différences.`},{titre:`Où cueillir`,texte:`Loin des routes, des champs traités, des chemins à chiens et des zones de pâture (douve du foie sur le cresson et le pissenlit des prés humides). Lavez soigneusement, cuisez ce qui peut l'être.`},{titre:`Les règles`,texte:`Cueillette raisonnable pour un usage familial, jamais de déracinement, pas de cueillette des espèces protégées ; certaines communes et parcs réglementent la cueillette. Demandez l'accord du propriétaire en terrain privé.`},{titre:`Les champignons`,texte:`Faites toujours vérifier votre cueillette par un pharmacien ou une association mycologique. Les applications d'identification de champignons ne sont pas fiables. En cas de symptômes après un repas de champignons : centre antipoison ou 15.`}],video:`plantes sauvages comestibles confusions mortelles ail des ours`,liens:[`cigue`,`colchique`,`muguet`,`ortie`,`pissenlit`,`plantes-toxiques`]},{id:`permaculture`,titre:`Organiser son terrain : zones, permaculture et plan d'ensemble`,rubrique:`demarrer`,emoji:`🗺️`,niveau:2,duree:`Une saison d'observation`,resume:`Placer potager, poulailler, compost, verger, mare et haies au bon endroit fait gagner des heures chaque semaine. Les principes simples de la permaculture appliqués à une maison avec jardin.`,etapes:[{titre:`Observer une saison`,texte:`Notez où se lève et se couche le soleil (été et hiver), où vient le vent, où l'eau stagne après la pluie, où gèle d'abord le sol, ce qui pousse spontanément. Le plan visuel de « Mon jardin » sert à le dessiner.`},{titre:`Les zones`,texte:`Zone 1 (à quelques pas de la cuisine) : aromatiques, salades, ce qu'on cueille tous les jours, composteur de cuisine. Zone 2 : potager principal, petits fruits, poulailler (visité quotidiennement). Zone 3 : verger, grandes cultures (pommes de terre, courges), parcs des animaux. Zone 4-5 : haie, prairie, coin sauvage.`},{titre:`Faire travailler les éléments ensemble`,texte:`Le poulailler près du compost et du verger (fientes, insectes, fruits tombés), la mare en point bas (eau, crapauds contre les limaces), le récupérateur près de la serre, la haie face au vent dominant, les arbres à feuilles caduques au sud de la maison (ombre l'été, soleil l'hiver).`},{titre:`Commencer petit`,texte:`Installez d'abord la zone 1 et le compost, puis agrandissez chaque année : un aménagement réussi se construit sur plusieurs saisons.`}],video:`permaculture zones aménagement jardin maison plan`,liens:[`creer-potager`,`haie`,`hotel-insectes`,`poulailler`]},{id:`jardin-pour-tous`,titre:`Jardiner avec des enfants, en vieillissant ou avec une mobilité réduite`,rubrique:`demarrer`,emoji:`♿`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Adapter le jardin et les gestes pour que chacun puisse jardiner longtemps, sans se faire mal et en sécurité.`,etapes:[{titre:`Mettre le jardin à la bonne hauteur`,texte:`Bacs surélevés à 70-80 cm pour jardiner debout ou assis (fauteuil : bac sur pieds avec espace pour les genoux, profondeur de travail de 60 cm maximum). Allées stables et larges (au moins 1,2 m pour un fauteuil), sans marches ni graviers profonds.`},{titre:`Des outils adaptés`,texte:`Manches longs et légers, outils à double poignée, sécateur à crémaillère qui demande moins de force, tabouret-agenouilloir, arrosoir de petite contenance ou tuyau sur dévidoir, goutte-à-goutte programmé.`},{titre:`Ménager le dos et les articulations`,texte:`Séances courtes, alternance des tâches, échauffement des poignets et des épaules, paillage et planches permanentes qui suppriment bêchage et désherbage. Faites-vous aider pour les charges (sacs de terreau, brouettes pleines).`},{titre:`Avec les enfants`,texte:`Un petit carré à eux, des cultures rapides et spectaculaires (radis, tournesols, courges, fraises, capucines), des outils à leur taille, un hôtel à insectes à fabriquer. Sécurité : clôture des mares et des récupérateurs, outils rangés, produits hors de portée, apprentissage des plantes à ne jamais goûter (voir les plantes dangereuses), vaccin antitétanique à jour.`},{titre:`Lire, écouter, voir`,texte:`Dans l'application : agrandissez le texte (Réglages), faites lire les fiches et les tutoriels à voix haute, utilisez le mode pas à pas avec commandes vocales quand les mains sont occupées.`}],video:`jardin surélevé accessible fauteuil seniors enfants potager`,liens:[`carre-potager-diy`,`securite-jardin`,`plantes-toxiques`,`hotel-insectes`]},{id:`fleurs-semis-entretien`,titre:`Semer, planter et entretenir les fleurs`,rubrique:`fleurs`,emoji:`🌸`,niveau:1,duree:`Toute la saison`,resume:`Annuelles, bisannuelles, vivaces, bulbes, grimpantes : quand semer ou planter, comment les faire fleurir longtemps, et les gestes d'entretien selon le type de fleur.`,etapes:[{titre:`Connaître le cycle`,texte:`Annuelle (cosmos, zinnia, capucine) : semée au printemps, fleurit l'été, meurt à l'automne. Bisannuelle (pensée, rose trémière, digitale) : semée l'été, fleurit l'année suivante. Vivace (échinacée, pivoine, aster) : revient chaque année. Bulbe (tulipe, lys, dahlia) : se plante à une saison précise. Chaque fiche l'indique.`},{titre:`Semer les annuelles`,texte:`Graines fines (muflier, pétunia, alysse) : en surface, au chaud, dès février-mars sous abri. Grosses graines (capucine, cosmos, tournesol, pois de senteur) : en place en avril-mai, après les gelées pour les frileuses. Les fleurs des champs (coquelicot, bleuet, nigelle) se sèment à la volée en automne ou au printemps sur sol nu.`},{titre:`Planter vivaces et bulbes`,texte:`Vivaces : au printemps ou mieux en automne (racines installées avant l'été). Bulbes de printemps (tulipes, narcisses) : en automne ; bulbes d'été (dahlias, glaïeuls) : au printemps après les gelées.`},{titre:`Faire durer la floraison`,texte:`Coupez les fleurs fanées (« nettoyage ») avant qu'elles ne fassent des graines : la plante refait des fleurs. Cueillez pour les bouquets le matin. Engrais riche en potasse (purin de consoude) pour les fleurs en pot.`},{titre:`Arroser et pailler`,texte:`Au pied, le matin ; paillage léger. Les fleurs méditerranéennes (lavande, gaura, échinacée) se contentent de peu d'eau ; les annuelles en pot boivent tous les jours en été.`},{titre:`Diviser et multiplier`,texte:`Divisez les touffes de vivaces tous les 3-4 ans au printemps ou en automne : vous rajeunissez la plante et obtenez de nouveaux pieds gratuits. Récoltez les graines des annuelles non hybrides (fiche « Récolter ses graines »).`},{titre:`Associer au potager`,texte:`Capucines, soucis, œillets d'Inde, cosmos, bourrache, alysse et phacélie attirent les pollinisateurs et les auxiliaires qui mangent les pucerons : semez-en quelques-uns au bout de chaque planche.`}],video:`semer fleurs annuelles vivaces entretien floraison`,liens:[`fleurs-comestibles`,`jardin-pollinisateurs`,`graines-maison`,`cosmos`,`capucine`]},{id:`fleurs-comestibles`,titre:`Les fleurs comestibles (et celles à ne jamais manger)`,rubrique:`fleurs`,emoji:`🍽️`,niveau:1,duree:`Lecture : 10 minutes`,resume:`Capucines, soucis, pensées, bourrache, roses, courgettes, lavande… Celles qui se mangent, comment les récolter et les préparer, et les règles de sécurité.`,etapes:[{titre:`Les règles de sécurité`,texte:`Seulement des fleurs identifiées avec certitude, cultivées par vous ou garanties « comestibles » : JAMAIS les fleurs de fleuriste ou de jardinerie (traitées), ni celles des bords de route. Retirez pistils et étamines (pollen allergisant), goûtez en petite quantité la première fois. Le filtre « Comestible » du catalogue les rassemble.`},{titre:`Les plus faciles`,texte:`Capucine (poivrée), souci (couleur safran), pensée et violette (douces), bourrache (goût d'huître), mauve, fleurs de courgette (farcies), ciboulette (piquante), lavande vraie (desserts, avec modération), rose (gelée, sucre), sureau (sirop, beignets), lilas, hémérocalle (boutons), coquelicot et bleuet (pétales), tournesol.`},{titre:`Récolter et conserver`,texte:`Le matin, après la rosée, fleurs juste ouvertes ; secouez pour chasser les insectes, rincez délicatement, posez sur un papier, au réfrigérateur dans une boîte : à utiliser dans la journée. Séchage (pétales de souci, de rose) ou cristallisation au sucre (violettes).`},{titre:`Les fleurs à ne JAMAIS manger`,texte:`Muguet, digitale, laurier-rose, glycine, lupin d'ornement, pois de senteur (graines), datura, colchique, narcisse et jonquille, jacinthe, hortensia, rhododendron, clématite, aconit, belladone, lys (et mortel pour les chats). En cas d'ingestion : centre antipoison ou 15.`},{titre:`Avec les animaux`,texte:`Ce qui est comestible pour vous ne l'est pas forcément pour eux : les hémérocalles et les lys tuent les chats. Vérifiez la ligne « Pour vos animaux » de chaque fiche.`}],video:`fleurs comestibles jardin liste sécurité recettes`,liens:[`capucine`,`souci`,`pensee`,`bourrache`,`plantes-toxiques`,`cueillette-sauvage`]},{id:`jardin-pollinisateurs`,titre:`Des fleurs toute l'année pour les pollinisateurs`,rubrique:`fleurs`,emoji:`🐝`,niveau:1,duree:`Une saison`,resume:`Un calendrier de floraisons de février à novembre pour nourrir abeilles, bourdons, papillons et syrphes, qui pollinisent fruits et légumes et mangent les pucerons.`,etapes:[{titre:`Fin d'hiver (février-mars)`,texte:`Crocus, primevères, violettes, perce-neige, saules et noisetiers, romarin : vitales pour les bourdons qui sortent d'hivernage.`},{titre:`Printemps (avril-mai)`,texte:`Fruitiers, tulipes botaniques, muscaris, pensées, lilas, bourrache, consoude, glycine, giroflées.`},{titre:`Été (juin-août)`,texte:`Lavande, phacélie, cosmos, zinnias, échinacées, rudbeckias, coquelicots, bleuets, tournesols, sauge, origan, thym, lavande, agapanthe, mauves, roses simples (pas les roses doubles, sans pollen accessible).`},{titre:`Automne (septembre-novembre)`,texte:`Asters, sedums, dahlias simples, lierre en fleur (indispensable : dernière grande ressource avant l'hiver), cosmos, capucines.`},{titre:`Les bons choix`,texte:`Préférez les fleurs SIMPLES (un seul rang de pétales) aux fleurs doubles décoratives, souvent stériles ou inaccessibles. Plantez par touffes d'une même espèce. Laissez fleurir quelques légumes (poireaux, radis, roquette, choux) et un coin de pissenlits. Le filtre « Pour les abeilles » du catalogue les rassemble.`},{titre:`Sans traitement`,texte:`Même « naturel », un insecticide (savon noir, pyrèthre) tue aussi les pollinisateurs : jamais sur les fleurs ouvertes, jamais en journée.`}],video:`fleurs mellifères toute l'année abeilles jardin`,liens:[`hotel-insectes`,`abeille`,`phacelie`,`lavande`,`fleurs-semis-entretien`]}],A=[{id:`balcon-voisinage`,titre:`Balcon : poids, eau qui coule, copropriété et voisins`,rubrique:`balcon`,emoji:`🏢`,niveau:1,duree:`30 minutes de vérifications`,resume:`Ce qu'il faut vérifier avant d'installer bacs, jardinières et récupérateur sur un balcon : charge admise, fixations, écoulements chez le voisin du dessous, règlement de copropriété.`,alias:[`poids balcon`,`charge balcon`,`copropriete balcon`,`eau qui coule balcon`,`voisin du dessous`,`jardiniere exterieure garde corps`,`fixer jardiniere`],materiel:[`Règlement de copropriété ou bail`,`Soucoupes à rebord haut, bacs à réserve d'eau`,`Supports de jardinière adaptés au garde-corps`],etapes:[{titre:`Le poids : la vraie limite`,texte:`Un terreau humide pèse 1 à 1,2 kg par litre : un bac de 100 L dépasse 120 kg, un carré potager de 1 m² sur 30 cm atteint 300 à 400 kg. Un balcon d'immeuble ancien est souvent prévu pour 250 à 350 kg/m² (moins pour un balcon en encorbellement fin), personnes comprises. Placez les charges lourdes contre le mur porteur et près des angles, jamais au milieu ou en bout de dalle.`,attention:`En cas de doute (fissures, balcon ancien), demandez au syndic la charge admissible avant d'installer de gros bacs. Allégez avec des billes d'argile au fond, du terreau léger et des pots en plastique ou en géotextile.`},{titre:`Les jardinières suspendues`,texte:`Accrochez-les côté intérieur du garde-corps : à l'extérieur, une chute peut blesser un passant et engage votre responsabilité. Utilisez des supports vissés ou à serrage prévus pour l'épaisseur de votre rambarde ; vérifiez-les chaque printemps et avant un coup de vent.`},{titre:`L'eau qui coule chez le voisin`,texte:`Arrosez lentement, avec des soucoupes à rebord haut sous chaque pot et des bacs à réserve d'eau. Évitez d'arroser quand le linge du voisin sèche ; jamais de jet d'eau pour nettoyer le sol si l'écoulement tombe chez les autres. Gardez libre l'évacuation d'eau de pluie du balcon (feuilles, terreau).`},{titre:`Le règlement de copropriété`,texte:`Il peut interdire les jardinières à l'extérieur, les canisses, les plantes grimpantes sur la façade, les barbecues ou les récupérateurs d'eau, et imposer une harmonie de façade. Lisez-le avant d'acheter ; en location, le bail peut aussi prévoir des règles.`},{titre:`Vent et étages élevés`,texte:`Au-delà du 4e étage, le vent dessèche et casse : choisissez des plantes basses et souples (graminées, aromatiques méditerranéennes, lierre), lestez les pots, attachez les tuteurs, rentrez parasols et voiles d'hivernage lors des tempêtes.`}],conseils:[`Une assurance habitation couvre en principe les dégâts des eaux chez le voisin, mais mieux vaut ne pas en arriver là.`,`Un plancher en caillebotis sur une étanchéité ancienne retient l'eau : soulevez-le chaque année pour nettoyer.`],video:`balcon poids jardinière copropriété conseils`,liens:[`potager-balcon`,`arrosage-auto-balcon`,`voisinage-regles`]},{id:`pigeons-balcon`,titre:`Pigeons au balcon : les éloigner sans les blesser`,rubrique:`balcon`,emoji:`🕊️`,niveau:1,duree:`1 heure`,resume:`Pigeons qui nichent dans les jardinières, picorent les semis et salissent : ce qui marche (filets, fils, pas de nourriture) et ce qui est interdit.`,alias:[`pigeons`,`pigeon balcon`,`eloigner pigeons`,`pigeons semis`,`fientes pigeons`,`pigeon niche`],materiel:[`Filet anti-oiseaux à mailles fines (ou voile anti-insectes) pour les semis`,`Pics ou fils tendus pour les rebords`,`Brosse, gants, masque pour nettoyer les fientes`],etapes:[{titre:`Ne rien laisser à manger`,texte:`Pas de pain, de graines pour oiseaux sur le balcon, de croquettes d'animaux dehors. Nourrir les pigeons est d'ailleurs interdit par le règlement sanitaire de la plupart des communes. Ramassez les graines tombées des mangeoires.`},{titre:`Protéger semis et jeunes plants`,texte:`Les pigeons arrachent les semis de pois, de salades, de choux. Posez un voile ou un filet tendu sur arceaux jusqu'à ce que les plants soient bien installés (3 à 4 semaines).`},{titre:`Empêcher l'installation`,texte:`Ils nichent dans les jardinières vides, les coins abrités et derrière les bacs. Garnissez les jardinières vides de bâtons verticaux plantés serré, tendez un fil fin à 5 cm au-dessus des rebords, posez des pics sur les corniches où ils se posent. Retirez tout début de nid avant la ponte.`,attention:`Une fois les œufs pondus, laissez le nid jusqu'à l'envol : détruire nids avec œufs ou oisillons est encadré, et les pigeons ramiers (gros, collier blanc) sont des oiseaux sauvages.`},{titre:`Nettoyer les fientes`,texte:`Les fientes sèches peuvent transmettre des maladies (ornithose, cryptococcose) : humidifiez-les avant de brosser, portez gants et masque, ne les compostez pas pour le potager.`}],erreurs:[`Les CD, hiboux en plastique et ballons effaroucheurs ne marchent que quelques jours.`,`Les gels collants et produits répulsifs blessent les oiseaux et sont souvent interdits.`],video:`éloigner pigeons balcon filet sans les blesser`,liens:[`potager-balcon`,`balcon-voisinage`]},{id:`arrosage-auto-balcon`,titre:`Arrosage automatique sur un balcon (avec ou sans robinet)`,rubrique:`arrosage`,emoji:`💧`,niveau:2,duree:`2 heures d'installation`,resume:`Goutte-à-goutte sur programmateur, pompe solaire sur réserve d'eau, bacs à réserve : arroser balcon et terrasse sans y penser, même en vacances.`,alias:[`arrosage automatique`,`goutte a goutte balcon`,`programmateur arrosage`,`arrosage sans robinet`,`pompe solaire arrosage`,`kit arrosage balcon`],materiel:[`Avec robinet : programmateur à pile, réducteur de pression, tuyau 13 mm, micro-tubes 4 mm, goutteurs réglables`,`Sans robinet : kit pompe solaire ou à USB + réservoir de 20 à 60 L`,`Bacs ou jardinières à réserve d'eau`],etapes:[{titre:`Choisir selon le balcon`,texte:`Avec un robinet extérieur : programmateur à pile + goutte-à-goutte, le plus fiable. Sans robinet : petite pompe solaire ou sur batterie qui puise dans un réservoir (pratique jusqu'à 10-15 pots). Pour quelques pots seulement : bacs à réserve d'eau, cônes et oyas suffisent.`},{titre:`Installer le goutte-à-goutte`,texte:`Tuyau principal le long du balcon, un micro-tube et un goutteur par pot (2 pour un grand bac). Réglez le débit : environ 1 L par jour pour une jardinière de 60 cm en été, 2 à 3 L pour un pot de tomate de 30 L.`,astuce:`Un réducteur de pression évite que les raccords sautent : sur un balcon, une fuite coule chez le voisin.`},{titre:`Programmer`,texte:`Arrosez tôt le matin (6 h), une ou deux fois par jour selon la chaleur. Faites un test d'une semaine avant de partir : contrôlez chaque jour que l'eau ne déborde pas des soucoupes et que la terre reste humide sans être détrempée.`},{titre:`Avant les vacances`,texte:`Groupez les pots à l'ombre légère, paillez, remplissez la réserve, changez la pile du programmateur, et confiez la clé à un voisin pour une vérification si vous partez plus de 10 jours.`},{titre:`L'hiver`,texte:`Videz tuyaux, pompe et programmateur avant les gelées et rangez-les à l'abri : l'eau qui gèle fait éclater les raccords.`}],video:`arrosage automatique balcon goutte à goutte programmateur pompe solaire`,liens:[`arrosage-vacances`,`oyas`,`potager-balcon`,`balcon-voisinage`]},{id:`hivernage-pots`,titre:`Hiverner les plantes en pot (balcon, terrasse)`,rubrique:`balcon`,emoji:`❄️`,niveau:1,duree:`1 à 2 heures à l'automne`,resume:`Les racines en pot gèlent bien plus vite qu'en pleine terre : quelles plantes rentrer, lesquelles protéger dehors, et comment éviter que les pots éclatent.`,alias:[`hiverner`,`hivernage`,`proteger du gel pots`,`rentrer les plantes`,`plantes en pot hiver`,`voile hivernage`,`geranium hiver`,`agrumes hiver`,`olivier en pot hiver`,`lavande en pot`,`hortensia en pot`],materiel:[`Voile d'hivernage (P30), papier bulle ou toile de jute`,`Cales ou pieds de pot`,`Pièce lumineuse et fraîche (5 à 12 °C) pour les plantes à rentrer`],etapes:[{titre:`Les plantes à rentrer avant les gelées`,texte:`Agrumes, géraniums (pélargoniums), bougainvillée, laurier-rose jeune, dipladénia, plantes d'intérieur sorties l'été, aromatiques fragiles (basilic, citronnelle, verveine citronnelle). Rentrez-les quand les nuits passent sous 5 °C, après avoir vérifié l'absence de cochenilles et de limaces sous le pot. Idéal : pièce lumineuse et fraîche (véranda, cage d'escalier claire), arrosage réduit.`},{titre:`Les plantes qui restent dehors`,texte:`Lavande, thym, romarin, sauge, olivier adulte, hortensia, rosiers, petits fruitiers, graminées, bulbes : elles supportent le froid, mais leurs racines en pot sont exposées. Regroupez les pots contre le mur abrité de la pluie, surélevez-les sur des cales (l'eau ne doit pas stagner dessous), entourez le pot de papier bulle ou de jute.`,astuce:`Un pot de moins de 30 cm de diamètre gèle à cœur dès -5 °C : rapprochez-le du mur ou mettez-le dans un pot plus grand rempli de paille.`},{titre:`Voiler les feuillages persistants`,texte:`Par gel annoncé sous -5 °C, enveloppez olivier, laurier, agrumes restés dehors d'un voile d'hivernage (jamais de plastique, qui fait de la condensation). Retirez-le dès le redoux.`},{titre:`Arroser l'hiver`,texte:`Les persistants en pot meurent souvent de soif l'hiver, surtout à l'abri de la pluie : arrosez légèrement hors gel, une à deux fois par mois. Les caducs (hortensia, rosier) ont besoin de très peu d'eau.`},{titre:`Les pots eux-mêmes`,texte:`Les pots en terre cuite non « ingélive » éclatent au gel : rentrez-les vides ou choisissez des pots résistants au gel. Videz soucoupes et réservoirs.`}],video:`hiverner plantes en pot balcon protéger du gel`,liens:[`gel-grele`,`potager-balcon`,`agrumes`]}],j={haie:[`haie`,`planter une haie`,`tailler la haie`,`haie champetre`,`haie brise vent`,`arbustes haie`],pelouse:[`pelouse jaune`,`gazon jaune`,`gazon`,`pelouse seche`,`mousse dans la pelouse`,`tondre`,`regarnir pelouse`],poulailler:[`construire poulailler`,`poulailler`,`combien de poules`,`poules en ville`],"abattage-volaille":[`tuer un poulet`,`tuer une poule`,`tuer un canard`,`saigner volaille`,`plumer`,`vider un poulet`,`fiel`,`retirer le fiel`,`abattre`],"preparer-lapin":[`tuer un lapin`,`depouiller lapin`],oeufs:[`oeufs`,`conserver les oeufs`,`oeufs frais`,`test de fraicheur`,`laver les oeufs`],"cultiver-pour-animaux":[`nourrir poules`,`nourrir les poules`,`que donner aux poules`,`nourrir lapins`,`restes pour les poules`,`nourrir chevres`],"plantes-interieur-bases":[`engrais plantes vertes`,`engrais plante interieur`,`entretenir plante verte`,`plante qui meurt`,`plante interieur meurt`],"plantes-toxiques":[`plante pour chat`,`plantes pour chats`,`plante sans danger chat`,`chat mange plante`,`chien mange plante`,`plante toxique chat`],"eau-arrosage-interieur":[`eau du robinet plantes`,`eau calcaire`,`arroser plante interieur`],"potager-balcon":[`potager balcon`,`legumes balcon`,`tomates en pot`,`balcon plein sud`,`balcon nord`,`balcon ombre`],"integrer-animaux":[`nouvelles poules`,`quarantaine`,`presenter les poules`],"voisinage-regles":[`declaration poules`,`declaration mairie`,`coq bruit`,`voisin coq`,`bruler dechets verts`,`distance plantation voisin`,`arbre du voisin`],"fumiers-securite":[`fumier dangereux`,`aminopyralide`,`fumier cheval herbicide`],"compost-tas":[`compost`,`composter`,`composteur`,`compost qui sent mauvais`,`compost en tas`],"taille-fruitiers":[`tailler pommier`,`tailler poirier`,`taille des arbres`,`quand tailler`],"arrosage-bien-arroser":[`combien arroser`,`quand arroser`,`arroser le soir`,`arroser le matin`],"semis-interieur":[`semis qui filent`,`semis etioles`,`fonte des semis`,`semer en godet`],desherbage:[`mauvaises herbes`,`desherber`,`chiendent`,`liseron`],"nuisibles-predateurs":[`renard`,`fouine`,`rats`,`sanglier`,`chevreuil`,`taupe`],couvaison:[`couveuse`,`faire couver`,`poussins`,`incubation`],"lumiere-led":[`lampe horticole`,`lampe plante`,`manque de lumiere`,`appartement sombre`],"vacances-plantes-interieur":[`vacances plantes`,`partir en vacances`,`arroser pendant absence`]},M=e=>({niveau:1,duree:`Lecture : 6 minutes`,rubrique:`animaux`,...e}),N=[M({id:`veterinaire-urgences`,titre:`Le vétérinaire, les urgences et la pharmacie de l'éleveur`,emoji:`⚕️`,resume:`Trouver un vétérinaire avant d'en avoir besoin, reconnaître une urgence, prendre la température, préparer une pharmacie de base et respecter les règles des médicaments (ordonnance, délai d'attente, registre).`,alias:[`vétérinaire`,`veterinaire`,`trouver un vétérinaire`,`vétérinaire rural`,`quand appeler le vétérinaire`,`urgence animal`,`pharmacie de l'éleveur`,`trousse de secours animaux`,`premiers secours animaux`,`température normale`,`prendre la température`,`délai d'attente`,`ordonnance`,`médicaments animaux`],etapes:[{titre:`Trouver un vétérinaire AVANT d'acheter`,texte:`Beaucoup de cabinets ne soignent que les chiens et les chats. Appelez ceux de votre secteur et demandez s'ils acceptent les animaux de ferme (on dit « rurale » ou « mixte »), les lapins et les volailles. Notez le numéro des urgences de nuit et de week-end. Le GDS (groupement de défense sanitaire) de votre département connaît les vétérinaires ruraux et organise des formations.`},{titre:`Les signes d'urgence (appelez le jour même)`,texte:`Tous : ne mange plus et ne boit plus, reste couché à l'écart, respiration rapide ou bouche ouverte, sang, plaie profonde, os cassé, convulsions, fièvre forte. Lapin : plus de crottes depuis 12 heures (stase). Chèvre et mouton : ventre gonflé à gauche (météorisation), mise bas bloquée plus de 30 minutes, ne rumine plus. Âne et cheval : se roule, regarde son flanc, gratte le sol (coliques). Volailles : plusieurs malades ou morts en peu de temps (déclaration possible).`},{titre:`Prendre la température`,texte:`Thermomètre numérique à embout souple, lubrifié (vaseline), dans le rectum pendant le temps indiqué, en tenant le thermomètre. Notez l'heure et la valeur pour le vétérinaire. Les valeurs normales de chaque espèce sont dans le tableau de la page « Un animal ne va pas bien » ; chez les volailles, la mesure est difficile : fiez-vous au comportement.`},{titre:`En attendant le vétérinaire`,texte:`Isolez l'animal au calme, au sec, à l'abri des autres (et des prédateurs). Eau à disposition, rien de forcé dans la bouche d'un animal couché (risque de fausse route). Réchauffez un animal froid (bouillotte enveloppée, lampe à distance). Ne donnez aucun médicament humain : paracétamol et ibuprofène sont toxiques pour plusieurs espèces. Photographiez ce que vous voyez (crottes, plaie, posture) et notez depuis quand.`},{titre:`La pharmacie de base`,texte:`Thermomètre numérique ; gants jetables ; désinfectant pour plaies (chlorhexidine ou povidone iodée diluée) ; compresses, bande cohésive, ruban adhésif ; seringues sans aiguille (pour faire boire) ; réhydratant oral vétérinaire ; tire-tique ; coupe-onglons ou sécateur à onglons et pince à ongles ; lampe frontale ; cage ou box d'isolement ; colostrum de réserve congelé (chèvres, brebis) ; carnet et stylo. Le reste (antibiotiques, anti-inflammatoires, vermifuges) se prend sur ordonnance, pour un problème précis.`},{titre:`Médicaments : les règles`,texte:`Pour un animal dont on mange les œufs, le lait, la viande ou le miel, seuls certains médicaments sont autorisés, et chacun a un délai d'attente pendant lequel ces produits ne se consomment pas. Gardez l'ordonnance (5 ans), notez chaque traitement dans le registre d'élevage, et entrez le délai d'attente dans « Mon jardin › Animaux › Noter un soin » : l'accueil vous rappelle jusqu'à quand jeter les œufs ou le lait.`}],conseils:[`Faites une visite de prévention dès l'arrivée des animaux : le vétérinaire vous connaîtra quand l'urgence arrivera.`,`Gardez près du téléphone : numéro du vétérinaire, poids approximatif de chaque animal, date du dernier vermifuge et des vaccins.`],erreurs:[`Attendre le lendemain avec un lapin qui ne mange plus ou une chèvre gonflée : ces urgences se jouent en heures.`,`Vermifuger tout le monde « au cas où » sans analyse de crottes : les vers deviennent résistants.`],video:`premiers secours animaux de ferme prendre température chèvre`,liens:[`registre-elevage`,`vers-digestifs`,`deces-animal`,`debuter-animaux`]}),M({id:`debuter-animaux`,titre:`Débuter avec des animaux : par où commencer`,emoji:`🐣`,duree:`Lecture : 8 minutes`,resume:`Choisir l'espèce qui convient à votre terrain, votre temps et votre budget, faire les déclarations, préparer abri, clôture et vétérinaire, bien acheter, et réussir le premier mois.`,alias:[`débuter avec des animaux`,`debuter elevage`,`premiers animaux`,`j'ai envie d'avoir des poules`,`avoir des chèvres`,`quel animal choisir`,`animal pour débutant`,`combien coûte une chèvre`,`combien coute une poule`,`prix d'une chèvre`,`coût de départ`,`déclarer ses poules`,`déclarer ses chèvres`,`déclaration poules mairie`,`numéro ede`,`elevage familial`],etapes:[{titre:`1. Choisir l'espèce`,texte:`Partez de vos contraintes : place, temps chaque jour, absences, voisins, budget, et ce que vous attendez (œufs, tonte de l'herbe, compagnie, viande). Le comparateur de la page Animaux met côte à côte les 14 espèces. Pour une première fois, les poules (3 ou 4) sont l'élevage le plus simple ; les chèvres et les moutons demandent clôture, soins des pieds, vermifugation raisonnée et un vrai suivi.`},{titre:`2. Les déclarations`,texte:`Poules et autres volailles : déclaration en mairie (formulaire Cerfa de détention de volailles), même pour quelques poules. Chèvres, moutons et porcs : déclaration à l'EDE (établissement de l'élevage, à la chambre d'agriculture) AVANT l'arrivée, qui vous donne un numéro d'élevage ; identification par boucles et registre d'élevage obligatoires. Ânes et chevaux : identification (puce, document SIRE) et déclaration du lieu de détention à l'IFCE. Ruches : déclaration chaque année. Lapins, cailles et pigeons de compagnie : renseignez-vous en mairie.`},{titre:`3. Préparer avant l'arrivée`,texte:`Abri sec et aéré, clôture adaptée (grillage enterré contre le renard pour les poules, clôture de 1,20 m au moins et sans appui pour les chèvres), points d'eau qui ne gèlent pas, réserve de foin ou d'aliment pour un mois, petite pharmacie, et un vétérinaire qui accepte vos animaux. Lisez le règlement de lotissement ou de copropriété, et prévenez vos voisins.`},{titre:`4. Bien acheter`,texte:`Achetez dans un élevage que vous pouvez visiter, des animaux vifs, propres, au poil ou plumage lisse, sans toux ni diarrhée, avec les papiers prévus (document de circulation, boucles). Jamais un animal seul pour les espèces grégaires : deux chèvres, deux moutons, deux ânes au minimum. Évitez les foires en période d'épidémie.`},{titre:`5. Le premier mois`,texte:`Quarantaine de 3 semaines à l'écart des animaux déjà présents. Transition alimentaire progressive (gardez un sac de l'aliment de l'éleveur). Observez chaque jour : appétit, crottes, comportement. Notez tout dans « Mon jardin › Animaux » : les rappels de soins (vermifuge, parage, nettoyage) s'organisent tout seuls.`},{titre:`6. Le vrai budget`,texte:`Comptez deux budgets : le départ (achat des animaux, abri, clôture, matériel), souvent bien plus élevé que les animaux eux-mêmes, et le mois (aliment, litière, vétérinaire, vermifuges, assurance). Les repères par espèce sont dans le comparateur ; prévoyez aussi une visite vétérinaire imprévue par an.`}],conseils:[`Commencez petit : trois poules la première année vous apprendront plus que dix animaux d'espèces différentes.`,`Trouvez dès le départ quelqu'un qui pourra s'occuper de vos animaux pendant vos absences.`],erreurs:[`Acheter sur un coup de cœur au marché sans abri ni clôture prêts.`,`Un seul animal d'une espèce grégaire : il dépérit ou s'échappe pour retrouver des congénères.`],video:`débuter élevage poules chèvres conseils`,liens:[`poulailler`,`integrer-animaux`,`registre-elevage`,`veterinaire-urgences`,`vacances-animaux`]}),M({id:`rapaces-volailles`,titre:`Protéger poules et poussins des rapaces`,emoji:`🦅`,resume:`Épervier, autour, buse : reconnaître une attaque de rapace, protéger les poussins et les petites volailles sans nuire à des oiseaux protégés par la loi.`,alias:[`rapace`,`rapaces`,`épervier`,`epervier`,`épervier poussins`,`buse`,`autour des palombes`,`milan`,`faucon poules`,`rapace poulailler`,`poussins enlevés`],etapes:[{titre:`Reconnaître une attaque`,texte:`Poussin ou jeune volaille disparu en plein jour sans trace, ou plumes plumées sur place (le rapace plume ; le renard arrache et emporte, la fouine tue la nuit plusieurs volailles). Les volailles qui crient et courent se cacher sous un buisson en levant les yeux signalent souvent un rapace.`},{titre:`Ce que dit la loi`,texte:`Tous les rapaces sont protégés : il est interdit de les tuer, de les capturer, de les blesser ou de détruire leurs nids. En cas de dégâts importants et répétés, contactez la DDT ou l'OFB de votre département.`},{titre:`Protéger les plus petits`,texte:`Poussins, cailles et jeunes pintades sous un filet ou dans un parc couvert les deux premiers mois. Un parcours avec des abris (arbustes, haies, palettes posées en toit, bâches) permet aux volailles de se cacher en 2 secondes : c'est la protection la plus efficace.`},{titre:`Les gardiens`,texte:`Un coq alerte et rassemble ses poules ; les oies et les pintades donnent l'alarme ; un chien de ferme dissuade. Les CD suspendus et les épouvantails marchent quelques jours seulement : changez-les de place souvent.`}],conseils:[`Les rapaces chassent surtout en fin d'hiver et au printemps, quand ils nourrissent leurs jeunes : soyez vigilant à cette saison.`],erreurs:[`Laisser des poussins en liberté sur une pelouse rase et dégagée.`],video:`protéger poules rapaces filet abri`,liens:[`nuisibles-predateurs`,`poussins`,`poule`]}),M({id:`verger-protection`,titre:`Protéger le verger toute l'année : traitements d'hiver et pièges`,emoji:`🍏`,rubrique:`recolte`,niveau:2,duree:`Lecture : 7 minutes`,resume:`Le calendrier d'un verger familial sain : nettoyage et traitements d'hiver autorisés au jardin, pièges à phéromones, glu et bandes-pièges, filets, ramassage des fruits tombés.`,alias:[`traitement d'hiver`,`traitement d'hiver arbres fruitiers`,`huile blanche`,`huile de paraffine`,`bouillie bordelaise arbres`,`piège à phéromones`,`piege a pheromones`,`glu arbre`,`bande engluée`,`bandes pièges`,`bande carton carpocapse`,`calendrier de traitement verger`,`protéger le verger`,`verger bio`],etapes:[{titre:`Hiver (décembre-février) : nettoyer`,texte:`Ramassez les fruits momifiés restés sur l'arbre et au sol (moniliose), les feuilles tavelées, coupez le bois mort et les chancres. Brossez les vieux troncs (mousses et vieilles écorces abritent des œufs de pucerons et des cochenilles). Un traitement à l'huile de paraffine, sur arbre en repos, hors gel, réduit pucerons, cochenilles et acariens : uniquement avec un produit portant la mention « emploi autorisé au jardin ».`},{titre:`Chute des feuilles et débourrement : le cuivre, avec modération`,texte:`La bouillie bordelaise (cuivre), à la chute des feuilles puis au gonflement des bourgeons, limite cloque du pêcher, chancres et tavelure. Le cuivre s'accumule dans le sol et nuit aux vers de terre : respectez la dose de l'étiquette, pas plus de 2 ou 3 passages par an, et préférez des variétés résistantes.`},{titre:`Printemps : surveiller`,texte:`Pièges blancs englués dans les pommiers et pruniers à la floraison (hoplocampe). Bandes de glu ou de colle sur le tronc (sur un ruban, jamais directement sur l'écorce) contre les fourmis qui élèvent les pucerons. Pièges jaunes contre la mouche de la cerise au changement de couleur des fruits. Les pièges à phéromones (carpocapse, tordeuses) servent surtout à savoir quand les papillons volent.`},{titre:`Été : piéger et ramasser`,texte:`Bandes de carton ondulé autour du tronc fin juin : les chenilles de carpocapse s'y installent, détruisez-les en automne. Ramassez les fruits tombés deux fois par semaine (poules bienvenues). Filets anti-insectes ou ensachage des plus beaux fruits contre la drosophile et le carpocapse ; filets contre les oiseaux sur les cerisiers.`},{titre:`Toute l'année : les alliés`,texte:`Nichoirs à mésanges (elles nourrissent leurs petits de chenilles), haies variées, fleurs au pied des arbres, perchoirs à rapaces contre les campagnols. Un verger enherbé, fauché tard, abrite les auxiliaires.`}],conseils:[`Notez chaque traitement dans « Mon jardin › Interventions » : vous verrez d'une année sur l'autre ce qui a marché.`],erreurs:[`Traiter au cuivre « par habitude » chaque mois : le sol en garde la trace des dizaines d'années.`,`Poser de la glu directement sur l'écorce ou laisser des bandes engluées en place où des oiseaux et des chauves-souris se collent.`],video:`traitement hiver arbres fruitiers huile paraffine bouillie bordelaise`,liens:[`carpocapse`,`hoplocampe`,`cloque`,`tavelure`,`moniliose`,`taille-par-fruitier`,`planter-verger`]})],P=e=>({niveau:1,duree:`Lecture : 6 minutes`,rubrique:`animaux`,...e}),F=[P({id:`api-debuter`,titre:`Débuter en apiculture : la première année`,emoji:`🐝`,duree:`Lecture : 8 minutes`,resume:`Se former avant d'acheter, commencer avec deux ruches, choisir entre essaim sur cadres et ruchette, le vrai budget, la déclaration, et ce qu'on peut attendre la première année (souvent peu ou pas de miel).`,alias:[`débuter en apiculture`,`debuter apiculture`,`commencer l'apiculture`,`comment commencer l'apiculture`,`première ruche`,`premiere ruche`,`combien de ruches pour débuter`,`acheter un essaim`,`acheter des abeilles`,`où acheter des abeilles`,`prix d'une ruche`,`budget apiculture`,`essaim sur cadres`,`ruchette`,`paquet d'abeilles`,`essaim nu`,`apiculteur débutant`],etapes:[{titre:`1. Se former d'abord`,texte:`Suivez une saison dans un rucher-école (syndicat ou association apicole de votre département) avant d'acheter : vous ouvrirez des ruches avec quelqu'un d'expérimenté, vous apprendrez à lire un cadre et à lutter contre le varroa. L'inscription coûte peu et ouvre souvent l'accès à du matériel partagé (extracteur).`},{titre:`2. Deux ruches plutôt qu'une`,texte:`Avec deux colonies, on compare (l'une est-elle anormalement faible ?) et on peut dépanner l'une avec un cadre de couvain de l'autre si elle perd sa reine. Une seule ruche qui meurt, c'est tout à recommencer.`},{titre:`3. Essaim sur cadres ou ruchette ?`,texte:`Achetez un essaim de l'année sur 5 ou 6 cadres (couvain, réserves, reine marquée de l'année), chez un apiculteur local qui peut vous le montrer, avec un certificat sanitaire. Les livraisons ont lieu d'avril à juin. Les « paquets d'abeilles » sans cadres et les essaims nus récupérés sont pour plus tard : ils demandent plus de savoir-faire. Évitez les abeilles importées de loin.`},{titre:`4. Le vrai budget`,texte:`Par ruche : 150 à 250 € l'essaim, 100 à 200 € la ruche Dadant 10 cadres avec une hausse, et une fois pour toutes 100 à 250 € d'équipement (vareuse avec voile, gants, enfumoir, lève-cadre, brosse, nourrisseur). L'extracteur se loue ou s'emprunte au syndicat. Comptez ensuite 20 à 40 € par ruche et par an (traitements contre le varroa, cire, sucre).`},{titre:`5. Déclarer et installer`,texte:`Déclarez vos ruches chaque année (entre le 1er septembre et le 31 décembre, en ligne sur le site du ministère de l'Agriculture), dès la première ruche. Choisissez l'emplacement avant l'arrivée des abeilles (voir « Où installer ses ruches ») et respectez les distances fixées par arrêté préfectoral.`},{titre:`6. La première année`,texte:`La colonie construit ses cadres et grossit : on ne récolte souvent rien, ou une petite hausse en fin d'été si la saison est bonne. Visitez toutes les 1 à 2 semaines au printemps, comptez le varroa en juillet, traitez en août, nourrissez si la ruche est légère en septembre. Notez chaque visite dans le carnet du rucher : les alertes vous guident.`}],conseils:[`Choisissez une abeille douce et locale (votre fournisseur sait comment se comportent ses colonies) : à la première saison, une colonie calme fait toute la différence.`,`Trouvez un parrain ou une marraine apiculteur près de chez vous : un coup de fil pendant une visite vaut tous les livres.`],erreurs:[`Acheter la ruche en kit et les abeilles sur internet sans avoir jamais ouvert une ruche.`,`Vouloir du miel la première année et récolter les réserves dont la colonie a besoin pour l'hiver.`],video:`débuter apiculture première année conseils`,liens:[`abeille`,`api-materiel`,`api-emplacement`,`api-visite`,`api-calendrier`,`api-reseau`,`api-varroa`]}),P({id:`api-emplacement`,titre:`Où installer ses ruches : jardin, ville, toit et voisins`,emoji:`📍`,resume:`Les distances à respecter, la bonne exposition, une ruche dans un petit jardin, en ville ou sur un toit, et comment éviter les ennuis avec les voisins.`,alias:[`emplacement ruche`,`où mettre une ruche`,`ou installer une ruche`,`distance ruche voisin`,`distance ruche maison`,`ruche dans un petit jardin`,`ruche en ville`,`ruche sur un toit`,`ruche sur un balcon`,`apiculture urbaine`,`arrêté préfectoral ruche`,`ruche voisinage`],etapes:[{titre:`Les distances`,texte:`Elles sont fixées par un arrêté préfectoral ou un arrêté municipal propre à chaque département : renseignez-vous en mairie ou auprès du GDSA. Souvent 10 à 20 m des habitations et de la voie publique, moins (ou rien) si la ruche est derrière une haie, un mur ou une palissade d'au moins 2 m de haut qui dépasse la ruche de chaque côté : les abeilles prennent alors de la hauteur en sortant.`},{titre:`La bonne place`,texte:`Trou de vol orienté au sud-est (soleil du matin), à l'abri des vents dominants, sur un support à 40 cm du sol, légèrement penché vers l'avant (l'eau de condensation s'écoule), avec un point d'eau proche (abreuvoir avec flotteurs, pour éviter qu'elles aillent boire à la piscine du voisin). Jamais dans un creux humide ni en plein courant d'air.`},{titre:`Un petit jardin`,texte:`C'est possible avec une ou deux ruches, une haie ou un brise-vue devant le trou de vol pour faire monter les abeilles, et en éloignant le passage des enfants et du linge qui sèche. Plantez des fleurs mellifères, mais les abeilles butinent surtout jusqu'à 3 km : le jardin seul ne les nourrit pas.`},{titre:`En ville ou sur un toit`,texte:`Le toit demande l'accord du propriétaire ou de la copropriété, un accès sûr (pas d'échelle avec une hausse pleine dans les bras), une protection contre le vent et la chaleur (toit noir l'été) et un point d'eau. En ville, la nourriture manque souvent : trop de ruches dans un quartier affament aussi les abeilles sauvages. Une ou deux ruches suffisent.`},{titre:`Les voisins`,texte:`Prévenez-les avant l'arrivée des abeilles, offrez un pot de miel, et expliquez quoi faire en cas d'essaim (vous appeler). Évitez les visites quand ils déjeunent dehors ou par temps orageux. En cas de personne allergique à proximité, cherchez un autre emplacement.`}],conseils:[`Pas de place ? Beaucoup d'agriculteurs et de jardins partagés accueillent volontiers une ou deux ruches.`],erreurs:[`Poser la ruche face à une allée ou à une terrasse : les abeilles passent à hauteur de visage.`],video:`emplacement ruche jardin distance voisins`,liens:[`api-debuter`,`api-securite`,`api-miellees`,`jardin-pollinisateurs`]}),P({id:`api-reine-perdue`,titre:`La reine a-t-elle disparu ? Le savoir et réagir`,emoji:`👑`,resume:`Trouver la reine sans perdre une heure, ce qui prouve qu'elle est là même sans la voir, reconnaître une colonie orpheline ou des ouvrières pondeuses, et que faire dans chaque cas.`,alias:[`pas de reine`,`reine introuvable`,`trouver la reine`,`comment trouver la reine`,`ruche orpheline`,`colonie orpheline`,`reine morte`,`reine perdue`,`ouvrières pondeuses`,`plus d'oeufs dans la ruche`,`plus de couvain`,`bourdonneuse`,`introduire une reine`],etapes:[{titre:`Pas besoin de voir la reine`,texte:`Des œufs (petits bâtonnets blancs dressés au fond des cellules, un par cellule) prouvent qu'il y avait une reine il y a moins de 3 jours. Regardez à contre-jour, soleil dans le dos, sur un cadre de couvain du centre. S'il y a des œufs, refermez : tout va bien.`},{titre:`Si on veut la trouver`,texte:`Fumez peu, ouvrez calmement, commencez par un cadre de rive, puis regardez d'abord la face du cadre que vous sortez (elle fuit vers l'ombre). Elle est plus longue, l'abdomen dépasse des ailes, les ouvrières se tournent vers elle ; une reine marquée se voit par sa pastille de couleur. Ne cherchez pas plus de 10 minutes : le couvain refroidit.`},{titre:`Signes d'une colonie orpheline`,texte:`Plus d'œufs ni de jeunes larves, colonie bruyante (un « bourdonnement plaintif » à l'ouverture), abeilles nerveuses, cellules royales en cours (la colonie essaie de refaire une reine), réserves de pollen qui s'accumulent.`},{titre:`Ouvrières pondeuses`,texte:`Plusieurs œufs par cellule, collés sur les parois, couvain de mâles bombé dans des cellules d'ouvrières : la colonie est orpheline depuis plusieurs semaines. Elle n'acceptera presque plus de reine : on la réunit à une colonie forte (méthode du papier journal) ou on secoue ses abeilles devant une autre ruche.`},{titre:`Que faire`,texte:`Si des cellules royales sont là, attendez 3 à 4 semaines sans ouvrir (la jeune reine éclot, part se faire féconder, puis pond). Sans cellules royales, donnez un cadre d'œufs et de jeunes larves d'une autre ruche : elle élèvera une reine. Ou introduisez une reine fécondée achetée, en cage, après avoir vérifié l'absence de cellules royales. Notez tout dans le carnet du rucher.`}],conseils:[`Faites marquer la reine (couleur de l'année) : vous saurez son âge et la trouverez trois fois plus vite.`],erreurs:[`Ouvrir tous les jours pour voir si la nouvelle reine pond : on la dérange pendant ses vols de fécondation.`],video:`trouver la reine abeille colonie orpheline`,liens:[`api-reines`,`api-visite`,`orpheline`,`api-debuter`]}),P({id:`api-ruche-morte`,titre:`Ma ruche est morte : comprendre pourquoi et repartir`,emoji:`🔍`,resume:`Lire ce qui reste dans une ruche morte (famine, varroa, humidité, orphelinage, pillage, maladie), éviter de contaminer les autres ruches, et nettoyer le matériel.`,alias:[`ruche morte`,`abeilles mortes en hiver`,`colonie morte`,`ruche vide au printemps`,`ruche vide`,`perte hivernale`,`pourquoi ma ruche est morte`,`autopsie ruche`,`abeilles mortes dans la ruche`,`abeilles tête dans les cellules`],etapes:[{titre:`D'abord, fermer`,texte:`Fermez le trou de vol dès que vous constatez la mort : les abeilles des autres ruches viendraient piller le miel, et avec lui d'éventuelles maladies. Emportez la ruche à l'abri pour l'examiner.`},{titre:`Famine`,texte:`Abeilles mortes la tête dans les cellules, en grappe serrée, à côté de cadres vides ; parfois du miel au bout de la ruche, que la grappe n'a pas pu atteindre par le froid. Leçon : peser les ruches à l'automne et en fin d'hiver, nourrir au candi si besoin.`},{titre:`Varroa et virus`,texte:`Peu d'abeilles mortes dans une ruche avec encore des réserves, quelques abeilles aux ailes déformées, couvain abandonné en petites plaques, nombreux points blancs (déjections de varroa) au plafond des cellules. C'est la cause la plus fréquente : la colonie s'est effondrée à l'automne. Leçon : compter en juillet, traiter en août, contrôler après.`},{titre:`Humidité, orphelinage, pillage`,texte:`Cadres moisis, eau au plancher : ruche mal aérée ou mal penchée. Plus de couvain du tout, peu d'abeilles, couvain de mâles : orphelinage. Cire déchiquetée, opercules arrachés, réserves vidées en quelques jours : pillage (souvent la suite d'une colonie déjà faible).`},{titre:`Maladie : ne rien réutiliser`,texte:`Couvain en mosaïque, cellules affaissées, odeur aigre ou de colle, larve qui s'étire en fil quand on y plonge une allumette : suspicion de loque. Ne réutilisez ni cadres ni miel, et appelez votre GDSA ou un technicien sanitaire : la loque américaine est à déclaration obligatoire.`},{titre:`Nettoyer et repartir`,texte:`Sans maladie : grattez la ruche, passez les parois à la flamme du chalumeau, fondez les vieux cadres (cire), gardez les cadres de miel sains au congélateur 48 heures (fausse teigne) pour un futur essaim. Déclarez la perte dans le carnet du rucher : le taux de pertes de l'hiver s'y calcule.`}],conseils:[`Prenez des photos des cadres et montrez-les à votre rucher-école : un diagnostic à plusieurs est plus fiable.`],erreurs:[`Laisser la ruche morte ouverte : elle devient une source de pillage et de maladies pour tout le voisinage.`],video:`ruche morte autopsie cause famine varroa`,liens:[`api-varroa`,`api-nourrissement`,`famine`,`loque-americaine`,`api-hivernage`]}),P({id:`api-pillage`,titre:`Le pillage : le reconnaître et l'arrêter`,emoji:`⚔️`,resume:`Quand des abeilles étrangères (ou des guêpes) attaquent une ruche pour voler son miel : les signes, les gestes qui l'arrêtent, et comment l'éviter.`,alias:[`pillage`,`pillage ruche`,`abeilles qui se battent`,`ruche pillée`,`réduire le trou de vol`,`réducteur d'entrée`,`guêpes ruche`],etapes:[{titre:`Reconnaître`,texte:`Agitation désordonnée devant le trou de vol, abeilles qui se battent et roulent au sol, vol en zigzag devant les fentes de la ruche, abeilles qui repartent lourdes ; dans la ruche, opercules arrachés, débris de cire au plancher. Une activité intense en fin d'été, sans pollen aux pattes, est suspecte.`},{titre:`Arrêter`,texte:`Réduisez le trou de vol à la largeur d'une ou deux abeilles, bouchez toutes les fentes, posez une planche ou un drap mouillé devant l'entrée pour désorienter les pillardes. Ne réouvrez pas la ruche pillée ce jour-là. Si la colonie est trop faible, réunissez-la à une autre.`},{titre:`Éviter`,texte:`Ne laissez jamais traîner de miel, de cadres ni de cire près du rucher. Nourrissez le soir, dans un nourrisseur couvre-cadres étanche, sans faire couler de sirop. Visites courtes en période de disette (fin d'été). Réducteurs d'entrée posés dès la fin de la miellée.`}],conseils:[`Les colonies faibles ou orphelines sont les premières pillées : surveillez-les en septembre.`],video:`pillage ruche que faire réducteur`,liens:[`api-nourrissement`,`api-ruche-morte`,`api-frelon`]}),P({id:`essaim-batiment`,titre:`Un essaim dans un mur, une cheminée ou un arbre`,emoji:`🏚️`,resume:`Qui appeler quand des abeilles s'installent dans une maison, ce qu'il ne faut pas faire, et la différence entre un essaim de passage et une colonie installée.`,alias:[`abeilles dans la cheminée`,`abeilles dans un mur`,`abeilles dans le toit`,`essaim dans mon jardin`,`essaim dans un arbre`,`abeilles installées maison`,`qui appeler pour un essaim`,`enlever un essaim`,`essaim pompiers`],etapes:[{titre:`Essaim de passage ou colonie installée ?`,texte:`Une grappe d'abeilles accrochée à une branche, un volet ou une boîte aux lettres est un essaim en transit : il repart souvent sous 1 à 3 jours, et un apiculteur peut le récupérer facilement. Des abeilles qui entrent et sortent d'un trou de mur ou d'une cheminée depuis plusieurs jours ont construit des rayons : c'est une colonie installée.`},{titre:`Qui appeler`,texte:`Essaim visible : la liste des récupérateurs d'essaims du syndicat apicole ou du GDSA de votre département, ou la mairie. Les pompiers n'interviennent plus pour les abeilles sauf danger immédiat. Colonie dans un mur : un apiculteur équipé ou une entreprise spécialisée en retrait d'abeilles (travaux d'ouverture parfois nécessaires, à la charge du propriétaire).`},{titre:`Ce qu'il ne faut pas faire`,texte:`Ne pas pulvériser d'insecticide (les rayons et le miel restent dans le mur, pourrissent et attirent d'autres insectes), ne pas boucher l'entrée d'une colonie installée (elles cherchent une autre sortie, parfois dans la maison), ne pas l'enfumer soi-même dans un conduit.`},{titre:`Frelons ou guêpes ?`,texte:`Si ce sont des frelons ou des guêpes (corps plus lisse, jaune vif ou noir, nid en papier), appelez un désinsectiseur ; pour le frelon asiatique, signalez le nid à la mairie ou sur la plateforme de votre région.`}],video:`récupérer essaim abeilles cheminée mur`,liens:[`api-essaimage`,`api-reseau`,`api-frelon`]}),P({id:`api-hivernage`,titre:`Préparer la ruche à l'hiver : réserves, isolation, aération`,emoji:`❄️`,resume:`Ce qui tue une colonie en hiver (faim, humidité, varroa, dérangement), comment vérifier les réserves, isoler sans étouffer, et que faire en fin d'hiver.`,alias:[`hivernage ruche`,`hiverner une ruche`,`isolation ruche`,`isoler la ruche`,`ruche en hiver`,`humidité ruche`,`partition ruche`,`candi`,`pain de sucre abeilles`,`sucre en pain abeilles`],etapes:[{titre:`Septembre : vérifier les réserves`,texte:`Une colonie a besoin de 15 à 20 kg de miel et de sucre pour l'hiver (davantage en montagne). Soupesez la ruche par l'arrière ou pesez-la (carnet du rucher) ; si elle est légère, nourrissez au sirop épais (2 kg de sucre pour 1 L d'eau) jusqu'à mi-octobre, quand les abeilles peuvent encore le transformer.`},{titre:`Resserrer et isoler`,texte:`Retirez la hausse, réduisez le trou de vol, posez une grille anti-souris. Une partition (planche) réduit le volume d'une colonie petite. Un isolant (plaque de liège ou de polystyrène) sur le couvre-cadres, sous le toit, réduit les pertes de chaleur ; les parois en bois de 25 mm suffisent dans la plupart des régions.`},{titre:`Aérer sans courant d'air`,texte:`L'ennemi n'est pas le froid mais l'humidité : la grappe produit de la vapeur qui se condense et retombe sur elle. Plateau grillagé ouvert, toit qui laisse circuler l'air au-dessus de l'isolant, ruche penchée vers l'avant. Pas de bâche collée sur la ruche.`},{titre:`Ne pas déranger`,texte:`On n'ouvre plus de novembre à février. On soupèse, on écoute (un léger bourdonnement en collant l'oreille), on dégage le trou de vol des abeilles mortes après le froid. Traitement d'hiver contre le varroa quand il n'y a plus de couvain, selon le plan de lutte.`},{titre:`Fin d'hiver : le moment critique`,texte:`En février-mars, le couvain reprend et les réserves fondent. Une ruche légère reçoit du candi (pâte de sucre) posé au-dessus de la grappe ; un pain de sucre humidifié dépanne. Jamais de sirop liquide par temps froid : les abeilles ne peuvent pas l'évaporer.`}],conseils:[`Notez le poids de chaque ruche à l'automne : la comparaison au printemps dit si la colonie a manqué.`],erreurs:[`Calfeutrer complètement la ruche : l'humidité moisit les cadres et refroidit la grappe.`],video:`préparer ruche hiver isolation candi`,liens:[`api-nourrissement`,`api-varroa`,`api-ruche-morte`,`famine`]})],I=e=>({niveau:1,duree:`Lecture : 5 minutes`,rubrique:`interieur`,...e}),L=[I({id:`sauver-plante`,titre:`Sauver une plante qui va mal : le plan en 6 étapes`,emoji:`🚑`,duree:`30 minutes`,resume:`Une démarche dans l'ordre pour trouver ce qui ne va pas (terre, racines, lumière, ravageurs, emplacement) et les gestes qui sauvent, sans tout faire en même temps.`,alias:[`sauver une plante`,`sauver ma plante`,`plante qui meurt`,`ma plante meurt`,`plante mourante`,`plante qui dépérit`,`plante achetée qui dépérit`,`plante malade intérieur`,`que faire plante qui va mal`,`réanimer une plante`,`racines pourries que faire`],materiel:[`Journal ou bâche`,`Sécateur ou ciseaux propres (désinfectés à l'alcool)`,`Terreau neuf adapté`,`Pot avec trou, 2 à 4 cm plus large que la motte (si besoin)`],etapes:[{titre:`1. Touchez la terre`,texte:`Enfoncez un doigt sur 3 cm. Détrempée, avec une odeur de moisi : excès d'eau, c'est la première cause de mort. Sèche comme de la poussière et motte décollée du pot : la plante a soif (trempez le pot 20 minutes dans une bassine, puis égouttez).`},{titre:`2. Regardez les racines`,texte:`Sortez la motte du pot. Racines claires et fermes : elles vont bien. Brunes, molles, qui se détachent en lambeaux : pourriture. Coupez toutes les parties molles, laissez sécher la motte 1 jour à l'air, rempotez dans un terreau neuf et un pot à peine plus grand, et n'arrosez pas avant 5 à 7 jours. Racines qui tournent en rond et sortent du trou : rempotage.`},{titre:`3. Vérifiez la lumière`,texte:`Tiges longues et pâles, plante qui penche, feuilles petites : elle manque de lumière. Rapprochez-la d'une fenêtre (sans soleil brûlant pour les plantes d'ombre) ou ajoutez une lampe. Taches blanches ou beiges sèches après un déplacement au soleil : brûlure.`},{titre:`4. Cherchez les ravageurs`,texte:`Avec une loupe ou la lampe du téléphone, sous les feuilles et à l'aisselle des tiges : amas cotonneux (cochenilles), petites toiles et feuilles ternes piquetées (araignées rouges), feuilles collantes (pucerons, cochenilles), moucherons sur la terre (sciarides). Isolez la plante des autres, puis traitez (voir la fiche du ravageur).`},{titre:`5. Changez ce qui a changé`,texte:`Une plante qui perd ses feuilles juste après l'achat, un déménagement ou l'arrivée du chauffage réagit souvent à un choc (lumière, température, air sec) : ne la déplacez plus, ne la rempotez pas, n'ajoutez pas d'engrais. Elle repart en 3 à 6 semaines.`},{titre:`6. Taillez et patientez`,texte:`Coupez les feuilles entièrement sèches ou pourries (pas les feuilles à moitié jaunes : la plante en récupère les réserves). Si la tige est encore ferme quelque part, prélevez une bouture saine en sécurité. Puis attendez : une plante soignée met des semaines à montrer du mieux.`}],conseils:[`Un seul changement à la fois : sinon on ne sait jamais ce qui a marché.`,`Le diagnostic « Santé » de l'appli aide à mettre un nom sur le problème.`],erreurs:[`Arroser plus une plante qui s'affaisse alors que sa terre est mouillée : elle se noie.`,`Rempoter, nourrir et déplacer le même jour une plante stressée.`],video:`sauver plante intérieur racines pourries`,liens:[`pourriture-racines`,`soif`,`manque-lumiere`,`cochenilles`,`rempoter`,`plantes-interieur-bases`]}),I({id:`pots-arrosage`,titre:`Pots, cache-pots et arrosage par le bas`,emoji:`🌿`,resume:`Pourquoi le trou au fond du pot compte plus que tout, comment utiliser un cache-pot ou un pot sans trou sans noyer la plante, et quand arroser par le bas, par trempage ou avec une mèche.`,alias:[`pot sans trou`,`cache-pot`,`cache pot`,`eau stagnante cache-pot`,`arroser par le bas`,`arrosage par le bas`,`trempage`,`bassiner`,`arrosage par mèche`,`mèche arrosage`,`pot en terre cuite ou plastique`,`billes d'argile au fond du pot`,`drainage pot`],etapes:[{titre:`Le trou, toujours`,texte:`Une plante en pot sans trou finit presque toujours par pourrir : l'eau en trop stagne au fond et asphyxie les racines. Gardez le pot de culture en plastique (avec trous) et glissez-le dans le joli pot, qui sert alors de cache-pot.`},{titre:`Le cache-pot`,texte:`Après chaque arrosage, videz l'eau qui reste au fond du cache-pot au bout de 15 minutes. Une couche de billes d'argile au fond du cache-pot (pas dans le pot !) surélève la plante au-dessus de l'eau. Contrairement à une idée reçue, des billes ou des cailloux AU FOND DU POT n'améliorent pas le drainage : ils remontent la zone humide vers les racines.`},{titre:`Arroser par le bas`,texte:`Posez le pot dans une bassine ou un évier avec 3 à 5 cm d'eau, 15 à 30 minutes, jusqu'à ce que la surface de la terre devienne humide, puis égouttez. Idéal pour les terreaux devenus secs qui ne retiennent plus l'eau, les violettes africaines (feuilles qui craignent l'eau), les cactus et les plantes à rosette. Une fois par mois, arrosez aussi par le haut pour rincer les sels de l'engrais.`},{titre:`Terre cuite ou plastique ?`,texte:`La terre cuite respire et sèche vite : parfaite pour les cactus, succulentes et ceux qui oublient d'arroser trop souvent... à l'envers. Le plastique garde l'humidité plus longtemps : mieux pour les fougères, calathéas, et ceux qui oublient d'arroser.`},{titre:`La mèche pour les absences`,texte:`Une mèche en coton ou en laine passée par le trou du pot et plongée dans un réservoir d'eau sous le pot arrose en continu, pour une à deux semaines d'absence. À tester avant de partir : certaines plantes (cactus, succulentes) n'aiment pas.`}],erreurs:[`Planter directement dans un pot décoratif sans trou parce qu'il est joli.`],video:`arroser par le bas plante intérieur cache-pot`,liens:[`eau-arrosage-interieur`,`rempoter`,`vacances-plantes-interieur`,`pourriture-racines`]}),I({id:`saisons-plantes-interieur`,titre:`Les saisons des plantes d'intérieur : repos d'hiver, sortie d'été, retour en septembre`,emoji:`📆`,resume:`Pourquoi une plante ne pousse plus en hiver (et ce qu'il faut changer), comment l'humidité de l'air se gère près des radiateurs, sortir les plantes au jardin l'été sans les brûler, et les rentrer sans ramener de ravageurs.`,alias:[`plante qui ne pousse plus en hiver`,`repos hivernal`,`repos d'hiver plante`,`plante en hiver`,`plante près du radiateur`,`chauffage plantes`,`humidifier l'air`,`humidité de l'air plantes`,`air sec plantes`,`sortir les plantes l'été`,`sortir les plantes dehors`,`rentrer les plantes`,`rentrer les plantes en septembre`,`plantes au balcon l'été`,`plante brûlée au soleil`],etapes:[{titre:`L'hiver : le repos`,texte:`De novembre à février, la lumière baisse de moitié : la plupart des plantes poussent peu ou pas. C'est normal. Arrosez 2 fois moins (laissez sécher davantage entre deux arrosages), arrêtez l'engrais, ne rempotez pas, et rapprochez-les des fenêtres (sans toucher la vitre froide). Les plantes près d'une lampe de culture, elles, continuent à pousser.`},{titre:`Radiateurs et air sec`,texte:`L'air chauffé descend souvent sous 30 % d'humidité : bouts de feuilles qui sèchent, araignées rouges. Éloignez les plantes des radiateurs (au moins 1 m), regroupez-les (elles s'humidifient entre elles), posez les pots sur un plateau de billes d'argile mouillées (sans que le pot trempe), ou utilisez un humidificateur dans la pièce. Brumiser les feuilles n'humidifie l'air que quelques minutes et favorise les taches sur certaines plantes.`},{titre:`Mai-juin : sortir progressivement`,texte:`Quand les nuits restent au-dessus de 12 °C, beaucoup de plantes d'intérieur adorent un été dehors, à l'ombre claire (sous un arbre, un balcon nord ou est). Habituez-les sur 10 à 15 jours : d'abord quelques heures à l'ombre, jamais en plein soleil d'un coup (les feuilles brûlent en une après-midi). Surveillez l'arrosage : dehors, elles boivent beaucoup plus.`},{titre:`Septembre : rentrer sans ravageurs`,texte:`Avant que les nuits passent sous 12 °C : inspectez chaque plante (dessous des feuilles, terre), douchez le feuillage, grattez le premier centimètre de terre, et gardez-les 2 semaines à l'écart des autres plantes de la maison. Elles perdront quelques feuilles en s'habituant à la lumière plus faible.`},{titre:`Printemps : le redémarrage`,texte:`Mars-avril, quand de nouvelles feuilles apparaissent : c'est le moment de rempoter si besoin, de reprendre l'engrais et d'augmenter l'arrosage. Tournez les pots d'un quart de tour chaque semaine pour qu'elles poussent droit.`}],conseils:[`Les plantes grasses et les cactus fleurissent mieux après un hiver au frais (10-12 °C) et presque au sec.`],video:`plantes intérieur hiver repos sortir été`,liens:[`air-sec`,`coup-soleil`,`plantes-interieur-bases`,`engrais-interieur`,`lutte-bio-interieur`]}),I({id:`engrais-interieur`,titre:`Nourrir ses plantes d'intérieur : quand, avec quoi, combien`,emoji:`🍽️`,resume:`Les plantes en pot n'ont que la terre de leur pot : l'engrais compte, mais à petite dose, au bon moment, et jamais sur une plante sèche ou malade.`,alias:[`engrais plante intérieur`,`engrais plantes vertes`,`nourrir plante intérieur`,`quel engrais plante intérieur`,`engrais liquide`,`bâtonnets d'engrais`,`engrais orchidée`,`engrais cactus`,`trop d'engrais`,`croûte blanche terreau`,`dose engrais`],etapes:[{titre:`Quand`,texte:`Pendant la pousse, de mars-avril à septembre : toutes les 2 à 4 semaines pour les plantes vertes, une fois par mois pour les cactus et succulentes. Rien en hiver (sauf sous lampe de culture), rien pendant les 2 mois qui suivent un rempotage (le terreau neuf contient déjà de quoi manger).`},{titre:`Avec quoi`,texte:`Un engrais liquide pour plantes vertes (plus d'azote, N) pour le feuillage ; pour plantes fleuries (plus de potassium, K) pour les orchidées, violettes et plantes à fleurs ; un engrais spécial pour cactus et orchidées, très peu dosé. Les bâtonnets se dosent mal : préférez le liquide.`},{titre:`Combien`,texte:`Moitié de la dose indiquée sur l'étiquette : les plantes d'intérieur poussent moins vite que dehors, et le surplus brûle les racines. Toujours sur une terre déjà humide (arrosez d'abord à l'eau claire si elle est sèche).`},{titre:`Trop d'engrais : les signes`,texte:`Croûte blanche sur la terre ou sur le bord du pot, bouts de feuilles brûlés, feuilles qui flétrissent alors que la terre est humide. Rincez la motte : faites couler sous le robinet un volume d'eau égal à 3 fois celui du pot, laissez égoutter, et arrêtez l'engrais 2 mois.`},{titre:`Et les engrais maison ?`,texte:`Le marc de café, les coquilles d'œuf et l'eau de cuisson n'apportent presque rien en pot et peuvent moisir ou attirer des moucherons. Un purin d'ortie très dilué (5 %) convient aux plantes vertes en été, à l'extérieur de préférence (odeur).`}],erreurs:[`Donner de l'engrais à une plante qui va mal : elle a besoin qu'on trouve la cause, pas d'être nourrie.`],video:`engrais plante intérieur dosage`,liens:[`saisons-plantes-interieur`,`sauver-plante`,`eau-arrosage-interieur`]})],R=e=>({niveau:1,duree:`Lecture : 6 minutes`,rubrique:`fleurs`,...e}),z=[R({id:`art-floral-bases`,titre:`Composer et faire durer un bouquet`,emoji:`💐`,duree:`30 minutes`,resume:`Couper au bon moment, conditionner les fleurs, préparer le vase, composer un bouquet équilibré (structure, fleurs vedettes, remplissage, feuillage), sans mousse florale, et le faire tenir deux fois plus longtemps.`,alias:[`faire un bouquet`,`composer un bouquet`,`bouquet`,`conserver un bouquet`,`faire durer un bouquet`,`eau du vase`,`fleurs coupées`,`fleurs coupees tiennent longtemps`,`conditionner les fleurs`,`bouquet de saison`,`bouquet champêtre`,`bouquet de mariée`,`bouquet rond`,`bouquet spiralé`,`mousse florale`,`pique-fleurs`,`kenzan`,`grillage à poule bouquet`,`couronne de fleurs`,`art floral`,`composition florale`],materiel:[`Sécateur ou couteau très propre`,`Seau d'eau fraîche`,`Vase lavé (eau de Javel puis rinçage)`,`Ficelle ou raphia`,`Pique-fleurs (kenzan) ou boule de grillage à poule pour les compositions`],etapes:[{titre:`1. Couper au bon moment`,texte:`Le matin, à la fraîche, ou le soir, jamais en plein soleil. Au bon stade pour chaque fleur (bouton coloré pour la rose et la tulipe, fleur ouverte pour le dahlia et le zinnia : voir la fiche de chaque fleur, rubrique « En bouquet »). Plongez aussitôt les tiges dans un seau d'eau emporté au jardin.`},{titre:`2. Conditionner`,texte:`Retirez toutes les feuilles qui tremperaient dans l'eau (elles pourrissent et nourrissent les bactéries). Recoupez chaque tige en biais de 2 cm, sous l'eau si possible. Tiges ligneuses (lilas, hortensia) : fendez-les sur 3 cm. Narcisses : à part 12 heures. Laissez reposer 2 heures au frais avant de composer : les fleurs se gorgent d'eau.`},{titre:`3. Composer`,texte:`Commencez par la structure (feuillages, branches), puis les fleurs vedettes en nombre impair (3, 5, 7), puis les fleurs de remplissage (alchémille, gypsophile, ammi) et enfin les fleurs légères qui dépassent (verveine, graminées). Hauteur du bouquet : environ une fois et demie celle du vase. Bouquet à la main : tournez-le d'un quart de tour en ajoutant chaque tige en biais dans le même sens (bouquet spiralé), liez au point de croisement.`},{titre:`4. Sans mousse florale`,texte:`La mousse florale verte est un plastique qui se délite en microparticules et ne se composte pas. Remplacez-la par un pique-fleurs (kenzan) au fond d'une coupe, une boule de grillage à poule froissée dans le vase, une grille de ruban adhésif sur l'ouverture, ou des branches entrecroisées.`},{titre:`5. Faire durer`,texte:`Vase propre, eau fraîche changée tous les 2 jours en recoupant les tiges de 1 cm. Loin des fruits (l'éthylène des pommes et des bananes fait faner), du soleil direct et des radiateurs. Le sachet de conservateur fourni par le fleuriste marche ; à défaut, une goutte d'eau de Javel par litre limite les bactéries (pas pour les tiges creuses).`},{titre:`6. Une couronne`,texte:`Sur une base de branches souples (lierre, clématite sauvage, osier) roulées en cercle, ou un cercle de paille, fixez de petits bouquets de feuillage et de fleurs séchées avec du fil de fer fin, tous dans le même sens, chaque bouquet couvrant les tiges du précédent.`}],conseils:[`Fleurs toxiques pour les chats : lys (mortel, même le pollen), et dans une moindre mesure tulipes, narcisses, chrysanthèmes, hortensias, eucalyptus. Avec un chat, préférez roses, gerberas, zinnias, freesias, lisianthus, statice.`,`Un bouquet du jardin vaut celui du fleuriste : un coin de fleurs à couper de 5 m² suffit pour un bouquet par semaine de juin à octobre.`],erreurs:[`Laisser des feuilles dans l'eau.`,`Mettre le bouquet à côté de la corbeille de fruits.`],video:`composer un bouquet de fleurs du jardin conditionnement`,liens:[`fleurs-a-couper`,`fleurs-sechees`,`couleurs-jardin`,`zinnia`,`dahlia`,`lys`]}),R({id:`fleurs-sechees`,titre:`Faire sécher des fleurs et des bouquets`,emoji:`🌾`,resume:`Les fleurs qui sèchent le mieux, quand les couper, les trois méthodes (tête en bas, debout, au silica gel ou sous presse) et comment garder les couleurs.`,alias:[`fleurs séchées`,`faire sécher des fleurs`,`sécher des fleurs`,`bouquet sec`,`bouquet séché`,`fleurs stabilisées`,`herbier`,`presser des fleurs`,`silica gel fleurs`,`immortelles`],etapes:[{titre:`Les meilleures à sécher`,texte:`Immortelles et statice, lavande, achillée, hortensia (fin d'été), gypsophile, nigelle (capsules), célosie, amarante, delphinium, rose en bouton, graminées (miscanthus, stipa, pennisetum), monnaie-du-pape, eucalyptus, chardons. Les fleurs très charnues (lys, tulipes) se sèchent mal.`},{titre:`Quand couper`,texte:`Par temps sec, en fin de matinée quand la rosée est partie, juste avant la pleine ouverture : la fleur continue de s'ouvrir en séchant. Retirez les feuilles.`},{titre:`Tête en bas`,texte:`Petites bottes de 5 à 10 tiges serrées par un élastique (les tiges rétrécissent), suspendues tête en bas dans un endroit sec, sombre et aéré (grenier, placard ventilé) pendant 2 à 4 semaines. L'obscurité garde les couleurs.`},{titre:`Debout ou à plat`,texte:`Hortensias et graminées : debout dans un vase avec 2 cm d'eau qu'on laisse s'évaporer. Fleurs fragiles (roses, pensées) : enfouies dans du silica gel (en vente en droguerie) 3 à 7 jours, couleurs intactes. Pour un herbier : entre deux feuilles de papier absorbant, sous des livres lourds, 2 à 3 semaines.`},{titre:`Garder et entretenir`,texte:`Loin du soleil direct (il blanchit les couleurs en quelques semaines) et de l'humidité. Dépoussiérez au sèche-cheveux froid. Une laque à cheveux légère fixe les graminées qui s'effritent.`}],video:`faire sécher des fleurs tête en bas bouquet sec`,liens:[`statice`,`lavande`,`achillee`,`hortensia`,`art-floral-bases`]}),R({id:`couleurs-jardin`,titre:`Associer les couleurs au jardin et en bouquet`,emoji:`🎨`,resume:`Les trois harmonies simples (camaïeu, complémentaires, contraste doux), le rôle du blanc et du vert, l'effet des couleurs sur la profondeur, et des associations qui marchent à coup sûr.`,alias:[`couleurs qui vont ensemble`,`associer les couleurs`,`harmonie de couleurs`,`cercle chromatique jardin`,`couleurs massif`,`massif bleu et jaune`,`camaïeu`,`couleurs complémentaires`,`jardin blanc`],etapes:[{titre:`Le camaïeu`,texte:`Des couleurs voisines : roses, mauves et violets ; ou jaune, orange et rouge. Harmonie douce, facile à réussir, très reposante. Variez alors les formes (boules, épis, ombelles) et les hauteurs pour éviter la monotonie.`},{titre:`Les complémentaires`,texte:`Des couleurs opposées qui se renforcent : jaune et violet, orange et bleu, rouge et vert. Effet vif et joyeux : utilisez une couleur dominante et l'autre en touches (par exemple beaucoup de bleu et quelques taches d'orange).`},{titre:`Le blanc et le vert`,texte:`Le blanc éclaire les coins d'ombre et le jardin du soir, et sépare des couleurs qui se heurtent. Les fleurs et feuillages vert acide (alchémille, euphorbe) lient toutes les couleurs entre elles : c'est le « sel » d'un massif ou d'un bouquet.`},{titre:`Couleurs et profondeur`,texte:`Les couleurs chaudes (rouge, orange, jaune) semblent plus proches : placez-les près de la maison ou de la terrasse. Les froides (bleu, violet, gris) semblent plus lointaines : au fond du jardin, elles l'agrandissent.`},{titre:`Associations qui marchent`,texte:`Népéta et rosiers roses ; rudbeckia et verveine de Buenos Aires ; lavande et achillée jaune ; hostas, fougères et astilbes blanches à l'ombre ; graminées blondes et orpin d'automne rose ; tulipes violettes et narcisses blancs. La page Fleurs propose des plantes de l'appli pour chaque harmonie.`}],video:`associer les couleurs massif de fleurs`,liens:[`vivaces-guide`,`art-floral-bases`,`concevoir-jardin`]}),R({id:`metier-fleuriste`,titre:`Devenir fleuriste, vendre ses fleurs : les repères`,emoji:`💐`,rubrique:`demarrer`,duree:`Lecture : 5 minutes`,resume:`Les métiers des fleurs (fleuriste, horticulteur de fleurs coupées, paysagiste), les formations, et ce qu'il faut savoir pour vendre quelques bouquets de son jardin.`,alias:[`devenir fleuriste`,`métier fleuriste`,`cap fleuriste`,`formation fleuriste`,`vendre des fleurs`,`vendre ses fleurs`,`fleurs locales`,`fleurs françaises`,`fleurs de france`,`slow flower`,`ferme florale`,`producteur de fleurs`,`devenir paysagiste`,`cap jardinier paysagiste`],etapes:[{titre:`Les métiers`,texte:`Fleuriste (art floral, conseil, boutique) ; horticulteur ou « fleuriculteur » qui produit des fleurs coupées (les fermes florales locales se multiplient) ; jardinier-paysagiste qui crée et entretient les jardins. Les trois demandent de l'endurance physique : froid, eau, port de charges, fêtes et week-ends.`},{titre:`Les formations`,texte:`Fleuriste : CAP fleuriste (1 ou 2 ans, accessible en reconversion et en apprentissage), puis brevet professionnel et brevet de maîtrise. Paysagiste : CAP jardinier paysagiste, bac pro aménagements paysagers, BTSA. Production : BPREA (brevet agricole) pour s'installer en fleurs coupées, avec des aides à l'installation comme en maraîchage.`},{titre:`Vendre quelques fleurs de son jardin`,texte:`Une vente occasionnelle entre particuliers reste tolérée ; dès que la vente devient régulière (marché, dépôt chez un commerçant, vente en ligne), il faut un statut (micro-entreprise agricole) et déclarer les revenus. Renseignez-vous auprès de la chambre d'agriculture.`},{titre:`Les fleurs locales et de saison`,texte:`Environ 85 % des fleurs vendues en France sont importées (Pays-Bas, Kenya, Équateur), souvent cultivées sous serre chauffée ou très traitées. Le label « Fleurs de France » et les collectifs de fleurs locales et de saison (type « slow flower ») référencent les producteurs proches de chez vous. La page Fleurs indique les fleurs locales disponibles chaque mois.`}],video:`devenir fleuriste cap reconversion`,liens:[`art-floral-bases`,`fleurs-a-couper`,`vendre-surplus`]}),R({id:`jardin-mediterraneen`,titre:`Créer un jardin méditerranéen (et sec)`,emoji:`☀️`,rubrique:`demarrer`,resume:`Un jardin qui se passe d'arrosage une fois installé : sol drainé, paillage minéral, plantes à feuillage gris et aromatique, plantation d'automne.`,alias:[`jardin méditerranéen`,`jardin mediterraneen`,`jardin provençal`,`jardin sec sans arrosage`,`jardin de graviers`,`paillage minéral`],etapes:[{titre:`Le sol`,texte:`La plupart des plantes méditerranéennes meurent l'hiver d'humidité, pas de froid. En sol lourd, ajoutez du gravier ou plantez sur une butte de 20-30 cm. Pas d'engrais : elles aiment les sols pauvres.`},{titre:`Les plantes`,texte:`Feuillages gris ou argentés et aromatiques : lavande, sauges, romarin, thym, santoline, perovskia, euphorbe characias, cistes, gaura, kniphofia, achillée, verveine de Buenos Aires, graminées (stipa, fétuque bleue). Arbres : olivier, arbre de Judée, grenadier ; arbustes : pittosporum, éléagnus, myrte, laurier-tin.`},{titre:`Planter à l'automne`,texte:`Plantez de jeunes plants (godets) en octobre-novembre : les racines s'installent tout l'hiver avec la pluie. Arrosez copieusement 2 ou 3 fois la première année, puis plus du tout.`},{titre:`Le paillage minéral`,texte:`Gravier, pouzzolane ou galets sur 5 à 8 cm, sans géotextile plastique dessous : il garde la fraîcheur, empêche les herbes et renvoie la chaleur que ces plantes aiment.`}],video:`créer jardin méditerranéen sec sans arrosage`,liens:[`jardin-sec`,`lavande`,`olivier`,`stipa`,`euphorbe`,`gaura`]}),R({id:`jardin-japonais`,titre:`Un jardin d'inspiration japonaise`,emoji:`🎋`,rubrique:`demarrer`,resume:`Les principes (asymétrie, pierre, eau, végétal persistant, vides), les plantes qui donnent l'ambiance sous nos climats et les erreurs de « décor » à éviter.`,alias:[`jardin japonais`,`jardin zen`,`jardin d'inspiration japonaise`,`jardin sec japonais`,`érable du japon`,`pierre et mousse`],etapes:[{titre:`Les principes`,texte:`Évoquer un paysage en petit : la pierre (montagne), le gravier ratissé ou l'eau (rivière, mer), le végétal taillé (collines). Asymétrie, groupes impairs, beaucoup de vide et de calme : moins d'objets, plus d'effet.`},{titre:`Les plantes`,texte:`Persistants taillés en nuages ou en boules (buis, osmanthe, pin), érable du Japon, cerisier à fleurs, azalées et rhododendrons en sol acide, nandina, bambous non traçants (Fargesia), fougères, hostas, carex, mousses à l'ombre fraîche. Peu de couleurs : surtout des verts, une floraison à la fois.`},{titre:`Le minéral`,texte:`Quelques belles pierres enterrées au tiers (elles doivent sembler sortir du sol), pas de pierres posées. Un gravier clair ratissé ou un pas japonais de dalles irrégulières qui ralentit la marche.`},{titre:`À éviter`,texte:`L'accumulation de lanternes, ponts rouges et bouddhas de jardinerie ; les bambous traçants (Phyllostachys) sans barrière anti-rhizome enterrée sur 70 cm : ils envahissent le jardin et celui des voisins.`}],video:`jardin japonais principes petit jardin`,liens:[`erable-japon`,`nandina`,`carex`,`allees-terrasses`]}),R({id:`jardin-bord-de-mer`,titre:`Jardiner en bord de mer : vent, sel et sable`,emoji:`🌊`,rubrique:`demarrer`,resume:`Créer d'abord un brise-vent avec des arbustes qui supportent les embruns, puis planter à l'abri ; les plantes qui tiennent au sel et au sable.`,alias:[`plantes bord de mer`,`jardin bord de mer`,`jardin en bord de mer`,`embruns`,`vent salé`,`jardin sableux`,`haie bord de mer`],etapes:[{titre:`D'abord le brise-vent`,texte:`Le vent salé brûle les feuilles des plantes non adaptées. Plantez en premier une haie libre d'arbustes résistants aux embruns : éléagnus, pittosporum, tamaris, argousier, griselinia, fusain du Japon, chêne vert. Un brise-vent ajouré (qui laisse passer la moitié du vent) protège mieux qu'un mur, qui crée des tourbillons.`},{titre:`À l'abri de la haie`,texte:`Plantes à feuilles grises, charnues ou cireuses : lavande, armérie maritime, statice, santoline, sédums, agapanthe, kniphofia, achillée, graminées (fétuque bleue, stipa), rosier rugueux.`},{titre:`Le sol sableux`,texte:`Il sèche vite et ne retient rien : compost en surface chaque automne, paillage épais, arrosage au goutte-à-goutte la première année. Choisissez de jeunes plants qui s'enracinent profondément.`}],video:`jardin bord de mer plantes résistantes embruns`,liens:[`eleagnus`,`pittosporum`,`statice`,`kniphofia`,`jardin-mediterraneen`]}),R({id:`jardin-de-pluie`,titre:`Un jardin de pluie (noue) pour l'eau du toit`,emoji:`🌧️`,rubrique:`arrosage`,resume:`Une dépression plantée qui recueille l'eau des toits et des allées, l'infiltre en 24 à 48 heures, évite les inondations et nourrit une flore de milieu frais.`,alias:[`jardin de pluie`,`noue`,`noue paysagère`,`infiltration eau de pluie`,`gestion eau pluviale`,`eau du toit dans le jardin`],etapes:[{titre:`Où et quelle taille`,texte:`À au moins 3 m de la maison (jamais contre les fondations), en pente douce, là où l'eau s'infiltre (test : un trou de 30 cm rempli d'eau doit se vider en moins de 24 heures). Surface : environ 10 à 20 % de la surface du toit raccordé.`},{titre:`Creuser`,texte:`Une cuvette de 15 à 30 cm de profondeur, à fond plat, avec un petit bourrelet en aval. Mélangez la terre du fond avec du compost et du sable si elle est lourde. Amenez l'eau de la descente de gouttière par une rigole de galets.`},{titre:`Planter`,texte:`Au fond, des plantes qui supportent d'avoir les pieds dans l'eau quelques jours puis la sécheresse : iris des marais, carex, salicaire, eupatoire, astilbe, hémérocalles, cornouillers. Sur les bords, des vivaces de sol frais à sec. Paillez avec du broyat.`},{titre:`Entretien`,texte:`Retirez les feuilles qui colmatent l'arrivée, arrosez la première année seulement. Aucun moustique : l'eau ne stagne pas plus de 48 heures.`}],video:`créer un jardin de pluie noue`,liens:[`recuperateur-pluie`,`iris-marais`,`carex`,`astilbe`,`drainage-terrain`]}),R({id:`bassin-ornement`,titre:`Créer un petit bassin d'ornement`,emoji:`💧`,rubrique:`fabriquer`,niveau:2,duree:`Un week-end`,resume:`Emplacement, bâche ou bac préformé, profondeurs étagées, plantes qui gardent l'eau claire, sécurité des enfants et réglementation.`,alias:[`bassin`,`bassin d'ornement`,`creer un bassin`,`bassin de jardin`,`bâche bassin`,`bassin préformé`,`plantes de bassin`,`eau verte bassin`,`nénuphar`],materiel:[`Bâche EPDM (plus durable que le PVC) ou bassin préformé`,`Feutre de protection`,`Sable`,`Pierres plates pour la margelle`,`Plantes aquatiques en paniers`],etapes:[{titre:`Emplacement`,texte:`Mi-ombre (5 à 6 heures de soleil : moins d'algues), loin des grands arbres (feuilles), visible de la maison. Prévoyez une plage en pente douce pour que les animaux qui tombent puissent ressortir.`},{titre:`Creuser en paliers`,texte:`Trois niveaux : bord à 10-20 cm (plantes de berge), palier à 30-40 cm (plantes immergées) et une fosse d'au moins 80 cm sur un tiers de la surface (l'eau n'y gèle pas et reste fraîche l'été). Ôtez cailloux et racines, étalez 5 cm de sable puis le feutre.`},{titre:`Bâche et remplissage`,texte:`Posez la bâche en laissant 50 cm de débord, remplissez progressivement à l'eau de pluie si possible, puis coupez et cachez le bord sous les pierres.`},{titre:`Planter pour une eau claire`,texte:`Un tiers à la moitié de la surface couverte de plantes : nénuphar (surface), plantes oxygénantes immergées (myriophylle, cornifle), plantes de berge (iris des marais, menthe aquatique, populage). Pas de poissons rouges dans un petit bassin : ils mangent têtards et larves et salissent l'eau.`},{titre:`Sécurité`,texte:`Un enfant peut se noyer dans 20 cm d'eau : grille rigide posée juste sous la surface, ou clôture, tant que les enfants sont petits.`}],video:`créer petit bassin de jardin bâche epdm`,liens:[`nenuphar`,`iris-marais`]}),R({id:`mur-vegetal`,titre:`Mur végétal et façade verte : ce qui marche vraiment`,emoji:`🧱`,rubrique:`fabriquer`,resume:`La différence entre grimpantes en façade (simples, durables) et murs végétaux à poches (spectaculaires mais exigeants), et comment réussir chacun.`,alias:[`mur végétal`,`mur vegetal`,`façade végétale`,`végétaliser un mur`,`jardin vertical décoratif`,`grimpante sur façade`,`mur vert`],etapes:[{titre:`La solution simple : les grimpantes`,texte:`Lierre, vigne vierge et hortensia grimpant s'accrochent seuls (crampons, ventouses) sur un mur sain ; clématites, chèvrefeuilles, jasmins, glycine et rosiers grimpants ont besoin de câbles tendus à 5 cm du mur. Une seule plante bien choisie couvre 10 à 20 m² en quelques années, sans arrosage automatique.`},{titre:`Le mur à poches`,texte:`Des plantes dans un feutre ou des modules fixés au mur, avec arrosage automatique et engrais permanents. Spectaculaire, mais une coupure d'eau d'une semaine en été le tue, et il coûte cher. Réservez-le à une petite surface, à l'ombre ou mi-ombre, avec des plantes robustes (heuchères, fougères, carex, bergénias, fraisiers).`},{titre:`Protéger le bâtiment`,texte:`Pas de plantes à crampons sur un crépi abîmé, un mur en bois ou un isolant par l'extérieur ; taillez chaque année autour des fenêtres, gouttières et tuiles. Accord de la copropriété pour une façade d'immeuble.`}],video:`végétaliser un mur grimpantes câbles`,liens:[`grimpantes-supports`,`vigne-vierge`,`lierre-jardin`,`clematite`]}),R({id:`arbres-petit-jardin`,titre:`Quel arbre pour un petit jardin, ou pour vite faire de l'ombre ?`,emoji:`🌳`,rubrique:`demarrer`,resume:`Les arbres qui restent petits, ceux qui poussent vite sans devenir des monstres, les distances légales avec les voisins et les erreurs à ne pas faire.`,alias:[`arbre petit jardin`,`arbre pour petit jardin`,`arbre à croissance rapide`,`arbre croissance rapide`,`ombre rapidement`,`arbre pour faire de l'ombre`,`arbre d'ombrage`,`petit arbre`,`arbre terrasse`,`quel arbre planter`],etapes:[{titre:`Les petits arbres (4 à 8 m)`,texte:`Amélanchier (fleurs, fruits, automne), arbre de Judée, cerisier à fleurs, érable du Japon, cornouiller des pagodes, lilas des Indes (Sud), pommier d'ornement, olivier (Sud), magnolia de Soulange, sorbier, mimosa (Sud, sol acide). Préférez les sujets en cépée (plusieurs troncs) : plus légers et naturels.`},{titre:`Vite de l'ombre`,texte:`Les arbres qui poussent vite (paulownia, peuplier, saule, bouleau, érable argenté) deviennent grands et fragiles. Pour une terrasse, une tonnelle avec glycine, vigne ou chèvrefeuille fait de l'ombre en 2 ou 3 ans ; un érable champêtre, un tilleul ou un mûrier platane (taillé en tête de chat) donnent une ombre durable en 5 à 8 ans.`},{titre:`Les distances légales`,texte:`Code civil : un arbre de plus de 2 m de haut doit être planté à au moins 2 m de la limite de propriété ; en dessous de 2 m de haut, à 50 cm. Des règles locales (PLU, lotissement) peuvent être plus strictes. Le voisin peut exiger l'élagage des branches qui dépassent chez lui.`},{titre:`Bien placer`,texte:`Regardez la taille ADULTE sur la fiche (pas celle du sujet acheté) : à 5 m au moins des fondations et des canalisations pour les grands arbres, jamais sous une ligne électrique. Plantez de novembre à mars, tuteurez 2 ans, arrosez 3 étés.`}],video:`quel arbre pour un petit jardin`,liens:[`amelanchier`,`arbre-judee`,`erable-japon`,`erable-champetre`,`planter-arbre`,`budget-reglementation`]})],B=[...T,...k,...E,...O,...A,...t,...r,...D,...s,...n,...l,...f,...m,...g,...v,...b,...S,i,a,...w,...N,...F,...L,...z].map(t=>e[t.id]?{...t,etapes:[...t.etapes,...e[t.id]]}:t).map(e=>j[e.id]?{...e,alias:[...e.alias??[],...j[e.id]]}:e),V=new Map(B.map(e=>[e.id,e])),H=e=>V.get(e);export{H as n,B as t};